import string as _string

def generate_product_link_token(length=8):
    """Generate a random alphanumeric token (mixed case + digits) of given length."""
    chars = _string.ascii_letters + _string.digits
    return ''.join(random.choices(chars, k=length))

def get_or_create_product_link_token(product_id: int) -> str:
    """
    Returns the existing link_token for a product, or generates and saves a new unique one.
    Token starts at 8 chars and grows by 1 for each collision until unique.
    Tokens are never reused even after product deletion.
    """
    row = db.execute_query(
        "SELECT link_token FROM products WHERE id = %s", (product_id,), fetch=True
    )
    if row and row[0].get('link_token'):
        return row[0]['link_token']

    # Generate a unique token
    length = 8
    while True:
        token = generate_product_link_token(length)
        # Check global uniqueness (across all products, including deleted ones via used_product_tokens)
        conflict = db.execute_query(
            "SELECT 1 FROM used_product_tokens WHERE token = %s", (token,), fetch=True
        )
        if not conflict:
            # Reserve token and assign
            db.execute_query(
                "INSERT INTO used_product_tokens (token) VALUES (%s) ON CONFLICT DO NOTHING", (token,)
            )
            db.execute_query(
                "UPDATE products SET link_token = %s WHERE id = %s", (token, product_id)
            )
            return token
        length += 1  # Collision: increase length

async def _is_stale_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    """Returns True if this is a command update older than 30 mins since bot start — should be skipped."""
    if not update.message or not update.message.text or not update.message.text.startswith('/'):
        return False
    msg_time = update.message.date
    if msg_time.tzinfo is None:
        msg_time = pytz.utc.localize(msg_time)
    bot_start = BOT_START_TIMES.get(context.bot.token)
    if not bot_start:
        return False
    age_seconds = (bot_start - msg_time).total_seconds()
    return age_seconds > 1800  # 30 minutes

async def send_stored_content(
    key: str,
    update: Update,
    context: ContextTypes.DEFAULT_TYPE,
    reply_markup: InlineKeyboardMarkup
):
    """
    Sends content from the DB, handling web (URL) and telegram (file_id) sources.
    This is the final, stable version.
    """
    bot_id = await get_bot_id(context.bot.token)
    result = db.execute_query(
        "SELECT content_data FROM content_blocks WHERE key = %s AND bot_id = %s", (key, bot_id), fetch=True
    )
    query = update.callback_query

    if not result or not result[0]['content_data']:
        await safe_edit_caption_or_text(
            query, f"ℹ️ Content for '{key.replace('_', ' ').title()}' has not been set by the admin yet.", reply_markup
        )
        return

    content_data = result[0]['content_data']


    chat_id = query.message.chat_id

    try:
        await query.message.delete()
    except Exception as e:
        logger.warning(f"Could not delete message before sending content: {e}")

    source = content_data.get('source')

    if source == 'web':

        title = content_data.get('title', ''); content = content_data.get('content', ''); media_url = content_data.get('media_url', '')
        caption = f"*{title}*\n\n{content}"
        try:

            if media_url: await context.bot.send_photo(chat_id=chat_id, photo=media_url, caption=caption, parse_mode=ParseMode.MARKDOWN)
            else: await context.bot.send_message(chat_id=chat_id, text=caption, parse_mode=ParseMode.MARKDOWN)
        except Exception as e: logger.error(f"Error sending 'web' source content for key '{key}': {e}")

    elif source == 'telegram':

        messages_to_send = content_data.get('messages', [])
        for msg_data in messages_to_send:
            msg_type = msg_data.get("type"); text = msg_data.get("text") or msg_data.get("caption", ""); entities = msg_data.get("entities"); file_id = msg_data.get("file_id")
            try:

                if msg_type == "text": await context.bot.send_message(chat_id=chat_id, text=text, entities=entities)
                elif msg_type == "photo": await context.bot.send_photo(chat_id=chat_id, photo=file_id, caption=text, caption_entities=entities)
                elif msg_type == "video": await context.bot.send_video(chat_id=chat_id, video=file_id, caption=text, caption_entities=entities)
                elif msg_type == "document": await context.bot.send_document(chat_id=chat_id, document=file_id, caption=text, caption_entities=entities)
            except Exception as e: logger.error(f"Error sending 'telegram' source content for key '{key}': {e}")

    else:

        await context.bot.send_message(chat_id=chat_id, text=f"ℹ️ Content for '{key}' is in an unrecognized format.")

    await context.bot.send_message(chat_id=chat_id, text="Select an option:", reply_markup=reply_markup)

async def replay_stored_messages(
    key: str,
    update: Update,
    context: ContextTypes.DEFAULT_TYPE,
    reply_markup: InlineKeyboardMarkup
):
    """
    Fetches a sequence of stored messages from the DB and replays them to the user.
    The reply_markup is attached to the very last message sent.
    """
    query = update.callback_query
    chat_id = update.effective_chat.id
    bot_id = await get_bot_id(context.bot.token)

    result = db.execute_query(
        "SELECT content_data FROM content_blocks WHERE key = %s AND bot_id = %s", (key, bot_id), fetch=True
    )

    if not result or not result[0]['content_data']:
        error_msg = f"ℹ️ Content for '{key.replace('_', ' ').title()}' has not been set by the admin yet."
        if query:
            await safe_edit_caption_or_text(query, error_msg, reply_markup)
        else:
            await context.bot.send_message(chat_id=chat_id, text=error_msg, reply_markup=reply_markup)
        return

    content_data = result[0]['content_data']
    messages_to_send = content_data.get('messages', [])

    if not messages_to_send:
        error_msg = f"ℹ️ Content for '{key.replace('_', ' ').title()}' is empty."
        if query:
            await safe_edit_caption_or_text(query, error_msg, reply_markup)
        else:
            await context.bot.send_message(chat_id=chat_id, text=error_msg, reply_markup=reply_markup)
        return

    if query:
        try:
            await query.message.delete()
        except Exception as e:
            logger.warning(f"Could not delete message before replaying content: {e}")


    total_messages = len(messages_to_send)
    for i, msg_data in enumerate(messages_to_send):
        is_last_message = (i == total_messages - 1)
        current_reply_markup = reply_markup if is_last_message else None

        msg_type = msg_data.get("type")
        text = msg_data.get("text") or msg_data.get("caption", "")
        entities = msg_data.get("entities")
        file_id = msg_data.get("file_id")

        try:
            if msg_type == "text":
                await context.bot.send_message(chat_id=chat_id, text=text, entities=entities, reply_markup=current_reply_markup)
            elif msg_type == "photo":
                await context.bot.send_photo(chat_id=chat_id, photo=file_id, caption=text, caption_entities=entities, reply_markup=current_reply_markup)
            elif msg_type == "video":
                await context.bot.send_video(chat_id=chat_id, video=file_id, caption=text, caption_entities=entities, reply_markup=current_reply_markup)
            elif msg_type == "document":
                await context.bot.send_document(chat_id=chat_id, document=file_id, caption=text, caption_entities=entities, reply_markup=current_reply_markup)
            await asyncio.sleep(0.1)
        except Exception as e:
            logger.error(f"Error replaying message part for key '{key}': {e}")
            if is_last_message:

                await context.bot.send_message(chat_id=chat_id, text="An error occurred displaying content.", reply_markup=reply_markup)


async def format_price(context: ContextTypes.DEFAULT_TYPE, price: Decimal, lang: str) -> str:
    """Formats a price based on the bot's current currency setting and user's language."""
    if price is None:
        price = Decimal(0)
    price_val = Decimal(price)
    try:
        rows = db.execute_query("SELECT currency FROM managed_bots WHERE bot_token = %s", (context.bot.token,), fetch=True)
        curr_code = (rows[0]["currency"] or "MMK") if rows and rows[0] else "MMK"
    except Exception:
        curr_code = "MMK"
    number_str = f"{price_val:,.0f}"
    if lang == 'my' and curr_code == 'MMK':
        return f"{to_burmese_numerals(number_str)} \u1000\u103b\u103d\u1031\u102c\u103a"
    else:
        return f"{number_str} {curr_code}"

def escape_markdown(text: str) -> str:
    """Escapes special characters for Telegram's MarkdownV1."""
    if not isinstance(text, str):
        text = str(text)

    escape_chars = r'([*_`\[])'
    return re.sub(escape_chars, r'\\\1', text)


async def send_loading_animation(query: Update.callback_query, context: ContextTypes.DEFAULT_TYPE):
    """Shows a looping 'Please Wait...' animation by editing a message."""
    animation_frames = ["Please Wait.", "Please Wait..", "Please Wait..."]
    frame_index = 0
    try:
        while True:

            await safe_edit_caption_or_text(
                query,
                animation_frames[frame_index],
                None
            )
            frame_index = (frame_index + 1) % len(animation_frames)

            await asyncio.sleep(0.75)
    except asyncio.CancelledError:

        pass
    except Exception:

        logger.warning("Error during loading animation, but proceeding.")

async def send_processing_animation(context: ContextTypes.DEFAULT_TYPE, chat_id: int, message_id: int):
    """Shows a progressive 'Processing...' animation by editing a message, stopping at 100%."""
    animation_frames = [
        "Processing.....15%",
        "Processing......30%",
        "Processing........55%",
        "Processing..........65%",
        "Processing............70%",
        "Processing..............80%",
        "Processing.................90%",
        "Processing....................100%"
    ]
    frame_index = 0
    try:
        while True:
            await context.bot.edit_message_text(
                chat_id=chat_id,
                message_id=message_id,
                text=animation_frames[frame_index]
            )
            # Increment frame_index only if it hasn't reached the last frame
            if frame_index < len(animation_frames) - 1:
                frame_index += 1
                
            await asyncio.sleep(0.25)
    except asyncio.CancelledError:
        # This is expected when the main task is done.
        pass
    except Exception as e:
        # Log other errors but don't crash
        logger.warning(f"Error during processing animation, but proceeding: {e}")

async def error_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle errors in the telegram bot."""
    error = context.error
    logger.error(f"Exception while handling an update: {error}", exc_info=error)


    if isinstance(error, telegram.error.TimedOut):
        logger.warning("Telegram API timeout - network issue")
        return

    elif isinstance(error, telegram.error.NetworkError):
        logger.warning("Network error occurred")
        return

    elif isinstance(error, telegram.error.RetryAfter):
        logger.warning(f"Rate limited, retry after {error.retry_after} seconds")
        return

    elif isinstance(error, telegram.error.BadRequest):
        logger.warning(f"Bad request: {error}")
        if "Query is too old" in str(error):
            if update and update.callback_query:
                await update.callback_query.answer(
                    "This button has expired. Please use /start to get a new menu.",
                    show_alert=True
                )
        return

    # Ignore 'NoneType' errors to prevent loops from channel updates
    if isinstance(error, AttributeError) and "'NoneType' object has no attribute 'id'" in str(error):
        logger.warning("Ignored NoneType error from potential channel post.")
        return

    try:
        if update and update.effective_message:
            # Only reply with error message if it's a private chat to avoid spamming channels/groups
            if update.effective_chat.type == "private":
                await update.effective_message.reply_text(
                    "❌ An error occurred. Please try again or contact support if the issue persists. Please take screenshot the error and send it to this bot -> @tg_ecommerce_official_bot",
                    reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🏠 Main Menu", callback_data="main_menu")]])
                )
    except Exception as e:
        logger.error(f"Could not send error message: {e}")


