    def migrate_subscription_keys_table(self):
        """
        Ensures the subscription_keys table exists with ALL required columns.
        Safe to run on an existing DB — adds missing columns without touching existing data.
        """
        try:
            with self.connection.cursor() as cursor:
                # Create table if it doesn't exist at all
                cursor.execute("""
                    CREATE TABLE IF NOT EXISTS subscription_keys (
                        id SERIAL PRIMARY KEY,
                        key_token VARCHAR(64) UNIQUE NOT NULL,
                        plan_name VARCHAR(50) NOT NULL,
                        days INTEGER NOT NULL,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        is_used BOOLEAN DEFAULT FALSE,
                        used_by_telegram_id BIGINT,
                        used_for_bot_id INTEGER,
                        used_at TIMESTAMP
                    );
                """)

                # Ensure correct column name exists and has no NOT NULL constraint blocking inserts
                cursor.execute("ALTER TABLE subscription_keys ADD COLUMN IF NOT EXISTS created_by_telegram_id BIGINT;")
                cursor.execute("ALTER TABLE subscription_keys ALTER COLUMN created_by_telegram_id DROP NOT NULL;")
                logger.info("Migration: Ensured 'created_by_telegram_id' column exists and is nullable.")

                # Add any other potentially missing columns for safety
                for col, definition in [
                    ("used_by_telegram_id", "BIGINT"),
                    ("used_for_bot_id", "INTEGER"),
                    ("used_at", "TIMESTAMP"),
                    ("is_used", "BOOLEAN DEFAULT FALSE"),
                ]:
                    cursor.execute(f"ALTER TABLE subscription_keys ADD COLUMN IF NOT EXISTS {col} {definition};")
                    logger.info(f"Migration: Ensured '{col}' column exists in 'subscription_keys' table.")

                self.connection.commit()
        except Exception as e:
            logger.error(f"Migration failed for subscription_keys table: {e}")
            self.connection.rollback()

