    def migrate_content_blocks_for_bots(self):
        """
        Final, robust migration for content_blocks. Ensures bot_id exists,
        fixes any incorrect foreign keys, and sets the correct composite primary key.
        """
        try:
            with self.connection.cursor() as cursor:

                cursor.execute("SELECT 1 FROM information_schema.columns WHERE table_name='content_blocks' AND column_name='bot_id'")
                if not cursor.fetchone():
                    cursor.execute("ALTER TABLE content_blocks ADD COLUMN bot_id INTEGER;")
                    logger.info("Added 'bot_id' column to 'content_blocks' table.")


                cursor.execute("""
                    SELECT con.conname FROM pg_constraint con
                    JOIN pg_class confrel ON confrel.oid = con.confrelid
                    WHERE con.conrelid = 'content_blocks'::regclass AND con.contype = 'f' AND confrel.relname = 'bots'
                """)
                incorrect_fk = cursor.fetchone()
                if incorrect_fk:
                    fk_name = incorrect_fk[0]
                    logger.warning(f"Found incorrect foreign key '{fk_name}' pointing to 'bots'. Dropping it.")
                    cursor.execute(f'ALTER TABLE content_blocks DROP CONSTRAINT "{fk_name}";')


                cursor.execute("""
                    SELECT 1 FROM pg_constraint con JOIN pg_class confrel ON confrel.oid = con.confrelid
                    WHERE con.conrelid = 'content_blocks'::regclass AND con.contype = 'f' AND confrel.relname = 'managed_bots'
                """)
                if not cursor.fetchone():
                    cursor.execute("""
                        ALTER TABLE content_blocks ADD CONSTRAINT content_blocks_bot_id_fkey
                        FOREIGN KEY (bot_id) REFERENCES managed_bots(id) ON DELETE CASCADE;
                    """)
                    logger.info("Added correct foreign key from 'content_blocks' to 'managed_bots'.")


                cursor.execute("ALTER TABLE content_blocks DROP CONSTRAINT IF EXISTS content_blocks_pkey;")
                cursor.execute("ALTER TABLE content_blocks ADD PRIMARY KEY (bot_id, key);")
                logger.info("Set composite primary key on (bot_id, key) for 'content_blocks'.")

                self.connection.commit()
        except psycopg2.errors.DuplicateObject:

            logger.info("Primary key on 'content_blocks' is already correct.")
            self.connection.rollback()
        except Exception as e:
            logger.error(f"Migration failed for content_blocks: {e}")
            self.connection.rollback()

    def migrate_affiliate_program(self):
        """Creates a central affiliate_users table and referral_commissions table."""
        try:
            with self.connection.cursor() as cursor:
                # 1. Create affiliate_users if not exists
                cursor.execute("""
                    CREATE TABLE IF NOT EXISTS affiliate_users (
                        telegram_id BIGINT PRIMARY KEY,
                        username VARCHAR(100),
                        full_name VARCHAR(200),
                        referred_by_telegram_id BIGINT REFERENCES affiliate_users(telegram_id) ON DELETE SET NULL,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                    );
                """)

                # 2. Rename old USD columns to MMK if they exist (Fixes "column does not exist" error)
                cursor.execute("""
                    SELECT column_name FROM information_schema.columns 
                    WHERE table_name = 'referral_commissions' AND column_name = 'amount_usd'
                """)
                if cursor.fetchone():
                    cursor.execute("ALTER TABLE referral_commissions RENAME COLUMN amount_usd TO amount_mmk;")
                    cursor.execute("ALTER TABLE referral_commissions RENAME COLUMN commission_usd TO commission_mmk;")
                    # Also resize the columns to fit larger MMK numbers
                    cursor.execute("ALTER TABLE referral_commissions ALTER COLUMN amount_mmk TYPE NUMERIC(15,2);")
                    cursor.execute("ALTER TABLE referral_commissions ALTER COLUMN commission_mmk TYPE NUMERIC(15,2);")
                    logger.info("Migrated referral_commissions columns from USD to MMK.")

                # 2.5 Add new columns for wallet and dynamic commissions
                cursor.execute("""
                    SELECT column_name FROM information_schema.columns 
                    WHERE table_name = 'affiliate_users' AND column_name = 'commission_percent'
                """)
                if not cursor.fetchone():
                    cursor.execute("ALTER TABLE affiliate_users ADD COLUMN commission_percent INTEGER DEFAULT 10;")
                    cursor.execute("ALTER TABLE affiliate_users ADD COLUMN payment_type VARCHAR(100);")
                    cursor.execute("ALTER TABLE affiliate_users ADD COLUMN account_name VARCHAR(100);")
                    cursor.execute("ALTER TABLE affiliate_users ADD COLUMN wallet_number VARCHAR(100);")
                    logger.info("Added wallet and commission columns to affiliate_users table.")

                # 3. Create referral_commissions if not exists
                cursor.execute("""
                    CREATE TABLE IF NOT EXISTS referral_commissions (
                        id SERIAL PRIMARY KEY,
                        referrer_telegram_id BIGINT NOT NULL,
                        referred_telegram_id BIGINT NOT NULL,
                        managed_bot_id INTEGER REFERENCES managed_bots(id) ON DELETE SET NULL,
                        plan_name VARCHAR(50) NOT NULL,
                        plan_type VARCHAR(20) NOT NULL,
                        amount_mmk NUMERIC(15,2) NOT NULL,
                        commission_mmk NUMERIC(15,2) NOT NULL,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                    )
                """)

                # 4. Add is_paid column if it doesn't exist
                cursor.execute("""
                    SELECT column_name FROM information_schema.columns 
                    WHERE table_name = 'referral_commissions' AND column_name = 'is_paid'
                """)
                if not cursor.fetchone():
                    cursor.execute("ALTER TABLE referral_commissions ADD COLUMN is_paid BOOLEAN DEFAULT FALSE;")
                    logger.info("Added 'is_paid' column to referral_commissions table.")

                self.connection.commit()
        except Exception as e:
            logger.error(f"Migration failed for affiliate program: {e}")
            self.connection.rollback()

