    def migrate_constraints_to_managed_bots(self):
        """
        Checks and corrects foreign keys that point to an outdated 'bots' table
        instead of the correct 'managed_bots' table. This is for backward compatibility.
        """

        tables_to_check = ['users', 'categories', 'products', 'cart', 'promotions', 'news', 'orders']

        try:
            with self.connection.cursor() as cursor:
                for table_name in tables_to_check:

                    cursor.execute("""
                        SELECT con.conname, confrel.relname AS referenced_table
                        FROM pg_constraint con
                        JOIN pg_class rel ON rel.oid = con.conrelid
                        JOIN pg_class confrel ON confrel.oid = con.confrelid
                        JOIN pg_attribute attr ON attr.attrelid = rel.oid AND attr.attnum = ANY(con.conkey)
                        WHERE rel.relname = %s AND con.contype = 'f' AND con.conname LIKE '%%bot_id%%'
                    """, (table_name,))

                    result = cursor.fetchone()
                    if result and result[1] == 'bots':
                        constraint_name = result[0]
                        logger.warning(f"Outdated constraint '{constraint_name}' on table '{table_name}' points to 'bots'. Fixing...")


                        cursor.execute(f'ALTER TABLE public."{table_name}" DROP CONSTRAINT "{constraint_name}";')


                        cursor.execute(
                            f'ALTER TABLE public."{table_name}" ADD CONSTRAINT "{table_name}_bot_id_fkey" '
                            'FOREIGN KEY (bot_id) REFERENCES public.managed_bots(id) ON DELETE CASCADE;'
                        )
                        logger.info(f"Constraint for '{table_name}' successfully migrated to 'managed_bots'.")
            self.connection.commit()
        except Exception as e:
            logger.error(f"Automatic schema migration for foreign keys failed: {e}")
            self.connection.rollback()

