        """Ensures payment_methods table has a correct bot_id FK to managed_bots."""
        try:
            with self.connection.cursor() as cursor:

                cursor.execute("SELECT 1 FROM information_schema.columns WHERE table_name='payment_methods' AND column_name='bot_id'")
                if not cursor.fetchone():
                    cursor.execute("ALTER TABLE payment_methods ADD COLUMN bot_id INTEGER;")
                    logger.info("Added 'bot_id' column to 'payment_methods' table.")


                cursor.execute("""
                    SELECT con.conname, confrel.relname AS referenced_table
                    FROM pg_constraint con
                    JOIN pg_class rel ON rel.oid = con.conrelid
                    JOIN pg_class confrel ON confrel.oid = con.confrelid
                    JOIN pg_attribute attr ON attr.attrelid = rel.oid AND attr.attnum = ANY(con.conkey)
                    WHERE rel.relname = 'payment_methods' AND con.contype = 'f' AND attr.attname = 'bot_id'
                """)
                existing_fk = cursor.fetchone()
                if existing_fk and existing_fk['referenced_table'] != 'managed_bots':
                    fk_name = existing_fk['conname']
                    logger.warning(f"Found incorrect foreign key '{fk_name}' pointing to '{existing_fk['referenced_table']}'. Dropping and recreating.")
                    cursor.execute(f'ALTER TABLE payment_methods DROP CONSTRAINT "{fk_name}";')


                    cursor.execute("""
                        ALTER TABLE payment_methods ADD CONSTRAINT payment_methods_bot_id_fkey
                        FOREIGN KEY (bot_id) REFERENCES managed_bots(id) ON DELETE CASCADE;
                    """)
                    logger.info("Re-created correct foreign key on payment_methods.bot_id pointing to managed_bots.")


                cursor.execute("SELECT conname FROM pg_constraint WHERE conrelid = 'payment_methods'::regclass AND contype = 'u' AND conname LIKE '%name_key%'")
                constraint = cursor.fetchone()
                if constraint:
                    cursor.execute(f"ALTER TABLE payment_methods DROP CONSTRAINT {constraint[0]};")

                cursor.execute("SELECT 1 FROM pg_constraint WHERE conname = 'payment_methods_bot_id_payment_number_key'")
                if not cursor.fetchone():
                    cursor.execute("ALTER TABLE payment_methods ADD CONSTRAINT payment_methods_bot_id_payment_number_key UNIQUE (bot_id, payment_number);")

                self.connection.commit()
        except Exception as e:
            logger.error(f"Migration failed for payment_methods table: {e}")
            self.connection.rollback()

