def delete_category(category_id: int) -> bool:
    """Deletes all products within a category, then the category itself."""
    try:
        with db.connection.cursor() as cursor:

            cursor.execute(
                "DELETE FROM cart WHERE product_id IN (SELECT id FROM products WHERE category_id = %s)",
                (category_id,)
            )

            cursor.execute("DELETE FROM products WHERE category_id = %s", (category_id,))

            cursor.execute("DELETE FROM categories WHERE id = %s", (category_id,))
        db.connection.commit()
        return True
    except Exception as e:
        logger.error(f"Failed to delete category and its products: {e}")
        db.connection.rollback()
        return False

def delete_product(product_id: int) -> bool:
    """Deletes a single product by its ID after removing it from all carts."""
    try:
        with db.connection.cursor() as cursor:

            cursor.execute("DELETE FROM cart WHERE product_id = %s", (product_id,))

            cursor.execute("DELETE FROM products WHERE id = %s", (product_id,))
        db.connection.commit()
        return True
    except Exception as e:
        logger.error(f"Failed to delete product: {e}")
        db.connection.rollback()
        return False





def get_shop_statistics(bot_id: int) -> Dict[str, Any]:
    """
    Fetches comprehensive sales and user statistics for a specific bot.
    This function is designed to be called by the /statistics command handler.
    """
    stats = {
        'monthly_orders': [],
        'total_users': 0,
        'new_users_week': 0,
        'new_users_today': 0,
        'top_products_month': []
    }

    try:

        stats['monthly_orders'] = db.execute_query(
            """
            SELECT final_amount, created_at FROM orders
            WHERE bot_id = %s AND status = 'confirmed' AND created_at >= DATE_TRUNC('month', NOW())
            """,
            (bot_id,), fetch=True
        ) or []


        total_users_res = db.execute_query("SELECT COUNT(*) AS count FROM users WHERE bot_id = %s", (bot_id,), fetch=True)
        stats['total_users'] = total_users_res[0]['count'] if total_users_res else 0

        new_users_week_res = db.execute_query("SELECT COUNT(*) AS count FROM users WHERE bot_id = %s AND created_at >= DATE_TRUNC('week', NOW())", (bot_id,), fetch=True)
        stats['new_users_week'] = new_users_week_res[0]['count'] if new_users_week_res else 0

        new_users_today_res = db.execute_query("SELECT COUNT(*) AS count FROM users WHERE bot_id = %s AND created_at >= DATE_TRUNC('day', NOW())", (bot_id,), fetch=True)
        stats['new_users_today'] = new_users_today_res[0]['count'] if new_users_today_res else 0


        stats['top_products_month'] = db.execute_query(
            """
            SELECT
                item->>'name' AS product_name,
                SUM((item->>'quantity')::int) AS total_sold,
                MAX((item->>'price')::numeric) AS unit_price
            FROM
                orders,
                jsonb_array_elements(items) AS item
            WHERE
                bot_id = %s AND status = 'confirmed' AND created_at >= DATE_TRUNC('month', NOW())
            GROUP BY
                product_name
            ORDER BY
                total_sold DESC
            LIMIT 5;
            """,
            (bot_id,), fetch=True
        ) or []

    except Exception as e:
        logger.error(f"Error fetching shop statistics for bot_id {bot_id}: {e}")

    return stats


