async def get_bot_specific_text(key: str, lang: str, bot_id: int, context: ContextTypes.DEFAULT_TYPE) -> str:
    """
    Fetches a bot-specific caption from the DB, falling back to default.
    Crucially, it appends the watermark to the 'welcome_caption' for free bots
    regardless of whether the caption is custom or default.
    """
    # 1. Start with the default text from translations.
    base_caption = get_text(key, lang)

    # 2. Try to get a custom caption from the database.
    custom_caption_res = db.execute_query(
        "SELECT content_data FROM content_blocks WHERE bot_id = %s AND key = %s",
        (bot_id, key),
        fetch=True
    )
    if custom_caption_res:
        content_data = custom_caption_res[0].get('content_data', {})
        if content_data.get('source') == 'text' and 'content' in content_data:
            # If a custom caption exists, use it instead of the default.
            # Escape markdown special chars from admin input so they don't
            # break Telegram's markdown parser when /start sends the caption.
            base_caption = escape_markdown(content_data['content'])

    # 3. If the key is 'welcome_caption', check if a watermark needs to be added.
    if key == 'welcome_caption':
        plan_data = get_bot_plan_details(bot_id)
        plan_name = plan_data.get('plan_name', 'Free') if plan_data else 'Free'

        if plan_name.lower() == 'free':
            watermark = "\n\nPowered by [E-commerce Myanmar](https://t.me/tg_ecommerce_official_bot)"
            # Append the watermark to the chosen caption (custom or default).
            base_caption += watermark

    return base_caption


async def cleanup_split_media(context: ContextTypes.DEFAULT_TYPE, chat_id: int):
    """Deletes the separated media message if it exists from a previous split-view."""
    if 'split_media_msg_ids' in context.user_data:
        msg_ids = context.user_data['split_media_msg_ids']
        for msg_id in msg_ids:
            try:
                await context.bot.delete_message(chat_id=chat_id, message_id=msg_id)
            except Exception:
                pass
        context.user_data.pop('split_media_msg_ids', None)

