async def get_or_create_user(telegram_id: int, username: str, first_name: str, last_name: str = None, account_name: str = None, bot_token: str = None) -> Optional[Dict]:
    """
    Gets or creates a user for a specific bot, ensuring their admin status is always correct.
    This version centralizes admin logic for clarity and robustness.
    """
    bot_id = await get_bot_id(bot_token)
    if not bot_id:
        logger.error(f"get_or_create_user failed: could not find bot_id for token.")
        return None



    is_owner_of_this_bot = False
    bot_owner_data = db.execute_query("SELECT owner_telegram_id FROM managed_bots WHERE id = %s", (bot_id,), fetch=True)
    if bot_owner_data and bot_owner_data[0]['owner_telegram_id'] == telegram_id:
        is_owner_of_this_bot = True


    is_super_admin_on_main_bot = (telegram_id == SUPER_ADMIN_TELEGRAM_ID and bot_token == TOKEN)


    should_be_admin = is_owner_of_this_bot or is_super_admin_on_main_bot



    user_data_list = db.execute_query(
        "SELECT * FROM users WHERE telegram_id = %s AND bot_id = %s",
        (telegram_id, bot_id), fetch=True
    )
    user_data = user_data_list[0] if user_data_list else None

    if user_data:


        final_admin_status = user_data.get('is_admin') or should_be_admin


        if (user_data.get('username') != username or
            user_data.get('first_name') != first_name or
            user_data.get('last_name') != last_name or
            user_data.get('is_admin') != final_admin_status):

            db.execute_query(
                "UPDATE users SET username = %s, first_name = %s, last_name = %s, is_admin = %s, updated_at = CURRENT_TIMESTAMP WHERE id = %s",
                (username, first_name, last_name, final_admin_status, user_data['id'])
            )
    else:

        db.execute_query(
            "INSERT INTO users (bot_id, telegram_id, username, first_name, last_name, account_name, is_admin) VALUES (%s, %s, %s, %s, %s, %s, %s) ON CONFLICT (bot_id, telegram_id) DO NOTHING",
            (bot_id, telegram_id, username, first_name, last_name, account_name, should_be_admin)
        )


    final_user_data_list = db.execute_query(
        "SELECT * FROM users WHERE telegram_id = %s AND bot_id = %s",
        (telegram_id, bot_id), fetch=True
    )

    return final_user_data_list[0] if final_user_data_list else None




