async def get_bot_id(token: str) -> Optional[int]:
    """Gets the integer ID of a bot from its token, using a cache."""
    if token in BOT_ID_CACHE:
        return BOT_ID_CACHE[token]

    bot_data = db.execute_query(
        "SELECT id FROM managed_bots WHERE bot_token = %s",
        (token,),
        fetch=True
    )
    if bot_data:
        bot_id = bot_data[0]['id']
        BOT_ID_CACHE[token] = bot_id
        return bot_id
    return None


