async def grant_trial_if_eligible(owner_telegram_id: int, bot_username: str, new_bot_db_id: int) -> bool:
    """
    Grants a one-time 3-day Pro trial for a newly created bot.
    Blocked if this owner_telegram_id + bot_username combo already used a trial before
    (even if the bot was deleted and re-registered).
    Returns True if the trial was granted.
    """
    try:
        existing = db.execute_query(
            "SELECT 1 FROM bot_trial_history WHERE owner_telegram_id = %s AND LOWER(bot_username) = LOWER(%s)",
            (owner_telegram_id, bot_username), fetch=True
        )
        if existing:
            return False

        trial_expiry = datetime.datetime.now() + datetime.timedelta(days=3)
        db.execute_query(
            "UPDATE managed_bots SET plan_name = 'Pro', plan_expiry = %s, plan_start_date = NOW() WHERE id = %s",
            (trial_expiry, new_bot_db_id)
        )
        db.execute_query(
            "INSERT INTO bot_trial_history (owner_telegram_id, bot_username) VALUES (%s, %s) "
            "ON CONFLICT (owner_telegram_id, bot_username) DO NOTHING",
            (owner_telegram_id, bot_username)
        )
        return True
    except Exception as e:
        logger.error(f"grant_trial_if_eligible error for owner {owner_telegram_id}, bot @{bot_username}: {e}")
        return False

