def search_products(bot_id: int, query: str) -> List[Dict]:
    """
    Search products by name, description, or tags for a specific bot.
    """
    search_term_substring = f"%{query}%"
    search_term_startswith = f"{query}%"

    sql_query = """
        SELECT *
        FROM products
        WHERE
            (name ILIKE %s OR description ILIKE %s OR tags::text ILIKE %s)
            AND is_active = TRUE AND COALESCE(show_on_telegram, TRUE) = TRUE AND bot_id = %s
        ORDER BY
            CASE
                WHEN name ILIKE %s THEN 1  -- Exact match (case-insensitive) has highest priority
                WHEN name ILIKE %s THEN 2  -- Name starts with the search term
                WHEN name ILIKE %s THEN 3  -- Name contains the search term
                ELSE 4                   -- Description or tags contain the search term
            END,
            name ASC -- Alphabetical sort for items with the same rank
    """

    params = (
        search_term_substring,
        search_term_substring,
        search_term_substring,
        bot_id,
        query,
        search_term_startswith,
        search_term_substring
    )

    rows = db.execute_query(sql_query, params, fetch=True) or []
    if not rows:
        import unicodedata as _ud
        all_rows = db.execute_query(
            "SELECT * FROM products WHERE bot_id = %s AND is_active = TRUE AND COALESCE(show_on_telegram, TRUE) = TRUE",
            (bot_id,),
            fetch=True
        ) or []
        
        def _bot_levenshtein_distance(s1, s2):
            if len(s1) < len(s2):
                return _bot_levenshtein_distance(s2, s1)
            if len(s2) == 0:
                return len(s1)
            previous_row = range(len(s2) + 1)
            for i, c1 in enumerate(s1):
                current_row = [i + 1]
                for j, c2 in enumerate(s2):
                    insertions = previous_row[j + 1] + 1
                    deletions = current_row[j] + 1
                    substitutions = previous_row[j] + (c1 != c2)
                    current_row.append(min(insertions, deletions, substitutions))
                previous_row = current_row
            return previous_row[-1]

        norm_query = _ud.normalize("NFKC", query).lower()
        query_words = [w for w in norm_query.split() if len(w) >= 3]
        if not query_words:
            query_words = [w for w in norm_query.split() if len(w) >= 2]
            
        STOPWORDS = {"plan", "pro", "shared", "private", "premium", "service", "monthly", "month", "months", "year", "standard", "budget", "link", "invite", "free", "giveaway", "plan🎬"}
        matching = []
        for r in all_rows:
            r_name = r.get("name", "")
            r_desc = r.get("description", "") or ""
            r_tags = str(r.get("tags", "") or "")
            norm_name = _ud.normalize("NFKC", r_name).lower() if r_name else ""
            norm_desc = _ud.normalize("NFKC", r_desc).lower() if r_desc else ""
            norm_tags = _ud.normalize("NFKC", r_tags).lower() if r_tags else ""
            
            # Check for substring match first
            if norm_query in norm_name or norm_query in norm_desc or norm_query in norm_tags:
                matching.append(r)
                continue
                
            # Check word overlap and Levenshtein edit distance for typos
            if query_words:
                name_words = norm_name.split()
                matched_non_stopwords = 0
                matched_stopwords = 0
                for qw in query_words:
                    is_match = False
                    for nw in name_words:
                        if qw in nw or nw in qw:
                            is_match = True
                            break
                        max_typos = 1 if len(qw) <= 5 else 2
                        if _bot_levenshtein_distance(qw, nw) <= max_typos:
                            is_match = True
                            break
                    if is_match:
                        if qw in STOPWORDS:
                            matched_stopwords += 1
                        else:
                            matched_non_stopwords += 1
                            
                total_matches = matched_non_stopwords + matched_stopwords
                has_valid_match = False
                query_has_non_stopwords = any(qw not in STOPWORDS for qw in query_words)
                
                if query_has_non_stopwords:
                    if matched_non_stopwords >= 1:
                        has_valid_match = True
                else:
                    if total_matches >= 1:
                        has_valid_match = True
                        
                if has_valid_match:
                    match_ratio = total_matches / len(query_words)
                    if match_ratio >= 0.4:
                        matching.append(r)
                    
        matching.sort(key=lambda x: (
            0 if norm_query == (_ud.normalize("NFKC", x.get("name", "")).lower() if x.get("name") else "") else
            1 if (_ud.normalize("NFKC", x.get("name", "")).lower() if x.get("name") else "").startswith(norm_query) else
            2 if norm_query in (_ud.normalize("NFKC", x.get("name", "")).lower() if x.get("name") else "") else 3
        ))
        rows = matching
    return rows







def get_user_cart(bot_id: int, user_id: int) -> List[Dict]:
    """Retrieve all items in a user's cart for a specific bot."""
    query = """
        SELECT p.id as product_id, p.name, p.price, c.quantity, p.image_url, p.stock_quantity
        FROM cart c
        JOIN products p ON c.product_id = p.id
        WHERE c.user_id = %s AND c.bot_id = %s
        ORDER BY p.name
    """
    return db.execute_query(query, (user_id, bot_id), fetch=True)

def add_item_to_cart(bot_id: int, user_id: int, product_id: int, quantity: int):
    """Add a specified quantity of an item to the user's cart for a specific bot."""
    if quantity <= 0:
        return False
    query = """
        INSERT INTO cart (bot_id, user_id, product_id, quantity)
        VALUES (%s, %s, %s, %s)
        ON CONFLICT (bot_id, user_id, product_id)
        DO UPDATE SET quantity = cart.quantity + EXCLUDED.quantity;
    """


    return db.execute_query(query, (bot_id, user_id, product_id, quantity))

def remove_item_from_cart(bot_id: int, user_id: int, product_id: int):
    """Remove an item from the user's cart for a specific bot."""
    query = "DELETE FROM cart WHERE user_id = %s AND product_id = %s AND bot_id = %s"
    return db.execute_query(query, (user_id, product_id, bot_id))

def clear_user_cart(bot_id: int, user_id: int):
    """Clear all items from a user's cart for a specific bot."""
    query = "DELETE FROM cart WHERE user_id = %s AND bot_id = %s"
    return db.execute_query(query, (user_id, bot_id))




def create_order(bot_id: int, user_id: int, items: List[Dict], total_amount: float, discount_amount: float, payment_method: str, shipping_address: Dict, payment_proof_messages: Optional[list] = None, status: str = 'confirmed', admin_notification_messages: Optional[List[Dict]] = None, delivery_fee: float = 0) -> Optional[str]:
    """Create a new order for a specific bot."""
    order_number = f"TS{user_id}{int(datetime.datetime.now().timestamp())}"

    total_amount_float = float(total_amount)
    discount_amount_float = float(discount_amount)
    delivery_fee_float = float(delivery_fee)
    final_amount_float = total_amount_float - discount_amount_float + delivery_fee_float

    processed_items = []
    for item in items:
        processed_item = item.copy()
        if isinstance(processed_item.get('price'), Decimal):
            processed_item['price'] = float(processed_item['price'])
        processed_items.append(processed_item)

    # Build buyer snapshot — frozen at order time, never changes even if user updates profile
    buyer_snapshot = {}
    try:
        buyer_row = db.execute_query(
            "SELECT telegram_id, first_name, last_name, username, account_name, phone_number, email, shipping_address FROM users WHERE id = %s",
            (user_id,), fetch=True
        )
        if buyer_row:
            b = buyer_row[0]
            full_name = f"{b.get('first_name') or ''} {b.get('last_name') or ''}".strip()
            addr = b.get('shipping_address')
            addr_text = addr.get('text', '') if isinstance(addr, dict) else (str(addr) if addr else '')
            buyer_snapshot = {
                "telegram_id": b.get('telegram_id'),
                "full_name": full_name or b.get('account_name') or 'N/A',
                "telegram_name": full_name or b.get('first_name') or 'N/A',
                "username": f"@{b.get('username')}" if b.get('username') else 'N/A',
                "phone": b.get('phone_number') or 'N/A',
                "email": b.get('email') or 'N/A',
                "address": addr_text or 'N/A',
            }
    except Exception as e:
        logger.warning(f"Could not build buyer_snapshot for order {order_number}: {e}")

    success = db.execute_query(
        """INSERT INTO orders (bot_id, order_number, user_id, total_amount, discount_amount, delivery_fee, final_amount, payment_method, shipping_address, items, payment_proof_messages, status, admin_notification_messages, buyer_snapshot)
           VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)""",
        (bot_id, order_number, user_id, total_amount_float, discount_amount_float, delivery_fee_float, final_amount_float, payment_method, json.dumps(shipping_address), json.dumps(processed_items), json.dumps(payment_proof_messages or []), status, json.dumps(admin_notification_messages or []), json.dumps(buyer_snapshot))
    )

    if success:
        clear_user_cart(bot_id, user_id)
        return order_number

    return None

