async def update_menu_display(
    query: telegram.CallbackQuery,
    context: ContextTypes.DEFAULT_TYPE,
    caption: str,
    reply_markup: InlineKeyboardMarkup,
    photo_url: str,
):
    """
    Updates the menu display by editing the media and caption, avoiding the delete-and-send flicker.
    When caption is too long (>1024 chars), sends poster + text as two separate messages,
    and always cleans up the orphan poster from the previous navigation before sending a new one.
    """
    chat_id = query.message.chat_id

    # --- Always clean up any orphan poster left from a previous long-caption navigation ---
    orphan_photo_id = context.user_data.pop('_orphan_poster_msg_id', None)
    if orphan_photo_id:
        try:
            await context.bot.delete_message(chat_id=chat_id, message_id=orphan_photo_id)
        except Exception:
            pass  # Already deleted or not found — safe to ignore

    # Try with Markdown first, fall back to plain text if special chars break it
    for parse_mode in [ParseMode.MARKDOWN, None]:
        try:
            await query.edit_message_media(
                media=InputMediaPhoto(media=photo_url, caption=caption, parse_mode=parse_mode),
                reply_markup=reply_markup
            )
            return
        except telegram.error.BadRequest as e:
            if "message is not modified" in str(e):
                return
            elif "caption is too long" in str(e).lower():
                # Caption exceeds Telegram's 1024-char limit.
                # Send poster (no caption) + full text as a separate message below.
                # Store the poster message_id so the NEXT navigation can delete it.
                logger.warning("Caption too long — sending poster + text as two separate messages.")
                try:
                    await query.message.delete()
                except Exception:
                    pass
                try:
                    poster_msg = await context.bot.send_photo(
                        chat_id=chat_id,
                        photo=photo_url
                    )
                    # Save the poster message_id for cleanup on next navigation
                    context.user_data['_orphan_poster_msg_id'] = poster_msg.message_id
                except Exception as photo_e:
                    logger.warning(f"Could not send poster: {photo_e}")
                for pm in [ParseMode.MARKDOWN, None]:
                    try:
                        await context.bot.send_message(
                            chat_id=chat_id,
                            text=caption,
                            reply_markup=reply_markup,
                            parse_mode=pm
                        )
                        return
                    except Exception:
                        continue
                return
            elif parse_mode is not None:
                continue  # retry without parse_mode
            else:
                # Both failed — fall back to delete/send
                logger.error(f"Could not edit message media, falling back to delete/send: {e}")
                for pm in [ParseMode.MARKDOWN, None]:
                    try:
                        await query.message.delete()
                        await context.bot.send_photo(
                            chat_id=chat_id,
                            photo=photo_url,
                            caption=caption,
                            reply_markup=reply_markup,
                            parse_mode=pm
                        )
                        return
                    except Exception as send_e:
                        if "caption is too long" in str(send_e).lower():
                            # Same two-message fallback here too
                            try:
                                poster_msg = await context.bot.send_photo(
                                    chat_id=chat_id,
                                    photo=photo_url
                                )
                                context.user_data['_orphan_poster_msg_id'] = poster_msg.message_id
                            except Exception:
                                pass
                            for pm2 in [ParseMode.MARKDOWN, None]:
                                try:
                                    await context.bot.send_message(
                                        chat_id=chat_id,
                                        text=caption,
                                        reply_markup=reply_markup,
                                        parse_mode=pm2
                                    )
                                    return
                                except Exception:
                                    continue
                            return
                        continue
        except Exception as e:
            logger.error(f"Unexpected error in update_menu_display: {e}")
            return

def get_shop_status(bot_id: int) -> bool:
    # Auto-close if no payment method or COD is available
    if not _has_payment_methods(bot_id):
        _cod_res = db.execute_query(
            "SELECT content_data FROM content_blocks WHERE key='cod_settings' AND bot_id=%s",
            (bot_id,), fetch=True
        )
        _cod_enabled = False
        if _cod_res and _cod_res[0]["content_data"]:
            _cd = _cod_res[0]["content_data"]
            if isinstance(_cd, str):
                _cd = json.loads(_cd)
            if isinstance(_cd, dict):
                _cod_enabled = _cd.get("cod_enabled", False)
        if not _cod_enabled:
            return False
    res = db.execute_query("SELECT content_data FROM content_blocks WHERE key='shop_settings' AND bot_id=%s", (bot_id,), fetch=True)
    if not res or not res[0]['content_data']:
        return True
        
    settings = res[0]['content_data']
    if isinstance(settings, str):
        try:
            settings = json.loads(settings)
        except Exception:
            return True
            
    if not isinstance(settings, dict):
        return True

    if not settings.get('auto_mode', False):
        return settings.get('is_open', True)

    # If admin manually closed the shop, always respect that even in auto mode
    if not settings.get('is_open', True):
        return False

    open_str = settings.get('open_time')
    close_str = settings.get('close_time')
    if not open_str or not close_str:
        return settings.get('is_open', True)
    
    try:
        now = datetime.datetime.now(MYANMAR_TIMEZONE).time()
        fmt = "%I:%M %p"
        open_t = datetime.datetime.strptime(open_str, fmt).time()
        close_t = datetime.datetime.strptime(close_str, fmt).time()
        
        if open_t < close_t:
            return open_t <= now <= close_t
        else:
            return now >= open_t or now <= close_t
    except Exception as e:
        logger.error(f"Error parsing shop time: {e}")
        return settings.get('is_open', True)


def _has_payment_methods(bot_id: int) -> bool:
    """Returns True if the bot has at least one payment method configured."""
    result = db.execute_query(
        "SELECT COUNT(*) as c FROM payment_methods WHERE bot_id = %s",
        (bot_id,), fetch=True
    )
    return (result[0]['c'] if result else 0) > 0

async def is_user_banned(user_id: int, bot_id: int) -> bool:
    user_data = get_user_by_telegram_id(user_id, bot_id)
    return bool(user_data and user_data.get('is_support_blocked'))

async def cleanup_ai_mode(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Helper to remove stuck Reply Keyboards (AI Agent, Giveaway Draw, etc.) 
    when the user triggers a global command.
    """
    needs_keyboard_cleanup = False
    
    # 1. Check AI Agent Mode
    if context.user_data.get('in_ai_agent_mode'):
        context.user_data['in_ai_agent_mode'] = False
        context.user_data.pop('ai_chat_history', None)
        needs_keyboard_cleanup = True

    # 1b. Check AI Accountant Mode
    if context.user_data.get('in_accountant_mode'):
        context.user_data['in_accountant_mode'] = False
        context.user_data.pop('accountant_history', None)
        needs_keyboard_cleanup = True

    # 2. Check Giveaway Draw Mode
    if 'draw_gw_id' in context.user_data:
        context.user_data.pop('draw_gw_id', None)
        context.user_data.pop('temp_winner', None)
        needs_keyboard_cleanup = True

    # 3. Check Share Phone Number keyboard
    if context.user_data.pop('awaiting_phone', None):
        needs_keyboard_cleanup = True

    # 4. Check Newsfeed ReplyKeyboard
    if context.user_data.pop('newsfeed_active', None):
        context.user_data.pop('newsfeed_offset', None)
        context.user_data.pop('newsfeed_per_page', None)
        context.user_data.pop('newsfeed_sort', None)
        context.user_data.pop('newsfeed_sort_msg_id', None)
        context.user_data.pop('newsfeed_back', None)
        needs_keyboard_cleanup = True
        
    # 3. Clean up the leftover "WINNER SELECTED" inline message
    last_msg_id = context.user_data.pop('last_winner_msg_id', None)
    if last_msg_id and update.effective_chat:
        try:
            await context.bot.delete_message(chat_id=update.effective_chat.id, message_id=last_msg_id)
        except Exception:
            pass
            
    # 4. Remove the Reply Keyboard if needed
    if needs_keyboard_cleanup and update.effective_chat:
        try:
            msg = await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text="🔄 ...", 
                reply_markup=ReplyKeyboardRemove()
            )
            await context.bot.delete_message(chat_id=update.effective_chat.id, message_id=msg.message_id)
        except Exception:
            pass

async def start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Send welcome message and main menu, handling both /start and button presses consistently."""
    if await _is_stale_command(update, context):
        return
    # --- SAFETY RESET START ---
    # 1. Force remove stuck keyboards (FAQ, AI, etc)
    await cleanup_ai_mode(update, context)
    
    # 2. Force exit 'Create Bot' Mode
    # This ensures the user is no longer "silenced" and their messages will forward to admins again.
    context.user_data['is_creating_bot'] = False
    # --- SAFETY RESET END ---

    user = update.effective_user
    user_data = await get_or_create_user(user.id, user.username, user.first_name, user.last_name, user.username, context.bot.token)


    bot_id = await get_bot_id(context.bot.token)

    

    maintenance_setting = db.execute_query(
        "SELECT value FROM global_settings WHERE key = 'maintenance_mode'",
        fetch=True
    )

    is_maintenance = maintenance_setting and maintenance_setting[0]['value'] == 'true'
    context.bot_data['maintenance_mode'] = is_maintenance


    if user_data and user_data.get('language'):
        context.user_data['language'] = user_data.get('language')
    lang = await get_user_lang(context)


    try:

        await get_or_create_affiliate_user(user.id, user.username, user.full_name)


        if update.message and update.message.text and update.message.text.startswith('/start'):
            parts = update.message.text.split(' ', 1)
            if len(parts) > 1:
                payload = parts[1].strip()

                # Handle token-based product deep links — check DB first before any prefix logic
                # This must run before all other payload checks to avoid false exclusions
                if len(payload) >= 8 and len(payload) <= 64 and payload.replace('_', '').replace('-', '').isalnum():
                    token_row = db.execute_query(
                        "SELECT id FROM products WHERE link_token = %s AND bot_id = %s AND is_active = TRUE",
                        (payload, bot_id), fetch=True
                    )
                    if token_row:
                        return await show_product_detail(update, context, product_id=token_row[0]['id'])

                # Handle Telegram Login flow (login-{uuid})
                if payload.startswith("login-"):
                    token = payload[6:]
                    if not re.match(r"^[a-f0-9\-]{36}$", token):
                        await update.message.reply_text("Invalid login link.")
                        return
                    existing = db.execute_query(
                        "SELECT status, telegram_name FROM pending_logins WHERE token=%s",
                        (token,), fetch=True
                    )
                    if existing:
                        row = existing[0]
                        status = row["status"]
                        name = row["telegram_name"] or user.first_name or "User"
                        if status == "pending":
                            keyboard = InlineKeyboardMarkup([
                                [InlineKeyboardButton("Confirm Login", callback_data=f"login_confirm_{token}"),
                                 InlineKeyboardButton("Decline", callback_data=f"login_decline_{token}")]
                            ])
                            await update.message.reply_text(
                                f"Login Request\n\nHey {name}, do you want to log in to the shop?\n\nThis will allow you to manage your orders and profile.",
                                reply_markup=keyboard
                            )
                        elif status == "confirmed":
                            await update.message.reply_text("You are already logged in! Close this chat and go back to the shop.")
                        else:
                            db.execute_query("UPDATE pending_logins SET status='pending' WHERE token=%s", (token,))
                            keyboard = InlineKeyboardMarkup([
                                [InlineKeyboardButton("Confirm Login", callback_data=f"login_confirm_{token}"),
                                 InlineKeyboardButton("Decline", callback_data=f"login_decline_{token}")]
                            ])
                            await update.message.reply_text(
                                f"Login Request\n\nHey {name}, do you want to log in again?\n\nThis will allow you to manage your orders and profile.",
                                reply_markup=keyboard
                            )
                    else:
                        name = user.full_name or user.first_name or "User"
                        db.execute_query(
                            "INSERT INTO pending_logins (token, bot_id, chat_id, telegram_user_id, telegram_name, telegram_username, status) VALUES (%s,%s,%s,%s,%s,%s,'pending')",
                            (token, bot_id, update.effective_chat.id, user.id, name, user.username or "")
                        )
                        keyboard = InlineKeyboardMarkup([
                            [InlineKeyboardButton("Confirm Login", callback_data=f"login_confirm_{token}"),
                             InlineKeyboardButton("Decline", callback_data=f"login_decline_{token}")]
                        ])
                        await update.message.reply_text(
                            f"Login Request\n\nHey {name}, do you want to log in to the shop?\n\nThis will allow you to manage your orders and profile.",
                            reply_markup=keyboard
                        )
                    return

                # Handle legacy numeric Product Deep Link (prod_NNNN with offset 1997)
                if payload.startswith('prod_'):
                    try:
                        product_id = int(payload[5:]) - 1997
                        if product_id > 0:
                            return await show_product_detail(update, context, product_id=product_id)
                    except (ValueError, IndexError):
                        pass  # Fallback to main menu if ID is invalid

                # Handle AI Deep Link
                if payload == 'ai':
                    # Verify permissions before entering AI mode
                    plan_name = get_bot_plan_details(bot_id).get('plan_name', 'Free').lower()
                    if plan_name not in ['free', 'basic']:
                        ai_settings = db.execute_query("SELECT is_enabled FROM bot_ai_settings WHERE bot_id = %s", (bot_id,), fetch=True)
                        if ai_settings and ai_settings[0]['is_enabled']:
                            return await enter_ai_agent_mode(update, context)

                # Handle Direct Links
                if payload == 'promo':
                    return await handle_promotions(update, context)
                if payload.startswith('gwref_'):
                    try:
                        # Format: gwref_{giveaway_id}_{referrer_id}
                        parts = payload.split('_')
                        giveaway_id = int(parts[1])
                        referrer_id = int(parts[2])
                        
                        # Check if giveaway is active
                        gw = db.execute_query("SELECT id FROM giveaways WHERE id = %s AND is_active = TRUE AND bot_id = %s", (giveaway_id, bot_id), fetch=True)
                        if gw and referrer_id != user.id:
                            # Check if user already joined
                            already_joined = db.execute_query("SELECT id FROM giveaway_participants WHERE giveaway_id = %s AND telegram_id = %s", (giveaway_id, user.id), fetch=True)
                            if not already_joined:
                                # Add new user with 1 ticket
                                db.execute_query("INSERT INTO giveaway_participants (bot_id, giveaway_id, telegram_id, referred_by) VALUES (%s, %s, %s, %s)", (bot_id, giveaway_id, user.id, referrer_id))
                                # Give referrer +1 ticket
                                db.execute_query("UPDATE giveaway_participants SET tickets = tickets + 1 WHERE giveaway_id = %s AND telegram_id = %s", (giveaway_id, referrer_id))
                                
                                try:
                                    await context.bot.send_message(
                                        chat_id=referrer_id, 
                                        text="🎉 Someone joined the giveaway using your link! You earned +1 Ticket 🎟️"
                                    )
                                except Exception:
                                    pass
                                
                                # Show the full giveaway post with referral share button
                                gw_full = db.execute_query("SELECT * FROM giveaways WHERE id = %s", (giveaway_id,), fetch=True)
                                if gw_full:
                                    gw_data = gw_full[0]
                                    messages_to_send = gw_data['content_data'].get('messages', [])
                                    bot_username = context.bot.username or (await context.bot.get_me()).username
                                    ref_link = f"https://t.me/{bot_username}?start=gwref_{giveaway_id}_{user.id}"
                                    participant_row = db.execute_query(
                                        "SELECT tickets FROM giveaway_participants WHERE giveaway_id = %s AND telegram_id = %s",
                                        (giveaway_id, user.id), fetch=True
                                    )
                                    tickets = participant_row[0]['tickets'] if participant_row else 1
                                    reply_markup = InlineKeyboardMarkup([
                                        [InlineKeyboardButton("🔗 Share to get more tickets!", url=f"https://t.me/share/url?url={ref_link}&text=Join this awesome giveaway!")],
                                        [InlineKeyboardButton("🔙 Back to Giveaways", callback_data="user_giveaways_list")]
                                    ])
                                    chat_id = update.message.chat_id
                                    total = len(messages_to_send)
                                    for i, msg_data in enumerate(messages_to_send):
                                        is_last = (i == total - 1)
                                        markup = reply_markup if is_last else None
                                        msg_type = msg_data.get("type")
                                        text = msg_data.get("text") or msg_data.get("caption", "")
                                        entities = msg_data.get("entities")
                                        file_id = msg_data.get("file_id")
                                        if is_last:
                                            text += f"\n\n✅ You are in!\n🎟️ *Your Tickets:* {tickets}\n🔗 *Referral Link:* `{ref_link}`"
                                        try:
                                            if msg_type == "text":
                                                await context.bot.send_message(chat_id=chat_id, text=text, entities=entities, reply_markup=markup, parse_mode=ParseMode.MARKDOWN)
                                            elif msg_type == "photo":
                                                await context.bot.send_photo(chat_id=chat_id, photo=file_id, caption=text, caption_entities=entities, reply_markup=markup, parse_mode=ParseMode.MARKDOWN)
                                            elif msg_type == "video":
                                                await context.bot.send_video(chat_id=chat_id, video=file_id, caption=text, caption_entities=entities, reply_markup=markup)
                                            elif msg_type == "document":
                                                await context.bot.send_document(chat_id=chat_id, document=file_id, caption=text, caption_entities=entities, reply_markup=markup)
                                            await asyncio.sleep(0.1)
                                        except Exception as e:
                                            logger.error(f"Error showing giveaway post after referral join: {e}")
                                else:
                                    await update.message.reply_text("🎉 You have successfully joined the giveaway and received 1 Ticket!")
                    except Exception as e:
                        logger.error(f"Giveaway referral error: {e}")
                if payload == 'news':
                    return await handle_news(update, context)
                if payload == 'setting':
                    return await handle_settings(update, context)
                if payload == 'shop':
                    return await browse_categories(update, context)
                if payload in ['newbot', 'create_bot']:
                    return await handle_create_your_bot(update, context)

                # Handle Subscription Key redemption deep link
                if payload.startswith('subkey_'):
                    return await handle_subkey_deeplink(update, context, payload)

                if payload.startswith('ref_'):
                    try:
                        referrer_id = int(payload[4:])


                        if referrer_id != user.id:

                            new_user_affiliate_data = db.execute_query(
                                "SELECT referred_by_telegram_id FROM affiliate_users WHERE telegram_id = %s",
                                (user.id,), fetch=True
                            )
                            is_new_referral = (new_user_affiliate_data and new_user_affiliate_data[0]['referred_by_telegram_id'] is None)


                            if is_new_referral:
                                db.execute_query(
                                    "UPDATE affiliate_users SET referred_by_telegram_id = %s WHERE telegram_id = %s",
                                    (referrer_id, user.id)
                                )

                                try:
                                    new_user_name = escape_markdown(user.full_name or "A new user")
                                    notification_text = f'🎉 "{new_user_name}" joined the bot via your referral link. You will be earned if the user upgrade.'
                                    await context.bot.send_message(
                                        chat_id=referrer_id,
                                        text=notification_text,
                                        parse_mode=ParseMode.MARKDOWN
                                    )
                                except Exception as e:
                                    logger.error(f"Failed to send referral notification to {referrer_id}: {e}")
                    except (ValueError, IndexError):
                        logger.warning(f"Invalid referral payload received: {payload}")
    except Exception as e:
        logger.error(f"Affiliate init error: {e}")


    if user_data and user_data.get('is_admin'):
        admin_commands = [
            BotCommand("start", "Main Menu"),
            BotCommand("shopping", "Go Shopping"),
            BotCommand("admin", "Admin Panel"),
            BotCommand("product", "Add New Product")
        ]
        await context.bot.set_my_commands(admin_commands, scope=BotCommandScopeChat(chat_id=user.id))
    else:
        try:
            user_commands = [
                BotCommand("start", "Main Menu"),
                BotCommand("shopping", "Go Shopping"),
                BotCommand("share", "Get your referral link")
            ]
            await context.bot.set_my_commands(user_commands, scope=BotCommandScopeChat(chat_id=user.id))
        except Exception:
            pass

    if not user_data:

        error_message = "❌ Sorry, we encountered an error setting up your account. Please try again later."
        if update.message:
            await update.message.reply_text(error_message)
        elif update.callback_query:
            await update.callback_query.message.reply_text(error_message)
        return ConversationHandler.END


    keyboard = []
    is_maintenance_mode = context.bot_data.get('maintenance_mode', False)


    if not is_maintenance_mode:
        website_data = db.execute_query(
            "SELECT content_data FROM content_blocks WHERE bot_id = %s AND key = 'website_link'", 
            (bot_id,), fetch=True
        )
        # Use custom URL if set, otherwise always fall back to default TeleShop website
        DEFAULT_WEBSITE_URL = "https://telegramecommerce.shop/"
        website_url = website_data[0]['content_data'].get('url') if website_data and website_data[0]['content_data'] else None
        web_button = InlineKeyboardButton("🌐 Website", web_app=WebAppInfo(url=website_url or DEFAULT_WEBSITE_URL))

        is_open = get_shop_status(bot_id)

        if is_open:
            keyboard.append([
                InlineKeyboardButton(get_text('shopping_button', lang), callback_data="browse"),
                InlineKeyboardButton("🔥 Deals", callback_data="updates_menu")
            ])
            search_row = [InlineKeyboardButton(get_text('search_button', lang), callback_data="search")]
            if web_button:
                search_row.append(web_button)
            keyboard.append(search_row)
            keyboard.append([
                InlineKeyboardButton("📦 Cart & Orders", callback_data="order_management"),
                InlineKeyboardButton("📱 Newsfeed", callback_data="newsfeed")
            ])
        else:
            if web_button:
                keyboard.append([web_button])

        keyboard.append([
            InlineKeyboardButton(get_text('profile_button', lang), callback_data="profile"), 
            InlineKeyboardButton(get_text('settings_button', lang), callback_data="settings")
        ])
    else:

        keyboard.append([InlineKeyboardButton(get_text('profile_button', lang), callback_data="profile")])


    keyboard.extend([
        [InlineKeyboardButton(get_text('support_button', lang), callback_data="support"), InlineKeyboardButton(get_text('about_button', lang), callback_data="about")]
    ])

    # --- AI Agent Button Logic ---
    if not is_maintenance_mode:
        plan_limits = await get_bot_plan_and_limits(bot_id)
        # Check if plan is Standard or higher (Standard, Pro, Business)
        # Free and Basic do not get AI Agent.
        plan_name = get_bot_plan_details(bot_id).get('plan_name', 'Free').lower()
        
        if plan_name not in ['free', 'basic'] and _has_payment_methods(bot_id):
            # Check if AI is enabled in DB
            ai_settings = db.execute_query("SELECT is_enabled FROM bot_ai_settings WHERE bot_id = %s", (bot_id,), fetch=True)
            if ai_settings and ai_settings[0]['is_enabled']:
                keyboard.append([InlineKeyboardButton("🗨️ Talk to AI Agent", callback_data="enter_ai_agent_mode")])
    # -----------------------------


    if not is_maintenance_mode:
        if context.bot.token == TOKEN2:
            keyboard.append([
                InlineKeyboardButton(
                    get_text('create_your_bot_button', lang),
                    url="https://t.me/tg_ecommerce_official_bot?start=newbot"
                )
            ])
        elif context.bot.token in MAIN_BOT_TOKENS:
            keyboard.append([
                InlineKeyboardButton(get_text('create_your_bot_button', lang), callback_data="create_your_bot")
            ])
            # Affiliate button removed from here as requested


    if user_data.get('is_admin'):
        if not is_maintenance_mode:
            # Group Admin Panels into one menu
            keyboard.append([
                InlineKeyboardButton("👑 Admin Panel", callback_data="shop_management")
            ])

        # Check Plan status
        plan_data = get_bot_plan_details(bot_id)
        current_plan = plan_data.get('plan_name', 'Free') if plan_data else 'Free'

        # Web Panel button — only for Standard, Pro, Business plans
        if current_plan.lower() in ('standard', 'pro', 'business'):
            keyboard.append([
                InlineKeyboardButton("🌐 Web Panel", url="https://www.telegramecommerce.shop/login")
            ])

        # Only show Upgrade in Main Menu if the plan is FREE
        if current_plan.lower() == 'free':
            keyboard.append([InlineKeyboardButton(get_text('upgrade_plan_button', lang), callback_data="upgrade_plan")])


    if is_maintenance_mode and user_data.get('telegram_id') == SUPER_ADMIN_TELEGRAM_ID and context.bot.token == TOKEN:
        maintenance_text = "🛠️ Global Maintenance: ON (Click to Disable)"
        keyboard.append([InlineKeyboardButton(maintenance_text, callback_data="toggle_global_maintenance")])
    reply_markup = InlineKeyboardMarkup(keyboard)

    welcome_caption = await get_bot_specific_text('welcome_caption', lang, bot_id, context)

    # Append closed notice if shop is closed or has no payment methods
    if not is_maintenance_mode:
        if not _has_payment_methods(bot_id) or not get_shop_status(bot_id):
            welcome_caption += "\n\n***🔒 The Shop is currently closed.***"

    welcome_photo_url = get_poster_file_id(bot_id, "welcome_poster", "https://i.postimg.cc/NGbB2g4Y/New-Project-25-80-CAA9-F.png")


    if update.callback_query:

        await update_menu_display(
            query=update.callback_query,
            context=context,
            caption=welcome_caption,
            reply_markup=reply_markup,
            photo_url=welcome_photo_url
        )
    else:

        await update.message.reply_photo(
            photo=welcome_photo_url,
            caption=welcome_caption,
            reply_markup=reply_markup,
            parse_mode=ParseMode.MARKDOWN
        )

        # --- Payment Setup Reminder for Admins ---
        # Only send when triggered by a real /start command (not a button),
        # only to admins, and only if they have NOT set a payment method yet.
        if user_data.get('is_admin') and not _has_payment_methods(bot_id):
            _username = context.bot.username or (await context.bot.get_me()).username
            _last5 = str(bot_id).zfill(5)[-5:]
            _pay_url = f"https://tg.telegramecommerce.shop/add-payment?u={_username}&c={_last5}&s1=1998830&s2=149577"
            await update.message.reply_text(
                "⚠️ Admin Panel အသုံးပြုရန်နှင့်\n"
                "ဝယ်ယူသူများထံမှ ငွေလက်ခံနိုင်ရန်အတွက်\n"
                "သင်၏ကိုယ်ပိုင် Payment Method တစ်ခု\n"
                "အရင်ဖြည့်သွင်းပေးပါ။\n\n"
                "Website တွင် အသုံးပြုရန် 👇\n crossmart.shop",
                reply_markup=InlineKeyboardMarkup([
                    [InlineKeyboardButton("➕ Add Payment", web_app=WebAppInfo(url=_pay_url))]
                ])
            )
            
        # --- End Reminder ---

    return State.MAIN_MENU



async def get_ai_link_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Generates a deep link to instantly wake up the AI Agent."""
    # Ensure AI keyboard is removed if command is used in AI mode
    await cleanup_ai_mode(update, context)
    
    bot_username = context.bot.username
    if not bot_username:
        try:
            me = await context.bot.get_me()
            bot_username = me.username
        except:
            await update.message.reply_text("❌ Could not determine bot username.")
            return

    link = f"https://t.me/{bot_username}?start=ai"
    
    await update.message.reply_text(
        f"🗨️ *Talk to AI Agent Link*\n\nShare this link to let users jump straight into AI mode:\n`{link}`",
        parse_mode=ParseMode.MARKDOWN
    )

