async def admin_command_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handles the /admin command shortcut for admins."""
    if await _is_stale_command(update, context):
        return
    # Ensure AI keyboard is removed if command is used in AI mode
    await cleanup_ai_mode(update, context)

    user = update.effective_user
    user_data = await get_or_create_user(user.id, user.username, user.first_name, user.last_name, user.username, context.bot.token)

    if not user_data or not user_data.get('is_admin'):
        await update.message.reply_text("❌ This command is for admins only.")
        return

    is_super_admin = user_data.get('telegram_id') == SUPER_ADMIN_TELEGRAM_ID and context.bot.token == TOKEN

    _username = context.bot.username or (await context.bot.get_me()).username
    bot_id = await get_bot_id(context.bot.token)
    _last5 = str(bot_id).zfill(5)[-5:]
    _prod_url = f"https://tg.telegramecommerce.shop/add-product?u={_username}&c={_last5}&s1=1998830&s2=149577"

    plan_name = (get_bot_plan_details(bot_id) or {}).get('plan_name', 'Free').lower()
    _show_web_panel = plan_name in ('standard', 'pro', 'business')

    keyboard = [
        [InlineKeyboardButton("🎨 Customize", callback_data="admin_panel")],
        [InlineKeyboardButton("🧩 Product Management", callback_data="admin_panel_2")],
    ]
    _wp_url = f"https://www.telegramecommerce.shop/manage-web-panel?bot_id={bot_id}&chat_id={user.id}&username={context.bot.username}"
    if _show_web_panel:
        keyboard.append([InlineKeyboardButton("🌐 Manage Web Login", web_app=WebAppInfo(url=_wp_url))])
    keyboard.extend([
        [InlineKeyboardButton("➕ Add New Product", web_app=WebAppInfo(url=_prod_url))],
        [InlineKeyboardButton("🤖 AI Assistant Admin Panel", callback_data="ai_admin_panel")],
    ])
    if is_super_admin:
        keyboard.append([InlineKeyboardButton("🔐 Super Admin Panel", callback_data="super_admin_panel")])
    keyboard.append([InlineKeyboardButton("🏠 Main Menu", callback_data="main_menu")])
    reply_markup = InlineKeyboardMarkup(keyboard)
    await update.message.reply_text(
        "👑 *Admin Quick Access*\n\nSelect a panel to manage your shop:",
        reply_markup=reply_markup,
        parse_mode=ParseMode.MARKDOWN
    )
    return State.MAIN_MENU


