async def browse_categories(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show product categories with a photo, respecting plan limits. Handles both command and callback."""
    query = update.callback_query
    
    # Handle cleaning up split media safely
    chat_id = update.effective_chat.id
    await cleanup_split_media(context, chat_id)

    # Remove any stuck reply keyboards (like FAQ or AI mode) if triggered via command
    if not query:
        await cleanup_ai_mode(update, context)
    
    lang = await get_user_lang(context)

    bot_id = await get_bot_id(context.bot.token)
    if not bot_id:
        if query:
            await query.answer("Error: This bot is not registered correctly.", show_alert=True)
        else:
            await update.message.reply_text("Error: This bot is not registered correctly.")
        return State.MAIN_MENU

    if await is_user_banned(update.effective_user.id, bot_id):
        if query: await query.answer("You have been banned from using this feature, Contact the admin", show_alert=True)
        else: await update.message.reply_text("You have been banned from using this feature, Contact the admin")
        return State.MAIN_MENU

    if not _has_payment_methods(bot_id):
        is_admin = (await get_or_create_user(update.effective_user.id, update.effective_user.username, update.effective_user.first_name, update.effective_user.last_name, update.effective_user.username, context.bot.token) or {}).get('is_admin')
        msg = "⚠️ Add at least one payment method to open the shop.\n\n-Go to Admin Panel\n-Click 🎨 Customize\n-Add your own payment method." if is_admin else "🚫 The shop is currently closed."
        if query: await query.answer(msg, show_alert=True)
        else: await update.message.reply_text(msg)
        return State.MAIN_MENU

    if not get_shop_status(bot_id):
        if query: await query.answer("🚫 The shop is currently closed. Please come back later!", show_alert=True)
        else: await update.message.reply_text("🚫 The shop is currently closed.")
        return State.MAIN_MENU

    if query:
        await query.answer()

    # 1. Fetch Categories

    # 1. Fetch Categories
    categories = get_categories(bot_id)

    # 2. Apply Plan Limits (Hidden Data Logic)
    plan_limits = await get_bot_plan_and_limits(bot_id)
    cat_limit = plan_limits.get('categories', 1)

    # Slice the list if the limit is not infinite
    if cat_limit != float('inf'):
        categories = categories[:int(cat_limit)]

    # 3. Build Keyboard
    keyboard = []
    if categories:
        row = []
        for i, category in enumerate(categories):
            row.append(InlineKeyboardButton(
                f"{category['emoji'] or '📦'} {category['name']}",
                callback_data=f"category_{category['id']}"
            ))
            if (i + 1) % 2 == 0:
                keyboard.append(row)
                row = []
        if row:
            keyboard.append(row)

    # Add Promos button if allowed
    if plan_limits['promotions_button']:
        keyboard.append([InlineKeyboardButton(get_text('promotions_button', lang), callback_data="promotions")])
    keyboard.append([InlineKeyboardButton(get_text('main_menu_button', lang), callback_data="main_menu")])

    reply_markup = InlineKeyboardMarkup(keyboard)
    caption = await get_bot_specific_text('browse_categories_caption', lang, bot_id, context)
    photo_url = get_poster_file_id(
        bot_id, "shopping_poster",
        "https://i.postimg.cc/Y0YX7mPH/IMG-20260309-200910-001.jpg"
    )

    if query:
        await update_menu_display(
            query=query,
            context=context,
            caption=caption,
            reply_markup=reply_markup,
            photo_url=photo_url
        )
    else:
        # Triggered via /shopping command
        await context.bot.send_photo(
            chat_id=chat_id,
            photo=photo_url,
            caption=caption,
            reply_markup=reply_markup,
            parse_mode=ParseMode.MARKDOWN
        )

    return State.BROWSE_CATEGORIES

async def show_category_products(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show a list of products in a specific category, respecting plan limits."""
    query = update.callback_query
    await cleanup_split_media(context, query.message.chat_id) # Cleanup split media
    await query.answer()
    lang = await get_user_lang(context)

    try:
        category_id = int(query.data.split("_")[1])
    except (IndexError, ValueError):
        await query.edit_message_caption(
            caption="❌ Invalid category selection.",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(get_text('back_to_categories_button', lang), callback_data="browse")]])
        )
        return State.BROWSE_CATEGORIES

    bot_id = await get_bot_id(context.bot.token)
    if not bot_id:
        await query.answer("Error: This bot is not registered correctly.", show_alert=True)
        return State.BROWSE_CATEGORIES

    # --- 1. Check if Category is Allowed (Visible) ---
    all_categories = get_categories(bot_id) # Fetches sorted by name
    plan_limits = await get_bot_plan_and_limits(bot_id)
    cat_limit = plan_limits.get('categories', 1)

    allowed_category_ids = []
    if cat_limit != float('inf'):
        # Only the first N categories are "Active/Visible"
        visible_cats = all_categories[:int(cat_limit)]
        allowed_category_ids = [c['id'] for c in visible_cats]
    else:
        allowed_category_ids = [c['id'] for c in all_categories]

    if category_id not in allowed_category_ids:
        # If user tries to access a hidden category (e.g. via old link)
        await query.edit_message_caption(
            caption="🔒 *Content Hidden*\n\nThis category is currently hidden due to the shop's plan limits.",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(get_text('back_to_categories_button', lang), callback_data="browse")]])
        )
        return State.BROWSE_CATEGORIES

    # --- 2. Fetch and Limit Products ---
    category_result = db.execute_query("SELECT name FROM categories WHERE id = %s", (category_id,), fetch=True)
    category_name = category_result[0]['name'] if category_result else "Unknown"

    products = get_products_by_category(bot_id, category_id)
    
    # Apply Product Limit (Slice the list)
    prod_limit = plan_limits.get('products', 5)
    if prod_limit != float('inf'):
        products = products[:int(prod_limit)]

    if not products:
        no_product_caption = get_text('no_products_in_category', lang).format(category_name=category_name)
        await query.edit_message_caption(
            caption=no_product_caption,
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(get_text('back_to_categories_button', lang), callback_data="browse")]])
        )
        return State.BROWSE_CATEGORIES

    caption = get_text('products_in_category_caption', lang).format(category_name=category_name)
    keyboard = []
    for product in products:
        keyboard.append([InlineKeyboardButton(product['name'], callback_data=f"product_{product['id']}")])

    keyboard.append([InlineKeyboardButton(get_text('back_to_categories_button', lang), callback_data="browse")])
    reply_markup = InlineKeyboardMarkup(keyboard)

    await safe_edit_caption_or_text(query, caption, reply_markup)

    return State.BROWSE_CATEGORIES

def to_burmese_numerals(number_string: str) -> str:
    """Converts a string of Arabic numerals to Burmese numerals."""
    burmese_digits = "၀၁၂၃၄၅၆၇၈၉"
    arabic_digits = "0123456789"
    translation_table = str.maketrans(arabic_digits, burmese_digits)
    return number_string.translate(translation_table)


def get_missing_variant_requirements(product, user_data):
    """Returns list of missing required variant selections, or empty list if valid."""
    specs = (product.get('specifications') or {}) if product else {}
    colors = specs.get('colors') or []
    options = specs.get('options') or []
    if not colors and not options:
        return []
    
    selections = user_data.get('variant_selections', {}).get(product['id'], {})
    missing = []
    if colors and not selections.get('color'):
        missing.append('Color')
    for opt in options:
        opt_name = opt.get('name', 'Option')
        if not selections.get('options', {}).get(opt_name):
            missing.append(opt_name)
    return missing

def get_variant_label(product, user_data):
    """Returns formatted variant string e.g. (Color: Red, Size: M) or empty string."""
    specs = (product.get('specifications') or {}) if product else {}
    colors = specs.get('colors') or []
    options = specs.get('options') or []
    if not colors and not options:
        return ""
    selections = user_data.get('variant_selections', {}).get(product['id'], {})
    parts = []
    if colors and selections.get('color'):
        c_val = get_color_display_name(selections['color'])
        parts.append(f"Color: {c_val}")
    for opt in options:
        opt_name = opt.get('name', 'Option')
        val = selections.get('options', {}).get(opt_name)
        if val:
            parts.append(f"{opt_name}: {val}")
    if parts:
        return f" ({', '.join(parts)})"
    return ""

HEX_COLOR_NAMES = {
    '#FF0000': 'Red', '#8B0000': 'Dark Red', '#DC143C': 'Crimson', '#800000': 'Maroon',
    '#FF4500': 'Orange Red', '#FF6347': 'Tomato', '#FF7F50': 'Coral', '#FFA500': 'Orange',
    '#FF8C00': 'Dark Orange', '#FFBF00': 'Amber', '#FFD700': 'Yellow', '#FFC107': 'Gold',
    '#DAA520': 'Goldenrod', '#FFF44F': 'Lemon', '#00FF00': 'Lime', '#32CD32': 'Lime Green',
    '#008000': 'Green', '#228B22': 'Forest Green', '#006400': 'Dark Green', '#808000': 'Olive',
    '#008080': 'Teal', '#00CED1': 'Cyan', '#87CEEB': 'Sky Blue', '#ADD8E6': 'Light Blue',
    '#0000FF': 'Blue', '#4169E1': 'Royal Blue', '#000080': 'Navy', '#4B0082': 'Indigo',
    '#800080': 'Purple', '#8A2BE2': 'Violet', '#E6E6FA': 'Lavender', '#FF00FF': 'Magenta',
    '#FFC0CB': 'Pink', '#FF69B4': 'Hot Pink', '#FF1493': 'Deep Pink', '#DDA0DD': 'Plum',
    '#DA70D6': 'Orchid', '#A52A2A': 'Brown', '#8B4513': 'Saddle Brown', '#A0522D': 'Sienna',
    '#D2691E': 'Chocolate', '#F5F5DC': 'Beige', '#D2B48C': 'Tan', '#FFFFFF': 'White',
    '#FFFFF0': 'Ivory', '#808080': 'Gray', '#C0C0C0': 'Silver', '#36454F': 'Charcoal',
    '#98FF98': 'Mint', '#000000': 'Black'
}

def get_color_display_name(c):
    if isinstance(c, str):
        if c.startswith('#') and c.upper() in HEX_COLOR_NAMES:
            return HEX_COLOR_NAMES[c.upper()]
        return c
    if isinstance(c, dict):
        if c.get('name'):
            return c['name']
        if c.get('label'):
            return c['label']
        hex_val = (c.get('color') or c.get('hex') or '').upper()
        if hex_val and hex_val in HEX_COLOR_NAMES:
            return HEX_COLOR_NAMES[hex_val]
        if hex_val:
            return hex_val
    return str(c)

def build_product_variant_keyboard(product, context, lang, extra_bottom_rows=None):
    """Builds product inline keyboard with accordion for Colors and Options."""
    pid = product['id']
    specs = product.get('specifications') or {}
    colors = specs.get('colors') or []
    options = specs.get('options') or []
    stock = product.get('stock_quantity')
    is_out_of_stock = stock is not None and stock == 0

    current_product_key = f"qty_{pid}"
    quantity = context.user_data.get(current_product_key, 0)

    user_selections = context.user_data.setdefault('variant_selections', {}).setdefault(pid, {})
    expanded_section = context.user_data.setdefault('variant_expanded', {}).get(pid, None)

    keyboard = []

    # 1. Colors Accordion Row
    if colors and not is_out_of_stock:
        selected_color = user_selections.get('color')
        color_label = f"🎨 Color: {selected_color}" if selected_color else "🎨 Color"
        keyboard.append([InlineKeyboardButton(color_label, callback_data=f"toggle_variant_color_{pid}")])

        if expanded_section == 'color':
            color_rows = []
            row = []
            for c in colors:
                c_name = get_color_display_name(c)
                is_sel = (selected_color == c_name)
                btn_text = f"☑ {c_name}" if is_sel else c_name
                row.append(InlineKeyboardButton(btn_text, callback_data=f"select_variant_color_{pid}_{c_name}"))
                if len(row) == 3:
                    color_rows.append(row)
                    row = []
            if row:
                color_rows.append(row)
            keyboard.extend(color_rows)

    # 2. Options Accordion Rows
    if options and not is_out_of_stock:
        for idx, opt in enumerate(options):
            opt_name = opt.get('name', f'Option {idx+1}')
            opt_values = opt.get('values') or []
            selected_val = user_selections.get('options', {}).get(opt_name)
            opt_label = f"📦 {opt_name}: {selected_val}" if selected_val else f"📦 {opt_name}"
            keyboard.append([InlineKeyboardButton(opt_label, callback_data=f"toggle_variant_opt_{pid}_{idx}")])

            if expanded_section == f'opt_{idx}':
                opt_rows = []
                row = []
                for v in opt_values:
                    v_label = v if isinstance(v, str) else (v.get('label') or v.get('name') or str(v))
                    is_sel = (selected_val == v_label)
                    btn_text = f"☑ {v_label}" if is_sel else v_label
                    row.append(InlineKeyboardButton(btn_text, callback_data=f"select_variant_opt_{pid}_{idx}_{v_label}"))
                    if len(row) == 3:
                        opt_rows.append(row)
                        row = []
                if row:
                    opt_rows.append(row)
                keyboard.extend(opt_rows)

    # 3. Quantity Controls & Action Buttons
    if not is_out_of_stock:
        quantity_buttons = []
        if quantity > 0:
            quantity_buttons.append(InlineKeyboardButton("➖", callback_data=f"decrease_qty_{pid}_{quantity}"))
            quantity_buttons.append(InlineKeyboardButton(get_text('reset_button', lang), callback_data=f"reset_qty_{pid}"))
        if stock is None or quantity < stock:
            quantity_buttons.append(InlineKeyboardButton("➕", callback_data=f"increase_qty_{pid}_{quantity}"))
        if quantity_buttons:
            keyboard.append(quantity_buttons)

        if quantity > 0:
            add_to_cart_text = get_text('add_to_cart_button_qty', lang).format(quantity=quantity)
            keyboard.append([InlineKeyboardButton(add_to_cart_text, callback_data=f"add_to_cart_qty_{pid}_{quantity}")])
            buy_now_text = get_text('buy_now_button_qty', lang).format(quantity=quantity)
            keyboard.append([InlineKeyboardButton(buy_now_text, callback_data=f"buy_now_direct_{pid}_{quantity}")])
        else:
            add_to_cart_text = get_text('add_to_cart_button', lang)
            keyboard.append([InlineKeyboardButton(add_to_cart_text, callback_data=f"add_to_cart_qty_{pid}_{0}")])

    if extra_bottom_rows:
        keyboard.extend(extra_bottom_rows)

    return InlineKeyboardMarkup(keyboard)

async def handle_toggle_variant_color(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    pid = int(query.data.split("_")[-1])
    expanded = context.user_data.setdefault('variant_expanded', {}).get(pid)
    context.user_data.setdefault('variant_expanded', {})[pid] = None if expanded == 'color' else 'color'
    await query.answer()
    await show_product_detail(update, context, pid)

async def handle_select_variant_color(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    parts = query.data.split("_")
    pid = int(parts[3])
    color_val = "_".join(parts[4:])
    context.user_data.setdefault('variant_selections', {}).setdefault(pid, {})['color'] = color_val
    context.user_data.setdefault('variant_expanded', {})[pid] = None
    await query.answer(f"Selected Color: {color_val}")
    await show_product_detail(update, context, pid)

async def handle_toggle_variant_opt(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    parts = query.data.split("_")
    pid = int(parts[3])
    idx = parts[4]
    expanded = context.user_data.setdefault('variant_expanded', {}).get(pid)
    target = f'opt_{idx}'
    context.user_data.setdefault('variant_expanded', {})[pid] = None if expanded == target else target
    await query.answer()
    await show_product_detail(update, context, pid)

async def handle_select_variant_opt(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    parts = query.data.split("_")
    pid = int(parts[3])
    idx = int(parts[4])
    val = "_".join(parts[5:])
    
    bot_id = await get_bot_id(context.bot.token)
    product = get_product(bot_id, pid)
    specs = (product.get('specifications') or {}) if product else {}
    options = specs.get('options') or []
    opt_name = options[idx]['name'] if idx < len(options) else f"Option {idx+1}"

    user_sel = context.user_data.setdefault('variant_selections', {}).setdefault(pid, {})
    user_sel.setdefault('options', {})[opt_name] = val
    context.user_data.setdefault('variant_expanded', {})[pid] = None
    await query.answer(f"Selected {opt_name}: {val}")
    await show_product_detail(update, context, pid)

async def show_product_detail(update: Update, context: ContextTypes.DEFAULT_TYPE, product_id: int = None):
    """
    Display product details. Handles being called from a CallbackQuery (button)
    or a Message (text search).
    """
    query = update.callback_query
    lang = await get_user_lang(context)
    responder = update.message if update.message else query.message

    try:
        is_initial_view = (query is None) or (not query.data.startswith(("decrease_qty_", "increase_qty_", "reset_qty_")))

        if not product_id:
            await query.answer()
            product_id = int(query.data.split("_")[1])
        else:
            if query: await query.answer()

        bot_id = await get_bot_id(context.bot.token)
        if not bot_id:
            await responder.reply_text("❌ Error: This bot is not correctly registered.")
            return State.BROWSE_CATEGORIES

        product = get_product(bot_id, product_id)
        if not product:
            await responder.reply_text(
                get_text('product_not_found', lang),
                reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(get_text('back_to_categories_button', lang), callback_data="browse")]])
            )
            return State.BROWSE_CATEGORIES

        product_name = escape_markdown(product['name'])
        product_description = escape_markdown(product['description'])
        effective_price = resolve_product_price(product, context.user_data)
        price_str = await format_price(context, effective_price, lang)

        # Generate Deep Link
        bot_username = context.bot.username
        if not bot_username:
            try:
                bot_user = await context.bot.get_me()
                bot_username = bot_user.username
            except Exception:
                bot_username = "YourBotUsername" # Fallback if API fails
        
        # OFFSET LOGIC: Add 1997 so that DB ID 1 becomes Link 1998
        product_link = f"https://t.me/{bot_username}?start={get_or_create_product_link_token(product['id'])}"

        # Stock display
        stock = product['stock_quantity']
        if stock is None:
            stock_line = ""
        elif stock == 0:
            stock_line = "\n📦 *Stock:* ❌ Out of Stock\n"
        else:
            stock_line = f"\n📦 *Stock:* {stock} left\n"

        specs = product.get('specifications') or {}
        colors = specs.get('colors') or []
        options = specs.get('options') or []
        sel_line = ""
        if colors or options:
            user_sel = context.user_data.setdefault('variant_selections', {}).setdefault(product['id'], {})
            parts = []
            if colors:
                sc = user_sel.get('color')
                if sc:
                    sc = get_color_display_name(sc)
                parts.append(f"Color:{sc}" if sc else "Color:❓")
            for opt in options:
                oname = opt.get('name', 'Option')
                so = user_sel.get('options', {}).get(oname)
                parts.append(f"{oname}: {so}" if so else f"{oname}: ❓")
            sel_line = "\n📌 *Selected:* " + " | ".join(parts) + "\n"

        full_caption = (
            f"*{product_name}*\n\n"
            f"{product_description}\n\n"
            f"{get_text('price_label', lang).format(price_str=price_str)}"
            f"{stock_line}"
            f"{sel_line}\n"
            f"🔗 *Product Link:*\n`{product_link}`\n\n"
            f"{get_text('product_caption_details', lang)}"
        )

        extra_bottom_rows = []
        if context.user_data.get('newsfeed_active'):
            extra_bottom_rows.append([InlineKeyboardButton("🔼 Collapse", callback_data=f"nf_collapse_{product['id']}")])
            telegram_id = update.effective_user.id if update.effective_user else 0
            reaction_row = _build_reaction_keyboard(bot_id, product['id'], telegram_id)
            extra_bottom_rows.append(reaction_row)
        else:
            extra_bottom_rows.append([InlineKeyboardButton(get_text('view_cart_button', lang), callback_data="view_cart")])
            extra_bottom_rows.append([InlineKeyboardButton(get_text('back_to_products_button', lang), callback_data=f"category_{product['category_id']}")])

        reply_markup = build_product_variant_keyboard(product, context, lang, extra_bottom_rows=extra_bottom_rows)

        # --- LOGIC TO HANDLE LONG DESCRIPTIONS ---
        # Telegram limit is 1024 chars for captions.
        send_separate_text = False
        media_caption_to_use = full_caption
        media_reply_markup = reply_markup
        text_message_to_send = None

        if len(full_caption) > 1000:
            send_separate_text = True
            media_caption_to_use = f"*{product_name}*\n\n_Details 👇👇_"
            text_message_to_send = full_caption
            media_reply_markup = None # Buttons go on the text message
        # ----------------------------------------

        media_list = []
        if raw_media_data := product.get('image_url'):
            try:
                loaded_data = json.loads(raw_media_data)
                if isinstance(loaded_data, list) and loaded_data: media_list = loaded_data
            except (json.JSONDecodeError, TypeError):
                media_list = [str(raw_media_data)]

        try:
            if is_initial_view:
                if query:
                    try:
                        await query.message.delete()
                    except Exception:
                        pass

                is_old_format = media_list and all(isinstance(item, str) for item in media_list)

                # Helper to collect media IDs if split view
                sent_media_ids = []

                if is_old_format:
                    logger.info(f"Using legacy media handler for product {product['id']} due to old data format.")
                    media_sent = False
                    for i, file_id in enumerate(media_list):
                        # Use the split logic here
                        current_caption = media_caption_to_use if not media_sent else ""
                        current_reply_markup = media_reply_markup if not media_sent else None
                        
                        try:
                            msg = await responder.reply_photo(photo=file_id, caption=current_caption, reply_markup=current_reply_markup, parse_mode=ParseMode.MARKDOWN)
                            if send_separate_text: sent_media_ids.append(msg.message_id)
                            media_sent = True
                        except telegram.error.BadRequest as e:
                            if "file of type" in str(e):
                                try:
                                    msg = await responder.reply_video(video=file_id, caption=current_caption, reply_markup=current_reply_markup, parse_mode=ParseMode.MARKDOWN)
                                    if send_separate_text: sent_media_ids.append(msg.message_id)
                                    media_sent = True
                                except Exception as inner_e:
                                    logger.error(f"Legacy retry as video failed for product {product['id']}: {inner_e}")
                            else:
                                raise e

                    if not media_sent:
                        fallback_photo = "https://i.postimg.cc/fbGWNR7C/en-article26.png"
                        msg = await responder.reply_photo(photo=fallback_photo, caption=media_caption_to_use, reply_markup=media_reply_markup, parse_mode=ParseMode.MARKDOWN)
                        if send_separate_text: sent_media_ids.append(msg.message_id)

                else:
                    parsed_media = []
                    for item in media_list:
                        if isinstance(item, dict):
                            media_type = 'video' if item.get('type') == 'video' else 'photo'
                            parsed_media.append((media_type, item.get('file_id')))

                    media_items_to_send = []
                    is_first = True
                    for media_type, file_id in parsed_media:
                        if is_first:
                            # Use caption logic here
                            if media_type == 'video':
                                media_items_to_send.append(InputMediaVideo(media=file_id, caption=media_caption_to_use, parse_mode=ParseMode.MARKDOWN))
                            else:
                                media_items_to_send.append(InputMediaPhoto(media=file_id, caption=media_caption_to_use, parse_mode=ParseMode.MARKDOWN))
                            is_first = False
                        else:
                            if media_type == 'video': media_items_to_send.append(InputMediaVideo(media=file_id))
                            else: media_items_to_send.append(InputMediaPhoto(media=file_id))

                    if len(media_items_to_send) > 1:
                        sent_messages = await responder.reply_media_group(media=media_items_to_send)
                        if send_separate_text:
                            for m in sent_messages: sent_media_ids.append(m.message_id)

                        if not send_separate_text:
                            await sent_messages[0].reply_text("Select an option:", reply_markup=reply_markup)
                            
                    elif len(media_items_to_send) == 1:
                        single_item = media_items_to_send[0]
                        if isinstance(single_item, InputMediaVideo):
                            msg = await responder.reply_video(video=single_item.media, caption=media_caption_to_use, reply_markup=media_reply_markup, parse_mode=ParseMode.MARKDOWN)
                        else:
                            msg = await responder.reply_photo(photo=single_item.media, caption=media_caption_to_use, reply_markup=media_reply_markup, parse_mode=ParseMode.MARKDOWN)
                        if send_separate_text: sent_media_ids.append(msg.message_id)
                    else:
                        fallback_photo = "https://i.postimg.cc/fbGWNR7C/en-article26.png"
                        msg = await responder.reply_photo(photo=fallback_photo, caption=media_caption_to_use, reply_markup=media_reply_markup, parse_mode=ParseMode.MARKDOWN)
                        if send_separate_text: sent_media_ids.append(msg.message_id)
                
                # Finally, if description was too long, send text message now
                if send_separate_text and text_message_to_send:
                    await responder.reply_text(text=text_message_to_send, reply_markup=reply_markup, parse_mode=ParseMode.MARKDOWN)
                    # Store IDs to clean up later
                    context.user_data['split_media_msg_ids'] = sent_media_ids

            else:
                # Handle EDITING message (Updating qty etc)
                if send_separate_text:
                    # Cleanup OLD media first to avoid piling up photos
                    await cleanup_split_media(context, query.message.chat_id)

                    try:
                        await query.message.delete()
                    except: 
                        pass
                        
                    # Resend logic 
                    fallback_photo = "https://i.postimg.cc/fbGWNR7C/en-article26.png"
                    first_file_id = fallback_photo
                    
                    if media_list:
                        item = media_list[0]
                        if isinstance(item, str): first_file_id = item
                        elif isinstance(item, dict): first_file_id = item.get('file_id')

                    # Resend and capture new ID
                    msg = await responder.reply_photo(photo=first_file_id, caption=media_caption_to_use, parse_mode=ParseMode.MARKDOWN)
                    await responder.reply_text(text=text_message_to_send, reply_markup=reply_markup, parse_mode=ParseMode.MARKDOWN)
                    
                    context.user_data['split_media_msg_ids'] = [msg.message_id]
                else:
                    await safe_edit_caption_or_text(query, full_caption, reply_markup)
        except Exception as e:
            logger.error(f"Error displaying media for product_id {product['id']}. Falling back to text. Error: {e}", exc_info=True)
            await responder.reply_text(text=full_caption, reply_markup=reply_markup, parse_mode=ParseMode.MARKDOWN)

        return State.VIEW_PRODUCT

    except Exception as e:
        logger.error(f"Error in show_product_detail: {e}", exc_info=True)
        lang = await get_user_lang(context)
        await responder.reply_text(
            get_text('error_loading_product', lang),
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(get_text('back_to_categories_button', lang), callback_data="browse")]])
        )
        return State.BROWSE_CATEGORIES


