async def view_cart_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Display the user's cart contents for the correct bot."""
    query = update.callback_query
    await cleanup_split_media(context, query.message.chat_id) # Cleanup split media
    lang = await get_user_lang(context)

    try:
        user = update.effective_user
        bot_id = await get_bot_id(context.bot.token)

        if not bot_id:
            await query.answer("Error: This bot is not registered correctly.", show_alert=True)
            return State.MAIN_MENU

        if await is_user_banned(user.id, bot_id):
            await query.answer("You have been banned from using this feature, Contact the admin", show_alert=True)
            return State.MAIN_MENU

        if not get_shop_status(bot_id):
            await query.answer("The shop is currently closed. Please come back later!", show_alert=True)
            return State.MAIN_MENU

        user_data = await get_or_create_user(user.id, user.username, user.first_name, user.last_name, user.username, context.bot.token)

        if not user_data:
            await query.answer("❌ Error retrieving cart. Please try again.", show_alert=True)
            return State.MAIN_MENU

        await query.answer()

        cart_items = get_user_cart(bot_id, user_data['id'])

        if not cart_items:
            caption = get_text('cart_empty_caption', lang)
            keyboard = [
                [InlineKeyboardButton(get_text('browse_products_button', lang), callback_data="browse")],
                [InlineKeyboardButton(get_text('main_menu_button', lang), callback_data="main_menu")]
            ]
        else:
            caption = await get_bot_specific_text('cart_caption_title', lang, bot_id, context)
            total_price = Decimal(0)
            for item in cart_items:
                item_price = Decimal(str(item['price']))
                item_total = item_price * item['quantity']
                price_str = await format_price(context, item_price, lang)
                item_total_str = await format_price(context, item_total, lang)
                item_name = escape_markdown(item['name'])
                caption += f"*{item_name}*\n`{item['quantity']} x {price_str}` = `{item_total_str}`\n"
                total_price += item_total

            total_price_str = await format_price(context, total_price, lang)
            caption += get_text('cart_total_prompt', lang).format(total_price=total_price_str)

            keyboard = [
                [InlineKeyboardButton(get_text('checkout_button', lang), callback_data="checkout")],
                [InlineKeyboardButton(get_text('browse_products_button', lang), callback_data="browse"),
                 InlineKeyboardButton(get_text('clear_cart_button', lang), callback_data="clear_user_cart")],
                [InlineKeyboardButton(get_text('main_menu_button', lang), callback_data="main_menu")]
            ]

        reply_markup = InlineKeyboardMarkup(keyboard)
        photo_url = get_poster_file_id(bot_id, "view_cart_poster", "https://i.postimg.cc/Y0YX7mPH/IMG-20260309-200910-001.jpg")

        await update_menu_display(query=query, context=context, caption=caption, reply_markup=reply_markup, photo_url=photo_url)

        return State.CART
    except Exception as e:
        logger.error(f"Error in view_cart_handler: {e}", exc_info=True)
        await query.answer("❌ An unexpected error occurred while viewing your cart.", show_alert=True)
        return State.MAIN_MENU



async def start_checkout(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Start the checkout process, checking for profile completion first."""
    query = update.callback_query
    await query.answer()
    lang = await get_user_lang(context)

    try:
        bot_id = await get_bot_id(context.bot.token)
        if not bot_id:
            await query.answer("Error: This bot is not registered correctly.", show_alert=True)
            return State.MAIN_MENU

        user = update.effective_user
        user_data = await get_or_create_user(user.id, user.username, user.first_name, user.last_name, user.username, context.bot.token)

        if not user_data:
            await query.answer("❌ Error starting checkout. Please try again.", show_alert=True)
            return State.CART


        phone_number = user_data.get('phone_number')
        shipping_address = user_data.get('shipping_address')

        if not phone_number or not shipping_address:
            # Save the original checkout callback so we can return to it after profile is complete
            context.user_data['checkout_origin'] = query.data

            caption = get_text('profile_incomplete_title', lang) + "\n\n" + get_text('profile_incomplete_body', lang)
            if not phone_number:
                caption += get_text('missing_phone_number', lang)
            if not shipping_address:
                caption += get_text('missing_shipping_address', lang)
            caption += get_text('profile_incomplete_instruction', lang)

            keyboard = []
            if not phone_number:
                keyboard.append([InlineKeyboardButton(get_text('add_phone_button', lang), callback_data="update_phone")])
            if not shipping_address:
                keyboard.append([InlineKeyboardButton(get_text('add_address_button', lang), callback_data="update_address")])

            back_button_callback = "view_cart" if not query.data.startswith("buy_now_direct_") else f"product_{query.data.split('_')[3]}"
            keyboard.append([InlineKeyboardButton(get_text('back_button', lang), callback_data=back_button_callback)])

            reply_markup = InlineKeyboardMarkup(keyboard)
            await safe_edit_caption_or_text(query, caption, reply_markup)
            return State.PROFILE


        cart_items = []
        if query.data.startswith("buy_now_direct_"):
            parts = query.data.split('_')
            product_id = int(parts[3])
            quantity = int(parts[4])

            product = get_product(bot_id, product_id)
            if product:
                missing = get_missing_variant_requirements(product, context.user_data)
                if missing:
                    await query.answer(f"⚠️ Please select {', '.join(missing)} first!", show_alert=True)
                    await show_product_detail(update, context, product_id)
                    return State.VIEW_PRODUCT

            if quantity == 0:
                await query.answer("❌ You did not select anything to buy.", show_alert=True)
                await show_product_detail(update, context, product_id)
                return State.VIEW_PRODUCT
            if product and (product['stock_quantity'] is None or product['stock_quantity'] >= quantity):
                variant_label = get_variant_label(product, context.user_data)
                item_name = f"{product['name']}{variant_label}" if (variant_label and variant_label not in product['name']) else product['name']
                cart_items.append({
                    'product_id': product['id'], 'name': item_name, 'price': product['price'],
                    'quantity': quantity, 'image_url': product['image_url'], 'variant_label': variant_label.strip(" ()")
                })
            else:
                await query.answer("❌ Product not available or insufficient stock.", show_alert=True)
                return State.VIEW_PRODUCT
        else:
            cart_items = get_user_cart(bot_id, user_data['id'])

        if not cart_items:
            await query.answer("Your cart is empty!", show_alert=True)
            return State.CART

        bot_id_for_total = await get_bot_id(context.bot.token)
        total = sum(Decimal(str(item['price'])) * item['quantity'] for item in cart_items)
        context.user_data['checkout_items'] = cart_items
        context.user_data['checkout_total'] = total

        total_str = await format_price(context, total, lang)
        caption = get_text('checkout_caption', lang).format(total_str=total_str)

        # Check MyanMyanPay MMQR status & threshold
        mmpay_status = db.q("SELECT enabled, shop_enabled FROM shop_payment_merchants WHERE bot_id=%s", (bot_id,), fetch_one=True)
        mmpay_active = bool(mmpay_status and mmpay_status.get("enabled") and mmpay_status.get("shop_enabled"))
        logger.info(f"Checkout payment options for bot {bot_id}: mmpay_active={mmpay_active}, total={total}")

        keyboard = []
        has_instant_mmpay = mmpay_active and float(total) >= 1000
        if has_instant_mmpay:
            keyboard.append([InlineKeyboardButton("⚡ MyanMyanPay (Instant MMQR)", callback_data="pay_mmpay")])
        else:
            active_payment_methods = get_payment_methods(bot_id, is_active=True)
            for method in active_payment_methods:
                keyboard.append([InlineKeyboardButton(f"💳 {method['name']}", callback_data=f"pay_{method['id']}")])

        if not keyboard:
            await query.answer("❌ No payment methods available. Please try again later.", show_alert=True)
            return State.CART

        keyboard.append([InlineKeyboardButton(get_text('back_to_cart_button', lang), callback_data="view_cart")])

        reply_markup = InlineKeyboardMarkup(keyboard)
        await safe_edit_caption_or_text(query, caption, reply_markup)

        return State.CHECKOUT

    except Exception as e:
        logger.error(f"Error in start_checkout: {e}", exc_info=True)
        await query.answer("❌ An unexpected error occurred during checkout.", show_alert=True)
        return State.CART


async def daily_shop_auto_backup_job(context: ContextTypes.DEFAULT_TYPE):
    """Job that runs at 12:00 AM every day to check enabled shops and send backup ZIP for yesterday (12:00 AM to 11:59 PM) to bot owner."""
    try:
        import sys, pytz
        from datetime import datetime, timedelta
        for p in ['/root/teleshop-dev', '/root/teleshop-api']:
            if p not in sys.path:
                sys.path.insert(0, p)
        from routes.admin import generate_shop_backup_zip, send_backup_zip_to_owner

        mm_tz = pytz.timezone('Asia/Yangon')
        yesterday = (datetime.now(mm_tz) - timedelta(days=1)).date()

        shops = db.q("SELECT id, daily_backup_enabled FROM managed_bots WHERE daily_backup_enabled = TRUE", fetch=True)
        if shops:
            for shop in shops:
                bot_id = shop.get("id")
                try:
                    zip_path = generate_shop_backup_zip(bot_id, target_date=yesterday)
                    if zip_path:
                        send_backup_zip_to_owner(bot_id, zip_path, is_auto=True)
                except Exception as e:
                    logger.error(f"Error executing auto backup for bot {bot_id}: {e}")
    except Exception as e:
        logger.error(f"Error in daily_shop_auto_backup_job: {e}")


async def process_mmpay_checkout(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Render 2-step confirmation screen for MyanMyanPay (MMQR)."""
    query = update.callback_query
    await query.answer()
    lang = await get_user_lang(context)
    bot_id = await get_bot_id(context.bot.token)
    cart_items = context.user_data.get('checkout_items', [])
    total = context.user_data.get('checkout_total', 0)

    if not cart_items:
        await query.answer("❌ Your checkout session has expired. Please view your cart again.", show_alert=True)
        return State.CART

    # Calculate delivery fee
    delivery_fee = 0
    try:
        bot_settings = db.execute_query("SELECT delivery_fee, free_delivery_threshold FROM managed_bots WHERE id=%s", (bot_id,), fetch=True)
        if bot_settings:
            df = float(bot_settings.get('delivery_fee') or 0)
            threshold = float(bot_settings.get('free_delivery_threshold') or 0)
            if df > 0:
                any_has_fee = False
                for ci in cart_items:
                    prod = db.execute_query("SELECT apply_delivery_fee FROM products WHERE id=%s", (ci.get('product_id'),), fetch=True)
                    if prod and prod.get('apply_delivery_fee'):
                        any_has_fee = True
                        break
                if any_has_fee:
                    if threshold > 0 and float(total) >= threshold:
                        delivery_fee = 0
                    else:
                        delivery_fee = df
    except Exception:
        pass

    final_total = float(total) + delivery_fee
    final_total_str = await format_price(context, final_total, lang)

    context.user_data['pending_mmpay'] = {
        'total': total,
        'delivery_fee': delivery_fee,
        'final_total': final_total,
        'cart_items': cart_items
    }

    items_lines = []
    for ci in cart_items:
        c_name = ci.get('name') or ci.get('product_name') or 'Product'
        c_qty = ci.get('quantity', 1)
        c_price = Decimal(ci.get('price', 0))
        c_price_str = await format_price(context, c_price, lang)
        items_lines.append(f"• {c_name} (x{c_qty}) - {c_price_str}")
    items_text = "\n".join(items_lines) if items_lines else "• (empty)"

    caption = (
        f"MMQR လက်ခံသော Mobile Wallet များနှင့် ငွေပေးချေနိုင်သည်။\n\n"
        f"📦 **Products:**\n{items_text}\n\n"
        f"💰 **Total Amount**: `{final_total_str}`\n\n"
        f"ကျေးဇူးပြုပြီး ငွေပေးချေရန် \n"
        f"အဆင်သင့်ဖြစ်မှ Place Order ကို နှိပ်ပေးပါ။"
    )

    keyboard = [
        [InlineKeyboardButton("✅ Place Order", callback_data="mmpay_confirm_qr")],
        [InlineKeyboardButton("❌ Back to Checkout", callback_data="start_checkout")]
    ]
    reply_markup = InlineKeyboardMarkup(keyboard)
    await safe_edit_caption_or_text(query, caption, reply_markup)
    return State.CHECKOUT


async def confirm_mmpay_qr(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Generate dynamic MMQR payload, send QR photo to Telegram, and set 15-minute timeout."""
    query = update.callback_query
    answered = False
    async def safe_answer(text=None, show_alert=False):
        nonlocal answered
        if not answered:
            try:
                if text:
                    await query.answer(text, show_alert=show_alert)
                else:
                    await query.answer()
                answered = True
            except Exception as _ex:
                logger.error(f"safe_answer error: {_ex}")
    lang = await get_user_lang(context)
    bot_id = await get_bot_id(context.bot.token)
    user = update.effective_user

    user_data = await get_or_create_user(user.id, user.username, user.first_name, user.last_name, user.username, context.bot.token)
    pending_mmpay = context.user_data.get('pending_mmpay', {})
    cart_items = pending_mmpay.get('cart_items', [])
    final_total = pending_mmpay.get('final_total', 0)

    if not cart_items or final_total <= 0:
        await safe_answer("❌ Checkout session expired. Please view your cart again.", show_alert=True)
        return State.CART

    # Anti-Spam Check 1: Active pending MMQR order
    active_order = db.q(
        """SELECT order_number FROM orders 
           WHERE bot_id=%s AND user_id=%s AND payment_method='mmpay' AND status='pending' 
           AND created_at >= NOW() - INTERVAL '15 minutes' LIMIT 1""",
        (bot_id, user_data['id']),
        fetch_one=True
    )
    if active_order:
        await safe_answer(
            "You cannot create new order while a QR code is pending, try again later",
            show_alert=True
        )
        return State.CHECKOUT

    # Anti-Spam Check 2: IP / User Cooldown Penalty
    import time
    user_streaks = context.bot_data.setdefault('mmpay_user_streaks', {})
    user_blocked = context.bot_data.setdefault('mmpay_user_blocked', {})
    now_ts = time.time()
    blocked_until = user_blocked.get(user.id, 0)
    if now_ts < blocked_until:
        remaining = int(blocked_until - now_ts)
        mins = remaining // 60
        secs = remaining % 60
        time_str = f"{mins}m {secs}s" if mins > 0 else f"{secs}s"
        await safe_answer(
            f"Try again in {time_str}. Don't place order if not sure",
            show_alert=True
        )
        return State.CHECKOUT

    import random, string, io, requests, qrcode
    rand_suffix = ''.join(random.choices(string.digits, k=10))
    order_number = f"WS{rand_suffix}"

    def json_default(obj):
        if isinstance(obj, Decimal):
            return float(obj)
        raise TypeError(f"Object of type {obj.__class__.__name__} is not JSON serializable")

    items_json = json.dumps(cart_items, default=json_default)
    b_name = user_data.get('account_name') or user_data.get('name') or user.first_name or user.username or 'N/A'
    b_phone = user_data.get('phone_number') or user_data.get('phone') or 'N/A'
    b_email = user_data.get('email') or 'N/A'
    b_addr = user_data.get('address') or user_data.get('shipping_address') or 'N/A'
    if isinstance(b_addr, dict):
        b_addr = b_addr.get('text') or str(b_addr)

    buyer_snapshot = json.dumps({
        "id": user_data['id'],
        "name": b_name,
        "full_name": b_name,
        "telegram_id": user.id,
        "phone": b_phone,
        "phone_number": b_phone,
        "email": b_email,
        "address": b_addr
    }, default=json_default)

    res = db.q(
        """INSERT INTO orders (bot_id, user_id, order_number, total_amount, final_amount, status, payment_method, items, buyer_snapshot, source, created_at, updated_at)
           VALUES (%s, %s, %s, %s, %s, 'pending', 'mmpay', %s, %s, 'telegram', NOW(), NOW()) RETURNING id""",
        (bot_id, user_data['id'], order_number, final_total, final_total, items_json, buyer_snapshot),
        fetch_one=True
    )
    order_id = res['id'] if res else None
    if not order_id:
        await safe_answer("❌ Error creating order. Please try again.", show_alert=True)
        return State.CHECKOUT

    qr_str = None
    try:
        resp = requests.post("http://127.0.0.1:3001/create-shop-order", json={
            "bot_id": bot_id,
            "order_id": order_id,
            "amount": final_total
        }, timeout=8)
        if resp.status_code == 200:
            data = resp.json()
            qr_str = data.get("qr")
    except Exception as e:
        logger.error(f"Error requesting MMQR string: {e}")

    if not qr_str:
        await safe_answer("❌ Failed to generate MMQR code. Please select a different payment method.", show_alert=True)
        return State.CHECKOUT

    qr_img = qrcode.QRCode(version=1, box_size=10, border=4)
    qr_img.add_data(qr_str)
    qr_img.make(fit=True)
    img = qr_img.make_image(fill_color="black", back_color="white")
    bio = io.BytesIO()
    img.save(bio, 'PNG')
    bio.seek(0)
    bio.name = f"mmpay_qr_{order_number}.png"

    items_lines = []
    for ci in cart_items:
        c_name = ci.get('name') or ci.get('product_name') or 'Product'
        c_qty = ci.get('quantity', 1)
        c_price = Decimal(ci.get('price', 0))
        c_price_str = await format_price(context, c_price, lang)
        items_lines.append(f"• {c_name} (x{c_qty}) - {c_price_str}")
    items_text = "\n".join(items_lines) if items_lines else "• (empty)"

    await safe_answer()
    final_total_str = await format_price(context, final_total, lang)
    caption = (
        f"🛍 **Order ID**: `#{order_number}`\n\n"
        f"📦 **Products:**\n{items_text}\n"
        f"💰 **Total Amount**: `{final_total_str}`\n\n"
        f"*Payment Powered by Myan Myan Pay MMQR*\n"
        f"⏰ **This QR code will expire in 15 minutes.**"
    )

    reply_markup = None

    chat_id = update.effective_chat.id
    items_lines = []
    for ci in cart_items:
        c_name = ci.get('name') or ci.get('product_name') or 'Product'
        c_qty = ci.get('quantity', 1)
        c_price = Decimal(ci.get('price', 0))
        c_price_str = await format_price(context, c_price, lang)
        items_lines.append(f"• {c_name} (x{c_qty}) - {c_price_str}")
    items_text = "\n".join(items_lines) if items_lines else "• (empty)"

    caption = (
        f"🛍 **Order ID**: `#{order_number}`\n\n"
        f"📦 **Products:**\n{items_text}\n"
        f"💰 **Total Amount**: `{final_total_str}`\n\n"
        f"*Payment Powered by Myan Myan Pay MMQR*\n"
        f"⏰ **This QR code will expire in 15 minutes.**"
    )

    sent_msg = await context.bot.send_photo(chat_id=chat_id, photo=bio, caption=caption, reply_markup=reply_markup, parse_mode='Markdown')
    try:
        existing_shipping = db.q("SELECT shipping_address FROM orders WHERE id=%s", (order_id,), fetch_one=True)
        ship_dict = {}
        if existing_shipping and existing_shipping.get('shipping_address'):
            val = existing_shipping['shipping_address']
            ship_dict = json.loads(val) if isinstance(val, str) else val
        ship_dict['qr_message_id'] = sent_msg.message_id
        db.q("UPDATE orders SET shipping_address=%s WHERE id=%s", (json.dumps(ship_dict), order_id))
    except Exception as _ex:
        logger.error(f"Failed to store qr_message_id: {_ex}")

    if context.job_queue:
        context.job_queue.run_once(
            mmpay_timeout_job,
            900,
            data={"bot_id": bot_id, "order_id": order_id, "chat_id": chat_id, "message_id": sent_msg.message_id, "order_number": order_number, "telegram_user_id": user.id}
        )

    try:
        user_id = user_data['id']
        db.q("DELETE FROM cart WHERE user_id=%s AND bot_id=%s", (user_id, bot_id))
        context.user_data['checkout_items'] = []
    except Exception:
        pass

    return State.CHECKOUT


async def check_mmpay_status_action(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Check payment status when user clicks 'Check Payment Status'."""
    query = update.callback_query
    bot_id = await get_bot_id(context.bot.token)
    parts = query.data.split('_')
    order_id = int(parts[2])

    order = db.q("SELECT id, order_number, status, final_amount, items FROM orders WHERE id=%s AND bot_id=%s", (order_id, bot_id), fetch_one=True)
    if not order:
        await query.answer("❌ Order not found.", show_alert=True)
        return

    st = str(order.get('status', '')).lower()
    if st in ['paid', 'confirmed']:
        await query.answer("✅ Payment Confirmed!", show_alert=True)
        total_str = await format_price(context, order.get('final_amount', 0), 'en')
        caption = (
            f"✅ **Payment Confirmed!**\n"
            f"━━━━━━━━━━━━━━━━━━━━━━\n"
            f"Order Number: `#{order.get('order_number')}`\n"
            f"Total Paid: `{total_str}`\n"
            f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
            f"Your order has been auto-verified via MyanMyanPay. Thank you for your purchase!"
        )
        try:
            await query.edit_message_caption(caption=caption, parse_mode='Markdown')
        except Exception:
            pass
    elif st in ['cancelled', 'expired']:
        await query.answer("❌ Order cancelled or expired.", show_alert=True)
        try:
            await query.edit_message_caption(caption=f"⏰ **Order #{order.get('order_number')} has expired or been cancelled.**", parse_mode='Markdown')
        except Exception:
            pass
    else:
        await query.answer("⏳ Payment not received yet. Please scan the QR code in your bank app and try again.", show_alert=True)


async def cancel_mmpay_order_action(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Cancel order when user taps Cancel Order."""
    query = update.callback_query
    bot_id = await get_bot_id(context.bot.token)
    parts = query.data.split('_')
    order_id = int(parts[2])

    db.q("UPDATE orders SET status='cancelled', updated_at=NOW() WHERE id=%s AND bot_id=%s AND status='pending'", (order_id, bot_id))
    await query.answer("Order cancelled.", show_alert=True)
    try:
        await query.edit_message_caption(caption="❌ **Order payment cancelled.**", parse_mode='Markdown')
    except Exception:
        pass


async def mmpay_timeout_job(context: ContextTypes.DEFAULT_TYPE):
    """15-minute timeout job for MMQR payment."""
    job_data = context.job.data
    order_id = job_data.get('order_id')
    bot_id = job_data.get('bot_id')
    chat_id = job_data.get('chat_id')
    message_id = job_data.get('message_id')
    order_number = job_data.get('order_number')

    order = db.q("SELECT status FROM orders WHERE id=%s AND bot_id=%s", (order_id, bot_id), fetch_one=True)
    if order and order.get('status') == 'pending':
        db.q("UPDATE orders SET status=expired, updated_at=NOW() WHERE id=%s AND bot_id=%s", (order_id, bot_id))
        tg_user_id = job_data.get(telegram_user_id)
        if tg_user_id:
            import time
            user_streaks = context.bot_data.setdefault('mmpay_user_streaks', {})
            user_blocked = context.bot_data.setdefault('mmpay_user_blocked', {})
            streak = user_streaks.get(tg_user_id, 0) + 1
            user_streaks[tg_user_id] = streak
            penalties = [300, 600, 900, 1200, 1800, 3600, 10800, 18000]
            penalty = penalties[min(streak - 1, len(penalties) - 1)]
            user_blocked[tg_user_id] = time.time() + penalty
            logger.info(f"[BotAntiSpam] User {tg_user_id} unpaid streak={streak}, blocked for {penalty}s")
        try:
            await context.bot.edit_message_caption(
                chat_id=chat_id,
                message_id=message_id,
                caption=f"⏰ **Payment QR Expired (15-minute timeout)**\n\nOrder `#{order_number}` has expired because payment was not completed within 15 minutes. Please check out again.",
                parse_mode='Markdown'
            )
        except Exception as e:
            logger.error(f"Failed to update expired MMQR message: {e}")


async def process_payment(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Process payment selection and display payment instructions."""
    query = update.callback_query
    await query.answer()
    lang = await get_user_lang(context)

    try:
        bot_id = await get_bot_id(context.bot.token)
        payment_method_id = int(query.data.split("_")[1])

        selected_payment_method = get_payment_method(bot_id, payment_method_id)

        if not selected_payment_method or not selected_payment_method['is_active']:
            await query.answer("❌ Selected payment method is not available or inactive. Please choose another.", show_alert=True)
            return State.CHECKOUT

        user = update.effective_user
        user_data = await get_or_create_user(user.id, user.username, user.first_name, user.last_name, user.username, context.bot.token)

        if not user_data:
            await query.answer("❌ Error processing payment. Please try again.", show_alert=True)
            return State.CHECKOUT

        cart_items = context.user_data.get('checkout_items', [])
        total = context.user_data.get('checkout_total', 0)

        if not cart_items:
            await query.answer("❌ Your checkout session has expired. Please view your cart again.", show_alert=True)
            return State.CART

        # Calculate delivery fee
        delivery_fee = 0
        try:
            bot_settings = db.execute_query("SELECT delivery_fee, free_delivery_threshold FROM managed_bots WHERE id=%s", (bot_id,), fetch=True)
            if bot_settings:
                df = float(bot_settings.get('delivery_fee') or 0)
                threshold = float(bot_settings.get('free_delivery_threshold') or 0)
                if df > 0:
                    any_has_fee = False
                    for ci in cart_items:
                        prod = db.execute_query("SELECT apply_delivery_fee FROM products WHERE id=%s", (ci.get('product_id'),), fetch=True)
                        if prod and prod.get('apply_delivery_fee'):
                            any_has_fee = True
                            break
                    if any_has_fee:
                        if threshold > 0 and float(total) >= threshold:
                            delivery_fee = 0
                        else:
                            delivery_fee = df
        except Exception:
            pass

        final_total = float(total) + delivery_fee

        context.user_data['pending_order'] = {
            'user_id': user_data['id'],
            'cart_items': cart_items,
            'total_amount': total,
            'discount_amount': 0,
            'delivery_fee': delivery_fee,
            'payment_method_name': selected_payment_method['name'],
            'payment_method_id': payment_method_id,
            'shipping_address': {},
            'payment_number': selected_payment_method.get('payment_number', 'N/A'),
            'qr_code_url': selected_payment_method.get('qr_code_url', None)
        }

        total_str = await format_price(context, total, lang)
        final_total_str = await format_price(context, final_total, lang)

        notes = selected_payment_method.get('notes')
        notes_section = f"*Notes* - {escape_markdown(notes)}\n" if notes else ""
        account_name = selected_payment_method.get('account_name')
        account_name_section = f"*Account Name* - {escape_markdown(account_name)}\n" if account_name else ""

        if delivery_fee > 0:
            delivery_fee_str = await format_price(context, delivery_fee, lang)
            caption = (
                f"\U0001f4b0 *Payment Details*\n\n"
                f"*Wallet* - {selected_payment_method['name']}\n"
                f"{account_name_section}"
                f"*Account Number* - `{selected_payment_method.get('payment_number', 'N/A')}`\n"
                f"{notes_section}"
                f"\n*Total* - {total_str}\n"
                f"*Delivery Fee* - {delivery_fee_str}\n"
                f"*Total* - {final_total_str}\n"
                f"\nPlease transfer *{final_total_str}* to the following account:\n"
                f"*Account/Payment Number:* `{selected_payment_method.get('payment_number', 'N/A')}`\n\n"
                f"After transferring, please click 'Transferred' and send a screenshot of your payment proof.\n\n"
                f"Thank you for your purchase! \U0001f6cd️"
            )
        else:
            caption = get_text('payment_details_caption', lang).format(
                payment_method_name=selected_payment_method['name'],
                total_str=total_str,
                payment_number=selected_payment_method.get('payment_number', 'N/A'),
                notes_section=notes_section,
                account_name_section=account_name_section
            )

        keyboard = [
            [InlineKeyboardButton(get_text('transferred_button', lang), callback_data="payment_transferred")],
            [InlineKeyboardButton(get_text('cancel_payment_button', lang), callback_data="payment_cancel")],
            [InlineKeyboardButton(get_text('main_menu_button', lang), callback_data="main_menu")]
        ]
        reply_markup = InlineKeyboardMarkup(keyboard)

        qr_code_url = selected_payment_method.get('qr_code_url')

        if qr_code_url:
            try:
                await query.edit_message_media(
                    media=InputMediaPhoto(media=qr_code_url, caption=caption, parse_mode=ParseMode.MARKDOWN),
                    reply_markup=reply_markup
                )
            except Exception as e:
                logger.warning(f"Could not display QR code image from URL: {e}. Falling back to text-only.")
                await safe_edit_caption_or_text(
                    query,
                    caption,
                    reply_markup
                )
        else:
            await safe_edit_caption_or_text(
                query,
                caption,
                reply_markup
            )

    except Exception as e:
        logger.error(f"Error in process_payment: {e}", exc_info=True)
        await query.answer("An error occurred. Please try again.", show_alert=True)
        return State.CHECKOUT

    return State.PAYMENT

async def show_my_orders(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show user's order history."""
    query = update.callback_query
    lang = await get_user_lang(context)

    user = update.effective_user
    bot_id = await get_bot_id(context.bot.token)

    if not bot_id:
        await query.answer("Error: This bot is not registered correctly.", show_alert=True)
        return State.MAIN_MENU

    if await is_user_banned(user.id, bot_id):
        await query.answer("You have been banned from using this feature, Contact the admin", show_alert=True)
        return State.MAIN_MENU

    if not get_shop_status(bot_id):
        await query.answer("The shop is currently closed. Please come back later!", show_alert=True)
        return State.MAIN_MENU

    user_data = await get_or_create_user(user.id, user.username, user.first_name, user.last_name, user.username, context.bot.token)

    if not user_data:
        await query.answer("❌ Error loading orders. Please try again.", show_alert=True)
        return State.MAIN_MENU

    await query.answer()

    user_orders = get_user_orders(bot_id, user_data['id'])

    if not user_orders:
        caption = get_text('my_orders_caption_empty', lang)
        keyboard = [[InlineKeyboardButton(get_text('start_shopping_button', lang), callback_data="browse")]]
    else:
        caption = await get_bot_specific_text('my_orders_caption', lang, bot_id, context)
        keyboard = []
        for order in user_orders:
            order_date = order['created_at'].strftime("%b %d, %Y")
            final_amount_str = await format_price(context, order['final_amount'], lang)
            button_text = get_text('order_button_text', lang).format(
                order_number=order['order_number'], final_amount=final_amount_str, order_date=order_date
            )
            keyboard.append([InlineKeyboardButton(button_text, callback_data=f"order_{order['order_number']}")])

    keyboard.append([InlineKeyboardButton(get_text('main_menu_button', lang), callback_data="main_menu")])

    reply_markup = InlineKeyboardMarkup(keyboard)
    photo_url = get_poster_file_id(
        bot_id, "my_orders_poster",
        "https://www.dropbox.com/scl/fi/4lafhtx8a4vlcr4pezjnx/images-5.jpeg?rlkey=oleeoxadn3uwjl15l5oktmtpk&raw=1"
    )

    await update_menu_display(query=query, context=context, caption=caption, reply_markup=reply_markup, photo_url=photo_url)

    return State.ORDER_CONFIRMATION

async def show_order_details(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show order details."""
    query = update.callback_query
    await query.answer()
    lang = await get_user_lang(context)

    order_number = query.data.split("_")[1]
    order = get_order(order_number)

    if not order:
        await query.answer("Order not found!", show_alert=True)
        return State.ORDER_CONFIRMATION



    items = order['items']
    items_text_lines = []
    for item in items:
        item_total_price = Decimal(item.get('price', 0)) * Decimal(item.get('quantity', 0))
        item_total_str = await format_price(context, item_total_price, lang)

        item_name = escape_markdown(item.get('name', 'Unknown Product'))
        items_text_lines.append(f"• {item_name} x{item.get('quantity', 0)} - {item_total_str}")

    items_text = "\n".join(items_text_lines)


    total_amount_str = await format_price(context, order['total_amount'], lang)
    discount_amount_str = await format_price(context, order['discount_amount'], lang)
    final_amount_str = await format_price(context, order['final_amount'], lang)

    caption = (
        f"📋 *Order Details*\n\n"
        f"*Order ID:* {order['order_number']}\n"
        f"*Order Date:* {order['created_at'].strftime('%b %d, %Y %H:%M')}\n"
        f"*Payment Method:* {order['payment_method']}\n"
        f"*Status:* {order['status'].title()}\n\n"
        f"*Items:*\n{items_text}\n\n"
        f"*Subtotal:* {total_amount_str}\n"
        f"*Discount:* {discount_amount_str}\n"
        f"*Total:* {final_amount_str}\n\n"
        "Thank you for your purchase!"
    )

    keyboard = [
        [InlineKeyboardButton("🛍️ Continue Shopping", callback_data="browse")],
        [InlineKeyboardButton("🏠 Main Menu", callback_data="main_menu")]
    ]

    reply_markup = InlineKeyboardMarkup(keyboard)

    await safe_edit_caption_or_text(
        query,
        caption,
        reply_markup
    )

    return State.ORDER_CONFIRMATION

