async def handle_search_query(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Process search query and show results."""
    search_query = update.message.text

    bot_id = await get_bot_id(context.bot.token)
    if not bot_id:
        await update.message.reply_text("Error: This bot is not registered correctly.")
        return State.MAIN_MENU
    results = search_products(bot_id, search_query)

    if not results:
        await update.message.reply_text(
            text=f"❌ No products found for '{escape_markdown(search_query)}'. Try a different search term.",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("🔙 Main Menu", callback_data="main_menu")]
            ]),
            parse_mode=ParseMode.MARKDOWN
        )

        return State.SEARCH


    context.user_data["search_results"] = results
    context.user_data["current_product_index"] = 0


    await show_product_detail(update, context, results[0]['id'])

    return State.VIEW_PRODUCT

