async def my_bots_plan(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """(Main Bot Only) Displays a list of all bots created by the user as inline buttons."""
    query = update.callback_query
    await query.answer()
    owner_telegram_id = update.effective_user.id

    owned_bots = db.execute_query(
        "SELECT id, bot_full_name, bot_username, plan_name, is_active FROM managed_bots WHERE owner_telegram_id = %s ORDER BY created_at",
        (owner_telegram_id,), fetch=True
    )

    keyboard = []
    if not owned_bots:
        caption = "🤖 *My Bots*\n\nYou have not created any bots yet."
    else:
        caption = "🤖 *My Bots*\n\nTap a bot to manage it."
        for bot in owned_bots:
            name = bot.get('bot_full_name') or f"Bot ID {bot['id']}"
            username = f"@{bot['bot_username']}" if bot.get('bot_username') else ""
            status = "🟢" if bot.get('is_active') else "🔴"
            label = f"{status} {name} {username}".strip()
            keyboard.append([InlineKeyboardButton(label, callback_data=f"user_bot_options_{bot['id']}")])

    keyboard.append([InlineKeyboardButton("🔙 Back", callback_data="main_menu")])
    await safe_edit_caption_or_text(query, caption, InlineKeyboardMarkup(keyboard))

    return State.MAIN_MENU


async def check_plan_expirations(context: ContextTypes.DEFAULT_TYPE) -> None:
    """A daily job to check for and downgrade expired subscription plans."""
    logger.info("Running daily job: Checking for expired bot plans...")


    expired_bots = db.execute_query(
        """
        SELECT id, bot_token, owner_telegram_id, bot_full_name
        FROM managed_bots
        WHERE plan_name != 'Free' AND plan_expiry IS NOT NULL AND plan_expiry < NOW()
        """,
        fetch=True
    )

    if not expired_bots:
        logger.info("No expired plans found.")
        return

    downgraded_count = 0
    for bot_info in expired_bots:
        bot_id = bot_info['id']
        bot_token = bot_info['bot_token']
        owner_id = bot_info['owner_telegram_id']
        bot_name = bot_info['bot_full_name']


        success = db.execute_query(
            "UPDATE managed_bots SET plan_name = 'Free', plan_expiry = NULL, plan_start_date = NULL WHERE id = %s",
            (bot_id,)
        )

        if success:
            downgraded_count += 1
            logger.info(f"Downgraded bot {bot_id} ('{bot_name}') to Free plan.")

            try:

                expired_bot_app = Application.builder().token(bot_token).build()
                notification_text = (
                    "🔔 Your subscription plan has expired.\n\n"
                    "Your bot has been automatically downgraded to the **Free Plan**.\n\n"
                    "To restore premium features, please go to Main Menu -> Upgrade Plan."
                )
                await expired_bot_app.bot.send_message(
                    chat_id=owner_id,
                    text=notification_text,
                    parse_mode=ParseMode.MARKDOWN
                )
            except Exception as e:
                logger.error(f"Failed to send expiration notice to owner {owner_id} for bot {bot_id}: {e}")

    logger.info(f"Plan expiration check complete. Downgraded {downgraded_count} bot(s).")
async def handle_profile(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show user profile. Works from both callback query and message context."""
    query = update.callback_query
    chat_id = update.effective_chat.id

    if query:
        await query.answer()

    # Silently dismiss any lingering Share Phone Number ReplyKeyboard
    if context.user_data.pop("awaiting_phone", None):
        try:
            await context.bot.send_message(
                chat_id=chat_id,
                text="🔄 Loading profile...",
                reply_markup=ReplyKeyboardRemove()
            )
        except Exception:
            pass

    user = update.effective_user
    user_data = await get_or_create_user(user.id, user.username, user.first_name, user.last_name, user.username, context.bot.token)

    if not user_data:
        if query:
            await query.answer("❌ Error loading profile. Please try again.", show_alert=True)
        else:
            await update.effective_message.reply_text("❌ Error loading profile. Please try again.")
        return State.MAIN_MENU


    address_text = "Not set"
    if shipping_address_data := user_data.get('shipping_address'):

        if isinstance(shipping_address_data, dict):
            address_text = shipping_address_data.get('text', 'Not set')
        else:

            address_text = str(shipping_address_data)

    lang = await get_user_lang(context)
    custom_name = user_data.get('account_name') or user_data.get('first_name', 'Not set')

    caption = get_text('profile_caption_title', lang)
    caption += get_text('profile_telegram_acc', lang).format(name=f"{user_data['first_name']} {user_data.get('last_name', '') or ''}".strip())
    caption += get_text('profile_account_name', lang).format(name=custom_name)
    caption += get_text('profile_username', lang).format(username=user_data.get('username', 'N/A'))
    caption += get_text('profile_member_since', lang).format(date=user_data['created_at'].strftime('%B %d, %Y'))
    admin_st_tmpl = get_text('profile_admin_status', lang)
    if admin_st_tmpl:
        caption += admin_st_tmpl.format(is_admin=('Yes' if user_data.get('is_admin') else 'No'))
    caption += get_text('profile_contact_info', lang)
    caption += get_text('profile_contact_name', lang).format(name=custom_name)
    caption += get_text('profile_phone', lang).format(phone=user_data.get('phone_number', 'Not set'))
    caption += get_text('profile_email', lang).format(email=user_data.get('email', 'Not set'))
    caption += get_text('profile_address', lang).format(address=address_text)
    caption += get_text('profile_update_prompt', lang)

    keyboard = [
        [InlineKeyboardButton(get_text('update_name_button', lang), callback_data="update_name")],
        [InlineKeyboardButton(get_text('update_phone_button', lang), callback_data="update_phone"),
         InlineKeyboardButton(get_text('update_email_button', lang), callback_data="update_email")],
        [InlineKeyboardButton(get_text('update_address_button', lang), callback_data="update_address")],
        [InlineKeyboardButton(get_text('main_menu_button', lang), callback_data="main_menu")]
    ]

    reply_markup = InlineKeyboardMarkup(keyboard)
    bot_id = await get_bot_id(context.bot.token)
    photo_url = get_poster_file_id(
        bot_id, "profile_poster",
        "https://www.dropbox.com/scl/fi/7p3qr153u7cv10ecsobi6/images-6.jpeg?rlkey=sez9crgdh9do85yp33t690dq7&raw=1"
    )
    if query:
        await update_menu_display(query=query, context=context, caption=caption, reply_markup=reply_markup, photo_url=photo_url)
    else:
        await context.bot.send_photo(
            chat_id=chat_id,
            photo=photo_url,
            caption=caption,
            reply_markup=reply_markup,
            parse_mode=ParseMode.MARKDOWN
        )

    return State.PROFILE
async def handle_update_name(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Prompts the user to enter their new name and stores the query for later."""
    query = update.callback_query
    await query.answer()


    context.user_data['pending_update'] = {'type': 'name', 'query': query}

    await safe_edit_caption_or_text(
        query,
        "✏️ *Update Name*\n\nPlease enter the name you would like to use for your account (e.g., your full name).",
        InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Back to Profile", callback_data="profile")]])
    )
    return State.AWAITING_NAME_UPDATE

async def process_name_update(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Updates the user's account name in the database and returns to the profile view."""
    new_name = update.message.text
    user_id = update.effective_user.id
    bot_id = await get_bot_id(context.bot.token)

    db.execute_query(
        "UPDATE users SET account_name = %s, updated_at = CURRENT_TIMESTAMP WHERE telegram_id = %s AND bot_id = %s",
        (new_name, user_id, bot_id)
    )

    await update.message.reply_text("✅ Your account name has been updated.")


    if 'pending_update' in context.user_data and 'query' in context.user_data['pending_update']:
        original_query = context.user_data['pending_update']['query']

        new_update = Update(update.update_id, message=None, callback_query=original_query)
        del context.user_data['pending_update']
        return await handle_profile(new_update, context)


    return await start(update, context)

async def _return_after_profile_field(update: Update, context: ContextTypes.DEFAULT_TYPE, filled_field: str):
    """
    Called after phone or address is filled/skipped from checkout flow.
    - If the other required field is still missing, show the incomplete profile screen again.
    - If both are now filled/skipped, re-trigger checkout automatically.
    filled_field: 'phone' or 'address'
    """
    checkout_origin = context.user_data.get('checkout_origin')
    if not checkout_origin:
        # Not from checkout flow — go to normal profile
        return await handle_profile(update, context)

    user = update.effective_user
    user_data = await get_or_create_user(user.id, user.username, user.first_name, user.last_name, user.username, context.bot.token)
    lang = await get_user_lang(context)

    phone_number = user_data.get('phone_number')
    shipping_address = user_data.get('shipping_address')

    still_missing_phone = not phone_number
    still_missing_address = not shipping_address

    # If both are now filled/skipped, clear origin and re-trigger checkout
    if not still_missing_phone and not still_missing_address:
        context.user_data.pop('checkout_origin', None)
        # Simulate a fake callback query re-trigger by building the incomplete profile keyboard
        # We can't re-trigger a callback, so we send a button that does it
        if update.message:
            await update.message.reply_text(
                "✅ Profile complete! Tap below to continue your purchase:",
                reply_markup=InlineKeyboardMarkup([[
                    InlineKeyboardButton("🛒 Continue to Checkout", callback_data=checkout_origin)
                ]])
            )
        else:
            query = update.callback_query
            await safe_edit_caption_or_text(
                query,
                "✅ Profile complete! Tap below to continue your purchase:",
                InlineKeyboardMarkup([[
                    InlineKeyboardButton("🛒 Continue to Checkout", callback_data=checkout_origin)
                ]])
            )
        return State.PROFILE

    # Otherwise, show updated incomplete profile screen
    caption = get_text('profile_incomplete_title', lang) + "\n\n" + get_text('profile_incomplete_body', lang)
    if still_missing_phone:
        caption += get_text('missing_phone_number', lang)
    if still_missing_address:
        caption += get_text('missing_shipping_address', lang)
    caption += get_text('profile_incomplete_instruction', lang)

    keyboard = []
    if still_missing_phone:
        keyboard.append([InlineKeyboardButton(get_text('add_phone_button', lang), callback_data="update_phone")])
    if still_missing_address:
        keyboard.append([InlineKeyboardButton(get_text('add_address_button', lang), callback_data="update_address")])

    back_button_callback = "view_cart" if not checkout_origin.startswith("buy_now_direct_") else f"product_{checkout_origin.split('_')[3]}"
    keyboard.append([InlineKeyboardButton(get_text('back_button', lang), callback_data=back_button_callback)])

    reply_markup = InlineKeyboardMarkup(keyboard)

    if update.message:
        await update.message.reply_text(caption, reply_markup=reply_markup, parse_mode=ParseMode.MARKDOWN)
    else:
        await safe_edit_caption_or_text(update.callback_query, caption, reply_markup)

    return State.PROFILE

