async def handle_phone_input(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Process phone number input."""
    if update.message.contact:
        phone_number = update.message.contact.phone_number
    else:
        phone_number = update.message.text

    user = update.effective_user
    user_data = await get_or_create_user(user.id, user.username, user.first_name, user.last_name, user.username, context.bot.token)

    if user_data:
        success = db.execute_query(
            "UPDATE users SET phone_number = %s, updated_at = CURRENT_TIMESTAMP WHERE id = %s",
            (phone_number, user_data['id'])
        )

        if success:
            await update.message.reply_text("✅ Phone number saved.", reply_markup=ReplyKeyboardRemove())
        else:
            await update.message.reply_text(
                "❌ Failed to update phone number. Please try again.",
                reply_markup=ReplyKeyboardRemove()
            )
            await update.message.reply_text(
                "You can return to your profile:",
                reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Back to Profile", callback_data="profile")]])
            )
            context.user_data.pop("awaiting_phone", None)
            return State.PROFILE

    context.user_data.pop("awaiting_phone", None)
    return await _return_after_profile_field(update, context, 'phone')

