async def affiliamarketing(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Shows affiliate program sub-menu with options."""
    query = update.callback_query
    if query:
        await query.answer()

    try:
        user = update.effective_user
        lang = await get_user_lang(context)

        affiliate_user_data = await get_or_create_affiliate_user(user.id, user.username, user.full_name)

        if not affiliate_user_data:
            if query: await query.answer("❌ Could not load your affiliate profile.", show_alert=True)
            else: await update.effective_message.reply_text("❌ Could not load your affiliate profile.")
            return State.SETTINGS

        # Get the MAIN bot's username to create a fixed, global referral link
        main_bot_details = await get_bot_details(TOKEN)
        if main_bot_details and main_bot_details.get('username'):
            # The referral code IS the user's own telegram_id
            user_telegram_id = affiliate_user_data.get('telegram_id')
            referral_link = f"https://t.me/{main_bot_details['username']}?start=ref_{user_telegram_id}"
        else:
            referral_link = "Error: Main bot details not found."

        # Stats: count referred users and total commissions from the global tables
        referred_count_res = db.execute_query(
            "SELECT COUNT(*) AS cnt FROM affiliate_users WHERE referred_by_telegram_id = %s",
            (user.id,), fetch=True
        )
        referred_count = referred_count_res[0]['cnt'] if referred_count_res else 0

        commissions_res = db.execute_query(
            "SELECT COALESCE(SUM(commission_mmk), 0) AS total FROM referral_commissions WHERE referrer_telegram_id = %s",
            (user.id,), fetch=True
        )
        total_commission = commissions_res[0]['total'] if commissions_res else 0

        unpaid_res = db.execute_query(
            "SELECT COALESCE(SUM(commission_mmk), 0) AS unpaid FROM referral_commissions WHERE referrer_telegram_id = %s AND is_paid = FALSE",
            (user.id,), fetch=True
        )
        unpaid_amount = unpaid_res[0]['unpaid'] if unpaid_res else 0

        wallet_info = ""
        if affiliate_user_data.get('payment_type'):
            wallet_info = f"\n\n*Wallet Info:*\n{escape_markdown(affiliate_user_data['payment_type'])}\n{escape_markdown(affiliate_user_data['account_name'])}\n`{affiliate_user_data['wallet_number']}`\n"

        pct = affiliate_user_data.get('commission_percent', 10)
        caption = (
            "🤝 *Affiliate Program*\n\n"
            f"Share your referral link below. You earn {pct}% commission whenever someone you refer upgrades their plan on any bot they create.\n\n"
            f"*Your Global Referral Link:*\n`{referral_link}`\n\n"
            "Your stats are combined across all bots.\n\n"
            f"*Total Referred Users:* {referred_count}\n"
            f"*All Time Earned:* {total_commission:,.0f} MMK\n"
            f"*Unpaid Amount:* {unpaid_amount:,.0f} MMK"
            f"{wallet_info}"
        )

        keyboard = [
            [InlineKeyboardButton("💳 Set Wallet Number", callback_data="aff_set_wallet")],
            [InlineKeyboardButton("💸 Withdraw", callback_data="aff_withdraw_request")],
            [InlineKeyboardButton("Affiliate T&C", web_app=WebAppInfo(url="https://saimaunglenn.github.io/Telegram-E-commerce-User-Guide/guide.html"))],
            [InlineKeyboardButton("🔙 Back to Settings", callback_data="settings")]
        ]
        if query:
            await safe_edit_caption_or_text(query, caption, InlineKeyboardMarkup(keyboard))
        else:
            await update.effective_message.reply_text(caption, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode=ParseMode.MARKDOWN)
    except Exception as e:
        logger.error(f"Affiliate marketing view error: {e}")
        if query: await query.answer("❌ Failed to load affiliate info.", show_alert=True)
        else: await update.effective_message.reply_text("❌ Failed to load affiliate info.")

    return State.SETTINGS


