async def super_admin_all_bots(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """(Super Admin) Fetches and displays details for all bots as an Excel file."""
    query = update.callback_query

    if update.effective_user.id != SUPER_ADMIN_TELEGRAM_ID:
        await query.answer("❌ Access Denied.", show_alert=True)
        return State.SETTINGS

    await query.answer("Fetching all bot details...")

    all_bots = db.execute_query(
        "SELECT id, bot_full_name, bot_username FROM managed_bots ORDER BY id",
        fetch=True
    )

    if not all_bots:
        await query.message.reply_text("ℹ️ No bots have been created in the system yet.")
        return State.SETTINGS

    try:
        import io

        wb = Workbook()
        ws = wb.active
        ws.title = "All Bots"

        # Header style
        header_fill = PatternFill("solid", start_color="2E86AB", end_color="2E86AB")
        header_font = Font(name="Arial", bold=True, color="FFFFFF", size=11)
        header_align = Alignment(horizontal="center", vertical="center")

        headers = ["#", "Bot Name", "Bot Username", "Admins"]
        col_widths = [5, 30, 25, 60]
        for col, (header, width) in enumerate(zip(headers, col_widths), 1):
            cell = ws.cell(row=1, column=col, value=header)
            cell.font = header_font
            cell.fill = header_fill
            cell.alignment = header_align
            ws.column_dimensions[cell.column_letter].width = width

        ws.row_dimensions[1].height = 20

        # Row styles
        row_font = Font(name="Arial", size=10)
        alt_fill = PatternFill("solid", start_color="F0F4F8", end_color="F0F4F8")

        for i, bot in enumerate(all_bots, 1):
            bot_id = bot['id']
            bot_name = bot.get('bot_full_name') or 'N/A'
            bot_username = f"@{bot.get('bot_username')}" if bot.get('bot_username') else 'N/A'

            admins = db.execute_query(
                "SELECT username FROM users WHERE bot_id = %s AND is_admin = TRUE ORDER BY username",
                (bot_id,), fetch=True
            )
            admin_list_str = ", ".join([f"@{a['username']}" for a in admins if a['username']])
            if not admin_list_str:
                admin_list_str = "No admins found"

            row_data = [i, bot_name, bot_username, admin_list_str]
            excel_row = i + 1
            fill = alt_fill if i % 2 == 0 else None

            for col, value in enumerate(row_data, 1):
                cell = ws.cell(row=excel_row, column=col, value=value)
                cell.font = row_font
                cell.alignment = Alignment(vertical="center", wrap_text=(col == 4))
                if fill:
                    cell.fill = fill

            ws.row_dimensions[excel_row].height = 18

        # Freeze header row
        ws.freeze_panes = "A2"

        # Save to buffer
        buffer = io.BytesIO()
        wb.save(buffer)
        buffer.seek(0)

        now_str = datetime.datetime.now().strftime("%Y%m%d_%H%M")
        filename = f"all_bots_{now_str}.xlsx"

        await context.bot.send_document(
            chat_id=query.message.chat_id,
            document=buffer,
            filename=filename,
            caption=f"🤖 *All Bots Report*\n\nTotal: {len(all_bots)} bots\nGenerated: {datetime.datetime.now().strftime('%Y-%m-%d %H:%M')}",
            parse_mode=ParseMode.MARKDOWN
        )

    except Exception as e:
        logger.error(f"Error generating bots Excel: {e}")
        await query.message.reply_text(f"❌ Error generating Excel file: {e}")

    return State.SETTINGS


async def toggle_global_maintenance(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Toggles the GLOBAL maintenance mode for ALL bots."""
    query = update.callback_query
    await query.answer()


    if not (update.effective_user.id == SUPER_ADMIN_TELEGRAM_ID and context.bot.token == TOKEN):
        await query.answer("❌ This is a Super Admin command on the main bot only.", show_alert=True)
        return State.SETTINGS


    current_setting = db.execute_query("SELECT value FROM global_settings WHERE key = 'maintenance_mode'", fetch=True)
    is_currently_on = current_setting and current_setting[0]['value'] == 'true'

    new_status_str = 'false' if is_currently_on else 'true'


    db.execute_query(
        "UPDATE global_settings SET value = %s WHERE key = 'maintenance_mode'",
        (new_status_str,)
    )


    context.bot_data['maintenance_mode'] = (new_status_str == 'true')

    await query.answer(f"Global maintenance mode is now {'ON' if not is_currently_on else 'OFF'}.", show_alert=True)


    return await start(update, context)

async def manage_affiliates_menu(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """(Super Admin) Displays list of affiliates sorted by referrals/unpaid earnings."""
    query = update.callback_query
    if query:
        await query.answer()

    if not (update.effective_user.id == SUPER_ADMIN_TELEGRAM_ID and context.bot.token == TOKEN):
        if query: await query.answer("❌ Access Denied.", show_alert=True)
        else: await update.effective_message.reply_text("❌ Access Denied.")
        return State.SETTINGS

    # Query to get affiliates sorted by unpaid total (highest first) then by total referrals
    sql = """
        SELECT 
            au.telegram_id, 
            au.full_name, 
            au.username,
            COUNT(rc.id) as referral_count,
            COALESCE(SUM(CASE WHEN rc.is_paid = FALSE THEN rc.commission_mmk ELSE 0 END), 0) as unpaid_total
        FROM affiliate_users au
        LEFT JOIN referral_commissions rc ON au.telegram_id = rc.referrer_telegram_id
        GROUP BY au.telegram_id
        HAVING COUNT(rc.id) > 0
        ORDER BY unpaid_total DESC, referral_count DESC
        LIMIT 20
    """
    affiliates = db.execute_query(sql, fetch=True)

    caption = "🤝 *Pay Commission*\n\nSelect a user to view details or pay commissions.\nSorted by Highest Unpaid Earnings."
    keyboard = [
        [InlineKeyboardButton("📈 Upgrade User %", callback_data="super_upgrade_percent")]
    ]

    if not affiliates:
        caption = "ℹ️ No active affiliates found."
    else:
        for aff in affiliates:
            name = aff['full_name'] or aff['username'] or str(aff['telegram_id'])
            unpaid = float(aff['unpaid_total'])
            count = aff['referral_count']
            
            # Button format: Name | Refs: 5 | 50,000 MMK
            btn_text = f"{name[:15]}.. | Ref:{count} | {unpaid:,.0f} MMK"
            keyboard.append([InlineKeyboardButton(btn_text, callback_data=f"view_affiliate_{aff['telegram_id']}")])

    keyboard.append([InlineKeyboardButton("🔙 Back", callback_data="settings")])
    
    if query:
        await safe_edit_caption_or_text(query, caption, InlineKeyboardMarkup(keyboard))
    else:
        await update.effective_message.reply_text(caption, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode=ParseMode.MARKDOWN)
    return State.MANAGE_AFFILIATES

async def view_affiliate_details(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """(Super Admin) Shows detailed stats for a specific affiliate and Pay button."""
    query = update.callback_query
    await query.answer()
    
    target_id = int(query.data.split('_')[-1])
    
    # Fetch detailed stats
    sql = """
        SELECT 
            au.telegram_id, au.full_name, au.username, au.payment_type, au.account_name, au.wallet_number,
            COUNT(rc.id) as total_referrals,
            COALESCE(SUM(rc.commission_mmk), 0) as lifetime_earnings,
            COALESCE(SUM(CASE WHEN rc.is_paid = FALSE THEN rc.commission_mmk ELSE 0 END), 0) as unpaid_balance
        FROM affiliate_users au
        LEFT JOIN referral_commissions rc ON au.telegram_id = rc.referrer_telegram_id
        WHERE au.telegram_id = %s
        GROUP BY au.telegram_id
    """
    data = db.execute_query(sql, (target_id,), fetch=True)
    
    if not data:
        await query.answer("User not found.", show_alert=True)
        return await manage_affiliates_menu(update, context)
        
    user_stats = data[0]
    unpaid_balance = float(user_stats['unpaid_balance'])
    
    caption = (
        f"👤 *Affiliate Details*\n\n"
        f"**Name:** {escape_markdown(user_stats['full_name'] or 'N/A')}\n"
        f"**Username:** @{escape_markdown(user_stats['username'] or 'N/A')}\n"
        f"**ID:** `{user_stats['telegram_id']}`\n\n"
        f"Payment - {escape_markdown(user_stats.get('payment_type') or 'Not Set')}\n"
        f"Account Name - {escape_markdown(user_stats.get('account_name') or 'Not Set')}\n"
        f"Wallet Number - `{user_stats.get('wallet_number') or 'Not Set'}`\n\n"
        f"📊 *Stats:*\n"
        f"• Total Referred Upgrades: {user_stats['total_referrals']}\n"
        f"• Lifetime Earnings: {user_stats['lifetime_earnings']:,.0f} MMK\n"
        f"• **Unpaid Balance:** {unpaid_balance:,.0f} MMK\n"
    )
    
    keyboard = []
    if unpaid_balance > 0:
        keyboard.append([InlineKeyboardButton(f"💸 Pay {unpaid_balance:,.0f} MMK", callback_data=f"pay_affiliate_{target_id}")])
    
    keyboard.append([InlineKeyboardButton("🔙 Back to List", callback_data="manage_affiliates")])
    
    await safe_edit_caption_or_text(query, caption, InlineKeyboardMarkup(keyboard))
    return State.AFFILIATE_USER_DETAIL

async def confirm_pay_affiliate(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """(Super Admin) Executes the payment (marks commissions as paid) and notifies the user."""
    query = update.callback_query

    target_id = int(query.data.split('_')[-1])

    # Double check balance
    check_sql = "SELECT COALESCE(SUM(commission_mmk), 0) as unpaid FROM referral_commissions WHERE referrer_telegram_id = %s AND is_paid = FALSE"
    res = db.execute_query(check_sql, (target_id,), fetch=True)
    amount = res[0]['unpaid'] if res else 0

    if amount <= 0:
        await query.answer("❌ Balance is already zero.", show_alert=True)
        return await view_affiliate_details(update, context)

    # Update DB
    update_sql = "UPDATE referral_commissions SET is_paid = TRUE WHERE referrer_telegram_id = %s AND is_paid = FALSE"
    db.execute_query(update_sql, (target_id,))

    await query.answer(f"✅ Marked {amount:,.0f} MMK as PAID.", show_alert=True)

    # Notify the affiliate user
    try:
        await context.bot.send_message(
            chat_id=target_id,
            text=f"🎉 *Congrats! Your withdrawal was approved!*\n\n"
                 f"*{amount:,.0f} MMK* has been marked as paid. Thank you!",
            parse_mode=ParseMode.MARKDOWN
        )
    except Exception as e:
        logger.warning(f"Could not notify affiliate user {target_id}: {e}")

    # Refresh view
    return await view_affiliate_details(update, context)


async def aff_withdraw_request(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """User requests a withdrawal — shows confirmation with wallet info and unpaid amount."""
    query = update.callback_query
    await query.answer()

    user = update.effective_user

    # Fetch affiliate data
    aff_data = await get_or_create_affiliate_user(user.id, user.username, user.full_name)
    if not aff_data:
        await query.answer("❌ Could not load your affiliate profile.", show_alert=True)
        return State.SETTINGS

    # Fetch unpaid amount
    unpaid_res = db.execute_query(
        "SELECT COALESCE(SUM(commission_mmk), 0) AS unpaid FROM referral_commissions WHERE referrer_telegram_id = %s AND is_paid = FALSE",
        (user.id,), fetch=True
    )
    unpaid_amount = float(unpaid_res[0]['unpaid']) if unpaid_res else 0.0

    if unpaid_amount <= 0:
        await query.answer("❌ You have no unpaid amount to withdraw.", show_alert=True)
        return State.SETTINGS

    wallet_type = aff_data.get('payment_type') or 'Not Set'
    account_name = aff_data.get('account_name') or 'Not Set'
    wallet_number = aff_data.get('wallet_number') or 'Not Set'

    if wallet_type == 'Not Set' or wallet_number == 'Not Set':
        await safe_edit_caption_or_text(
            query,
            "⚠️ *No Wallet Info Found*\n\nPlease set your wallet number first before requesting a withdrawal.",
            InlineKeyboardMarkup([[InlineKeyboardButton("💳 Set Wallet Number", callback_data="aff_set_wallet"),
                                   InlineKeyboardButton("🔙 Back", callback_data="affiliate")]])
        )
        return State.SETTINGS

    caption = (
        "💸 *Withdrawal Confirmation*\n\n"
        f"*Amount to Withdraw:* {unpaid_amount:,.0f} MMK\n\n"
        f"*Wallet Info:*\n"
        f"• Type: {escape_markdown(wallet_type)}\n"
        f"• Account Name: {escape_markdown(account_name)}\n"
        f"• Number: `{wallet_number}`\n\n"
        "Please confirm your withdrawal request."
    )
    keyboard = [
        [InlineKeyboardButton("✅ Confirm Withdraw", callback_data="aff_withdraw_confirm"),
         InlineKeyboardButton("❌ Cancel", callback_data="affiliate")]
    ]
    await safe_edit_caption_or_text(query, caption, InlineKeyboardMarkup(keyboard))
    return State.SETTINGS


