    try:
        await context.bot.send_message(
            chat_id=SUPER_ADMIN_TELEGRAM_ID,
            text=admin_caption,
            reply_markup=admin_keyboard,
            parse_mode=ParseMode.MARKDOWN
        )
    except Exception as e:
        logger.error(f"Could not send withdrawal request to super admin: {e}")

    # Confirm to user
    await safe_edit_caption_or_text(
        query,
        "✅ *Withdrawal request submitted!*\n\nYour request has been sent to the admin. You will be notified once it's processed.",
        InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Back", callback_data="affiliate")]])
    )
    return State.SETTINGS


