async def handle_create_your_bot(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Creates a new bot via Telegram Managed Bots API — no BotFather visit required."""
    query = update.callback_query
    if query:
        await query.answer()

    owner_telegram_id = update.effective_user.id

    # 1. Check existing bots count
    owned_bots = db.execute_query(
        "SELECT plan_name FROM managed_bots WHERE owner_telegram_id = %s",
        (owner_telegram_id,), fetch=True
    ) or []
    owned_bots_count = len(owned_bots)

    # 2. Calculate User's Total Limit
    bot_limit = 0
    upgraded_plans_found = any(bot['plan_name'].lower() != 'free' for bot in owned_bots)

    if upgraded_plans_found:
        for bot in owned_bots:
            plan_name = bot['plan_name'].lower()
            if plan_name != 'free':
                plan_limits = get_plan_limits(plan_name)
                bot_limit += plan_limits.get('total_bots', 0)
    else:
        bot_limit = get_plan_limits('free').get('total_bots', 1)

    # 3. STRICT LIMIT CHECK
    if owned_bots_count >= bot_limit:
        caption = (
            f"❌ *Bot Limit Reached*\n\n"
            f"You have {owned_bots_count}/{bot_limit} bots.\n\n"
            "You have reached the limit of total bots. Remove some of your bots or upgrade one bot."
        )
        keyboard = [
            [InlineKeyboardButton("🤖 Manage My Bots", callback_data="user_manage_my_bots")],
            [InlineKeyboardButton("🔙 Back", callback_data="settings")]
        ]
        if query:
            await safe_edit_caption_or_text(query, caption, InlineKeyboardMarkup(keyboard))
        else:
            await update.message.reply_text(caption, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode=ParseMode.MARKDOWN)
        return State.SETTINGS

    # 4. Auto-suggest bot username based on owner's Telegram ID
    main_bot_row = db.execute_query(
        "SELECT bot_username FROM managed_bots WHERE bot_token = %s", (TOKEN,), fetch=True
    )
    manager_username = main_bot_row[0]['bot_username'] if main_bot_row else "tg_ecommerce_official_bot"

    raw_username = (update.effective_user.username or str(owner_telegram_id)).lower()
    # Keep only alphanumeric chars (Telegram username rules)
    clean_username = re.sub(r'[^a-z0-9]', '', raw_username)
    suggested_username = f"{clean_username}tgecmbot"
    suggested_name = f"{update.effective_user.first_name or 'My'} Shop"

    # Un-blacklist if user is explicitly re-creating this bot username
    try:
        db.execute_query(
            "DELETE FROM deleted_managed_bots WHERE LOWER(bot_username) = LOWER(%s)",
            (suggested_username.lower(),)
        )
    except Exception:
        pass

    # 5. Build Managed Bot creation link
    create_link = (
        f"https://t.me/newbot/{manager_username}/{suggested_username}"
        f"?name={suggested_name.replace(' ', '+')}"
    )

    caption = (
        "🤖 *Create Your Own Shop*\n\n"
        "Click *'Create My Bot Now'* for one click create bot\n\n"
        "Click *'Use My API Token'* to use your own bot's API\n\n"
        f"*Bot Limit:* {owned_bots_count}/{bot_limit}\n\n"
        "After you confirm, your bot will start automatically."
    )

    keyboard = [
        [InlineKeyboardButton("🚀 Create My Bot Now", url=create_link)],
        [InlineKeyboardButton("🔑 Use My API Token", callback_data="use_my_api_token")],
        [InlineKeyboardButton("🔙 Back", callback_data="settings")]
    ]
    reply_markup = InlineKeyboardMarkup(keyboard)

    if query:
        await safe_edit_caption_or_text(query, caption, reply_markup)
    else:
        await update.message.reply_text(caption, reply_markup=reply_markup, parse_mode=ParseMode.MARKDOWN)

    return State.SETTINGS

