async def handle_managed_bot_update(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Handles the managed_bot update from Telegram when a user creates a new bot
    via the Managed Bots link. Fetches the token and launches the bot automatically.
    """
    try:
        # Extract managed_bot data from raw update
        raw = update.to_dict() if hasattr(update, 'to_dict') else {}
        managed_bot_data = raw.get('managed_bot', {})

        if not managed_bot_data:
            return  # Silent — normal updates, no warning needed

        new_bot_info = managed_bot_data.get('bot', {})
        new_bot_id = new_bot_info.get('id')
        new_bot_username = new_bot_info.get('username', 'unknown')
        new_bot_full_name = new_bot_info.get('first_name', 'Unknown')
        owner_telegram_id = managed_bot_data.get('user', {}).get('id')
        owner_full_name = managed_bot_data.get('user', {}).get('first_name', 'User')

        if not new_bot_id or not owner_telegram_id:
            logger.error("managed_bot update missing bot id or owner id.")
            return

        logger.info(f"Managed bot created: @{new_bot_username} by user {owner_telegram_id}")

        # Fetch the new bot's token via getManagedBotToken
        try:
            response = requests.post(
                f"https://api.telegram.org/bot{context.bot.token}/getManagedBotToken",
                json={"user_id": new_bot_id},
                timeout=10
            )
            result = response.json()
            if not result.get('ok'):
                logger.error(f"getManagedBotToken failed: {result}")
                return
            # result['result'] may be a string token directly, or a dict with 'token' key
            raw_result = result['result']
            if isinstance(raw_result, str):
                new_bot_token = raw_result
            elif isinstance(raw_result, dict):
                new_bot_token = raw_result.get('token')
            else:
                logger.error(f"Unexpected getManagedBotToken result format: {raw_result}")
                return
            if not new_bot_token:
                logger.error(f"Could not extract token from result: {raw_result}")
                return
        except Exception as e:
            logger.error(f"Failed to call getManagedBotToken: {e}")
            return

        # Check if this bot already exists (by username — token may have changed via revoke)
        existing_by_username = db.execute_query(
            "SELECT id, bot_token FROM managed_bots WHERE LOWER(bot_username) = LOWER(%s)",
            (new_bot_username,), fetch=True
        )

        if existing_by_username:
            existing_id = existing_by_username[0]['id']
            existing_token = existing_by_username[0]['bot_token']

            if existing_token == new_bot_token:
                # Exact same token — already running, nothing to do
                logger.info(f"Bot @{new_bot_username} already registered with same token, skipping.")
                return

            # Token changed (admin revoked) — update token and resume, data preserved
            logger.info(f"Bot @{new_bot_username} token rotated, resuming with new token.")
            db.execute_query(
                "UPDATE managed_bots SET bot_token = %s, bot_full_name = %s, is_active = TRUE WHERE id = %s",
                (new_bot_token, new_bot_full_name, existing_id)
            )
            await bot_queue.put(new_bot_token)
            try:
                await context.bot.send_message(
                    chat_id=owner_telegram_id,
                    text=(
                        f"🔄 *Your bot token was refreshed!*\n\n"
                        f"*Bot:* @{escape_markdown(new_bot_username)}\n\n"
                        "Your bot is resuming automatically. All your data is safe. ✅"
                    ),
                    parse_mode=ParseMode.MARKDOWN
                )
            except Exception as e:
                logger.error(f"Failed to notify owner of token refresh: {e}")
            try:
                await context.bot.send_message(
                    chat_id=SUPER_ADMIN_TELEGRAM_ID,
                    text=(
                        f"🔄 *Managed Bot Token Refreshed*\n\n"
                        f"👤 *Owner:* {escape_markdown(owner_full_name)} (`{owner_telegram_id}`)\n"
                        f"🤖 *Bot:* {escape_markdown(new_bot_full_name)} (@{escape_markdown(new_bot_username)})"
                    ),
                    parse_mode=ParseMode.MARKDOWN
                )
            except Exception as e:
                logger.error(f"Failed to notify super admin of token refresh: {e}")
            return

        # Check if this bot was previously deleted/removed
        deleted_entry = db.execute_query(
            "SELECT id FROM deleted_managed_bots WHERE LOWER(bot_username) = LOWER(%s)",
            (new_bot_username,), fetch=True
        )
        if deleted_entry:
            logger.info(f"Managed bot update for @{new_bot_username} ignored because bot was previously deleted/removed.")
            return

        # New bot — register in DB
        db.execute_query(
            "INSERT INTO managed_bots (bot_token, owner_telegram_id, bot_username, bot_full_name) "
            "VALUES (%s, %s, %s, %s) ON CONFLICT (bot_token) DO NOTHING;",
            (new_bot_token, owner_telegram_id, new_bot_username, new_bot_full_name)
        )

        # --- Trial Logic: 3-day Pro trial, one-time per owner+bot ---
        new_row = db.execute_query(
            "SELECT id FROM managed_bots WHERE bot_token = %s", (new_bot_token,), fetch=True
        )
        trial_granted = False
        if new_row:
            trial_granted = await grant_trial_if_eligible(owner_telegram_id, new_bot_username, new_row[0]['id'])

        # Set TeleShop logo as profile photo for new bot
        try:
            logo_path = "/opt/teleshop/logo.png"
            if os.path.exists(logo_path):
                with open(logo_path, "rb") as logo_file:
                    photo_response = requests.post(
                        f"https://api.telegram.org/bot{new_bot_token}/setMyProfilePhoto",
                        files={"photo": logo_file},
                        timeout=15
                    )
                if photo_response.json().get("ok"):
                    logger.info(f"Profile photo set for @{new_bot_username}")
                else:
                    logger.error(f"Profile photo failed: {photo_response.json()}")
        except Exception as e:
            logger.error(f"Failed to set profile photo for @{new_bot_username}: {e}")

        # Launch bot
        await bot_queue.put(new_bot_token)

        # Notify owner — setting up first, then edit to "ready" after backend warms up
        bot_name_esc = escape_markdown(new_bot_full_name)
        bot_username_esc = escape_markdown(new_bot_username)
        deep_link = f"https://t.me/{new_bot_username}?start=start"
        trial_line = "\n🎁 *3-Day Pro Trial activated!* Enjoy all Pro features until it expires.\n" if trial_granted else ""

        setup_msg = None
        try:
            setup_msg = await context.bot.send_message(
                chat_id=owner_telegram_id,
                text=(
                    f"⏳ *Setting up your bot...*\n\n"
                    f"*Bot Name:* {bot_name_esc}\n"
                    f"*Username:* @{bot_username_esc}\n\n"
                    "This takes about 15 seconds. Please don't block or delete the bot — "
                    "it will be ready shortly. ⚙️"
                ),
                parse_mode=ParseMode.MARKDOWN
            )
        except Exception as e:
            logger.error(f"Failed to notify owner {owner_telegram_id}: {e}")

        async def _finalize_ready_notice():
            await asyncio.sleep(15)
            ready_text = (
                f"🎉 *Your bot is ready!*\n\n"
                f"*Bot Name:* {bot_name_esc}\n"
                f"*Username:* @{bot_username_esc}\n"
                f"{trial_line}\n"
                f"Tap below to open your new shop bot and start setting it up!\n\n"
                "You can customize everything from the Admin Panel inside your bot."
            )
            reply_markup = InlineKeyboardMarkup([
                [InlineKeyboardButton(f"🤖 Open {new_bot_full_name}", url=deep_link)]
            ])
            try:
                if setup_msg:
                    await context.bot.edit_message_text(
                        chat_id=owner_telegram_id,
                        message_id=setup_msg.message_id,
                        text=ready_text,
                        parse_mode=ParseMode.MARKDOWN,
                        reply_markup=reply_markup
                    )
                else:
                    await context.bot.send_message(
                        chat_id=owner_telegram_id,
                        text=ready_text,
                        parse_mode=ParseMode.MARKDOWN,
                        reply_markup=reply_markup
                    )
            except Exception as e:
                logger.error(f"Failed to send ready notice to {owner_telegram_id}: {e}")

        asyncio.create_task(_finalize_ready_notice())

        # Notify super admin
        try:
            await context.bot.send_message(
                chat_id=SUPER_ADMIN_TELEGRAM_ID,
                text=(
                    f"🤖 *New Managed Bot Created*\n\n"
                    f"👤 *Owner:* {escape_markdown(owner_full_name)} (`{owner_telegram_id}`)\n"
                    f"🤖 *Bot:* {escape_markdown(new_bot_full_name)} (@{escape_markdown(new_bot_username)})"
                ),
                parse_mode=ParseMode.MARKDOWN
            )
        except Exception as e:
            logger.error(f"Failed to notify super admin: {e}")
        # Send /start via Telethon userbot
        try:
            import subprocess, os as _os
            _result = subprocess.run(
                [_os.path.join(_os.path.dirname(__file__) or '.', 'Telethon.py'), new_bot_username],
                capture_output=True, text=True, timeout=30,
            )
            if _result.returncode == 0:
                logger.info(f'Superadmin chat established with @{new_bot_username}')
            else:
                logger.warning(f'Superadmin chat failed for @{new_bot_username}: {_result.stderr.strip()}')
        except Exception as _e:
            logger.warning(f'Superadmin send_start exception for @{new_bot_username}: {_e}')

    except Exception as e:
        logger.error(f"handle_managed_bot_update error: {e}", exc_info=True)


async def is_token_valid(token: str) -> bool:
    """Checks with Telegram if a bot token is valid."""
    try:

        temp_bot = Application.builder().token(token).build().bot
        await temp_bot.get_me()
        return True
    except telegram.error.InvalidToken:
        return False
    except Exception as e:
        logger.error(f"An unexpected error occurred during token validation: {e}")
        return False



