async def handle_bot_token_input(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Receives and validates a bot API token from the user with a processing animation."""
    bot_token = update.message.text.strip()
    owner_telegram_id = update.effective_user.id
    user_full_name = update.effective_user.full_name

    # Start the animation
    status_message = await update.message.reply_text("Processing.")
    animation_task = asyncio.create_task(
        send_processing_animation(context, status_message.chat_id, status_message.message_id)
    )

    try:
        # --- Validation Logic ---
        existing_bot = db.execute_query("SELECT id FROM managed_bots WHERE bot_token = %s", (bot_token,), fetch=True)
        if existing_bot:
            await status_message.edit_text("❌ This bot has already been registered in our system. Please try another token.")
            return State.AWAITING_BOT_TOKEN

        # --- Check if this is a token renewal for an existing bot (same username, token changed) ---
        bot_details_check = await get_bot_details(bot_token)
        if bot_details_check:
            new_username = bot_details_check.get('username', '').lower()
            new_full_name = bot_details_check.get('full_name', 'Unknown')
            orphaned_bot = db.execute_query(
                "SELECT id FROM managed_bots WHERE LOWER(bot_username) = %s AND (is_active = FALSE OR bot_token != %s)",
                (new_username, bot_token), fetch=True
            )
            if orphaned_bot:
                orphaned_id = orphaned_bot[0]['id']
                # Resume: update the token and reactivate, data fully preserved
                db.execute_query(
                    "UPDATE managed_bots SET bot_token = %s, bot_full_name = %s, is_active = TRUE WHERE id = %s",
                    (bot_token, new_full_name, orphaned_id)
                )
                await bot_queue.put(bot_token)
                animation_task.cancel()
                await status_message.delete()
                bot_name_esc = escape_markdown(new_full_name)
                bot_user_esc = escape_markdown(new_username)
                await update.message.reply_text(
                    f"✅ *Token renewed successfully!*\n\n"
                    f"Your bot *{bot_name_esc}* (@{bot_user_esc}) has been resumed with its existing data.\n\n"
                   
                    f"Start now - @{bot_user_esc}",
                    parse_mode=ParseMode.MARKDOWN
                )
                return ConversationHandler.END

        is_valid = await is_token_valid(bot_token)

        if not is_valid:
            await status_message.edit_text(
                "❌ **Validation Failed.** The token you provided is not a valid Telegram Bot API token. "
                "Please get a new one from @BotFather and try again.",
                reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Back to Settings", callback_data="settings")]])
            )
            return State.AWAITING_BOT_TOKEN

        # --- Success Path ---
        await status_message.delete() # Delete the "Processing" message on success

        bot_details = await get_bot_details(bot_token)
        bot_username = bot_details.get('username') if bot_details else "Unknown"
        bot_full_name = bot_details.get('full_name') if bot_details else "Unknown"

        # Insert new bot
        db.execute_query(
            "INSERT INTO managed_bots (bot_token, owner_telegram_id, bot_username, bot_full_name) VALUES (%s, %s, %s, %s) ON CONFLICT (bot_token) DO NOTHING;",
            (bot_token, owner_telegram_id, bot_username, bot_full_name)
        )
        await bot_queue.put(bot_token)

        # --- Trial Logic: 3-day Pro trial, one-time per owner+bot ---
        new_row = db.execute_query(
            "SELECT id FROM managed_bots WHERE bot_token = %s", (bot_token,), fetch=True
        )
        trial_granted = False
        if new_row:
            trial_granted = await grant_trial_if_eligible(owner_telegram_id, bot_username, new_row[0]['id'])

        # --- NOTIFY SUPER ADMIN ---
        try:
            notification_msg = (
                f"🤖 *New Bot Created*\n\n"
                f"👤 *Owner Name:* {escape_markdown(user_full_name)}\n"
                f"🆔 *Owner ID:* `{owner_telegram_id}`\n"
                f"🤖 *Bot Name:* {escape_markdown(bot_full_name)}\n"
                f"🔗 *Bot Username:* @{escape_markdown(bot_username)}"
            )
            await context.bot.send_message(
                chat_id=SUPER_ADMIN_TELEGRAM_ID,
                text=notification_msg,
                parse_mode=ParseMode.MARKDOWN
            )
        except Exception as e:
            logger.error(f"Failed to notify super admin about new bot: {e}")

        # Send /start via Telethon userbot
        try:
            import subprocess, os as _os
            _result = subprocess.run(
                [_os.path.join(_os.path.dirname(__file__) or '.', 'Telethon.py'), bot_username],
                capture_output=True, text=True, timeout=30,
            )
            if _result.returncode == 0:
                logger.info(f'Superadmin chat established with @{bot_username}')
            else:
                logger.warning(f'Superadmin chat failed for @{bot_username}: {_result.stderr.strip()}')
        except Exception as _e:
            logger.warning(f'Superadmin send_start exception for @{bot_username}: {_e}')

        # --- Reply to User ---
        bot_name = escape_markdown(bot_full_name)
        bot_username_escaped = escape_markdown(bot_username)
        trial_note = "\n🎁 *3-Day Pro Trial activated!* Enjoy all Pro features until it expires.\n" if trial_granted else ""
        deep_link = f"https://t.me/{bot_username}?start=start"

        setup_msg = await update.message.reply_text(
            f"⏳ *Setting up your bot...*\n\n"
            f"Your bot *{bot_name}* (@{bot_username_escaped}) is being prepared.\n\n"
            "This takes about 15 seconds. Please don't block or delete the bot — "
            "it will be ready shortly. ⚙️",
            parse_mode=ParseMode.MARKDOWN
        )

        async def _finalize_ready_notice():
            await asyncio.sleep(15)
            ready_text = (
                f"🎉 *Congrats! Your bot is ready!*\n\n"
                f"Your bot *{bot_name}* (@{bot_username_escaped}) is now running.\n"
                f"{trial_note}\n"
                "You can customize your bot's content from the 'Admin Panel' inside your new bot.\n\n"
                "Join our channel for updates: @tgecommerceofficial"
            )
            reply_markup = InlineKeyboardMarkup([[InlineKeyboardButton("🏠 Main Menu", callback_data="main_menu")]])
            try:
                await context.bot.edit_message_text(
                    chat_id=setup_msg.chat_id,
                    message_id=setup_msg.message_id,
                    text=ready_text,
                    parse_mode=ParseMode.MARKDOWN,
                    reply_markup=reply_markup
                )
            except Exception as e:
                logger.error(f"Failed to send ready notice for manual token bot @{bot_username}: {e}")

        asyncio.create_task(_finalize_ready_notice())

        # Clear the creating flag so forwarding resumes normally later
        context.user_data['is_creating_bot'] = False
        
        return State.MAIN_MENU

    finally:
        animation_task.cancel()
        try:
            await animation_task
        except asyncio.CancelledError:
            pass # This is expected


