async def manage_newsfeed_settings(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Admin menu to enable/disable the Newsfeed feature."""
    query = update.callback_query
    if query:
        await query.answer()

    bot_id = await get_bot_id(context.bot.token)

    # Read current newsfeed enabled state from DB
    row = db.execute_query(
        "SELECT content_data FROM content_blocks WHERE bot_id = %s AND key = 'newsfeed_settings'",
        (bot_id,), fetch=True
    )
    if row and row[0]['content_data']:
        data = row[0]['content_data'] if isinstance(row[0]['content_data'], dict) else json.loads(row[0]['content_data'])
        is_enabled = data.get('enabled', True)
    else:
        is_enabled = True  # Default: enabled

    status_emoji = "✅" if is_enabled else "❌"
    toggle_label = "🔕 Disable Newsfeed" if is_enabled else "🔔 Enable Newsfeed"

    caption = (
        f"📱 *Newsfeed Settings*\n\n"
        f"Status: {status_emoji} {'Enabled' if is_enabled else 'Disabled'}\n\n"
        f"When enabled, users can browse all products in the Newsfeed section from the main menu.\n"
        f"When disabled, the Newsfeed button will not respond for users."
    )
    keyboard = InlineKeyboardMarkup([
        [InlineKeyboardButton(toggle_label, callback_data="ap2_newsfeed_toggle")],
        [InlineKeyboardButton("🔙 Back", callback_data="ap2_back_to_menu")]
    ])

    if query:
        await safe_edit_caption_or_text(query, caption, keyboard)
    else:
        await update.effective_message.reply_text(caption, reply_markup=keyboard, parse_mode=ParseMode.MARKDOWN)

    return State.MANAGE_NEWSFEED


async def toggle_newsfeed_enabled(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Toggles the newsfeed enabled/disabled state."""
    query = update.callback_query

    bot_id = await get_bot_id(context.bot.token)

    # Read current state
    row = db.execute_query(
        "SELECT content_data FROM content_blocks WHERE bot_id = %s AND key = 'newsfeed_settings'",
        (bot_id,), fetch=True
    )
    if row and row[0]['content_data']:
        raw = row[0]['content_data']
        data = raw if isinstance(raw, dict) else json.loads(raw)
        current = data.get('enabled', True)
    else:
        current = True

    new_state = not current

    # Single upsert query — avoids race condition and double-query bug
    db.execute_query(
        """
        INSERT INTO content_blocks (bot_id, key, content_data)
        VALUES (%s, 'newsfeed_settings', %s::jsonb)
        ON CONFLICT (bot_id, key) DO UPDATE
            SET content_data = EXCLUDED.content_data
        """,
        (bot_id, json.dumps({'enabled': new_state}))
    )

    await query.answer(f"Newsfeed {'✅ Enabled' if new_state else '❌ Disabled'}!", show_alert=True)
    return await manage_newsfeed_settings(update, context)


