async def receive_new_category_name(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Validates the new category name and asks for confirmation."""
    new_name = update.message.text.strip()
    bot_id = await get_bot_id(context.bot.token)
    
    if len(new_name) > 20:
        await update.message.reply_text("❌ Name is too long (max 20 characters). Please send a shorter name.")
        return State.EDIT_CATEGORY_NAME_INPUT

    # Check duplicates
    existing = db.execute_query("SELECT id FROM categories WHERE bot_id = %s AND name = %s", (bot_id, new_name), fetch=True)
    if existing:
        await update.message.reply_text(f"❌ The category name '{new_name}' already exists. Please choose a different name.")
        return State.EDIT_CATEGORY_NAME_INPUT

    context.user_data['edit_new_name'] = new_name
    current_name = context.user_data.get('edit_current_name', 'Unknown')

    caption = (
        f"📝 *Confirm Update*\n\n"
        f"Old Name: {escape_markdown(current_name)}\n"
        f"New Name: *{escape_markdown(new_name)}*\n\n"
        "Do you want to update this category?"
    )
    keyboard = [
        [InlineKeyboardButton("✅ Update", callback_data="ap2_edit_cat_confirm")],
        [InlineKeyboardButton("❌ Cancel", callback_data="ap2_edit_category_list")]
    ]
    await update.message.reply_text(caption, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode=ParseMode.MARKDOWN)
    return State.EDIT_CATEGORY_CONFIRM

async def execute_edit_category(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Updates the category name in the database."""
    query = update.callback_query
    await query.answer()

    category_id = context.user_data.get('edit_target_id')
    new_name = context.user_data.get('edit_new_name')

    if not category_id or not new_name:
        await query.answer("Session expired.", show_alert=True)
        return await list_categories_for_edit(update, context)

    db.execute_query("UPDATE categories SET name = %s WHERE id = %s", (new_name, category_id))
    
    await query.answer(f"✅ Category renamed to '{new_name}'!", show_alert=True)
    return await list_categories_for_edit(update, context)


