async def _epi_cleanup_preview_messages(context: ContextTypes.DEFAULT_TYPE, chat_id: int):
    """Deletes all previously stored preview messages to keep chat clean."""
    msg_ids = context.user_data.pop('epi_msg_ids', [])
    for mid in msg_ids:
        try:
            await context.bot.delete_message(chat_id=chat_id, message_id=mid)
        except Exception:
            pass


async def show_edit_product_info_preview(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Shows product info preview with media and edit buttons. Cleans up old preview first."""
    query = update.callback_query
    if query:
        await query.answer()
        if query.data.startswith("epi_prod_"):
            product_id = int(query.data.split('_')[-1])
            context.user_data['epi_product_id'] = product_id
        else:
            product_id = context.user_data.get('epi_product_id')
    else:
        product_id = context.user_data.get('epi_product_id')

    chat_id = update.effective_chat.id
    bot_id = await get_bot_id(context.bot.token)
    lang = await get_user_lang(context)

    prod_res = db.execute_query(
        "SELECT id, name, price, description, image_url, stock_quantity FROM products WHERE id = %s AND bot_id = %s",
        (product_id, bot_id), fetch=True
    )
    if not prod_res:
        if query:
            await query.answer("Product not found.", show_alert=True)
        return State.EDIT_PRODUCT_INFO_PROD_LIST

    prod = prod_res[0]
    context.user_data['epi_current'] = dict(prod)

    price_str = await format_price(context, prod['price'], lang)
    stock_val = prod['stock_quantity']
    stock_str = "Unlimited" if stock_val is None else str(stock_val)
    desc = prod['description'] or 'Not set'

    caption = (
        f"📋 *Product Info*\n\n"
        f"🏷️ *Name:* {escape_markdown(prod['name'])}\n"
        f"💰 *Price:* {price_str}\n"
        f"📦 *Stock:* {stock_str}\n"
        f"📝 *Description:*\n{escape_markdown(desc)}"
    )

    keyboard = [
        [InlineKeyboardButton("✏️ Edit Name", callback_data="epi_edit_name"),
         InlineKeyboardButton("✏️ Edit Price", callback_data="epi_edit_price")],
        [InlineKeyboardButton("✏️ Edit Stock", callback_data="epi_edit_stock"),
         InlineKeyboardButton("✏️ Edit Description", callback_data="epi_edit_desc")],
        [InlineKeyboardButton("🖼️ Update Media", callback_data="epi_edit_media")],
        [InlineKeyboardButton("🔙 Back", callback_data=f"epi_cat_{context.user_data.get('epi_cat_id', 0)}")],
    ]
    reply_markup = InlineKeyboardMarkup(keyboard)

    # Parse media
    media_list = []
    raw_media = prod.get('image_url')
    if raw_media:
        try:
            loaded = json.loads(raw_media)
            if isinstance(loaded, list) and loaded:
                media_list = loaded
        except (json.JSONDecodeError, TypeError):
            media_list = [str(raw_media)]

    # Delete ALL previous preview messages first
    await _epi_cleanup_preview_messages(context, chat_id)

    # Also delete the triggering message (e.g. admin's typed value or "✅ Updated!" reply)
    try:
        if update.message:
            await update.message.delete()
    except Exception:
        pass
    try:
        if query and query.message:
            await query.message.delete()
    except Exception:
        pass

    CAPTION_LIMIT = 1024
    send_separate_text = len(caption) > CAPTION_LIMIT
    media_caption = caption if not send_separate_text else escape_markdown(prod['name'])

    sent_ids = []

    try:
        if media_list:
            media_items = []
            is_first = True
            for item in media_list:
                if isinstance(item, dict):
                    fid = item.get('file_id')
                    mtype = item.get('type', 'photo')
                elif isinstance(item, str):
                    fid = item
                    mtype = 'photo'
                else:
                    continue

                if is_first:
                    if mtype == 'video':
                        media_items.append(InputMediaVideo(media=fid, caption=media_caption, parse_mode=ParseMode.MARKDOWN))
                    else:
                        media_items.append(InputMediaPhoto(media=fid, caption=media_caption, parse_mode=ParseMode.MARKDOWN))
                    is_first = False
                else:
                    if mtype == 'video':
                        media_items.append(InputMediaVideo(media=fid))
                    else:
                        media_items.append(InputMediaPhoto(media=fid))

            if len(media_items) > 1:
                sent = await context.bot.send_media_group(chat_id=chat_id, media=media_items)
                sent_ids.extend([m.message_id for m in sent])
                msg = await context.bot.send_message(
                    chat_id=chat_id,
                    text=caption if send_separate_text else "Select an option:",
                    reply_markup=reply_markup, parse_mode=ParseMode.MARKDOWN
                )
                sent_ids.append(msg.message_id)
            elif len(media_items) == 1:
                single = media_items[0]
                if isinstance(single, InputMediaVideo):
                    msg = await context.bot.send_video(chat_id=chat_id, video=single.media,
                        caption=media_caption, parse_mode=ParseMode.MARKDOWN)
                else:
                    msg = await context.bot.send_photo(chat_id=chat_id, photo=single.media,
                        caption=media_caption, parse_mode=ParseMode.MARKDOWN)
                sent_ids.append(msg.message_id)
                if send_separate_text:
                    msg2 = await context.bot.send_message(chat_id=chat_id, text=caption,
                        reply_markup=reply_markup, parse_mode=ParseMode.MARKDOWN)
                else:
                    msg2 = await context.bot.send_message(chat_id=chat_id,
                        text="Select an option:", reply_markup=reply_markup)
                sent_ids.append(msg2.message_id)
            else:
                raise ValueError("No valid media items")
        else:
            msg = await context.bot.send_message(chat_id=chat_id, text=caption,
                reply_markup=reply_markup, parse_mode=ParseMode.MARKDOWN)
            sent_ids.append(msg.message_id)

    except Exception as e:
        logger.error(f"Error displaying edit product info preview: {e}")
        msg = await context.bot.send_message(chat_id=chat_id, text=caption,
            reply_markup=reply_markup, parse_mode=ParseMode.MARKDOWN)
        sent_ids.append(msg.message_id)

    # Store IDs so next refresh can clean them up
    context.user_data['epi_msg_ids'] = sent_ids

    return State.EDIT_PRODUCT_INFO_PREVIEW


async def epi_edit_field_prompt(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Prompts admin to send a new value for the selected field."""
    query = update.callback_query
    await query.answer()
    field = query.data  # epi_edit_name / epi_edit_price / epi_edit_stock / epi_edit_desc

    prompts = {
        "epi_edit_name": "✏️ Send the new *product name*:",
        "epi_edit_price": "✏️ Send the new *price* (numbers only):",
        "epi_edit_stock": "✏️ Send the new *stock quantity* (whole number), or send `0` for zero, `unlimited` for unlimited:",
        "epi_edit_desc": "✏️ Send the new *description*:",
    }
    context.user_data['epi_editing_field'] = field

    await context.bot.send_message(
        chat_id=update.effective_chat.id,
        text=prompts.get(field, "✏️ Send the new value:"),
        reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Back to Preview", callback_data="epi_back_to_preview")]]),
        parse_mode=ParseMode.MARKDOWN
    )
    return State.EDIT_PRODUCT_INFO_EDIT_FIELD


async def epi_receive_field_value(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Saves the edited field value to the database and returns to preview."""
    field = context.user_data.get('epi_editing_field')
    value = update.message.text.strip()
    product_id = context.user_data.get('epi_product_id')
    bot_id = await get_bot_id(context.bot.token)

    if field == "epi_edit_name":
        existing = db.execute_query(
            "SELECT id FROM products WHERE bot_id = %s AND LOWER(name) = LOWER(%s) AND id != %s",
            (bot_id, value, product_id), fetch=True
        )
        if existing:
            await update.message.reply_text("❌ A product with that name already exists. Please send a different name.")
            return State.EDIT_PRODUCT_INFO_EDIT_FIELD
        db.execute_query("UPDATE products SET name = %s WHERE id = %s", (value, product_id))

    elif field == "epi_edit_price":
        try:
            price = Decimal(value)
            db.execute_query("UPDATE products SET price = %s WHERE id = %s", (price, product_id))
            
        except Exception:
            await update.message.reply_text("❌ Invalid price. Please send numbers only.")
            return State.EDIT_PRODUCT_INFO_EDIT_FIELD

    elif field == "epi_edit_stock":
        if value.lower() == 'unlimited':
            db.execute_query("UPDATE products SET stock_quantity = NULL WHERE id = %s", (product_id,))
        elif value.isdigit():
            db.execute_query("UPDATE products SET stock_quantity = %s WHERE id = %s", (int(value), product_id))
        else:
            await update.message.reply_text("❌ Invalid stock. Send a number or 'unlimited'.")
            return State.EDIT_PRODUCT_INFO_EDIT_FIELD
        

    elif field == "epi_edit_desc":
        db.execute_query("UPDATE products SET description = %s WHERE id = %s", (value, product_id))

    context.user_data.pop('epi_editing_field', None)
    return await show_edit_product_info_preview(update, context)


async def epi_start_media_update(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Starts the media replacement flow."""
    query = update.callback_query
    await query.answer()
    context.user_data['epi_new_media'] = []

    await context.bot.send_message(
        chat_id=update.effective_chat.id,
        text=(
            "🖼️ *Update Media*\n\n"
            "Send new photos or videos one by one.\n"
            "This will *replace* all existing media.\n\n"
            "Press *✅ Done* when finished or *⏭️ Skip* to keep existing media."
        ),
        reply_markup=ReplyKeyboardMarkup([["✅ Done", "⏭️ Keep Existing"]], resize_keyboard=True, one_time_keyboard=True),
        parse_mode=ParseMode.MARKDOWN
    )
    return State.EDIT_PRODUCT_INFO_AWAIT_MEDIA


async def epi_receive_media(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Collects new media for the product."""
    if 'epi_new_media' not in context.user_data:
        context.user_data['epi_new_media'] = []

    media_item = None
    if update.message.photo:
        media_item = {'type': 'photo', 'file_id': update.message.photo[-1].file_id}
    elif update.message.video:
        media_item = {'type': 'video', 'file_id': update.message.video.file_id}

    if media_item:
        context.user_data['epi_new_media'].append(media_item)
        count = len(context.user_data['epi_new_media'])
        await update.message.reply_text(f"✅ Media {count} received. Send more or press *✅ Done*.", parse_mode=ParseMode.MARKDOWN)
    else:
        await update.message.reply_text("⚠️ Unsupported media. Please send a photo or video.")

    return State.EDIT_PRODUCT_INFO_AWAIT_MEDIA


async def epi_finish_media(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Saves new media or keeps existing, then returns to preview."""
    action = update.message.text.strip()
    await update.message.reply_text("⏳ Saving...", reply_markup=ReplyKeyboardRemove())

    product_id = context.user_data.get('epi_product_id')

    if action == "✅ Done":
        new_media = context.user_data.get('epi_new_media', [])
        if new_media:
            db.execute_query("UPDATE products SET image_url = %s WHERE id = %s",
                             (json.dumps(new_media), product_id))
    context.user_data.pop('epi_new_media', None)
    return await show_edit_product_info_preview(update, context)


