async def confirm_delete_payment(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Asks for final confirmation before deleting a payment method."""
    query = update.callback_query
    await query.answer()
    method_id = int(query.data.split('_')[-1])
    bot_id = await get_bot_id(context.bot.token)

    method = get_payment_method(bot_id, method_id)
    if not method:
        await query.answer("❌ Payment method not found.", show_alert=True)
        return State.DELETE_PAYMENT_LIST

    method_name = escape_markdown(method['name'])
    warning_caption = f"Are you sure you want to permanently delete the payment method **{method_name}**?"
    keyboard = [
        [InlineKeyboardButton("✅ Yes, Delete", callback_data=f"ap2_del_pay_execute_{method_id}")],
        [InlineKeyboardButton("❌ No, Cancel", callback_data="ap2_delete_payment_list")]
    ]
    await safe_edit_caption_or_text(query, warning_caption, InlineKeyboardMarkup(keyboard))
    return State.DELETE_PAYMENT_CONFIRM

async def execute_delete_payment(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Executes the deletion of a payment method."""
    query = update.callback_query
    await query.answer("Deleting...")
    method_id = int(query.data.split('_')[-1])

    if delete_payment_method(method_id):
        await query.answer("✅ Payment method deleted successfully.", show_alert=True)
        # Auto-close shop if no payment methods remain
        bot_id = await get_bot_id(context.bot.token)
        if bot_id and not _has_payment_methods(bot_id):
            await query.answer("⚠️ No payment methods remaining — shop has been automatically closed.", show_alert=True)
    else:
        await query.answer("❌ An error occurred during deletion.", show_alert=True)

    return await list_payments_for_deletion(update, context)


