async def receive_plan_payment_qr(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    if update.message and update.message.photo:
        file_id = update.message.photo[-1].file_id
        try:
            # Ensure downloads directory exists
            os.makedirs("downloads", exist_ok=True)
            # Create a unique filename for the QR code
            file_name = f"downloads/plan_qr_{uuid.uuid4().hex}.jpg"
            
            # Download the file to the local directory
            new_file = await context.bot.get_file(file_id)
            await new_file.download_to_drive(file_name)
            
            # Save the local path instead of file_id
            context.user_data['new_plan_payment']['qr_code_url'] = file_name
        except Exception as e:
            logger.error(f"Error downloading Plan Payment QR: {e}")
            context.user_data['new_plan_payment']['qr_code_url'] = file_id # Fallback
    else:
        context.user_data['new_plan_payment']['qr_code_url'] = None
        
    return await save_plan_payment(update, context)

