async def save_plan_payment(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    data = context.user_data.get('new_plan_payment', {})
    if not data:
        if update.message:
            await update.message.reply_text("Session expired.")
        return State.SETTINGS
        
    db.execute_query(
        "INSERT INTO plan_payments (payment_name, account_number, account_name, qr_code_url) VALUES (%s, %s, %s, %s)",
        (data.get('payment_name'), data.get('account_number'), data.get('account_name'), data.get('qr_code_url'))
    )
    
    text = f"✅ Plan Payment Method '{data.get('payment_name')}' saved successfully!"
    if update.message:
        await update.message.reply_text(text)
        await update.message.reply_text("Returning to Main Menu.", reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🏠 Main Menu", callback_data="main_menu")]]))
    elif update.callback_query:
        await update.callback_query.edit_message_text(text, reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🏠 Main Menu", callback_data="main_menu")]]))
        
    context.user_data.pop('new_plan_payment', None)
    return State.MAIN_MENU

