# lines 3420-3481
def generate_payment_qr_image(qr_string: str) -> BytesIO:
    """Generates a branded QR payment image using the MMQR template."""
    TEMPLATE_PATH = "/opt/teleshop/img/mmqr.png"
    LOGO_PATH = "/opt/teleshop/img/logo.png"

    # QR box position on template (x, y, width, height)
    QR_X, QR_Y, QR_W, QR_H = 545, 1200, 425, 425
    LOGO_SIZE = 80  # logo size in center of QR

    # Generate QR code
    qr = qrcode.QRCode(
        error_correction=qrcode.constants.ERROR_CORRECT_H,
        box_size=10,
        border=1
    )
    qr.add_data(qr_string)
    qr.make(fit=True)
    qr_img = qr.make_image(fill_color="black", back_color="white").convert("RGBA")
    qr_img = qr_img.resize((QR_W, QR_H), Image.LANCZOS)

    # Paste logo in center of QR
    try:
        logo = Image.open(LOGO_PATH).convert("RGBA")
        logo = logo.resize((LOGO_SIZE, LOGO_SIZE), Image.LANCZOS)
        logo_x = (QR_W - LOGO_SIZE) // 2
        logo_y = (QR_H - LOGO_SIZE) // 2
        qr_img.paste(logo, (logo_x, logo_y), logo)
    except Exception as e:
        logger.warning(f"Could not paste logo on QR: {e}")

    # Save QR directly without template
    output = BytesIO()
    qr_img.convert("RGB").save(output, format="PNG")
    output.seek(0)
    return output


async def select_plan(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Handles the Upgrade Now button and generates MMQR auto payment QR code."""
    query = update.callback_query
    message = update.effective_message
    _loading_msg = None

    if query:
        await query.answer()
        parts = query.data.split("_")
        plan_name = parts[2].capitalize()
        plan_type = parts[3].capitalize()
        context.user_data["upgrade_selection"] = {"plan_name": plan_name, "plan_type": plan_type}
        _loading_msg = await context.bot.send_message(
            chat_id=query.message.chat_id,
            text="⏳ Generating QR Code... \nPlease wait a few seconds."
        )
    else:
        await message.reply_text("Going back...", reply_markup=ReplyKeyboardRemove())
        plan_info = context.user_data.get("upgrade_selection")
        if not plan_info:
            await message.reply_text("Session expired. Please start over.")
            return await start(update, context)
        plan_name = plan_info["plan_name"]
        plan_type = plan_info["plan_type"]

    bot_id = await get_bot_id(context.bot.token)
    user_id = update.effective_user.id
    plan_amount = get_plan_price_mmk(plan_name, plan_type)

    if not plan_amount:
        await context.bot.send_message(
            chat_id=message.chat_id,
            text="❌ Could not determine plan price. Please contact support.",
            parse_mode=ParseMode.MARKDOWN
        )
        return State.UPGRADE_PLAN_MENU

    # orderId format: PLAN_{bot_id}_{user_id}_{plan_name}_{plan_type}
    plan_abbr = {"Basic": "ba", "Standard": "st", "Pro": "pr", "Business": "bu"}.get(plan_name, plan_name[:2])
    short_type = "y" if plan_type.lower() == "yearly" else "m"
    short_ts = f"{int(time.time() * 1000) % 100000000:08d}"
    order_id = f"PL-{bot_id % 10000:04d}-{plan_abbr}-{short_type}-{short_ts}"

    try:
        response = requests.post(
            "http://localhost:3000/create-order",
            json={
                "orderId": order_id,
                "amount": int(plan_amount),
                "items": [{"name": f"{plan_name} Plan ({plan_type})", "amount": int(plan_amount), "quantity": 1}]
            },
            timeout=10
        )
        response.raise_for_status()
        data = response.json()
        qr_string = data.get("qr")

        if not qr_string:
            raise Exception("No QR string returned from payment server")

        # Generate branded QR image
        qr_image = generate_payment_qr_image(qr_string)

        caption = (
            f"🚀 *{plan_name} Plan ({plan_type})*\n\n"
            f"💵 Amount: *{plan_amount:,.0f} MMK*\n\n"
            f"📱 Scan the MMQR code with *KBZPay / Wave / CB Pay, and others...*\n\n"
            f"✅ Payment will be *automatically confirmed* after scanning.\n"
            f"No screenshot needed!"
        )

        keyboard = [
            [InlineKeyboardButton("🔙 Back", callback_data=f"show_plan_details_{plan_name.lower()}_{plan_type.lower()}")]
        ]

        try:
            await message.delete()
        except Exception:
            pass

        sent_msg = await context.bot.send_photo(
            chat_id=message.chat_id,
            photo=qr_image,
            caption=caption,
            reply_markup=InlineKeyboardMarkup(keyboard),
            parse_mode=ParseMode.MARKDOWN
        )

        try:
            await _loading_msg.delete()
        except Exception:
            pass

        # Store QR message info so webhook can delete it after payment
        try:
            requests.post(
                "http://localhost:3000/store-qr-message",
                json={
                    "orderId": order_id,
                    "messageId": sent_msg.message_id,
                    "chatId": message.chat_id,
                    "botToken": context.bot.token
                },
                timeout=5
            )
        except Exception:
            pass

    except Exception as e:
        logger.error(f"MMQR payment generation failed: {e}")
        await context.bot.send_message(
            chat_id=message.chat_id,
            text=(
                f"⚠️ *Auto payment temporarily unavailable.*\n\n"
                f"Please contact [@maunglenn](https://t.me/maunglenn) to upgrade to *{plan_name} Plan ({plan_type})*.\n"
                f"Amount: *{plan_amount:,.0f} MMK*"
            ),
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Back", callback_data=f"show_plan_details_{plan_name.lower()}_{plan_type.lower()}")]]),
            parse_mode=ParseMode.MARKDOWN
        )

    return State.UPGRADE_SHOW_QR


