async def finish_upgrade_proof(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Finalizes the upgrade request and notifies the super admin."""
    proof_file_id = context.user_data.get('upgrade_proof_file_id')

    if not proof_file_id:

        reply_keyboard = ReplyKeyboardMarkup([["Done", "Back"]], resize_keyboard=True, one_time_keyboard=True)
        await update.message.reply_text(
            "⚠️ You have not sent any payment proof. Please send a screenshot first, then press 'Done'.",
            reply_markup=reply_keyboard
        )
        return State.UPGRADE_AWAIT_PROOF

    await update.message.reply_text("Submitting your request for review...", reply_markup=ReplyKeyboardRemove())


    admin_user = update.effective_user
    bot_id = await get_bot_id(context.bot.token)
    bot_info = db.execute_query("SELECT bot_username, bot_full_name FROM managed_bots WHERE id = %s", (bot_id,), fetch=True)

    if not bot_info:
        await update.message.reply_text("❌ Critical error: Could not identify this bot. Please contact support.")
        return State.MAIN_MENU

    bot_name = escape_markdown(bot_info[0]['bot_full_name'] or "N/A")
    bot_username = escape_markdown(bot_info[0]['bot_username'] or "N/A")
    admin_username = escape_markdown(admin_user.username or "N/A")
    plan_info = context.user_data['upgrade_selection']
    plan_name = plan_info['plan_name']


    notification_text = (
        f"🔔 *Plan Upgrade Request*\n\n"
        f"Bot Name: *{bot_name}*\n"
        f"Bot Username: @{bot_username}\n"
        f"Bot Admin: @{admin_username}\n\n"
        f"has requested to upgrade to the *{plan_name} ({plan_info['plan_type']})* plan.\n\n"
        "Please review the payment proof above and take action."
    )


    keyboard = [
        [
            InlineKeyboardButton("✅ Confirm & Upgrade", callback_data=f"upgrade_confirm_{bot_id}_{admin_user.id}_{plan_name}_{plan_info['plan_type'].lower()}"),
            InlineKeyboardButton("❌ Decline", callback_data=f"upgrade_decline_{bot_id}_{admin_user.id}_{plan_name}_{plan_info['plan_type'].lower()}")
        ]
    ]

    try:

        file = await context.bot.get_file(proof_file_id)


        photo_bytes = await file.download_as_bytearray()


        main_bot_app = Application.builder().token(TOKEN).build()


        await main_bot_app.bot.send_photo(
            chat_id=SUPER_ADMIN_TELEGRAM_ID,
            photo=bytes(photo_bytes),
            caption=f"Payment proof from @{admin_username} for bot @{bot_username}"
        )


        await main_bot_app.bot.send_message(
            chat_id=SUPER_ADMIN_TELEGRAM_ID,
            text=notification_text,
            reply_markup=InlineKeyboardMarkup(keyboard),
            parse_mode=ParseMode.MARKDOWN
        )


        await update.message.reply_text(
            "✅ Your upgrade request has been sent for review. You will be notified once it is approved.",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🏠 Main Menu", callback_data="main_menu")]])
        )
    except Exception as e:
        logger.error(f"Failed to send upgrade notification to super admin: {e}")
        await update.message.reply_text("❌ There was an error submitting your request. Please resubmit your payment screenshot. This won't result in a double charge." )

    context.user_data.pop('upgrade_selection', None)
    context.user_data.pop('upgrade_proof_file_id', None)

    return State.MAIN_MENU


def add_custom_command(bot_id: int, command_name: str, content_data: List[Dict]) -> bool:
    """Saves a new custom command to the database."""
    content_json = json.dumps(content_data)
    return db.execute_query(
        """
        INSERT INTO custom_commands (bot_id, command_name, content_data)
        VALUES (%s, %s, %s)
        ON CONFLICT (bot_id, command_name) DO UPDATE SET content_data = EXCLUDED.content_data;
        """,
        (bot_id, command_name, content_json)
    )

def get_custom_command(bot_id: int, command_name: str) -> Optional[List[Dict]]:
    """Retrieves the content for a custom command."""
    result = db.execute_query(
        "SELECT content_data FROM custom_commands WHERE bot_id = %s AND command_name = %s AND is_active = TRUE",
        (bot_id, command_name),
        fetch=True
    )
    if result:
        return result[0]['content_data']
    return None

def get_all_auto_replies_with_id(bot_id: int) -> List[Dict]:
    """Fetches all auto-replies with their primary key ID."""
    return db.execute_query(
        "SELECT id, button_name FROM auto_replies WHERE bot_id = %s ORDER BY button_name",
        (bot_id,), fetch=True
    )

def delete_auto_reply(autoreply_id: int) -> bool:
    """Deletes an auto-reply configuration by its ID."""
    return db.execute_query("DELETE FROM auto_replies WHERE id = %s", (autoreply_id,))

