async def receive_command_name(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Receives and validates the new command name."""
    command_name = update.message.text.strip()
    error_message = None


    if '/' in command_name:
        error_message = "❌ Invalid command. The `/` symbol is not allowed. Please send the command name only (e.g., `help`)."
    elif not re.match(r'^[a-z0-9]{1,30}$', command_name):
        error_message = (
            "❌ **Invalid Format!** Please follow the rules:\n\n"
            "• Only lowercase letters and numbers\n"
            "• No spaces or other special characters\n"
            "• 1-30 characters long"
        )

    if error_message:
        await update.message.reply_text(error_message)
        return State.ADD_COMMAND_NAME


    bot_id = await get_bot_id(context.bot.token)
    if get_custom_command(bot_id, command_name):
        await update.message.reply_text(f"❌ The command `/{command_name}` already exists. Please choose a different name.")
        return State.ADD_COMMAND_NAME


    context.user_data['new_custom_command']['name'] = command_name
    context.user_data['new_custom_command']['content'] = []

    await update.message.reply_text(
        f"✅ Command `/{command_name}` is set.\n\n"
        "Now, send me the content for this command. You can send text, photos, videos, etc. "
        "I will collect everything in the order you send it."
    )
    return State.ADD_COMMAND_CONTENT

async def collect_command_content(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Collects all messages sent by the admin for the custom command."""
    is_first_message = not context.user_data['new_custom_command']['content']
    serialized_msg = serialize_message(update.message)

    if serialized_msg:
        context.user_data['new_custom_command']['content'].append(serialized_msg)

        if is_first_message:
            reply_keyboard = ReplyKeyboardMarkup([["Done", "Cancel"]], resize_keyboard=True)
            await update.message.reply_text("👍 First message received. Send more content, or use the buttons below.", reply_markup=reply_keyboard)
        else:
            await update.message.reply_text("👍 Message received.")
    else:
        await update.message.reply_text("⚠️ Sorry, that message type is not supported.")

    return State.ADD_COMMAND_CONTENT

async def save_custom_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Saves the collected content for the custom command to the database."""
    command_data = context.user_data.get('new_custom_command')

    if not command_data or not command_data.get('content'):
        await update.message.reply_text("⚠️ You didn't send any content. Command creation cancelled.", reply_markup=ReplyKeyboardRemove())
    else:
        bot_id = await get_bot_id(context.bot.token)
        command_name = command_data['name']
        content = command_data['content']

        if add_custom_command(bot_id, command_name, content):
            await update.message.reply_text(f"✅ Command `/{command_name}` has been saved successfully!", reply_markup=ReplyKeyboardRemove())
        else:
            await update.message.reply_text("❌ A database error occurred. Could not save the command.", reply_markup=ReplyKeyboardRemove())

    context.user_data.pop('new_custom_command', None)
    await handle_admin_panel_2(update, context)
    return State.ADMIN_PANEL_2

async def cancel_custom_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Cancels the custom command creation process."""
    context.user_data.pop('new_custom_command', None)
    await update.message.reply_text("❌ Command creation cancelled.", reply_markup=ReplyKeyboardRemove())
    await handle_admin_panel_2(update, context)
    return State.ADMIN_PANEL_2

async def handle_dynamic_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handles all commands by checking the database for a custom command first."""
    if await _is_stale_command(update, context):
        return
    if not update.effective_message or not update.effective_message.text:
        return

    command_name = update.effective_message.text[1:].split('@')[0]
    bot_id = await get_bot_id(context.bot.token)

    command_content = get_custom_command(bot_id, command_name)

    if command_content:
        # DB may return content_data as a raw JSON string; parse it if so
        if isinstance(command_content, str):
            try:
                import json
                command_content = json.loads(command_content)
            except (json.JSONDecodeError, ValueError):
                logger.error(f"Invalid JSON in custom command '{command_name}'")
                command_content = None
        if not command_content:
            return
        for msg_data in command_content:
            msg_type = msg_data.get("type")
            text = msg_data.get("text") or msg_data.get("caption", "")
            entities = msg_data.get("entities")
            file_id = msg_data.get("file_id")
            try:
                if msg_type == "text": await context.bot.send_message(chat_id=update.effective_chat.id, text=text, entities=entities)
                elif msg_type == "photo": await context.bot.send_photo(chat_id=update.effective_chat.id, photo=file_id, caption=text, caption_entities=entities)
                elif msg_type == "video": await context.bot.send_video(chat_id=update.effective_chat.id, video=file_id, caption=text, caption_entities=entities)
                elif msg_type == "document": await context.bot.send_document(chat_id=update.effective_chat.id, document=file_id, caption=text, caption_entities=entities)
                await asyncio.sleep(0.1)
            except Exception as e:
                logger.error(f"Error sending dynamic command '{command_name}': {e}")


def get_all_custom_commands(bot_id: int) -> List[Dict]:
    """Retrieves all custom commands for a specific bot."""
    return db.execute_query(
        "SELECT id, command_name FROM custom_commands WHERE bot_id = %s AND is_active = TRUE ORDER BY command_name",
        (bot_id,),
        fetch=True
    )


async def cancel_flow(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Generic cancellation function for 🧩 Product Management flows."""
    query = update.callback_query
    if query:
        await query.answer()

    context.user_data.pop('new_category_data', None)
    context.user_data.pop('new_product_data', None)
    context.user_data.pop('new_payment_data', None)
    
    # Cleanup giveaway draw message if it exists
    last_msg_id = context.user_data.pop('last_winner_msg_id', None)
    if last_msg_id and update.effective_chat:
        try:
            await context.bot.delete_message(chat_id=update.effective_chat.id, message_id=last_msg_id)
        except Exception:
            pass
    
    # Ensure bot creation flag is cleared if cancelled
    context.user_data['is_creating_bot'] = False

    try:
        await update.effective_message.reply_text(
            "Operation cancelled.",
            reply_markup=ReplyKeyboardRemove()
        )
    except Exception:
        pass

    return await handle_admin_panel_2(update, context)



