async def start_add_product(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Starts the 'Add Product' flow."""
    query = update.callback_query

    bot_id = await get_bot_id(context.bot.token)


    limits = await get_bot_plan_and_limits(bot_id)
    product_count_res = db.execute_query("SELECT COUNT(*) as count FROM products WHERE bot_id = %s", (bot_id,), fetch=True)
    product_count = product_count_res[0]['count'] if product_count_res else 0

    if product_count >= limits['products']:
        await query.answer(f"❌ You have reached the limit ({product_count}/{limits['products']}) for products. Please upgrade your plan to add more.", show_alert=True)
        return State.ADMIN_PANEL_2

    await query.answer()


    categories = get_categories(bot_id)
    if not categories:
        # Save flag so after category is created, we redirect back to add product
        context.user_data['redirect_to_add_product'] = True
