async def receive_product_price(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Stores the product price (or skips) and asks for the description."""
    query = update.callback_query
    price = None

    if query and query.data == "ap2_skip_price":
        await query.answer("Price skipped.")
        message = query.message
        price = Decimal('0.00')
    else:
        message = update.message

        if not message.text:
            await message.reply_text("❌ Invalid input. Please send numbers only for the price, or press Skip.")
            return State.ADD_PRODUCT_PRICE

        try:
            price = Decimal(message.text.strip())
        except Exception:
            await message.reply_text("❌ Invalid price. Please send numbers only, or press Skip.")
            return State.ADD_PRODUCT_PRICE

    context.user_data['new_product_data']['price'] = price

    keyboard = [[InlineKeyboardButton("⏭️ Skip", callback_data="ap2_skip_stock")]]
    await message.reply_text(
        "✅ Price saved.\n\n📦 Send Total Stock in number (e.g. 50)\nPress Skip if this product has unlimited stock.",
        reply_markup=InlineKeyboardMarkup(keyboard)
    )
    return State.ADD_PRODUCT_STOCK
