async def save_product(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Saves the fully assembled product to the database."""
    query = update.callback_query
    await query.answer()

    product_data = context.user_data['new_product_data']
    bot_id = await get_bot_id(context.bot.token)


    media_json = json.dumps(product_data.get('media', []))

    db.execute_query(
        """
        INSERT INTO products (bot_id, category_id, name, price, description, image_url, stock_quantity)
        VALUES (%s, %s, %s, %s, %s, %s, %s)
        """,
        (
            bot_id,
            product_data['category_id'],
            product_data['name'],
            product_data.get('price'),
            product_data.get('description'),
            media_json,
            product_data.get('stock_quantity')
        )
    )

    await safe_edit_caption_or_text(query, f"✅ Product '{product_data['name']}' saved successfully!", None)
    context.user_data.pop('new_product_data', None)

    await handle_admin_panel_2(update, context)
    return State.ADMIN_PANEL_2

async def handle_admin_add_media(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Entry point: admin clicked Add Photos on new product notification."""
    try:
        query = update.callback_query
        await query.answer()

        product_id = int(query.data.split("_")[-1])
        product = db.execute_query(
            "SELECT name FROM products WHERE id=%s",
            (product_id,), fetch=True
        )
        product_name = product[0]["name"] if product else "Unknown"

        context.user_data["admin_add_media_product_id"] = product_id
        context.user_data["admin_add_media_product_name"] = product_name
        context.user_data["admin_add_media_collection"] = []

        reply_keyboard = ReplyKeyboardMarkup(
            [["✅ Done", "❌ Cancel"]],
            resize_keyboard=True,
            one_time_keyboard=False,
        )

        await query.edit_message_text(
            f"\U0001f4f8 Adding media for: {product_name}\n\n"
            f"Send photos or videos one by one, then press '\u2705 Done' when finished.",
        )
        await context.bot.send_message(
            chat_id=query.message.chat_id,
            text="Use the buttons below:",
            reply_markup=reply_keyboard,
        )
        return State.ADMIN_ADD_MEDIA
    except Exception as e:
        logger.error(f"admin_add_media: Error:  {e}", exc_info=True)
        try:
            await query.answer("Error occurred", show_alert=True)
        except Exception:
            pass
        return State.ADMIN_PANEL_2



async def receive_admin_add_media(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Collects photos/videos for the admin add media flow."""
    if "admin_add_media_collection" not in context.user_data:
        context.user_data["admin_add_media_collection"] = []

    media_item = None
    if update.message.photo:
        media_item = {"type": "photo", "file_id": update.message.photo[-1].file_id}
    elif update.message.video:
        media_item = {"type": "video", "file_id": update.message.video.file_id}

    if media_item:
        context.user_data["admin_add_media_collection"].append(media_item)
        count = len(context.user_data["admin_add_media_collection"])
        await update.message.reply_text(
            f"📸 Media received ({count} total). Send more or press '✅ Done'."
        )
    else:
        await update.message.reply_text("Please send a photo or video.")

