async def finish_admin_add_media(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Saves collected media to product image_url and finishes."""
    product_id = context.user_data.get("admin_add_media_product_id")
    product_name = context.user_data.get("admin_add_media_product_name", "product")
    media_list = context.user_data.get("admin_add_media_collection", [])

    if product_id and media_list:
        media_json = json.dumps(media_list)
        db.execute_query(
            "UPDATE products SET image_url = %s WHERE id = %s",
            (media_json, product_id),
        )
        await update.message.reply_text(
            f"✅ Saved {len(media_list)} media file(s) to '{product_name}' successfully!",
            reply_markup=ReplyKeyboardRemove(),
        )
    else:
        await update.message.reply_text(
            "⚠️ No media received. Product saved without photos.",
            reply_markup=ReplyKeyboardRemove(),
        )

    context.user_data.pop("admin_add_media_product_id", None)
    context.user_data.pop("admin_add_media_product_name", None)
    context.user_data.pop("admin_add_media_collection", None)

    return State.MAIN_MENU


