# ── AI ACCOUNTANT ─────────────────────────────────────────────────────────────

def _fetch_accountant_data_all_bots() -> str:
    """
    Gathers comprehensive shop data across ALL bots for the superadmin AI Accountant.
    Includes per-bot breakdown plus cross-bot totals and rankings.
    """
    now = datetime.datetime.now(pytz.utc)
    start_of_day   = now.replace(hour=0, minute=0, second=0, microsecond=0)
    start_of_week  = (now - datetime.timedelta(days=now.weekday())).replace(hour=0, minute=0, second=0, microsecond=0)
    start_of_month = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)

    lines = [
        "=== SUPERADMIN FULL DATABASE SNAPSHOT (ALL BOTS) ===",
        f"Generated at: {now.strftime('%Y-%m-%d %H:%M UTC')}",
        ""
    ]

    # ── ALL BOTS LIST ─────────────────────────────────────────────────────────
    all_bots = db.execute_query(
        "SELECT id, bot_username, bot_full_name, owner_telegram_id, plan_name, is_active FROM managed_bots ORDER BY id",
        fetch=True
    ) or []

    lines.append("--- ALL REGISTERED BOTS ---")
    lines.append(f"Total bots: {len(all_bots)}")
    for b in all_bots:
        lines.append(
            f"  bot_id={b['id']} | @{b['bot_username'] or 'unknown'} ({b['bot_full_name'] or 'N/A'}) "
            f"| owner_id={b['owner_telegram_id']} | plan={b['plan_name']} | active={b['is_active']}"
        )
    lines.append("")

    # ── CROSS-BOT ORDER SUMMARY ───────────────────────────────────────────────
    all_confirmed = db.execute_query(
        """
        SELECT o.bot_id, o.final_amount, o.created_at,
               mb.bot_username, mb.bot_full_name
        FROM orders o
        LEFT JOIN managed_bots mb ON o.bot_id = mb.id
        WHERE o.status = 'confirmed'
          AND o.created_at >= NOW() - INTERVAL '365 days'
        ORDER BY o.created_at DESC
        """,
        fetch=True
    ) or []

    total_rev_all = sum(Decimal(str(o['final_amount'])) for o in all_confirmed)
    total_rev_month = sum(Decimal(str(o['final_amount'])) for o in all_confirmed if o['created_at'].astimezone(pytz.utc) >= start_of_month)
    total_rev_week  = sum(Decimal(str(o['final_amount'])) for o in all_confirmed if o['created_at'].astimezone(pytz.utc) >= start_of_week)
    total_rev_today = sum(Decimal(str(o['final_amount'])) for o in all_confirmed if o['created_at'].astimezone(pytz.utc) >= start_of_day)

    lines.append("--- CROSS-BOT REVENUE TOTALS (all bots combined) ---")
    lines.append(f"Today: {total_rev_today:,.0f} MMK ({sum(1 for o in all_confirmed if o['created_at'].astimezone(pytz.utc) >= start_of_day)} orders)")
    lines.append(f"This week: {total_rev_week:,.0f} MMK ({sum(1 for o in all_confirmed if o['created_at'].astimezone(pytz.utc) >= start_of_week)} orders)")
    lines.append(f"This month: {total_rev_month:,.0f} MMK ({sum(1 for o in all_confirmed if o['created_at'].astimezone(pytz.utc) >= start_of_month)} orders)")
    lines.append(f"Last 365 days: {total_rev_all:,.0f} MMK ({len(all_confirmed)} orders)")
    lines.append("")

    # ── PER-BOT BREAKDOWN ─────────────────────────────────────────────────────
    lines.append("--- PER-BOT BREAKDOWN ---")
    bot_revenue: dict = {}
    for o in all_confirmed:
        bid = o['bot_id']
        bname = f"@{o['bot_username'] or 'bot_id=' + str(bid)}"
        if bid not in bot_revenue:
            bot_revenue[bid] = {'name': bname, 'total': Decimal(0), 'month': Decimal(0), 'count': 0, 'count_month': 0}
        bot_revenue[bid]['total'] += Decimal(str(o['final_amount']))
        bot_revenue[bid]['count'] += 1
        if o['created_at'].astimezone(pytz.utc) >= start_of_month:
            bot_revenue[bid]['month'] += Decimal(str(o['final_amount']))
            bot_revenue[bid]['count_month'] += 1

    sorted_bots = sorted(bot_revenue.items(), key=lambda x: x[1]['total'], reverse=True)
    for bid, data in sorted_bots:
        lines.append(
            f"  {data['name']} (bot_id={bid}): "
            f"365d={data['total']:,.0f} MMK ({data['count']} orders) | "
            f"this month={data['month']:,.0f} MMK ({data['count_month']} orders)"
        )
    lines.append("")

    # ── TOP SELLING BOTS ─────────────────────────────────────────────────────
    lines.append("--- TOP SELLING BOTS (this month, by revenue) ---")
    top5 = sorted_bots[:5]
    for rank, (bid, data) in enumerate(top5, 1):
        lines.append(f"  #{rank} {data['name']}: {data['month']:,.0f} MMK this month")
    lines.append("")

    # ── PER-BOT DETAILED DATA ────────────────────────────────────────────────
    # Fetch ALL orders (all statuses, 365 days) with full detail for order lookup
    all_orders_full = db.execute_query(
        """
        SELECT o.id, o.order_number, o.bot_id, o.total_amount, o.discount_amount, o.final_amount,
               o.status, o.payment_method, o.created_at,
               o.items, o.buyer_snapshot,
               u.username, u.first_name, u.last_name
        FROM orders o
        LEFT JOIN users u ON o.user_id = u.id
        WHERE o.created_at >= NOW() - INTERVAL '365 days'
        ORDER BY o.bot_id, o.created_at DESC
        """,
        fetch=True
    ) or []

    for b in all_bots:
        bid = b['id']
        bname = f"@{b['bot_username'] or 'bot_id=' + str(bid)}"
        lines.append(f"{'='*60}")
        lines.append(f"BOT: {bname} (bot_id={bid}) | plan={b['plan_name']} | owner={b['owner_telegram_id']}")
        lines.append(f"{'='*60}")

        # Orders for this bot (confirmed only for revenue)
        bot_orders = [o for o in all_confirmed if o['bot_id'] == bid]
        bot_orders_month = [o for o in bot_orders if o['created_at'].astimezone(pytz.utc) >= start_of_month]
        bot_rev_month = sum(Decimal(str(o['final_amount'])) for o in bot_orders_month)
        lines.append(f"Orders (365d): {len(bot_orders)} | This month: {len(bot_orders_month)} | Revenue this month: {bot_rev_month:,.0f} MMK")

        # Users
        u_res = db.execute_query("SELECT COUNT(*) as c FROM users WHERE bot_id = %s", (bid,), fetch=True)
        lines.append(f"Total users: {u_res[0]['c'] if u_res else 0}")

        # Products
        prod_res = db.execute_query("SELECT COUNT(*) as c FROM products WHERE bot_id = %s AND is_active=TRUE", (bid,), fetch=True)
        lines.append(f"Active products: {prod_res[0]['c'] if prod_res else 0}")

        # ── INDIVIDUAL ORDER DETAILS (all statuses, for order lookup by ID) ──
        bot_all_orders = [o for o in all_orders_full if o['bot_id'] == bid]
        lines.append(f"--- ORDER HISTORY ({len(bot_all_orders)} orders, last 365 days) ---")
        for o in bot_all_orders:
            snap = {}
            try:
                snap = o['buyer_snapshot'] if isinstance(o['buyer_snapshot'], dict) else (
                    json.loads(o['buyer_snapshot']) if o['buyer_snapshot'] else {}
                )
            except Exception:
                pass
            buyer_full  = snap.get('full_name') or f"{o.get('first_name','') or ''} {o.get('last_name','') or ''}".strip() or 'N/A'
            buyer_tgname = snap.get('telegram_name') or 'N/A'
            buyer_user  = snap.get('username') or (f"@{o.get('username')}" if o.get('username') else 'N/A')
            buyer_phone = snap.get('phone') or 'N/A'
            buyer_email = snap.get('email') or 'N/A'
            buyer_addr  = snap.get('address') or 'N/A'
            buyer_tgid  = snap.get('telegram_id') or 'N/A'
            items_str = ", ".join(
                f"{it.get('name','?')} x{it.get('quantity',1)}"
                for it in (o['items'] if isinstance(o['items'], list) else [])
            )
            lines.append(
                f"  ORDER_ID={o['order_number']} | date={o['created_at'].strftime('%Y-%m-%d %H:%M')} | "
                f"status={o['status']} | amount={Decimal(str(o['final_amount'])):,.0f} MMK | "
                f"payment={o.get('payment_method','N/A')} | "
                f"buyer_name={buyer_full} | tg_name={buyer_tgname} | username={buyer_user} | "
                f"phone={buyer_phone} | email={buyer_email} | address={buyer_addr} | "
                f"tg_id={buyer_tgid} | items=[{items_str}]"
            )
        lines.append("")

    return "\n".join(lines)


def _fetch_accountant_data(bot_id: int) -> str:
    """
    Gathers comprehensive shop data for the given bot_id and formats it
    as a plain-text context block to be injected into the AI system prompt.
    Strictly scoped to the provided bot_id so clone bot admins only see their own data.
    """
    now = datetime.datetime.now(pytz.utc)
    start_of_day   = now.replace(hour=0, minute=0, second=0, microsecond=0)
    start_of_week  = (now - datetime.timedelta(days=now.weekday())).replace(hour=0, minute=0, second=0, microsecond=0)
    start_of_month = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)

    lines = [f"=== SHOP DATABASE SNAPSHOT (bot_id={bot_id}) ===",
             f"Generated at: {now.strftime('%Y-%m-%d %H:%M UTC')}",
             ""]

    # ── ORDERS ────────────────────────────────────────────────────────────────
    lines.append("--- ORDERS ---")

    # All confirmed orders (last 90 days)
    all_orders = db.execute_query(
        """
        SELECT o.id, o.order_number, o.total_amount, o.discount_amount, o.final_amount,
               o.status, o.payment_method, o.created_at,
               u.username, u.first_name, u.last_name,
               o.items, o.buyer_snapshot
        FROM orders o
        LEFT JOIN users u ON o.user_id = u.id
        WHERE o.bot_id = %s
          AND o.created_at >= NOW() - INTERVAL '365 days'
        ORDER BY o.created_at DESC
        """,
        (bot_id,), fetch=True
    ) or []

    confirmed = [o for o in all_orders if o['status'] == 'confirmed']
    pending   = [o for o in all_orders if o['status'] == 'pending']
    cancelled = [o for o in all_orders if o['status'] == 'cancelled']

    orders_today  = [o for o in confirmed if o['created_at'].astimezone(pytz.utc) >= start_of_day]
    orders_week   = [o for o in confirmed if o['created_at'].astimezone(pytz.utc) >= start_of_week]
    orders_month  = [o for o in confirmed if o['created_at'].astimezone(pytz.utc) >= start_of_month]

    rev_today  = sum(Decimal(str(o['final_amount'])) for o in orders_today)
    rev_week   = sum(Decimal(str(o['final_amount'])) for o in orders_week)
    rev_month  = sum(Decimal(str(o['final_amount'])) for o in orders_month)
    rev_all90  = sum(Decimal(str(o['final_amount'])) for o in confirmed)

    lines.append(f"Today confirmed orders: {len(orders_today)}, revenue: {rev_today:,.0f} MMK")
    lines.append(f"This week confirmed orders: {len(orders_week)}, revenue: {rev_week:,.0f} MMK")
    lines.append(f"This month confirmed orders: {len(orders_month)}, revenue: {rev_month:,.0f} MMK")
    lines.append(f"Last 365 days confirmed orders: {len(confirmed)}, revenue: {rev_all90:,.0f} MMK")
    lines.append(f"Pending orders (last 90 days): {len(pending)}")
    lines.append(f"Cancelled orders (last 90 days): {len(cancelled)}")

    avg_order = rev_month / len(orders_month) if orders_month else Decimal(0)
    lines.append(f"Average order value (this month): {avg_order:,.0f} MMK")
    lines.append("")

    # All orders with full buyer snapshot (last 365 days) — used for Order ID lookup
    lines.append("All orders detail (last 365 days, all statuses):")
    for o in all_orders:
        snap = o.get('buyer_snapshot') or {}
        if isinstance(snap, str):
            try: snap = json.loads(snap)
            except: snap = {}
        buyer_full   = snap.get('full_name') or o.get('first_name') or 'N/A'
        buyer_tgname = snap.get('telegram_name') or 'N/A'
        buyer_user   = snap.get('username') or (f"@{o.get('username')}" if o.get('username') else 'N/A')
        buyer_phone  = snap.get('phone') or 'N/A'
        buyer_email  = snap.get('email') or 'N/A'
        buyer_addr   = snap.get('address') or 'N/A'
        buyer_tgid   = snap.get('telegram_id') or 'N/A'
        items_str = ", ".join(
            f"{it.get('name','?')} x{it.get('quantity',1)}"
            for it in (o['items'] if isinstance(o['items'], list) else [])
        )
        lines.append(
            f"  ORDER_ID={o['order_number']} | date={o['created_at'].strftime('%Y-%m-%d %H:%M')} | "
            f"status={o['status']} | amount={Decimal(str(o['final_amount'])):,.0f} MMK | "
            f"payment={o.get('payment_method','N/A')} | "
            f"buyer_name={buyer_full} | tg_name={buyer_tgname} | username={buyer_user} | "
            f"phone={buyer_phone} | email={buyer_email} | address={buyer_addr} | "
            f"tg_id={buyer_tgid} | items=[{items_str}]"
        )
    lines.append("")

    # ── PRODUCT SALES BREAKDOWN ───────────────────────────────────────────────
    lines.append("--- PRODUCT SALES (this month, confirmed orders) ---")
    product_sales: dict = {}
    for o in orders_month:
        try:
            items = o['items'] if isinstance(o['items'], list) else []
        except Exception:
            items = []
        for item in items:
            name = item.get('name', 'unknown')
            qty  = int(item.get('quantity', 1))
            price = Decimal(str(item.get('price', 0)))
            if name not in product_sales:
                product_sales[name] = {'qty': 0, 'revenue': Decimal(0)}
            product_sales[name]['qty']     += qty
            product_sales[name]['revenue'] += price * qty

    if product_sales:
        sorted_products = sorted(product_sales.items(), key=lambda x: x[1]['qty'], reverse=True)
        for pname, pdata in sorted_products:
            lines.append(f"  {pname}: {pdata['qty']} units sold, revenue {pdata['revenue']:,.0f} MMK")
    else:
        lines.append("  No product sales data this month.")
    lines.append("")

    # ── PRODUCTS CATALOG ─────────────────────────────────────────────────────
    lines.append("--- PRODUCTS IN CATALOG ---")
    products = db.execute_query(
        """
        SELECT p.name, p.price, p.stock_quantity, p.is_active, c.name as category
        FROM products p
        LEFT JOIN categories c ON p.category_id = c.id
        WHERE p.bot_id = %s
        ORDER BY c.name, p.name
        """,
        (bot_id,), fetch=True
    ) or []

    lines.append(f"Total products: {len(products)}")
    active_products = [p for p in products if p['is_active']]
    lines.append(f"Active products: {len(active_products)}")

    low_stock = [p for p in products if p['stock_quantity'] is not None and p['stock_quantity'] <= 5]
    if low_stock:
        lines.append(f"Low stock products (<= 5 units):")
        for p in low_stock:
            lines.append(f"  {p['name']}: {p['stock_quantity']} units left (price: {Decimal(str(p['price'])):,.0f} MMK)")
    else:
        lines.append("No low stock products.")

    for p in products:
        stock_str = str(p['stock_quantity']) if p['stock_quantity'] is not None else "unlimited"
        lines.append(
            f"  [{p['category'] or 'No Category'}] {p['name']} | "
            f"price: {Decimal(str(p['price'])):,.0f} MMK | stock: {stock_str} | active: {p['is_active']}"
        )
    lines.append("")

    # ── CATEGORIES ────────────────────────────────────────────────────────────
    lines.append("--- CATEGORIES ---")
    categories = db.execute_query(
        "SELECT name, is_active FROM categories WHERE bot_id = %s ORDER BY name",
        (bot_id,), fetch=True
    ) or []
    lines.append(f"Total categories: {len(categories)}")
    for cat in categories:
        lines.append(f"  {cat['name']} | active: {cat['is_active']}")
    lines.append("")

    # ── USERS ─────────────────────────────────────────────────────────────────
    lines.append("--- USERS ---")
    total_users_res = db.execute_query(
        "SELECT COUNT(*) as count FROM users WHERE bot_id = %s", (bot_id,), fetch=True
    )
    new_today_res = db.execute_query(
        "SELECT COUNT(*) as count FROM users WHERE bot_id = %s AND created_at >= DATE_TRUNC('day', NOW())",
        (bot_id,), fetch=True
    )
    new_week_res = db.execute_query(
        "SELECT COUNT(*) as count FROM users WHERE bot_id = %s AND created_at >= DATE_TRUNC('week', NOW())",
        (bot_id,), fetch=True
    )
    new_month_res = db.execute_query(
        "SELECT COUNT(*) as count FROM users WHERE bot_id = %s AND created_at >= DATE_TRUNC('month', NOW())",
        (bot_id,), fetch=True
    )
    total_users = total_users_res[0]['count'] if total_users_res else 0
    new_today   = new_today_res[0]['count'] if new_today_res else 0
    new_week    = new_week_res[0]['count'] if new_week_res else 0
    new_month   = new_month_res[0]['count'] if new_month_res else 0

    lines.append(f"Total users: {total_users}")
    lines.append(f"New users today: {new_today}")
    lines.append(f"New users this week: {new_week}")
    lines.append(f"New users this month: {new_month}")
    lines.append("")

    # ── PAYMENT METHODS ───────────────────────────────────────────────────────
    lines.append("--- PAYMENT METHODS ---")
    payment_methods = db.execute_query(
        "SELECT name, is_active FROM payment_methods WHERE bot_id = %s",
        (bot_id,), fetch=True
    ) or []
    for pm in payment_methods:
        lines.append(f"  {pm['name']} | active: {pm['is_active']}")
    lines.append("")

    # ── PROMOTIONS ────────────────────────────────────────────────────────────
    lines.append("--- PROMOTIONS ---")
    promos = db.execute_query(
        """
        SELECT title, discount_percentage, discount_amount, is_active, valid_until
        FROM promotions WHERE bot_id = %s ORDER BY is_active DESC
        """,
        (bot_id,), fetch=True
    ) or []
    for pr in promos:
        disc = f"{pr['discount_percentage']}%" if pr['discount_percentage'] else f"{Decimal(str(pr['discount_amount'] or 0)):,.0f} MMK off"
        until = pr['valid_until'].strftime('%Y-%m-%d') if pr['valid_until'] else "no expiry"
        lines.append(f"  {pr['title']} | discount: {disc} | active: {pr['is_active']} | until: {until}")
    lines.append("")

    # ── REVENUE BY PAYMENT METHOD ─────────────────────────────────────────────
    lines.append("--- REVENUE BY PAYMENT METHOD (this month) ---")
    pay_method_rev: dict = {}
    for o in orders_month:
        pm_name = o.get('payment_method') or 'unknown'
        if pm_name not in pay_method_rev:
            pay_method_rev[pm_name] = {'count': 0, 'revenue': Decimal(0)}
        pay_method_rev[pm_name]['count']   += 1
        pay_method_rev[pm_name]['revenue'] += Decimal(str(o['final_amount']))
    for pm_name, pm_data in sorted(pay_method_rev.items(), key=lambda x: x[1]['revenue'], reverse=True):
        lines.append(f"  {pm_name}: {pm_data['count']} orders, {pm_data['revenue']:,.0f} MMK")
    lines.append("")

    return "\n".join(lines)


async def enter_ai_accountant_mode(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Activates AI Accountant mode for admins only."""
    query = update.callback_query
    if query:
        await query.answer()

    user = update.effective_user
    user_data = await get_or_create_user(
        user.id, user.username, user.first_name, user.last_name, user.username, context.bot.token
    )

    if not user_data or not user_data.get('is_admin'):
        if query:
            await query.answer("❌ Admins only.", show_alert=True)
        return State.MAIN_MENU

    # Get API key from bot_ai_settings
    bot_id = await get_bot_id(context.bot.token)
    ai_settings = db.execute_query(
        "SELECT api_key, ai_provider FROM bot_ai_settings WHERE bot_id = %s", (bot_id,), fetch=True
    )
    if not ai_settings or not ai_settings[0].get("api_key"):
        ai_settings = db.execute_query(
            "SELECT api_key, ai_provider FROM bot_ai_settings WHERE bot_id = 214", fetch=True
        )
    if not ai_settings or not ai_settings[0].get('api_key'):
        msg = (
            "⚠️ *AI Accountant requires an API key.*\n\n"
            "Please go to *Admin Panel → AI Assistant Admin Panel → AI Agent Setup* "
            "and add your DeepSeek API key first."
        )
        if query:
            await safe_edit_caption_or_text(
                query, msg,
                InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Back", callback_data="ai_admin_panel")]])
            )
        return State.ADMIN_PANEL_2

    # Clear previous accountant history
    context.user_data.pop('accountant_history', None)
    context.user_data['in_accountant_mode'] = True

    chat_id = query.message.chat_id if query else update.effective_chat.id

    keyboard = [[KeyboardButton("🔙 Exit Accountant")]]
    reply_markup = ReplyKeyboardMarkup(keyboard, resize_keyboard=True, one_time_keyboard=False)

    await context.bot.send_message(
        chat_id=chat_id,
        text=(
            "🧮 *AI Accountant*\n\n"
            "I have full access to your shop database.\n"
            "Ask me anything about your shop statistics, orders, products, revenue, or users!\n\n"
            "Examples:\n"
            "• How many products did I sell today?\n"
            "• What is today's total revenue?\n"
            "• Which product sold the most this month?\n"
            "• How many new users joined this week?\n"
            "• Show me all pending orders.\n"
            "• Which payment method is most used?"
        ),
        reply_markup=reply_markup,
        parse_mode=ParseMode.MARKDOWN
    )
    return State.AI_ACCOUNTANT_MODE


async def handle_ai_accountant_message(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Handles admin messages inside AI Accountant mode."""
    user_text = update.message.text.strip() if update.message and update.message.text else ""

    # Exit trigger
    if user_text in ["🔙 Exit Accountant", "/start", "/cancel"]:
        return await exit_ai_accountant_mode(update, context)

    user = update.effective_user
    user_data = await get_or_create_user(
        user.id, user.username, user.first_name, user.last_name, user.username, context.bot.token
    )
    if not user_data or not user_data.get('is_admin'):
        return await exit_ai_accountant_mode(update, context)

    bot_id = await get_bot_id(context.bot.token)
    chat_id = update.effective_chat.id

    # Get API key
    ai_settings = db.execute_query(
        "SELECT api_key, ai_provider FROM bot_ai_settings WHERE bot_id = %s", (bot_id,), fetch=True
    )
    if not ai_settings or not ai_settings[0].get("api_key"):
        ai_settings = db.execute_query(
            "SELECT api_key, ai_provider FROM bot_ai_settings WHERE bot_id = 214", fetch=True
        )
    if not ai_settings or not ai_settings[0].get('api_key'):
        await update.message.reply_text("❌ API key not configured. Exiting Accountant mode.")
        return await exit_ai_accountant_mode(update, context)

    api_key = ai_settings[0]['api_key']

    # Fetch live database snapshot
    async def keep_typing():
        while True:
            await context.bot.send_chat_action(chat_id=chat_id, action="typing")
            await asyncio.sleep(4)

    typing_task = asyncio.create_task(keep_typing())
    is_superadmin_main = (user.id == SUPER_ADMIN_TELEGRAM_ID and context.bot.token == TOKEN)
    try:
        if is_superadmin_main:
            db_snapshot = await asyncio.get_event_loop().run_in_executor(
                None, _fetch_accountant_data_all_bots
            )
        else:
            db_snapshot = await asyncio.get_event_loop().run_in_executor(
                None, _fetch_accountant_data, bot_id
            )
    except Exception as e:
        logger.error(f"AI Accountant DB fetch error: {e}")
        db_snapshot = "Error fetching database data."

    # Build system prompt
    if is_superadmin_main:
        system_prompt = (
            "You are an AI Accountant for all bots on this platform.\n"
            "Rules:\n"
            "- Answer using ONLY the snapshot data below. Never invent numbers.\n"
            "- Be SHORT: 1–3 sentences or a tight bullet list. No long paragraphs.\n"
            "- Always include amounts in MMK.\n"
            "- For order lookups: return status, amount, buyer, items only.\n"
            "- Match user language (Burmese→Burmese, English→English).\n"
            "- Refuse non-shop questions.\n\n"
            f"{db_snapshot}"
        )
    else:
        system_prompt = (
            "You are an AI Accountant for this shop.\n"
            "Rules:\n"
            "- Answer using ONLY the snapshot data below. Never invent numbers.\n"
            "- Be SHORT: 1–3 sentences or a tight bullet list. No long paragraphs.\n"
            "- Always include amounts in MMK.\n"
            "- For order lookups: return status, amount, buyer, items only.\n"
            "- Match user language (Burmese→Burmese, English→English).\n"
            "- Refuse non-shop questions.\n\n"
            f"{db_snapshot}"
        )

    # Conversation history
    history = context.user_data.get('accountant_history', [])
    history.append({"role": "user", "content": user_text})
    # Keep last 10 messages
    history = history[-10:]

    api_messages = [{"role": "system", "content": system_prompt}] + history

    try:
        provider = ai_settings[0].get('ai_provider') or 'deepseek'
        client, model = get_ai_client_and_model(api_key, provider)

        # Keep the typing indicator running while calling the API
        try:
            if provider == "gemini":
                def _call_gemini():
                    return call_gemini_ai(api_key, api_messages)
                resp = await asyncio.get_event_loop().run_in_executor(None, _call_gemini)
                reply_content = resp.text.strip()
            else:
                def _call_openai():
                    return client.chat.completions.create(
                        model=model,
                        messages=api_messages,
                        stream=False,
                        max_tokens=1000
                    )
                resp = await asyncio.get_event_loop().run_in_executor(None, _call_openai)
                reply_content = resp.choices[0].message.content.strip()
        finally:
            typing_task.cancel()

        history.append({"role": "assistant", "content": reply_content})
        context.user_data['accountant_history'] = history

        # Light cleanup - strip all markdown that doesn't render in Telegram plain text
        clean_reply = reply_content
        clean_reply = clean_reply.replace("###", "")
        clean_reply = clean_reply.replace("**", "")
        clean_reply = clean_reply.replace("__", "")
        clean_reply = clean_reply.replace("*", "")
        lines_out = []
        for line in clean_reply.splitlines():
            lines_out.append(line)
            if line.strip():
                lines_out.append("")
        clean_reply = "\n".join(lines_out).strip()

        # Send the reply directly
        try:
            await update.message.reply_text(clean_reply)
        except Exception:
            await update.message.reply_text(clean_reply)

    except Exception as e:
        logger.error(f"AI Accountant API error: {e}")
        if history and history[-1]["role"] == "user":
            history.pop()
        await update.message.reply_text("❌ Connection error. Please try again.")

    return State.AI_ACCOUNTANT_MODE

async def exit_ai_accountant_mode(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Exits AI Accountant mode and returns to the AI Admin Panel."""

    context.user_data['in_accountant_mode'] = False
    context.user_data.pop('accountant_history', None)

    eff_msg = update.effective_message
    if update.callback_query:
        await update.callback_query.answer()

    await eff_msg.reply_text("✅ Exiting AI Accountant mode...", reply_markup=ReplyKeyboardRemove())
    return await handle_ai_admin_panel(update, context)


# ── AI ASSISTANT ADD PRODUCT ─────────────────────────────────────────────────

async def ai_cancel_to_ai_panel(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Cancels AI add product flow and returns to AI Admin Panel."""
    query = update.callback_query
    if query:
        await query.answer()
    # Clean up any partial AI product data
    context.user_data.pop('ai_new_product', None)
    # If triggered by a command, notify user
    if update.message:
        await update.message.reply_text("❌ AI product creation cancelled.", reply_markup=ReplyKeyboardRemove())
    return await handle_ai_admin_panel(update, context)


async def start_ai_add_product(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Entry point for AI-assisted product creation."""
    query = update.callback_query

    bot_id = await get_bot_id(context.bot.token)

    # Check product limit
    limits = await get_bot_plan_and_limits(bot_id)
    product_count_res = db.execute_query("SELECT COUNT(*) as count FROM products WHERE bot_id = %s", (bot_id,), fetch=True)
    product_count = product_count_res[0]['count'] if product_count_res else 0
    if product_count >= limits['products']:
        await query.answer(f"❌ Product limit reached ({product_count}/{limits['products']}). Please upgrade.", show_alert=True)
        return State.ADMIN_PANEL_2

    # Check if AI API key is configured
    ai_settings = db.execute_query(
        "SELECT api_key FROM bot_ai_settings WHERE bot_id = %s", (bot_id,), fetch=True
    )
    if not ai_settings or not ai_settings[0].get("api_key"):
        ai_settings = db.execute_query(
            "SELECT api_key FROM bot_ai_settings WHERE bot_id = 214", fetch=True
        )
    if not ai_settings or not ai_settings[0].get('api_key'):
        await query.answer(
            "⚠️ No API key found. Please add your DeepSeek API key in AI Agent Setup first.",
            show_alert=True
        )
        return State.ADMIN_PANEL_2

    await query.answer()
    context.user_data['ai_new_product'] = {}

    await safe_edit_caption_or_text(
        query,
        "🤖 *AI Assistant — Add Product*\n\n"
        "Send the product post in either way:\n\n"
        "📸 *Option 1:* Send a *photo with caption* — AI will extract product info and use the image automatically.\n\n"
        "📝 *Option 2:* Paste the *text post* only — you will add media in the next step.\n\n"
        "AI will auto-extract:\n"
        "• Product name\n"
        "• Wholesale price (unit price × pack quantity)\n"
        "• Stock (unlimited if not stated)\n"
        "• Description (original caption)\n\n"
        "Contact/redirect lines are excluded silently.",
        InlineKeyboardMarkup([[InlineKeyboardButton("❌ Cancel", callback_data="ap2_cancel")]])
    )
    return State.AI_ADD_PRODUCT_AWAIT_POST


async def ai_analyze_facebook_post(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Receives text-only post. Delegates to shared analyzer."""
    post_text = update.message.text
    if not post_text or not post_text.strip():
        await update.message.reply_text("❌ No text received. Please paste the post content or send a photo with caption.")
        return State.AI_ADD_PRODUCT_AWAIT_POST
    return await _ai_analyze_post_content(update, context, post_text=post_text.strip(), photo_file_id=None)


async def ai_analyze_photo_with_caption(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Receives photo + caption. Delegates to shared analyzer with image pre-captured."""
    caption = update.message.caption
    if not caption or not caption.strip():
        await update.message.reply_text("❌ Photo received but no caption found. Please send the photo with the product caption.")
        return State.AI_ADD_PRODUCT_AWAIT_POST
    photo_file_id = update.message.photo[-1].file_id
    return await _ai_analyze_post_content(update, context, post_text=caption.strip(), photo_file_id=photo_file_id)


async def _ai_analyze_post_content(
    update: Update,
    context: ContextTypes.DEFAULT_TYPE,
    post_text: str,
    photo_file_id: Optional[str]
) -> int:
    """Core AI analysis logic for both text-only and photo+caption flows."""
    bot_id = await get_bot_id(context.bot.token)
    ai_settings = db.execute_query(
        "SELECT api_key, ai_provider FROM bot_ai_settings WHERE bot_id = %s", (bot_id,), fetch=True
    )
    if not ai_settings or not ai_settings[0].get('api_key'):
        ai_settings = db.execute_query(
            "SELECT api_key, ai_provider FROM bot_ai_settings WHERE bot_id = 214", fetch=True
        )
    api_key = ai_settings[0]['api_key']

    thinking_msg = await update.message.reply_text("🤖 Analyzing post content, please wait...")

    # ── Strip contact/redirect lines silently ──────────────────────────────
    # Remove lines that contain phone numbers or order redirect instructions
    cleaned_lines = []
    for line in post_text.splitlines():
        line_stripped = line.strip()
        # Skip lines with phone-like patterns or "Order" redirect messages
        if re.search(r'(09[\d\s\-]+|viber|Order တင်|ကို Order|မှာပဲ)', line_stripped, re.IGNORECASE):
            continue
        cleaned_lines.append(line)
    cleaned_text = "\n".join(cleaned_lines).strip()
    description_text = cleaned_text  # description uses cleaned caption

    # ── Detect if this is a duplicate post with only price changed ─────────
    existing = context.user_data.get('ai_new_product', {})
    existing_desc = existing.get('description', '')
    is_price_update = False
    if existing_desc:
        # Compare ignoring price lines — if content similarity is high, treat as price update
        def strip_price_lines(txt):
            return "\n".join(
                l for l in txt.splitlines()
                if not re.search(r'(စျေး|price|ဈေး|နှုန်း|\d[\d,]+)', l, re.IGNORECASE)
            )
        if strip_price_lines(description_text).strip() == strip_price_lines(existing_desc).strip():
            is_price_update = True

    prompt = f"""You are a Myanmar wholesale product data extractor. Analyze this wholesale product post carefully.

CRITICAL WHOLESALE PRICE LOGIC:
- This is a WHOLESALE market. Retail unit prices are shown for marketing only.
- If the post mentions a pack/bundle (ဖာ, အထုပ်, ဗူး, box, pack, etc.) with a quantity AND a per-unit price, the REAL price = per_unit_price × quantity_per_pack.
- Example: "၁ဖာ အခဲ ၁၂၀ ပါ, စျေး 3420" → real price = 3420 × 120 = 410400
- Example: "၁ဖာ အထုပ် ၂၃၀ ပါ, စျေး 2600" → real price = 2600 × 230 = 598000
- Example: "၁ဗူး ၅၀ ကစ, ၁ဗူး 3650" → minimum order 50 bottles, price per bottle = 3650 (no multiplication here since 3650 IS the per-bottle price already and pack size = 1)
- If only a single item price exists with no pack quantity mentioned, use that price directly.
- If multiple price tiers exist (e.g. bulk discount for 10+), use the BASE (smaller quantity) price.
- If no price found, use 0.

STOCK LOGIC:
- If no stock quantity is mentioned, use null (means unlimited).
- Only use a number if an explicit stock count is stated.

NAME LOGIC:
- Extract a clean product name, strip all emojis and symbols (✅, 💕, etc.).
- Max 60 characters.

DESCRIPTION LOGIC:
- Use the FULL cleaned post text below as-is. Do not shorten or edit.

CATEGORY LOGIC:
- Suggest a short category name fitting this product (e.g. "ဆေးဝါး", "အစားအစာ", "Food", "Condiments", etc.)

Return ONLY a valid JSON object with these exact keys:
- "name": string
- "price": number (the CALCULATED wholesale price)
- "stock": number or null
- "description": string (full cleaned post)
- "suggested_category": string
- "price_calculation": string (brief note on how price was calculated, e.g. "3420 × 120 = 410400")

Post content:
\"\"\"
{description_text}
\"\"\"

Return ONLY the JSON. No markdown, no explanation."""

    try:
        provider = ai_settings[0].get('ai_provider') or 'deepseek'
        client, model = get_ai_client_and_model(api_key, provider)

        if provider == "gemini":
            def _call_gemini():
                return call_gemini_ai(api_key, [{"role": "user", "content": prompt}])
            resp = await asyncio.get_event_loop().run_in_executor(None, _call_gemini)
            raw = resp.text.strip()
        else:
            def _call_openai():
                return client.chat.completions.create(
                    model=model,
                    messages=[{"role": "user", "content": prompt}],
                    stream=False
                )
            resp = await asyncio.get_event_loop().run_in_executor(None, _call_openai)
            raw = resp.choices[0].message.content.strip()

        raw = re.sub(r"^```(?:json)?", "", raw).strip()
        raw = re.sub(r"```$", "", raw).strip()
        extracted = json.loads(raw)

    except json.JSONDecodeError:
        await thinking_msg.edit_text("❌ AI returned an unexpected format. Please try again.")
        return State.AI_ADD_PRODUCT_AWAIT_POST
    except Exception as e:
        logger.error(f"AI product extraction error: {e}")
        await thinking_msg.edit_text(f"❌ AI error: {e}\n\nPlease try again.")
        return State.AI_ADD_PRODUCT_AWAIT_POST

    # Handle stock
    raw_stock = extracted.get('stock')
    try:
        stock_value = int(raw_stock) if raw_stock is not None else None
    except (ValueError, TypeError):
        stock_value = None

    # Handle price
    try:
        price_value = Decimal(str(extracted.get('price', 0)))
    except Exception:
        price_value = Decimal('0')

    price_note = extracted.get('price_calculation', '')
    extracted_name = str(extracted.get('name', 'Unnamed Product'))[:60]

    await thinking_msg.delete()

    # ── Check DB for existing product with same name (price update path) ──
    existing_in_db = db.execute_query(
        "SELECT id, name, price FROM products WHERE bot_id = %s AND LOWER(name) = LOWER(%s) LIMIT 1",
        (bot_id, extracted_name), fetch=True
    )

    if existing_in_db:
        old_price = Decimal(str(existing_in_db[0]['price']))
        product_id = existing_in_db[0]['id']
        if old_price != price_value:
            db.execute_query("UPDATE products SET price = %s WHERE id = %s", (price_value, product_id))
            note = (
                f"🔄 *Price Updated*\n\n"
                f"Product: *{escape_markdown(extracted_name)}*\n"
                f"Old price: {old_price}\n"
                f"New price: {price_value}"
            )
            if price_note:
                note += f"\n📐 Calculation: {escape_markdown(price_note)}"
            note += "\n\n✅ Product price updated in shop."
            await update.message.reply_text(note, parse_mode=ParseMode.MARKDOWN)
        else:
            await update.message.reply_text(
                f"ℹ️ *{escape_markdown(extracted_name)}* already exists with the same price \\({price_value}\\)\\. No changes made\\.",
                parse_mode=ParseMode.MARKDOWN_V2
            )
        context.user_data.pop('ai_new_product', None)
        await handle_admin_panel_2(update, context)
        return State.ADMIN_PANEL_2

    # ── NEW PRODUCT path ───────────────────────────────────────────────────
    media_list = []
    if photo_file_id:
        media_list = [{'type': 'photo', 'file_id': photo_file_id}]

    context.user_data['ai_new_product'] = {
        'name': extracted_name,
        'price': price_value,
        'price_note': price_note,
        'stock_quantity': stock_value,
        'description': description_text,
        'suggested_category': str(extracted.get('suggested_category', 'General'))[:25],
        'media': media_list,
        'image_from_caption': bool(photo_file_id),
    }

    confirmation_note = ""
    if price_note:
        confirmation_note = f"\n📐 *Price calculation:* {escape_markdown(price_note)}"

    await update.message.reply_text(
        f"✅ Product info extracted!{confirmation_note}\n\nNow selecting category...",
        parse_mode=ParseMode.MARKDOWN
    )
    return await _show_ai_category_confirmation(update, context)


async def _show_ai_category_confirmation(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Shows existing categories + AI suggested category for admin to confirm."""
    bot_id = await get_bot_id(context.bot.token)
    categories = get_categories(bot_id)
    suggested = context.user_data['ai_new_product']['suggested_category']

    text = (
        f"📂 *Category Selection*\n\n"
        f"AI suggests category: *{escape_markdown(suggested)}*\n\n"
        f"Please select an existing category, confirm AI suggestion, or create a new one:"
    )

    keyboard = []
    if categories:
        for cat in categories:
            label = f"✅ {cat['name']}" if cat['name'].lower() == suggested.lower() else cat['name']
            keyboard.append([InlineKeyboardButton(label, callback_data=f"ai_prod_cat_existing_{cat['id']}")])
    keyboard.append([InlineKeyboardButton(f"✨ Create \"{suggested}\"", callback_data="ai_prod_cat_create_suggested")])
    keyboard.append([InlineKeyboardButton("➕ Create Custom Category", callback_data="ai_prod_cat_create_custom")])
    keyboard.append([InlineKeyboardButton("❌ Cancel", callback_data="ap2_cancel")])

    if update.callback_query:
        await safe_edit_caption_or_text(update.callback_query, text, InlineKeyboardMarkup(keyboard))
    else:
        await update.message.reply_text(text, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode=ParseMode.MARKDOWN)

    return State.AI_ADD_PRODUCT_CONFIRM_CATEGORY


async def ai_product_select_category(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Handles category selection for AI product flow."""
    query = update.callback_query
    await query.answer()
    bot_id = await get_bot_id(context.bot.token)
    data = query.data

    if data.startswith("ai_prod_cat_existing_"):
        category_id = int(data.split("_")[-1])
        context.user_data['ai_new_product']['category_id'] = category_id

    elif data == "ai_prod_cat_create_suggested":
        suggested = context.user_data['ai_new_product']['suggested_category']
        db.execute_query("INSERT INTO categories (bot_id, name, emoji) VALUES (%s, %s, %s)", (bot_id, suggested, "📦"))
        new_cat = db.execute_query(
            "SELECT id FROM categories WHERE bot_id = %s AND name = %s ORDER BY id DESC LIMIT 1",
            (bot_id, suggested), fetch=True
        )
        context.user_data['ai_new_product']['category_id'] = new_cat[0]['id'] if new_cat else None

    elif data == "ai_prod_cat_create_custom":
        await safe_edit_caption_or_text(
            query,
            "✏️ Please send the name for the new category:",
            InlineKeyboardMarkup([[InlineKeyboardButton("❌ Cancel", callback_data="ap2_cancel")]])
        )
        context.user_data['ai_new_product']['awaiting_custom_category'] = True
        return State.AI_ADD_PRODUCT_CONFIRM_CATEGORY

    return await _ask_ai_product_media(query, context)


async def ai_product_receive_custom_category(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Receives custom category name typed by admin."""
    if not context.user_data.get('ai_new_product', {}).get('awaiting_custom_category'):
        return State.AI_ADD_PRODUCT_CONFIRM_CATEGORY

    cat_name = update.message.text.strip()
    bot_id = await get_bot_id(context.bot.token)

    db.execute_query("INSERT INTO categories (bot_id, name, emoji) VALUES (%s, %s, %s)", (bot_id, cat_name, "📦"))
    new_cat = db.execute_query(
        "SELECT id FROM categories WHERE bot_id = %s AND name = %s ORDER BY id DESC LIMIT 1",
        (bot_id, cat_name), fetch=True
    )
    context.user_data['ai_new_product']['category_id'] = new_cat[0]['id'] if new_cat else None
    context.user_data['ai_new_product'].pop('awaiting_custom_category', None)

    await update.message.reply_text(f"✅ Category '{cat_name}' created!")
    return await _ask_ai_product_media(update, context)


async def _ask_ai_product_media(trigger, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Asks admin to send media for the AI product. Skips if image already captured from caption."""
    p = context.user_data.get('ai_new_product', {})

    # If image was already captured from the caption photo, go straight to preview
    if p.get('image_from_caption') and p.get('media'):
        if hasattr(trigger, 'message') and trigger.message:
            await trigger.message.reply_text(
                "📸 Image from your post has been captured automatically. Proceeding to preview...",
                reply_markup=ReplyKeyboardRemove()
            )
            return await _show_ai_product_preview(trigger, context)
        else:
            await trigger.reply_text(
                "📸 Image from your post has been captured automatically. Proceeding to preview...",
                reply_markup=ReplyKeyboardRemove()
            )
            return await _show_ai_product_preview(trigger, context)

    text = (
        "📸 *Upload Media*\n\n"
        "Please send photos or videos for this product one by one.\n\n"
        "Press *✅ Done* when finished, or *⏭️ Skip Media* to add no media."
    )
    reply_keyboard = ReplyKeyboardMarkup(
        [["✅ Done", "⏭️ Skip Media"]],
        resize_keyboard=True, one_time_keyboard=True
    )
    if hasattr(trigger, 'message') and trigger.message:
        await trigger.message.reply_text(text, reply_markup=reply_keyboard, parse_mode=ParseMode.MARKDOWN)
    else:
        await trigger.reply_text(text, reply_markup=reply_keyboard, parse_mode=ParseMode.MARKDOWN)
    return State.AI_ADD_PRODUCT_AWAIT_MEDIA


async def ai_product_receive_media(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Collects media for the AI product."""
    if 'media' not in context.user_data['ai_new_product']:
        context.user_data['ai_new_product']['media'] = []

    media_item = None
    if update.message.photo:
        media_item = {'type': 'photo', 'file_id': update.message.photo[-1].file_id}
    elif update.message.video:
        media_item = {'type': 'video', 'file_id': update.message.video.file_id}

    if media_item:
        context.user_data['ai_new_product']['media'].append(media_item)
        count = len(context.user_data['ai_new_product']['media'])
        await update.message.reply_text(
            f"✅ Media {count} received. Send more or press *✅ Done*.",
            parse_mode=ParseMode.MARKDOWN
        )
    else:
        await update.message.reply_text("⚠️ Unsupported media type. Please send a photo or video.")

    return State.AI_ADD_PRODUCT_AWAIT_MEDIA


async def ai_product_finish_media(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Handles Done or Skip Media — moves to preview."""
    await update.message.reply_text("⏳ Preparing preview...", reply_markup=ReplyKeyboardRemove())
    return await _show_ai_product_preview(update, context)


async def _show_ai_product_preview(trigger, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Shows full product preview with per-field edit buttons."""
    p = context.user_data['ai_new_product']
    lang = await get_user_lang(context)
    price_str = await format_price(context, p.get('price', Decimal(0)), lang)
    stock_val = p.get('stock_quantity', 0)
    stock_str = str(stock_val) if stock_val is not None else "Unlimited"
    media_count = len(p.get('media', []))
    desc_full = p.get('description') or 'Not set'
    desc_preview = desc_full[:300] + ('...' if len(desc_full) > 300 else '')

    summary = (
        f"📋 *Product Preview*\n\n"
        f"🏷️ *Name:* {escape_markdown(p.get('name', 'N/A'))}\n"
        f"💰 *Price:* {price_str}\n"
        f"📦 *Stock:* {stock_str}\n"
        f"📸 *Media:* {media_count} file(s)\n"
        f"📝 *Description (preview):*\n{escape_markdown(desc_preview)}\n\n"
        "Review and confirm, or edit any field below:"
    )

    keyboard = [
        [InlineKeyboardButton("✏️ Edit Name", callback_data="ai_edit_name"),
         InlineKeyboardButton("✏️ Edit Price", callback_data="ai_edit_price")],
        [InlineKeyboardButton("✏️ Edit Stock", callback_data="ai_edit_stock"),
         InlineKeyboardButton("✏️ Edit Description", callback_data="ai_edit_desc")],
        [InlineKeyboardButton("✅ Confirm & Save", callback_data="ai_prod_save")],
        [InlineKeyboardButton("❌ Cancel", callback_data="ap2_cancel")]
    ]

    if hasattr(trigger, 'callback_query') and trigger.callback_query:
        await safe_edit_caption_or_text(trigger.callback_query, summary, InlineKeyboardMarkup(keyboard))
    else:
        msg = trigger.message if hasattr(trigger, 'message') else trigger
        await msg.reply_text(summary, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode=ParseMode.MARKDOWN)

    return State.AI_ADD_PRODUCT_PREVIEW


async def ai_product_edit_field(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Routes to the correct field edit based on button pressed."""
    query = update.callback_query
    await query.answer()

    prompts = {
        "ai_edit_name": "✏️ Send the new *product name*:",
        "ai_edit_price": "✏️ Send the new *price* (numbers only):",
        "ai_edit_stock": "✏️ Send the new *stock quantity* (whole number only):",
        "ai_edit_desc": "✏️ Send the new *description*:",
    }

    context.user_data['ai_new_product']['editing_field'] = query.data

    await safe_edit_caption_or_text(
        query,
        prompts.get(query.data, "✏️ Send the new value:"),
        InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Back to Preview", callback_data="ai_back_to_preview")]])
    )
    return State.AI_ADD_PRODUCT_EDIT_FIELD


async def ai_product_receive_edit(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Receives the edited value, updates context, then returns to preview."""
    field = context.user_data['ai_new_product'].get('editing_field')
    value = update.message.text.strip()

    if field == "ai_edit_name":
        context.user_data['ai_new_product']['name'] = value[:60]
    elif field == "ai_edit_price":
        try:
            context.user_data['ai_new_product']['price'] = Decimal(value)
        except Exception:
            await update.message.reply_text("❌ Invalid price. Please send numbers only.")
            return State.AI_ADD_PRODUCT_EDIT_FIELD
    elif field == "ai_edit_stock":
        if not value.isdigit():
            await update.message.reply_text("❌ Invalid stock. Please send a whole number.")
            return State.AI_ADD_PRODUCT_EDIT_FIELD
        context.user_data['ai_new_product']['stock_quantity'] = int(value)
    elif field == "ai_edit_desc":
        context.user_data['ai_new_product']['description'] = value

    context.user_data['ai_new_product'].pop('editing_field', None)
    await update.message.reply_text("✅ Updated!")
    return await _show_ai_product_preview(update, context)


async def ai_product_back_to_preview(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Back button from edit field returns to preview."""
    query = update.callback_query
    await query.answer()
    context.user_data['ai_new_product'].pop('editing_field', None)
    return await _show_ai_product_preview(update, context)


async def ai_product_save(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Saves the AI-assembled product to the database."""
    query = update.callback_query
    await query.answer()

    p = context.user_data['ai_new_product']
    bot_id = await get_bot_id(context.bot.token)
    media_json = json.dumps(p.get('media', []))

    db.execute_query(
        """
        INSERT INTO products (bot_id, category_id, name, price, description, image_url, stock_quantity)
        VALUES (%s, %s, %s, %s, %s, %s, %s)
        """,
        (
            bot_id,
            p['category_id'],
            p['name'],
            p.get('price'),
            p.get('description'),
            media_json,
            p.get('stock_quantity')
        )
    )

    await safe_edit_caption_or_text(
        query,
        f"✅ *Product '{escape_markdown(p['name'])}' saved successfully!*\n\nIt is now live in your shop.",
        None
    )
    context.user_data.pop('ai_new_product', None)

    await handle_admin_panel_2(update, context)
    return State.ADMIN_PANEL_2

