async def start_add_payment(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Starts the 'Add Payment Method' flow."""
    query = update.callback_query


    bot_id = await get_bot_id(context.bot.token)
    limits = await get_bot_plan_and_limits(bot_id)
    payment_method_count_res = db.execute_query("SELECT COUNT(*) as count FROM payment_methods WHERE bot_id = %s", (bot_id,), fetch=True)
    payment_method_count = payment_method_count_res[0]['count'] if payment_method_count_res else 0

    if payment_method_count >= limits['payment_methods']:
        await query.answer(f"❌ You have reached the limit ({payment_method_count}/{limits['payment_methods']}) for payment methods. Please upgrade your plan to add more.", show_alert=True)
        return State.MANAGE_PAYMENT

    await query.answer()
    context.user_data['new_payment_data'] = {}

    await safe_edit_caption_or_text(
        query,
        "Enter the name for the new payment method (e.g., KBZPay, WavePay).",
        InlineKeyboardMarkup([[InlineKeyboardButton("❌ Cancel", callback_data="ap2_manage_payment")]])
    )
    return State.ADD_PAYMENT_NAME

