async def receive_payment_notes(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Stores the notes (or skips) and asks for an optional QR code."""
    query = update.callback_query
    notes = None

    if query and query.data == "ap2_skip_notes":
        await query.answer("Notes skipped.")
        message = query.message
    else:
        message = update.message
        if not message.text:
            await message.reply_text("⚠️ Please send text only for the notes, or press Skip.")
            return State.ADD_PAYMENT_NOTES
        notes = message.text.strip()

    context.user_data['new_payment_data']['notes'] = notes

    keyboard = [[InlineKeyboardButton("⏭️ Skip", callback_data="ap2_skip_qr")]]
    await message.reply_text(
        "Notes saved. Now, please send a QR code image for this payment method (optional).",
        reply_markup=InlineKeyboardMarkup(keyboard)
    )
    return State.ADD_PAYMENT_QR

async def receive_payment_qr(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Stores the QR code (or skips) and shows final confirmation."""
    query = update.callback_query
    qr_file_id = None

    if query and query.data == "ap2_skip_qr":
        await query.answer("QR Code skipped.")
        message = query.message
    elif update.message and update.message.photo:
        message = update.message
        qr_file_id = update.message.photo[-1].file_id
    else:
        await update.message.reply_text("⚠️ Please send a photo, or press Skip.")
        return State.ADD_PAYMENT_QR

    context.user_data['new_payment_data']['qr'] = qr_file_id
    payment_data = context.user_data['new_payment_data']
    notes = payment_data.get('notes')
    notes_display = escape_markdown(notes) if notes else "Not set"

    summary = (
        f"📝 *Review New Payment Method*\n\n"
        f"**Name:** {escape_markdown(payment_data.get('name', 'N/A'))}\n"
        f"**Number:** {escape_markdown(payment_data.get('number', 'N/A'))}\n"
        f"**Notes:** {notes_display}\n"
        f"**QR Code:** {'Provided' if qr_file_id else 'Not set'}\n\n"
        "Please confirm to save."
    )

    keyboard = [
        [InlineKeyboardButton("✅ Save Method", callback_data="ap2_pay_save")],
        [InlineKeyboardButton("❌ Discard", callback_data="ap2_cancel")]
    ]

    await message.reply_text(
        summary,
        reply_markup=InlineKeyboardMarkup(keyboard),
        parse_mode=ParseMode.MARKDOWN
    )
    return State.ADD_PAYMENT_CONFIRM


