async def save_payment_method(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Saves the new payment method to the database."""
    query = update.callback_query
    await query.answer()

    payment_data = context.user_data['new_payment_data']
    bot_id = await get_bot_id(context.bot.token)


    success = db.execute_query(
        """
        INSERT INTO payment_methods (bot_id, name, payment_number, qr_code_url, is_active, notes)
        VALUES (%s, %s, %s, %s, %s, %s)
        """,
        (
            bot_id,
            payment_data['name'],
            payment_data['number'],
            payment_data.get('qr'),
            True,
            payment_data.get('notes')
        )
    )

    if success:
        await safe_edit_caption_or_text(query, f"✅ Payment method '{payment_data['name']}' saved successfully!", None)
        context.user_data.pop('new_payment_data', None)
    else:
        await safe_edit_caption_or_text(
            query,
            f"❌ Failed to save payment method. The payment *number* '{escape_markdown(payment_data['number'])}' might already exist.",
            None
        )

    await handle_admin_panel_2(update, context)
    return State.ADMIN_PANEL_2



async def handle_manage_orders(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Shows a list of orders pending review."""
    query = update.callback_query
    lang = await get_user_lang(context)

    bot_id = await get_bot_id(context.bot.token)
    if not bot_id:
        await query.answer("Error: This bot is not registered correctly.", show_alert=True)
        return State.ADMIN_PANEL

    pending_orders = get_pending_orders(bot_id)


    if not pending_orders:
        await query.answer("There are no orders to review currently.", show_alert=True)
        return State.ADMIN_PANEL

    await query.answer()

    caption = "📋 *Pending Orders for Review*\n\nSelect an order to view its details and payment proof."
    keyboard = []


    for order in pending_orders:
        order_date = order['created_at'].strftime("%b %d")

        final_amount_str = await format_price(context, order['final_amount'], lang)
        button_text = f"Order {order['order_number']} ({final_amount_str}) - {order_date}"
        keyboard.append([InlineKeyboardButton(button_text, callback_data=f"admin_view_order_{order['order_number']}")])

    keyboard.append([InlineKeyboardButton("🔙 Admin Panel", callback_data="admin_panel")])
    reply_markup = InlineKeyboardMarkup(keyboard)

    await safe_edit_caption_or_text(
        query,
        caption,
        reply_markup
    )

    return State.ADMIN_PANEL




async def admin_view_order_details(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Shows a specific pending order's details to an admin."""
    query = update.callback_query
    await query.answer()
    lang = await get_user_lang(context)

    order_number = query.data.split('_')[-1]
    order = get_order(order_number)

    if not order:
        await query.edit_message_text(
            "❌ Order not found. It might have been processed by another admin.",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Manage Orders", callback_data="manage_orders")]])
        )
        return State.ADMIN_PANEL

    customer = get_user_by_id(order['user_id'])
    if not customer:
        await query.edit_message_text("❌ Error: Could not retrieve customer data for this order.")
        return State.ADMIN_PANEL

    proof_message_ids = order.get('payment_proof_messages')
    if proof_message_ids:
        await query.message.reply_text(f"🧾 Payment proof for order `{order_number}`:", parse_mode=ParseMode.MARKDOWN)
        for entry in proof_message_ids:
            msg_id = entry["message_id"] if isinstance(entry, dict) else entry
            try:
                await context.bot.forward_message(
                    chat_id=update.effective_chat.id,
                    from_chat_id=customer['telegram_id'],
                    message_id=msg_id
                )
                time.sleep(0.1)
            except Exception as e:
                await query.message.reply_text(f"⚠️ Could not forward payment proof (ID: {msg_id}). Error: {e}")
    else:
        await query.message.reply_text("⚠️ No payment proof was submitted for this order.")

    total_amount_str = await format_price(context, order['final_amount'], lang)
    customer_full_name = f"{customer.get('first_name', '')} {customer.get('last_name', '')}".strip()

    details_text = (
        f"🚨 *Review Order: {order_number}* 🚨\n\n"
        f"*Customer:* {customer_full_name} (@{customer.get('username', 'N/A')})\n"
        f"*Customer TG ID:* `{customer['telegram_id']}`\n"
        f"*Total Amount:* {total_amount_str}\n"
        f"*Payment Method:* {order['payment_method']}\n\n"
        "Please review the payment proof and confirm or reject the payment."
    )

    keyboard = InlineKeyboardMarkup([
        [InlineKeyboardButton("✅ Yes, Payment Received", callback_data=f"confirm_payment_yes_{order_number}_{customer['telegram_id']}")],
        [InlineKeyboardButton("❌ No, Payment Not Received", callback_data=f"confirm_payment_no_{order_number}_{customer['telegram_id']}")],
        [InlineKeyboardButton("🔙 Back to Orders List", callback_data="manage_orders")]
    ])

    await safe_edit_caption_or_text(query, details_text, keyboard)

    return State.ADMIN_PANEL

