async def handle_delete_payment_method_execute(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Execute deletion of a payment method."""
    query = update.callback_query
    await query.answer()

    method_id = int(query.data.split('_')[-1])
    method_name = get_payment_method(method_id)['name']

    success = delete_payment_method(method_id)

    if success:
        bot_id = await get_bot_id(context.bot.token)
        no_payments_left = bot_id and not _has_payment_methods(bot_id)
        success_msg = f"✅ Payment method '{method_name}' deleted successfully!"
        if no_payments_left:
            success_msg += "\n\n⚠️ No payment methods remaining — the shop has been automatically closed. Add a payment method to reopen."
        await safe_edit_caption_or_text(
            query,
            success_msg,
            InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Manage Methods", callback_data="manage_payment_methods")]])
        )
    else:
        await safe_edit_caption_or_text(
            query,
            f"❌ Failed to delete payment method '{method_name}'. Please try again.",
            InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Manage Methods", callback_data="manage_payment_methods")]])
        )

    return State.ADMIN_PANEL




