async def collect_broadcast_content(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Collects all messages sent by the admin for a broadcast."""
    is_first_message = not context.user_data.get('broadcast_messages_to_send')
    serialized_msg = serialize_message(update.message)

    if serialized_msg:
        context.user_data.setdefault('broadcast_messages_to_send', []).append(serialized_msg)

        if is_first_message:
            reply_keyboard = ReplyKeyboardMarkup(
                [[KeyboardButton("Finish"), KeyboardButton("Cancel")]],
                resize_keyboard=True
            )
            await update.message.reply_text("👍 First message received. Use the buttons below to manage your broadcast.", reply_markup=reply_keyboard)
        else:
            await update.message.reply_text("👍 Message received. Send more or press '✅ Finish'.")
    else:
        await update.message.reply_text("⚠️ Sorry, that message type is not supported.")


    return State.BROADCAST_MESSAGE


async def collect_global_broadcast_content(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """
    (NEW) Collects all messages sent by the admin for a GLOBAL broadcast.
    This is a separate function to avoid state conflicts with the single-bot broadcast.
    """
    is_first_message = not context.user_data.get('broadcast_messages_to_send')
    serialized_msg = serialize_message(update.message)

    if serialized_msg:
        context.user_data.setdefault('broadcast_messages_to_send', []).append(serialized_msg)

        if is_first_message:
            reply_keyboard = ReplyKeyboardMarkup(
                [[KeyboardButton("Finish"), KeyboardButton("Cancel")]],
                resize_keyboard=True
            )
            await update.message.reply_text("👍 First message received. Use the buttons below to manage your broadcast.", reply_markup=reply_keyboard)
        else:
            await update.message.reply_text("👍 Message received. Send more or press '✅ Finish'.")
    else:
        await update.message.reply_text("⚠️ Sorry, that message type is not supported.")


    return State.GLOBAL_BROADCAST_MESSAGE

async def finalize_broadcast(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Asks for confirmation before broadcasting after 'Finish' is pressed."""
    messages_to_send = context.user_data.get('broadcast_messages_to_send', [])

    if not messages_to_send:
        await update.message.reply_text("⚠️ No messages were collected. Broadcast cancelled.", reply_markup=ReplyKeyboardRemove())
        await handle_admin_panel(update, context)
        return State.ADMIN_PANEL

    caption = (
        f"⚠️ *Confirm Broadcast*\n\n"
        f"You are about to send *{len(messages_to_send)}* message(s) to all non-admin users.\n\n"
        "Are you sure you want to proceed?"
    )
    keyboard = [
        [InlineKeyboardButton("✅ Yes, Broadcast Now", callback_data="broadcast_confirm_yes")],
        [InlineKeyboardButton("❌ No, Cancel", callback_data="broadcast_confirm_no")]
    ]

    await update.message.reply_text(caption, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode=ParseMode.MARKDOWN)
    return State.BROADCAST_MESSAGE

async def cancel_broadcast(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Cancels the broadcast creation process."""
    context.user_data.pop('broadcast_messages_to_send', None)

    if update.callback_query:
        await update.callback_query.answer("Broadcast Cancelled")
        await safe_edit_caption_or_text(
            update.callback_query,
            "❌ Broadcast cancelled.",
            InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Admin Panel", callback_data="admin_panel")]])
        )
    else:
        await update.message.reply_text("❌ Broadcast cancelled.", reply_markup=ReplyKeyboardRemove())

    return await handle_admin_panel(update, context)



