async def prompt_for_caption_update(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Asks the admin to send a new caption."""
    query = update.callback_query

    caption_key = query.data.replace('update_caption_', '')
    bot_id = await get_bot_id(context.bot.token)
    limits = await get_bot_plan_and_limits(bot_id)

    allowed_updates = limits['update_info']
    if allowed_updates != 'all' and caption_key not in allowed_updates:
        await query.answer("❌ Your current plan does not allow updating this caption. Please upgrade.", show_alert=True)
        return State.ADMIN_UPDATE_CAPTION

    await query.answer()


    caption_key = query.data.replace('update_caption_', '')
    context.user_data['caption_update_key'] = caption_key


    section_name = caption_key.replace('_', ' ').replace('caption', '').replace('title', '').replace('menu', '').strip().title()

    await safe_edit_caption_or_text(
        query,
        f"✍️ *Updating: {section_name} Caption*\n\nPlease send the new text you want to use for this section's caption.",
        InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Back", callback_data="admin_update_caption")]])
    )

    return State.AWAITING_CAPTION_UPDATE

async def save_updated_caption(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Receives text from an admin and saves it as the new caption."""
    if not update.message or not update.message.text:
        await update.message.reply_text("⚠️ Please send text only.")
        return State.AWAITING_CAPTION_UPDATE

    caption_key = context.user_data.get('caption_update_key')
    if not caption_key:
        await update.message.reply_text("❌ Error: Session expired. Could not determine which caption to update. Please start over.")

        caption = "✍️ *Update Captions*\n\nSelect which caption you would like to update."
        keyboard = [
            [InlineKeyboardButton("Update Welcome Caption", callback_data="update_caption_welcome_caption")],
            [InlineKeyboardButton("Update Search Caption", callback_data="update_caption_search_caption")],
            [InlineKeyboardButton("Update View Cart Caption", callback_data="update_caption_cart_caption_title")],
            [InlineKeyboardButton("Update My Order Caption", callback_data="update_caption_my_orders_caption")],
            [InlineKeyboardButton("Update Setting Caption", callback_data="update_caption_settings_caption")],
            [InlineKeyboardButton("Update Support Caption", callback_data="update_caption_support_caption")],
            [InlineKeyboardButton("Update About Caption", callback_data="update_caption_about_menu_caption")],
            [InlineKeyboardButton("Update Order Confirmation Message", callback_data="update_caption_order_confirmation_message")],
            [InlineKeyboardButton("🔙 Back to Admin Panel", callback_data="admin_panel")]
        ]
        await update.message.reply_text(caption, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode=ParseMode.MARKDOWN)
        return State.ADMIN_UPDATE_CAPTION

    new_caption_text = update.message.text
    content_payload = {"source": "text", "content": new_caption_text}
    bot_id = await get_bot_id(context.bot.token)
    user_data = await get_or_create_user(update.effective_user.id, update.effective_user.username, update.effective_user.first_name, update.effective_user.last_name, update.effective_user.username, context.bot.token)
    admin_user_id = user_data['id'] if user_data else None

    query_str = """
        INSERT INTO content_blocks (bot_id, key, content_data, updated_by_user_id, updated_at)
        VALUES (%s, %s, %s, %s, NOW())
        ON CONFLICT (bot_id, key) DO UPDATE SET
            content_data = EXCLUDED.content_data,
            updated_at = NOW(),
            updated_by_user_id = EXCLUDED.updated_by_user_id;
    """
    db.execute_query(query_str, (bot_id, caption_key, json.dumps(content_payload), admin_user_id))

    await update.message.reply_text("✅ Caption successfully updated!")
    context.user_data.pop('caption_update_key', None)

    # Return to the main caption menu to re-evaluate options
    return await admin_update_caption_menu(update, context)
