async def email_notif_receive_input(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Validates and asks confirmation for the email typed by admin."""
    text = update.message.text.strip() if update.message and update.message.text else ""
    # Basic email validation
    if not re.match(r'^[\w\.\+\-]+@[\w\-]+\.[a-zA-Z]{2,}$', text):
        await update.message.reply_text(
            "❌ That doesn't look like a valid email address. Please try again:",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Cancel", callback_data="email_notification_menu")]])
        )
        return State.AWAITING_NOTIFICATION_EMAIL

    context.user_data['pending_notification_email'] = text
    await update.message.reply_text(
        f"📧 Confirm your email address:\n\n`{text}`\n\nIs this correct?",
        parse_mode=ParseMode.MARKDOWN,
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("✅ Yes, Save", callback_data="email_notif_confirm_save"),
             InlineKeyboardButton("❌ No, Re-enter", callback_data="email_notif_set")]
        ])
    )
    return State.EMAIL_NOTIFICATION_MENU


async def email_notif_confirm_save(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Saves the confirmed email to DB."""
    query = update.callback_query
    await query.answer()
    email = context.user_data.pop('pending_notification_email', None)
    if not email:
        await query.answer("Session expired. Please try again.", show_alert=True)
        return await email_notification_menu(update, context)

    bot_id = await get_bot_id(context.bot.token)
    db.execute_query(
        "UPDATE managed_bots SET admin_notification_email = %s WHERE id = %s",
        (email, bot_id)
    )
    await safe_edit_caption_or_text(
        query,
        f"✅ *Email saved!*\n"
        f"`{email}`\n\n"
        f"📬 Please check your spam folder for your first order alert and mark it as *'Not Spam'* so future emails land in your inbox.\n\n"
        f"ပထမဆုံး Order ကို\n"
        f"Primary နဲ့ Spam နှစ်ခုလုံးမှာ စစ်ပေးပါ။\n\n"
        f"Spam ထဲရောက်နေပါက\n"
        f"*'Report not spam'* ကိုနှိပ်ပေးပါ။",
        InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Back to Email Menu", callback_data="email_notification_menu")]])
    )
    return State.EMAIL_NOTIFICATION_MENU


async def email_notif_remove(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Removes the saved notification email."""
    query = update.callback_query
    await query.answer()
