    new_state = not currently_enabled
    db.execute_query(
        "UPDATE managed_bots SET email_notifications_enabled = %s WHERE id = %s",
        (new_state, bot_id)
    )
    await query.answer(f"{'✅ Enabled' if new_state else '❌ Disabled'} email notifications.", show_alert=False)
    return await email_notification_menu(update, context)


