async def execute_global_broadcast(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Performs the broadcast to all users of all active bots."""
    query = update.callback_query
    messages_to_send = context.user_data.get('broadcast_messages_to_send', [])
    await query.answer()
    await safe_edit_caption_or_text(query, "⏳ Preparing global broadcast... (This may take a moment for media files)", None)


    processed_messages = []
    for msg in messages_to_send:
        processed_msg = msg.copy()
        file_id = processed_msg.get('file_id')
        if file_id:
            try:

                file = await context.bot.get_file(file_id)
                file_content = await file.download_as_bytearray()
                processed_msg['file_content'] = bytes(file_content)
            except Exception as e:
                logger.error(f"Failed to download media for global broadcast (file_id: {file_id}): {e}")
                continue
        processed_messages.append(processed_msg)

    all_active_bots = db.execute_query("SELECT id, bot_token FROM managed_bots WHERE is_active = TRUE", fetch=True)
    if not all_active_bots:
        await safe_edit_caption_or_text(query, "❌ No active bots found.", InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Back to Settings", callback_data="settings")]]))
        return State.SETTINGS

    total_success = 0
    total_failed = 0

    await safe_edit_caption_or_text(query, f"⏳ Sending broadcast to users of {len(all_active_bots)} bots...", None)

    for bot in all_active_bots:
        bot_id = bot['id']
        bot_token = bot['bot_token']

        try:
            temp_bot_app = Application.builder().token(bot_token).build()
            users_of_this_bot = db.execute_query(
                "SELECT telegram_id FROM users WHERE is_admin = FALSE AND bot_id = %s AND telegram_id IS NOT NULL",
                (bot_id,), fetch=True
            )

            for user in users_of_this_bot:
                telegram_id = user['telegram_id']
                try:
                    for msg in processed_messages:
                        msg_type, text, entities, file_content = msg.get("type"), msg.get("text") or msg.get("caption", ""), msg.get("entities"), msg.get("file_content")
                        if msg_type == "text":
                            await temp_bot_app.bot.send_message(chat_id=telegram_id, text=text, entities=entities)
                        elif msg_type == "photo":
                            await temp_bot_app.bot.send_photo(chat_id=telegram_id, photo=file_content, caption=text, caption_entities=entities)
                        elif msg_type == "video":
                            await temp_bot_app.bot.send_video(chat_id=telegram_id, video=file_content, caption=text, caption_entities=entities)
                        elif msg_type == "document":
                            await temp_bot_app.bot.send_document(chat_id=telegram_id, document=file_content, caption=text, caption_entities=entities)
                        await asyncio.sleep(0.1)
                    total_success += 1
                except (telegram.error.Forbidden, telegram.error.BadRequest) as e:
                    logger.warning(f"Could not send global broadcast to user {telegram_id} (bot {bot_id}): {e}.")
                    total_failed += 1
        except Exception as e:
            logger.error(f"Failed to process broadcast for bot ID {bot_id}: {e}")

    await safe_edit_caption_or_text(
        query,
        f"✅ Global broadcast complete!\n\n➡️ Sent to: {total_success} users\n❌ Failed for: {total_failed} users.",
        InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Back to Settings", callback_data="settings")]])
    )

    await context.bot.send_message(chat_id=query.message.chat_id, text="Broadcast menu closed.", reply_markup=ReplyKeyboardRemove())
    context.user_data.pop('broadcast_messages_to_send', None)

    return State.SETTINGS





