async def collect_content_update(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Collects all messages sent by the admin for a content block."""
    is_first_message = not context.user_data.get('collected_messages')
    serialized_msg = serialize_message(update.message)

    if serialized_msg:
        context.user_data.setdefault('collected_messages', []).append(serialized_msg)
        if is_first_message:
            reply_keyboard = ReplyKeyboardMarkup([["Save", "Cancel"]], resize_keyboard=True)
            await update.message.reply_text("👍 First message received. Use the buttons below.", reply_markup=reply_keyboard)
        else:
            await update.message.reply_text("👍 Message received. Send more or press '✅ Save'.")
    else:
        await update.message.reply_text("⚠️ Sorry, that message type is not supported.")
    return State.AWAITING_CONTENT_UPDATE



async def save_content_update(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Saves the collected content to the database."""
    content_key = context.user_data.get('update_content_key')
    collected_messages = context.user_data.get('collected_messages', [])

    if not content_key:
        await update.message.reply_text("❌ Error: Couldn't identify what to update. Cancelling.", reply_markup=ReplyKeyboardRemove())
        return await admin_update_info_menu(update, context)

    if not collected_messages:
        await update.message.reply_text("⚠️ You didn't send any content. Nothing to save.", reply_markup=ReplyKeyboardRemove())
        return await admin_update_info_menu(update, context)

    user = update.effective_user
    user_data = await get_or_create_user(user.id, user.username, user.first_name, user.last_name, user.username, context.bot.token)
    admin_user_id = user_data['id'] if user_data else None


    bot_id = await get_bot_id(context.bot.token)

    content_payload = {"source": "telegram", "messages": collected_messages}

    query_str = """
        INSERT INTO content_blocks (bot_id, key, content_data, updated_by_user_id, updated_at)
        VALUES (%s, %s, %s, %s, NOW())
        ON CONFLICT (bot_id, key) DO UPDATE SET
            content_data = EXCLUDED.content_data,
            updated_at = NOW(),
            updated_by_user_id = EXCLUDED.updated_by_user_id;
    """
    db.execute_query(query_str, (bot_id, content_key, json.dumps(content_payload), admin_user_id))

    await update.message.reply_text("✅ Content successfully saved!", reply_markup=ReplyKeyboardRemove())
    context.user_data.pop('update_content_key', None)
    context.user_data.pop('collected_messages', None)

    return await admin_update_info_menu(update, context)

async def cancel_content_update(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Cancels the content update process."""
