def serialize_message(message: Update.message) -> Optional[Dict]:
    """Converts a Telegram message into a dictionary for JSON storage."""

    if message.text:
        entities = [e.to_dict() for e in message.entities] if message.entities else []
        return {"type": "text", "text": message.text, "entities": entities}

    caption = message.caption or ""
    caption_entities = [e.to_dict() for e in message.caption_entities] if message.caption_entities else []

    if message.photo:
        return {"type": "photo", "file_id": message.photo[-1].file_id, "caption": caption, "entities": caption_entities}
    if message.video:
        return {"type": "video", "file_id": message.video.file_id, "caption": caption, "entities": caption_entities}
    if message.document:
        return {"type": "document", "file_id": message.document.file_id, "caption": caption, "entities": caption_entities}
    if message.sticker:
        return {"type": "sticker", "file_id": message.sticker.file_id}
    if message.voice:
        return {"type": "voice", "file_id": message.voice.file_id, "caption": caption, "entities": caption_entities}
    if message.audio:
        return {"type": "audio", "file_id": message.audio.file_id, "caption": caption, "entities": caption_entities}

    return None

async def safe_edit_caption_or_text(query, text: str, reply_markup: InlineKeyboardMarkup, entities: List = None):
    """Safely edits a message's caption or text content, whichever is applicable."""
    try:
        await query.edit_message_caption(
            caption=text,
            reply_markup=reply_markup,
            parse_mode=ParseMode.MARKDOWN,
            caption_entities=entities
        )
    except telegram.error.BadRequest as caption_err:
        err_str = str(caption_err).lower()

        if "caption is too long" in err_str:
            # Caption exceeds 1024-char limit — fall back to plain text message edit
            try:
                await query.edit_message_text(
                    text=text,
                    reply_markup=reply_markup,
                    parse_mode=ParseMode.MARKDOWN,
                    entities=entities
                )
                return
            except telegram.error.BadRequest:
                try:
                    await query.edit_message_text(
                        text=text,
                        reply_markup=reply_markup
                    )
                    return
                except telegram.error.BadRequest as e:
                    if "message is not modified" not in str(e).lower():
                        logger.error(f"safe_edit failed — caption too long and text edit also failed: {e}")
            return

        # Try editing as text (handles "there is no caption" case)
        try:
            await query.edit_message_text(
                text=text,
                reply_markup=reply_markup,
                parse_mode=ParseMode.MARKDOWN,
                entities=entities
            )
        except telegram.error.BadRequest as e:
            err_str2 = str(e).lower()
            if "message is not modified" in err_str2:
                return
            # Markdown parse error on text edit — retry without parse_mode
            if "can't parse" in err_str2 or "parse entities" in err_str2:
                try:
                    await query.edit_message_caption(
                        caption=text,
                        reply_markup=reply_markup
                    )
                    return
                except telegram.error.BadRequest:
                    pass
                try:
                    await query.edit_message_text(
                        text=text,
                        reply_markup=reply_markup
                    )
                    return
                except telegram.error.BadRequest as e2:
                    if "message is not modified" not in str(e2).lower():
                        logger.error(f"safe_edit failed on both caption and text edits: {e2}")
            else:
                logger.error(f"safe_edit failed on both caption and text edits: {e}")

