async def generate_admin_key(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Generates and displays a one-time admin promotion key."""
    query = update.callback_query
    await query.answer()

    bot_id = await get_bot_id(context.bot.token)
    alphabet = string.ascii_letters + string.digits + string.punctuation

    safe_alphabet = ''.join(c for c in alphabet if c not in ['*', '_', '`', '[', ']'])
    key = ''.join(secrets.choice(safe_alphabet) for i in range(10))

    db.execute_query("INSERT INTO admin_promotion_keys (bot_id, key_value) VALUES (%s, %s)", (bot_id, key))

    caption = (
        "🔑 *New Moderator Key Generated*\n\n"
        "Copy the key below and send it to your new moderator. Tell them to send this key to the bot.\n\n"
        f"`{key}`\n\n"
        "⚠️ This key is valid for **1 hour** and can only be used **once**."
    )
    keyboard = [[InlineKeyboardButton("🔙 Back", callback_data="manage_admins")]]
    await safe_edit_caption_or_text(query, caption, InlineKeyboardMarkup(keyboard))
    return State.MANAGE_ADMINS

async def process_admin_key_redemption(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handler for users sending a potential admin key."""




    if not update.message or not update.message.text:
        return

    key = update.message.text.strip()
    if len(key) != 10:
        return

    bot_id = await get_bot_id(context.bot.token)
    user = update.effective_user
    user_data = await get_or_create_user(user.id, user.username, user.first_name, user.last_name, user.username, context.bot.token)


    key_data = db.execute_query(
        "SELECT id, created_at, is_used FROM admin_promotion_keys WHERE key_value = %s AND bot_id = %s",
        (key, bot_id), fetch=True
    )

    if not key_data:
        return


    key_record = key_data[0]

    if user_data and user_data['is_admin']:
        await update.message.reply_text("❌ You are already a moderator.")
        raise ApplicationHandlerStop

    if key_record['is_used']:

        raise ApplicationHandlerStop

    time_since_creation = datetime.datetime.now(pytz.utc) - key_record['created_at'].replace(tzinfo=pytz.utc)
    if time_since_creation > datetime.timedelta(hours=1):
        await update.message.reply_text("❌ This key has expired. Please request a new one from an admin.")
        raise ApplicationHandlerStop


    db.execute_query("UPDATE users SET is_admin = TRUE WHERE id = %s", (user_data['id'],))
    db.execute_query("UPDATE admin_promotion_keys SET is_used = TRUE WHERE id = %s", (key_record['id'],))

    await update.message.reply_text(
        "🎉 Congratulations! The key was valid and you are now a moderator.",
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("Go to Admin Panel", callback_data="admin_panel")]
        ])
    )

    raise ApplicationHandlerStop

async def list_removable_admins(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Lists all moderators for the current bot, excluding the owner. Owner-only action."""
    query = update.callback_query
    await query.answer()

    current_admin_telegram_id = update.effective_user.id
    bot_id = await get_bot_id(context.bot.token)

    # Only the owner can remove moderators
    owner_row = db.execute_query(
        "SELECT owner_telegram_id FROM managed_bots WHERE id = %s", (bot_id,), fetch=True
    )
    is_owner = owner_row and owner_row[0]['owner_telegram_id'] == current_admin_telegram_id
    if not is_owner:
        await query.answer("❌ Only the bot owner can remove moderators.", show_alert=True)
        return State.MANAGE_ADMINS

    removable_admins = db.execute_query(
        """
        SELECT u.id, u.first_name, u.last_name, u.username FROM users u
        JOIN managed_bots mb ON u.bot_id = mb.id
        WHERE u.is_admin = TRUE
          AND u.bot_id = %s
          AND u.telegram_id != mb.owner_telegram_id
          AND u.telegram_id != %s
          AND u.telegram_id != %s
        ORDER BY u.first_name
        """,
        (bot_id, current_admin_telegram_id, SUPER_ADMIN_TELEGRAM_ID),
        fetch=True
    )

    caption = "➖ *Remove Moderator*\n\n"
    keyboard = []

    if not removable_admins:
        caption += "There are no moderators to remove."
    else:
        caption += "Select a moderator to remove. This action cannot be undone."
        for admin in removable_admins:
            full_name = f"{admin.get('first_name', '')} {admin.get('last_name', '')}".strip() or 'N/A'
            username_text = f"(@{admin.get('username')})" if admin.get('username') else ''
            keyboard.append([InlineKeyboardButton(f"{full_name} {username_text}", callback_data=f"remove_admin_confirm_{admin['id']}")])

    keyboard.append([InlineKeyboardButton("🔙 Back", callback_data="manage_admins")])
    await safe_edit_caption_or_text(query, caption, InlineKeyboardMarkup(keyboard))
    return State.MANAGE_ADMINS

