async def view_moderator_list(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Shows all moderators for this bot. Accessible by both owner and moderators (read-only)."""
    query = update.callback_query
    await query.answer()

    bot_id = await get_bot_id(context.bot.token)

    # Fetch owner info
    owner_row = db.execute_query(
        "SELECT owner_telegram_id FROM managed_bots WHERE id = %s", (bot_id,), fetch=True
    )
