async def manage_cloned_bots_menu(update: Update, context: ContextTypes.DEFAULT_TYPE, page: int = 0):
    """Displays a paginated list of all cloned bots (20 per page) with Back/Next buttons."""
    query = update.callback_query
    await query.answer("Loading bot details...")

    if update.effective_user.id != SUPER_ADMIN_TELEGRAM_ID:
        await query.answer("❌ Access Denied.", show_alert=True)
        return State.ADMIN_PANEL

    # Check if page came from callback_data (cloned_bots_page_N)
    if query and query.data and query.data.startswith("cloned_bots_page_"):
        page = int(query.data.split("_")[-1])

    cloned_bots = db.execute_query(
        "SELECT id, bot_token, bot_username, bot_full_name FROM managed_bots WHERE bot_token NOT IN (%s, %s) ORDER BY id",
        (TOKEN, "8667755023:AAHiOtzW2FKCT-aB0BusVoFe-g511cMDpVQ"), fetch=True
    )

    keyboard = []
    if not cloned_bots:
        caption = "🤖 *Manage Cloned Bots*\n\nThere are no cloned bots in the system."
    else:
        total = len(cloned_bots)
        total_pages = (total + CLONED_BOTS_PAGE_SIZE - 1) // CLONED_BOTS_PAGE_SIZE
        page = max(0, min(page, total_pages - 1))
        start = page * CLONED_BOTS_PAGE_SIZE
        end = start + CLONED_BOTS_PAGE_SIZE
        page_bots = cloned_bots[start:end]

        caption = (
            f"🤖 *Manage Cloned Bots*\n\n"
            f"Select a bot to manage it.\n"
            f"Page {page + 1} of {total_pages} — Showing {start + 1}–{min(end, total)} of {total} bots"
        )

        for bot in page_bots:
            button_text = f"Bot ID {bot['id']} (Inactive/Invalid Token)"
            if bot['bot_full_name'] and bot['bot_username']:
                button_text = f"{bot['bot_full_name']} (@{bot['bot_username']})"
            else:
                details = await get_bot_details(bot['bot_token'])
                if details:
                    button_text = f"{details['full_name']} (@{details['username']})"
                    db.execute_query(
                        "UPDATE managed_bots SET bot_username = %s, bot_full_name = %s WHERE id = %s",
                        (details['username'], details['full_name'], bot['id'])
                    )
            keyboard.append([InlineKeyboardButton(button_text, callback_data=f"view_cloned_bot_{bot['id']}")])

        # Back / Next navigation row
        nav_row = []
        if page > 0:
            nav_row.append(InlineKeyboardButton("⬅️ Back", callback_data=f"cloned_bots_page_{page - 1}"))
        if page < total_pages - 1:
            nav_row.append(InlineKeyboardButton("Next ➡️", callback_data=f"cloned_bots_page_{page + 1}"))
        if nav_row:
            keyboard.append(nav_row)

    keyboard.append([InlineKeyboardButton("🔙 Admin Panel", callback_data="admin_panel")])
    await safe_edit_caption_or_text(query, caption, InlineKeyboardMarkup(keyboard))
    return State.MANAGE_CLONED_BOTS

