async def execute_remove_bot(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Performs the final removal of the bot and ALL of its associated data from the database."""
    query = update.callback_query
    bot_id = int(query.data.split('_')[-1])


    bot_data = db.execute_query("SELECT bot_token, bot_username, owner_telegram_id FROM managed_bots WHERE id = %s", (bot_id,), fetch=True)
    token_to_stop = bot_data[0]['bot_token'] if bot_data else None
    bot_uname = bot_data[0].get('bot_username') if bot_data else None
    owner_tid = bot_data[0].get('owner_telegram_id') if bot_data else None


    if token_to_stop:
        if token_to_stop in BOT_ID_CACHE:
            del BOT_ID_CACHE[token_to_stop]
        if token_to_stop in RUNNING_TASKS:
            task_to_cancel = RUNNING_TASKS[token_to_stop]
            task_to_cancel.cancel()
            logger.info(f"Sent cancellation request to the running task for bot ...{token_to_stop[-6:]}.")


    try:
        if bot_uname:
            try:
                db.execute_query(
                    "INSERT INTO deleted_managed_bots (bot_username, owner_telegram_id) VALUES (%s, %s) "
                    "ON CONFLICT (bot_username) DO UPDATE SET deleted_at = NOW()",
                    (bot_uname.lower(), owner_tid)
                )
            except Exception:
                pass

        with db.connection.cursor() as cursor:
            logger.info(f"Deleting all database records for bot_id: {bot_id}")

            cursor.execute("DELETE FROM news WHERE bot_id = %s", (bot_id,))
            cursor.execute("DELETE FROM promotions WHERE bot_id = %s", (bot_id,))
            cursor.execute("DELETE FROM cart WHERE bot_id = %s", (bot_id,))
            cursor.execute("DELETE FROM products WHERE bot_id = %s", (bot_id,))
            cursor.execute("DELETE FROM categories WHERE bot_id = %s", (bot_id,))
            cursor.execute("DELETE FROM plan_orders WHERE bot_id = %s", (bot_id,))
            cursor.execute("DELETE FROM managed_bots WHERE id = %s", (bot_id,))
        db.connection.commit()
        success = True
    except Exception as e:
        logger.error(f"Failed to completely remove bot ID {bot_id}: {e}")
        db.connection.rollback()
        success = False

    if success:
        await query.answer("✅ Bot has been stopped and all its data removed.", show_alert=True)
        if token_to_stop:
            logger.info(f"Bot ID {bot_id} (token ...{token_to_stop[-6:]}) was stopped and all data removed from DB.")
    else:
        await query.answer("❌ A database error occurred. The bot may still be running. Check logs.", show_alert=True)

    return await manage_cloned_bots_menu(update, context)


