async def user_remove_bot_execute(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Executes the removal of the user's own bot after confirmation."""
    query = update.callback_query
    await query.answer()
    bot_id = int(query.data.split('_')[-1])

    # Security: ensure this bot belongs to the user
    owner_telegram_id = update.effective_user.id
    bot_data = db.execute_query(
        "SELECT bot_token, bot_full_name, bot_username FROM managed_bots WHERE id = %s AND owner_telegram_id = %s",
        (bot_id, owner_telegram_id), fetch=True
    )
    if not bot_data:
        await query.answer("❌ Bot not found or access denied.", show_alert=True)
        return State.SETTINGS

    token_to_stop = bot_data[0]['bot_token']
    bot_uname = bot_data[0].get('bot_username')

    # Stop the running bot instance
    if token_to_stop in BOT_ID_CACHE:
        del BOT_ID_CACHE[token_to_stop]
    if token_to_stop in RUNNING_TASKS:
        task_to_cancel = RUNNING_TASKS[token_to_stop]
        task_to_cancel.cancel()

    # Delete all bot data
    try:
        if bot_uname:
            try:
                db.execute_query(
                    "INSERT INTO deleted_managed_bots (bot_username, owner_telegram_id) VALUES (%s, %s) "
                    "ON CONFLICT (bot_username) DO UPDATE SET deleted_at = NOW()",
                    (bot_uname.lower(), owner_telegram_id)
                )
            except Exception:
                pass

        with db.connection.cursor() as cursor:
            cursor.execute("DELETE FROM news WHERE bot_id = %s", (bot_id,))
            cursor.execute("DELETE FROM promotions WHERE bot_id = %s", (bot_id,))
            cursor.execute("DELETE FROM cart WHERE bot_id = %s", (bot_id,))
            cursor.execute("DELETE FROM products WHERE bot_id = %s", (bot_id,))
            cursor.execute("DELETE FROM categories WHERE bot_id = %s", (bot_id,))
            cursor.execute("DELETE FROM plan_orders WHERE bot_id = %s", (bot_id,))
            cursor.execute("DELETE FROM managed_bots WHERE id = %s", (bot_id,))
        db.connection.commit()
        await query.answer("✅ Bot removed successfully.", show_alert=True)
        logger.info(f"User {owner_telegram_id} removed their own bot_id={bot_id}.")
    except Exception as e:
        db.connection.rollback()
        logger.error(f"Failed to remove bot_id={bot_id} by user {owner_telegram_id}: {e}")
        await query.answer("❌ A database error occurred. Please try again.", show_alert=True)
        return State.SETTINGS

    return await user_manage_my_bots(update, context)


import re as _re_web

def _is_valid_email(email: str) -> bool:
    return bool(_re_web.match(r'^[^@\s]+@[^@\s]+\.[^@\s]+$', email))

def _is_valid_web_pw(pw: str) -> bool:
    """Min 6 chars, must have at least one letter and one digit."""
    return len(pw) >= 6 and bool(_re_web.search(r'[A-Za-z]', pw)) and bool(_re_web.search(r'\d', pw))


async def manage_web_login_menu(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Show Manage Web Login menu — signup or change/forgot password."""
    query = update.callback_query

    user = update.effective_user
    bot_id = await get_bot_id(context.bot.token)

    # Plan check
    bot_plan_data = get_bot_plan_details(bot_id)
    bot_plan = (bot_plan_data.get('plan_name', 'Free') if bot_plan_data else 'Free').lower()
    if bot_plan != 'business':
        if query:
            await query.answer(
                text="⚠️ Your Plan does not support this feature.",
                show_alert=True
            )
        else:
            await update.effective_message.reply_text(
                "⚠️ *Your Plan does not support this feature.*",
                parse_mode=ParseMode.MARKDOWN
            )
        return State.ADMIN_PANEL

    if query:
        await query.answer()

    # Check if already signed up
    row = db.execute_query(
        "SELECT web_panel_email, password_hash FROM users WHERE telegram_id = %s AND bot_id = %s",
        (user.id, bot_id), fetch=True
    )
    already_signed_up = bool(row and row[0].get('web_panel_email') and row[0].get('password_hash'))

    if already_signed_up:
        email = row[0]['web_panel_email']
        caption = (
            "🌐 *Manage Web Login*\n\n"
            f"✅ Web Panel is already set up.\n"
            f"📧 Email: `{escape_markdown(email)}`\n\n"
            "What would you like to do?"
        )
        keyboard = InlineKeyboardMarkup([
            [InlineKeyboardButton("🔑 Change Password", callback_data="web_panel_change_pw")],
            [InlineKeyboardButton("❓ Forgot Password?", callback_data="web_panel_forgot_pw")],
            [InlineKeyboardButton("🔙 Back", callback_data="admin_panel")],
        ])
    else:
        caption = "🌐 *Manage Web Login*\n\nSet up your Web Admin Panel login credentials."
        keyboard = InlineKeyboardMarkup([
            [InlineKeyboardButton("✍️ Sign up for Web Panel", callback_data="web_panel_signup")],
            [InlineKeyboardButton("🔙 Back", callback_data="admin_panel")],
        ])

    if query:
        await safe_edit_caption_or_text(query, caption, keyboard)
    else:
        await update.effective_message.reply_text(caption, reply_markup=keyboard, parse_mode=ParseMode.MARKDOWN)
    return State.WEB_PANEL_SIGNUP


