async def list_bots_for_login_management(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """(Super Admin) Lists all bots to manage their owner's web login."""
    query = update.callback_query
    await query.answer()

    all_bots = db.execute_query(
        "SELECT id, bot_full_name, bot_username, owner_telegram_id FROM managed_bots ORDER BY id",
        fetch=True
    )

    caption = "🔑 *Manage Web Logins*\n\nSelect a bot to create or update the web panel login for its owner."
    keyboard = []
    if not all_bots:
        caption += "\n\nThere are no bots in the system."
    else:
        for bot in all_bots:
            owner = get_user_by_telegram_id(bot['owner_telegram_id'], bot['id'])
            owner_full_name = 'Unknown'
            if owner:
                owner_full_name = f"{owner.get('first_name', '')} {owner.get('last_name', '')}".strip() or 'Unknown'
            bot_name = bot.get('bot_full_name') or 'Unnamed Bot'
            button_text = f"{bot_name} (Owner: {owner_full_name})"

            keyboard.append([InlineKeyboardButton(button_text, callback_data=f"set_login_for_{bot['id']}_{bot['owner_telegram_id']}")])

    keyboard.append([InlineKeyboardButton("🔙 Admin Panel", callback_data="admin_panel")])
    await safe_edit_caption_or_text(query, caption, InlineKeyboardMarkup(keyboard))
    return State.MANAGE_WEB_LOGINS

async def prompt_for_username(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """(Super Admin) Asks for the web panel USERNAME for the selected bot owner."""
    query = update.callback_query
    await query.answer()

    parts = query.data.split('_')
    bot_id = int(parts[-2])
    owner_telegram_id = int(parts[-1])

    context.user_data['credential_target_bot_id'] = bot_id
    context.user_data['credential_target_owner_id'] = owner_telegram_id

    owner_user = get_user_by_telegram_id(owner_telegram_id, bot_id)
    if not owner_user:
        await query.answer("❌ Error: Could not find the owner for this bot.", show_alert=True)
        return State.MANAGE_WEB_LOGINS

    owner_full_name = f"{owner_user.get('first_name', '')} {owner_user.get('last_name', '')}".strip() or owner_telegram_id
    caption = (
        f"You are creating web login credentials for *{escape_markdown(str(owner_full_name))}*.\n\n"
        "First, please send the **username** you want to assign."
    )
    keyboard = [[InlineKeyboardButton("🔙 Cancel", callback_data="list_bots_for_login")]]
    await safe_edit_caption_or_text(query, caption, InlineKeyboardMarkup(keyboard))
    return State.AWAITING_WEB_USERNAME

async def receive_web_username(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """(Super Admin) Receives and validates the uniqueness of the username, then asks for the password."""
    new_username = update.message.text.strip()
    target_bot_id = context.user_data.get('credential_target_bot_id')

    if not new_username or ' ' in new_username:
        await update.message.reply_text("❌ Invalid username. Please avoid spaces and send again.")
        return State.AWAITING_WEB_USERNAME

    existing_user = db.execute_query(
        "SELECT id FROM users WHERE username = %s AND bot_id = %s",
        (new_username, target_bot_id), fetch=True
    )
    if existing_user:
        await update.message.reply_text("❌ This username is already taken for this bot. Please choose a different one.")
        return State.AWAITING_WEB_USERNAME

    context.user_data['new_web_username'] = new_username

    await update.message.reply_text(
        f"✅ Username set to `{escape_markdown(new_username)}`.\n\n"
        "Now, please send the **password** you want to assign.",
        parse_mode=ParseMode.MARKDOWN
    )
    return State.AWAITING_WEB_PASSWORD

async def save_user_password(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """(Super Admin) Receives the password, then saves both username and password hash."""
    new_password = update.message.text
    target_owner_id = context.user_data.get('credential_target_owner_id')
    target_bot_id = context.user_data.get('credential_target_bot_id')
    new_username = context.user_data.get('new_web_username')

    if not all([target_owner_id, target_bot_id, new_username]):
        await update.message.reply_text("❌ Session expired. Please start over.")
        return await handle_admin_panel(update, context)

    password_hash = generate_password_hash(new_password)


    success = db.execute_query(
        "UPDATE users SET username = %s, password_hash = %s, is_admin = TRUE WHERE telegram_id = %s AND bot_id = %s",
        (new_username, password_hash, target_owner_id, target_bot_id)
    )

    if success:
        await update.message.reply_text("✅ Web credentials have been updated successfully!")
    else:
        await update.message.reply_text("❌ A database error occurred. Credentials not updated.")

    context.user_data.pop('credential_target_owner_id', None)
    context.user_data.pop('credential_target_bot_id', None)
    context.user_data.pop('new_web_username', None)

    return await handle_admin_panel(update, context)


