async def prompt_for_photo_update(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Asks the admin to send a new photo for a specific section."""
    query = update.callback_query

    section_key = query.data.replace('update_photo_', '')
    poster_key = f"{section_key}_poster"

    bot_id = await get_bot_id(context.bot.token)
    limits = await get_bot_plan_and_limits(bot_id)

    allowed_updates = limits['update_photo']
    if allowed_updates != 'all' and poster_key not in allowed_updates:
        await query.answer("❌ Your current plan does not allow updating this poster. Please upgrade.", show_alert=True)
        return State.ADMIN_UPDATE_PHOTO

    await query.answer()

    section_key = query.data.replace('update_photo_', '')
    context.user_data['photo_update_key'] = f"{section_key}_poster"
    section_name = section_key.replace('_', ' ').title()

    await safe_edit_caption_or_text(
        query,
        f"🖼️ *Updating: {section_name} Poster*\n\nPlease send the new photo you want to use for this section.",
        InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Back", callback_data="admin_update_photo")]])
    )

    return State.AWAITING_PHOTO_UPDATE

async def save_updated_photo(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Receives a photo from an admin and saves its file_id to the database."""
    if not update.message or not update.message.photo:
        await update.message.reply_text("⚠️ Please send a photo, not a file or other media type.")
        return State.AWAITING_PHOTO_UPDATE


    user_data = await get_or_create_user(update.effective_user.id, update.effective_user.username, update.effective_user.first_name, update.effective_user.last_name, update.effective_user.username, context.bot.token)
    admin_user_id = user_data['id'] if user_data else None

    poster_key = context.user_data.get('photo_update_key')
    if not poster_key:
        await update.message.reply_text("❌ Error: Could not determine which poster to update. Please start over.")
        return await admin_update_photo_menu(update, context)

    file_id = update.message.photo[-1].file_id
    content_payload = {"source": "telegram", "file_id": file_id}
    bot_id = await get_bot_id(context.bot.token)

    query_str = """
        INSERT INTO content_blocks (bot_id, key, content_data, updated_by_user_id, updated_at)
        VALUES (%s, %s, %s, %s, NOW())
        ON CONFLICT (bot_id, key) DO UPDATE SET
            content_data = EXCLUDED.content_data,
            updated_at = NOW(),
            updated_by_user_id = EXCLUDED.updated_by_user_id;
    """
    db.execute_query(query_str, (bot_id, poster_key, json.dumps(content_payload), admin_user_id))

    await update.message.reply_text(
        "✅ Poster successfully updated!",
        reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Back to Photo Menu", callback_data="admin_update_photo")]])
    )
    context.user_data.pop('photo_update_key', None)
    return State.ADMIN_UPDATE_PHOTO



async def cancel_content_update(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Cancels the content update process."""
    await update.message.reply_text("❌ Update cancelled.", reply_markup=ReplyKeyboardRemove())
    context.user_data.clear()
    return await handle_admin_panel(update, context)
