async def confirm_delete_autoreply(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Asks for final confirmation before deleting an auto-reply button."""
    query = update.callback_query
    await query.answer()
    autoreply_id = int(query.data.split('_')[-1])

    autoreply_data = db.execute_query("SELECT button_name FROM auto_replies WHERE id = %s", (autoreply_id,), fetch=True)
    if not autoreply_data:
        await query.answer("❌ This button may have already been deleted.", show_alert=True)
        return await list_autoreplies_for_deletion(update, context)

    button_name = escape_markdown(autoreply_data[0]['button_name'])

    warning_caption = f"⚠️ *Are you sure?*\n\nYou are about to delete the auto-reply button:\n\n`{button_name}`\n\nThis action cannot be undone."

    keyboard = [
        [InlineKeyboardButton("✅ Yes, Delete", callback_data=f"execute_del_autoreply_{autoreply_id}")],
        [InlineKeyboardButton("❌ No, Cancel", callback_data="ap2_remove_autoreply")]
    ]
    await safe_edit_caption_or_text(query, warning_caption, InlineKeyboardMarkup(keyboard))
    return State.DELETE_AUTOREPLY_CONFIRM

async def execute_delete_autoreply(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Deletes the selected auto-reply button and refreshes the list."""
    query = update.callback_query
    
    autoreply_id = int(query.data.split('_')[-1])

    if delete_auto_reply(autoreply_id):
        await query.answer("✅ Auto-reply button deleted successfully.", show_alert=True)
    else:
        await query.answer("❌ An error occurred during deletion.", show_alert=True)

    # Refresh the list to show the change
    return await list_autoreplies_for_deletion(update, context)


