async def handle_payment_proof_finished(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Finalizes the order and sends all proof to admins for review."""
    lang = await get_user_lang(context)
    finalizing_msg = await update.message.reply_text(get_text('finalizing_order', lang), reply_markup=ReplyKeyboardRemove())
    await asyncio.sleep(2)
    try:
        await finalizing_msg.edit_text("Submitted.....")
    except Exception:
        pass

    pending_order = context.user_data.get('pending_order')
    proof_message_ids = context.user_data.get('payment_proof_messages', [])

    if not pending_order:
        await update.effective_message.reply_text(
            "❌ Error: No pending order found to confirm payment. Please start a new order.",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🏠 Main Menu", callback_data="main_menu")]])
        )
        return State.MAIN_MENU

    if not proof_message_ids:
        await update.effective_message.reply_text(
            "You haven't sent any payment proof. The admin will review your order manually. Your order is pending.",
        )

    bot_id = await get_bot_id(context.bot.token)
    if not bot_id:
        await update.effective_message.reply_text("Error: This bot is not registered correctly.")
        return State.MAIN_MENU

    order_items = []
    for item in pending_order['cart_items']:
        pid = item.get('product_id')
        raw_name = item.get('name', 'Product')
        if " (" in raw_name:
            base_pname = raw_name.split(" (")[0]
        else:
            base_pname = raw_name

        prod_obj = get_product(bot_id, pid) if pid else None
        v_label = get_variant_label(prod_obj, context.user_data) if prod_obj else ""

        full_item_name = f"{base_pname}{v_label}" if (v_label and v_label not in raw_name) else raw_name
        order_items.append({
            "product_id": pid,
            "name": full_item_name,
            "quantity": item['quantity'],
            "price": item['price'],
            "variant_label": v_label.strip(" ()") if v_label else ""
        })

    admin_notifications = []

    order_number = create_order(
        bot_id=bot_id,
        user_id=pending_order['user_id'],
        items=order_items,
        total_amount=pending_order['total_amount'],
        discount_amount=pending_order['discount_amount'],
        delivery_fee=pending_order.get('delivery_fee', 0),
        payment_method=pending_order['payment_method_name'],
        shipping_address=pending_order['shipping_address'],
        payment_proof_messages=proof_message_ids,
        status='pending_review'
    )

    if order_number:
        # Send FCM push notification to web panel admins
        try:
            requests.post(
                "http://localhost:8000/internal/fcm/notify",
                json={
                    "key": "fe566da1682fda8790efa6fafeb8da4c",
                    "bot_id": bot_id,
                    "title": "New Order Received",
                    "body": f"Order #{order_number} via Telegram bot",
                    "data": {"url": "/orders"}
                },
                timeout=5
            )
        except Exception:
            pass

        admin_ids = await get_admin_telegram_ids(bot_id)
        user_info = await get_or_create_user(update.effective_user.id, update.effective_user.username, update.effective_user.first_name, update.effective_user.last_name, update.effective_user.username, context.bot.token)

        for admin_id in admin_ids:
            try:
                for entry in proof_message_ids:
                    msg_id = entry["message_id"] if isinstance(entry, dict) else entry
                    await context.bot.forward_message(chat_id=admin_id, from_chat_id=update.effective_chat.id, message_id=msg_id)
                    time.sleep(0.1)

                total_amount_str = await format_price(context, pending_order['total_amount'], lang)
                delivery_fee_amount = pending_order.get('delivery_fee', 0)
                final_total = float(pending_order['total_amount']) + float(delivery_fee_amount)
                final_total_str = await format_price(context, final_total, lang)
                customer_full_name = f"{user_info.get('first_name', '')} {user_info.get('last_name', '')}".strip() or "Customer"
                
                addr_data = pending_order.get('shipping_address') or {}
                if isinstance(addr_data, str):
                    try:
                        addr_data = json.loads(addr_data)
                    except Exception:
                        addr_data = {'address': addr_data}
                
                phone_num = user_info.get('phone_number') or addr_data.get('phone') or addr_data.get('phone_number') or 'N/A'
                full_address = addr_data.get('address') or addr_data.get('shipping_address') or 'N/A'

                items_list = pending_order.get('cart_items') or pending_order.get('items') or order_items or []
                items_breakdown = ""
                for it in items_list:
                    it_pid = it.get('product_id')
                    raw_name = it.get('name', 'Product')
                    if " (" in raw_name:
                        base_pname = raw_name.split(" (")[0]
                    else:
                        base_pname = raw_name

                    it_qty = it.get('quantity', 1)
                    variant_str = ""
                    if it_pid:
                        bot_id_cur = await get_bot_id(context.bot.token)
                        prod_obj = get_product(bot_id_cur, it_pid)
                        if prod_obj:
                            variant_str = get_variant_label(prod_obj, context.user_data)

                    item_line_header = f"{base_pname} x{it_qty}{variant_str}"
                    it_name = escape_markdown(item_line_header)
                    it_price = Decimal(str(it.get('price', 0)))
                    it_price_str = await format_price(context, it_price, lang)
                    it_subtotal_str = await format_price(context, it_price * it_qty, lang)
                    items_breakdown += f"• *{it_name}*\n  `{it_qty} × {it_price_str}` = `{it_subtotal_str}`\n"

                delivery_fee_line = f"*Delivery Fee:* {await format_price(context, delivery_fee_amount, lang)}\n" if delivery_fee_amount else ""

                admin_notification_text = (
                    f"🚨 *New Order Pending Review!* 🚨\n\n"
                    f"📋 *Order ID:* `{order_number}`\n"
                    f"👤 *Customer:* {customer_full_name} (@{user_info.get('username', 'N/A')})\n"
                    f"📞 *Phone:* `{phone_num}`\n"
                    f"📍 *Address:* {escape_markdown(full_address)}\n\n"
                    f"📦 *Ordered Items:*\n{items_breakdown}\n"
                    f"💳 *Payment Method:* {pending_order['payment_method_name']}\n"
                    f"💰 *Subtotal:* {total_amount_str}\n"
                    f"{delivery_fee_line}"
                    f"💵 *Final Total:* *{final_total_str}*\n\n"
                    f"The user has submitted the proof above. Please review and confirm the payment.\n\n"
                    f"⟵ *Swipe left on this message to reply to customer*"
                )

                keyboard = InlineKeyboardMarkup([
                    [InlineKeyboardButton("✅ Yes, Payment Received", callback_data=f"confirm_payment_yes_{order_number}_{user_info['telegram_id']}")],
                    [InlineKeyboardButton("❌ No, Payment Not Received", callback_data=f"confirm_payment_no_{order_number}_{user_info['telegram_id']}")]
                ])

                sent_message = await context.bot.send_message(
                    chat_id=admin_id,
                    text=admin_notification_text,
                    parse_mode=ParseMode.MARKDOWN,
                    reply_markup=keyboard
                )
                admin_notifications.append({'admin_id': admin_id, 'message_id': sent_message.message_id})
            except Exception as e:
                logger.error(f"Failed to notify admin {admin_id}: {e}")

        db.execute_query(
            "UPDATE orders SET admin_notification_messages = %s WHERE order_number = %s",
            (json.dumps(admin_notifications), order_number)
        )

        success_message = get_text('order_pending_review', lang).format(order_number=order_number)
        await update.effective_message.reply_text(
            success_message,
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(get_text('main_menu_button', lang), callback_data="main_menu")]])
        )

        # ── Send email notification to bot admin on new order ──
        try:
            email_row = db.execute_query(
                "SELECT admin_notification_email, email_notifications_enabled FROM managed_bots WHERE id = %s",
                (bot_id,), fetch=True
            )
            if email_row and email_row[0].get('email_notifications_enabled') and email_row[0].get('admin_notification_email'):
                admin_email = email_row[0]['admin_notification_email']
                total_str = await format_price(context, pending_order['total_amount'], lang)

                # Gather buyer info
                b_name = f"{user_info.get('first_name', '')} {user_info.get('last_name', '')}".strip() or "-"
                b_phone = user_info.get('phone_number') or "-"
                if b_phone == "None (User Skipped)":
                    b_phone = "-"
                b_email = user_info.get('email') or "-"

                addr_raw = user_info.get('shipping_address')
                if addr_raw:
                    try:
                        addr_obj = addr_raw if isinstance(addr_raw, dict) else json.loads(addr_raw)
                        b_address = addr_obj.get('text', '-')
                        if b_address == "None (User Skipped)":
                            b_address = "-"
                    except Exception:
                        b_address = "-"
                else:
                    b_address = "-"

                bot_username = context.bot.username or ""

                await asyncio.get_event_loop().run_in_executor(
                    None,
                    send_order_email_notification,
                    admin_email,
                    order_number,
                    total_str,
                    order_items,
                    b_name,
                    b_phone,
                    b_email,
                    b_address,
                    bot_username,
                )
        except Exception as e:
            logger.error(f"Failed to send new-order email notification for order {order_number}: {e}")

    else:
        await update.effective_message.reply_text(
            get_text('order_finalize_failed', lang),
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(get_text('main_menu_button', lang), callback_data="main_menu")]])
        )

    context.user_data.pop('pending_order', None)
    context.user_data.pop('payment_proof_messages', None)

    # If user came from newsfeed, send them back there
    if context.user_data.get('newsfeed_active'):
        context.user_data['newsfeed_back'] = True
        await _send_newsfeed_page(update, context)
        return State.NEWSFEED

    return State.MAIN_MENU


async def get_admin_telegram_ids(bot_id: int) -> List[int]:
    """Fetches the telegram_ids of all admin users for a specific bot."""
    admin_users = db.execute_query(
        "SELECT telegram_id FROM users WHERE is_admin = TRUE AND bot_id = %s",
        (bot_id,),
        fetch=True
    )
    return [user['telegram_id'] for user in admin_users] if admin_users else []



async def store_message_for_web_admin(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Store user message in the database for the web admin panel."""
    user = update.effective_user
    message = update.message

    try:

        message_data = {
            'telegram_id': user.id,
            'username': user.username or '',
            'first_name': user.first_name or '',
            'message_text': '',
            'message_type': 'text',
            'file_id': None,
            'caption': None
        }


        if message.text:
            message_data['message_text'] = message.text
            message_data['message_type'] = 'text'
        elif message.photo:
            message_data['file_id'] = message.photo[-1].file_id
            message_data['message_type'] = 'photo'
            message_data['caption'] = message.caption or ''
        elif message.video:
            message_data['file_id'] = message.video.file_id
            message_data['message_type'] = 'video'
            message_data['caption'] = message.caption or ''
        elif message.document:
            message_data['file_id'] = message.document.file_id
            message_data['message_type'] = 'document'
            message_data['caption'] = message.caption or ''
        elif message.voice:
            message_data['file_id'] = message.voice.file_id
            message_data['message_type'] = 'voice'
        elif message.audio:
            message_data['file_id'] = message.audio.file_id
            message_data['message_type'] = 'audio'
            message_data['caption'] = message.caption or ''
        else:
            message_data['message_text'] = '[Unsupported message type]'
            message_data['message_type'] = 'other'



        try:
            response = requests.post(
                'http://localhost:5000/api/messages/store',
                json=message_data,
                timeout=5
            )
            if response.status_code == 200:
                logger.info(f"Successfully stored message from user {user.id} for web admin")
            else:
                logger.error(f"Failed to store message for web admin: {response.status_code}")
        except Exception as e:
            logger.error(f"Error sending message to web admin: {e}")

    except Exception as e:
        logger.error(f"Error preparing message for web admin: {e}")


