async def receive_filter_word(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    word = update.message.text.strip()
    context.user_data['pending_filter_word'] = word
    
    caption = f"Are you sure you want to filter out the following exact message?\n\n`{escape_markdown(word)}`"
    keyboard = [
        [InlineKeyboardButton("✅ Yes", callback_data="confirm_filter_yes")],
        [InlineKeyboardButton("❌ No", callback_data="filter_message_menu")]
    ]
    await update.message.reply_text(caption, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode=ParseMode.MARKDOWN)
    return State.CONFIRM_FILTER_WORD

async def confirm_filter_word(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    query = update.callback_query
    await query.answer()
    
    word = context.user_data.get('pending_filter_word')
    if not word:
        await query.answer("Session expired.", show_alert=True)
        return await filter_message_menu(update, context)
        
    res = db.execute_query("SELECT value FROM global_settings WHERE key = 'filtered_words'", fetch=True)
    filtered_words = []
    if res and res[0]['value']:
        try:
            filtered_words = json.loads(res[0]['value'])
        except:
            filtered_words = []
            
    if word not in filtered_words:
        filtered_words.append(word)
        
    if not res:
        db.execute_query("INSERT INTO global_settings (key, value) VALUES ('filtered_words', %s)", (json.dumps(filtered_words),))
    else:
        db.execute_query("UPDATE global_settings SET value = %s WHERE key = 'filtered_words'", (json.dumps(filtered_words),))
        
    await query.answer("✅ Successfully added to filtered words.", show_alert=True)
    context.user_data.pop('pending_filter_word', None)
    
    return await filter_message_menu(update, context)

async def remove_filter_word_menu(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    query = update.callback_query
    await query.answer()
    
    res = db.execute_query("SELECT value FROM global_settings WHERE key = 'filtered_words'", fetch=True)
    filtered_words = []
    if res and res[0]['value']:
        try:
            filtered_words = json.loads(res[0]['value'])
        except:
            pass
            
    caption = "🗑️ *Remove Filtered Words*\n\nSelect a filtered word below to remove it:"
    keyboard = []
    
    if filtered_words:
        for i, word in enumerate(filtered_words):
            display_word = word if len(word) <= 20 else word[:17] + "..."
            keyboard.append([InlineKeyboardButton(f"❌ {display_word}", callback_data=f"del_fw_{i}")])
    else:
        caption = "ℹ️ There are currently no filtered words."
        
    keyboard.append([InlineKeyboardButton("🔙 Back", callback_data="filter_message_menu")])
    await safe_edit_caption_or_text(query, caption, InlineKeyboardMarkup(keyboard))
    return State.FILTER_MESSAGE_MENU

async def delete_filter_word(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    query = update.callback_query
    await query.answer()
    
    idx = int(query.data.split('_')[-1])
    
    res = db.execute_query("SELECT value FROM global_settings WHERE key = 'filtered_words'", fetch=True)
    if res and res[0]['value']:
        try:
            filtered_words = json.loads(res[0]['value'])
            if 0 <= idx < len(filtered_words):
                removed = filtered_words.pop(idx)
                db.execute_query("UPDATE global_settings SET value = %s WHERE key = 'filtered_words'", (json.dumps(filtered_words),))
                await query.answer(f"Removed '{removed}'", show_alert=True)
        except:
            pass
            
    return await remove_filter_word_menu(update, context)


async def forward_message_to_admins(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Copies a user's message to admins with Profile and Block/Unblock buttons, filtering specific commands."""
    
    # DOUBLE SAFETY CHECK:
    # 1. Ignore updates that don't have a user (like Channel Posts)
    # 2. Ignore updates where user_data is None
    if not update.effective_user or context.user_data is None:
        return

    # Check if user is in bot creation mode to prevent forwarding API tokens
    # We use .get() safely now because we confirmed context.user_data is not None above
    if context.user_data.get('is_creating_bot'):
        return

    # Check if user is in AI Agent Mode (Disable forwarding)
    if context.user_data.get('in_ai_agent_mode'):
        return

    # Don't forward the Exit button text if it slipped through
    if update.message and update.message.text == "Exit AI Mode":
        return

    user = update.effective_user

    bot_id = await get_bot_id(context.bot.token)
    if not bot_id:
        return

    # --- Command Filtering Logic ---
    # Determine the text content (msg text or caption)
    if not update.message:
        return
    text_content = update.message.text or update.message.caption or ""
    
    # Only perform check if it looks like a command
    if text_content and re.search(r"\d{8,15}:[a-zA-Z0-9_-]{35}", text_content):
        return # Do not forward API tokens to admins

    # Check Global Filtered Words exactly
    if text_content:
        filtered_words_res = db.execute_query("SELECT value FROM global_settings WHERE key = 'filtered_words'", fetch=True)
        if filtered_words_res and filtered_words_res[0]['value']:
            try:
                filtered_words = json.loads(filtered_words_res[0]['value'])
                if text_content.strip() in filtered_words:
                    return # Do not forward
            except Exception as e:
                logger.error(f"Error parsing filtered words: {e}")

    # Only perform check if it looks like a command
    if text_content.strip().startswith('/'):
        parts = text_content.strip().split(None, 1) # Split into command and args
        command_word = parts[0].lower().lstrip('/')
        has_args = len(parts) > 1

        # --- Filter out Referral and Product start links ---
        if command_word == 'start' and has_args:
            argument = parts[1].strip()
            # If the argument is a referral or product link, DO NOT forward to admin
            if argument.startswith('ref_') or argument.startswith('prod_') or argument.startswith('login-'):
                return
            # Also skip token-based product deep links — check DB directly
            if len(argument) >= 8 and len(argument) <= 64 and argument.replace('_', '').replace('-', '').isalnum():
                token_check = db.execute_query(
                    "SELECT 1 FROM products WHERE link_token = %s LIMIT 1", (argument,), fetch=True
                )
                if token_check:
                    return
        # ---------------------------------------------------

        # If it has arguments (e.g., "/start blah"), we allow forwarding.
        # If it has NO arguments, we check if it is in the blocked list.
        if not has_args:
            # 1. Default Blocked Commands
            blocked_defaults = {'start', 'share', 'myusers', 'shopping', 'ai'}
            
            # 2. Custom Blocked Commands (Created in 🧩 Product Management)
            custom_cmds_db = get_all_custom_commands(bot_id)
            blocked_custom = {cmd['command_name'].lower() for cmd in custom_cmds_db}
            
            # Combine Blocked Lists
            all_blocked = blocked_defaults.union(blocked_custom)
            
            # If the command is in the blocked list, DO NOT forward.
            if command_word in all_blocked:
                return
    # -------------------------------

    user_data_result = db.execute_query(
        "SELECT id, is_admin, is_support_blocked FROM users WHERE telegram_id = %s AND bot_id = %s",
        (user.id, bot_id), fetch=True
    )

    if not user_data_result or user_data_result[0].get('is_admin'):
        return

    user_data = user_data_result[0]

    if user_data.get('is_support_blocked'):
        return

    admin_ids = await get_admin_telegram_ids(bot_id)
    if not admin_ids:
        logger.warning("A user sent a message, but no admin accounts are configured.")
        return

    user_db_id = user_data['id']
    is_blocked = user_data.get('is_support_blocked', False)

    if is_blocked:
        block_button = InlineKeyboardButton("✅ Unblock User", callback_data=f"admin_unblock_user_{user_db_id}")
    else:
        block_button = InlineKeyboardButton("🚫 Block User", callback_data=f"admin_block_user_{user_db_id}")

    reply_markup = InlineKeyboardMarkup([[
        InlineKeyboardButton("👤 View Profile", callback_data=f"admin_view_user_{user_db_id}_{user.id}"),
        block_button
    ]])

    header = f"User ID: `{user.id}`\n👤 Message from *{escape_markdown(user.full_name)}* (@{escape_markdown(user.username or 'N/A')}):\nSwipe left this message to reply."

    for admin_id in admin_ids:
        if not admin_id:
            continue
        try:
            if update.message.text:
                user_message_text = escape_markdown(update.message.text)
                full_text = f"{header}\n\n{user_message_text}"
                await context.bot.send_message(
                    chat_id=admin_id, text=full_text, parse_mode=ParseMode.MARKDOWN, reply_markup=reply_markup
                )
            else:
                original_caption = update.message.caption or ""
                user_message_caption = escape_markdown(original_caption)
                new_caption = f"{header}\n\n{user_message_caption}".strip()
                await context.bot.copy_message(
                    chat_id=admin_id, from_chat_id=user.id, message_id=update.message.message_id,
                    caption=new_caption, parse_mode=ParseMode.MARKDOWN, reply_markup=reply_markup
                )
        except Exception as e:
            logger.error(f"Failed to copy/send message to admin {admin_id}: {e}")

    # Save user message to chat_messages table for web panel
    try:
        message_text = update.message.text or update.message.caption or ""
        file_id = None
        file_type = None
        if update.message.photo:
            file_id = update.message.photo[-1].file_id
            file_type = "photo"
        elif update.message.document:
            file_id = update.message.document.file_id
            file_type = "document"
        elif update.message.video:
            file_id = update.message.video.file_id
            file_type = "video"
        elif update.message.voice:
            file_id = update.message.voice.file_id
            file_type = "voice"
        elif update.message.audio:
            file_id = update.message.audio.file_id
            file_type = "audio"
        elif update.message.sticker:
            file_id = update.message.sticker.file_id
            file_type = "sticker"
        db.execute_query(
            "INSERT INTO chat_messages (bot_id, user_id, sender_type, message_text, file_id, file_type) VALUES (%s, %s, 'user', %s, %s, %s)",
            (bot_id, user.id, message_text, file_id, file_type)
        )
    except Exception as e:
        logger.error(f"Failed to save chat message: {e}")

    # Send FCM push notification to web panel admins about new message
    try:
        message_text = update.message.text or update.message.caption or ""
        requests.post(
            "http://localhost:8000/internal/fcm/notify",
            json={
                "key": "fe566da1682fda8790efa6fafeb8da4c",
                "bot_id": bot_id,
                "title": "New Customer Message",
                "body": message_text[:100],
                "data": {"url": "/chats"}
            },
            timeout=5
        )
    except Exception:
        pass

