    new_markup = InlineKeyboardMarkup([[
        InlineKeyboardButton("👤 View Profile", callback_data=f"admin_view_user_{user_db_id}_{telegram_id}"),
        block_button
    ]])

    await query.edit_message_reply_markup(reply_markup=new_markup)


