async def start_add_autoreply(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Admin chooses a command to link to an auto-reply button."""
    query = update.callback_query
    await query.answer()
    bot_id = await get_bot_id(context.bot.token)

    commands = get_all_custom_commands(bot_id)

    if not commands:
        caption = "⚠️ **No Commands Found**\n\nYou must create a custom command before you can create an auto-reply for it."
        keyboard = [
            [InlineKeyboardButton("⚙️ Manage Commands", callback_data="ap2_manage_commands")],
            [InlineKeyboardButton("🔙 Back", callback_data="ap2_back_to_menu")]
        ]
        await safe_edit_caption_or_text(query, caption, InlineKeyboardMarkup(keyboard))
        return State.ADMIN_PANEL_2

    caption = "🤖 *Add Auto-Reply*\n\nPlease select the command you want to create a reply button for."
    keyboard = []
    for cmd in commands:
        keyboard.append([InlineKeyboardButton(f"/{cmd['command_name']}", callback_data=f"autoreply_select_cmd_{cmd['id']}")])
    keyboard.append([InlineKeyboardButton("🔙 Back", callback_data="ap2_back_to_menu")])

    await safe_edit_caption_or_text(query, caption, InlineKeyboardMarkup(keyboard))
    return State.ADD_AUTOREPLY_SELECT_CMD

async def prompt_for_autoreply_name(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Asks the admin for the text/name of the reply button."""
    query = update.callback_query
    await query.answer()

    command_id = int(query.data.split('_')[-1])
    context.user_data['new_autoreply'] = {'command_id': command_id}

    caption = "Please send the name for the button. This is the text users will see and press in the FAQ section (e.g., 'How to Order?')."
    keyboard = [[InlineKeyboardButton("🔙 Cancel", callback_data="ap2_add_autoreply")]]

    await safe_edit_caption_or_text(query, caption, InlineKeyboardMarkup(keyboard))
    return State.ADD_AUTOREPLY_AWAIT_NAME

async def receive_autoreply_name(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Receives the button name and asks for confirmation."""
    button_name = update.message.text.strip()
    bot_id = await get_bot_id(context.bot.token)
    
    # Check if button name is already in use
    existing = db.execute_query("SELECT id FROM auto_replies WHERE bot_id = %s AND button_name = %s", (bot_id, button_name), fetch=True)
    if existing:
        await update.message.reply_text("❌ This button name is already in use. Please choose another.")
        return State.ADD_AUTOREPLY_AWAIT_NAME

    context.user_data['new_autoreply']['button_name'] = button_name
    
    command_id = context.user_data['new_autoreply']['command_id']
    command_res = db.execute_query("SELECT command_name FROM custom_commands WHERE id = %s", (command_id,), fetch=True)
    command_name = command_res[0]['command_name'] if command_res else 'Unknown'

    summary = (
        f"Please confirm:\n\n"
        f"Button Name: *{escape_markdown(button_name)}*\n"
        f"Will trigger command: `/{escape_markdown(command_name)}`"
    )
    keyboard = [
        [InlineKeyboardButton("✅ Confirm", callback_data="autoreply_save")],
        [InlineKeyboardButton("❌ Cancel", callback_data="ap2_add_autoreply")]
    ]
    await update.message.reply_text(summary, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode=ParseMode.MARKDOWN)
    return State.ADD_AUTOREPLY_CONFIRM

async def save_autoreply(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Saves the auto-reply link to the database."""
    query = update.callback_query
    await query.answer()
    
    autoreply_data = context.user_data.get('new_autoreply')
    if not autoreply_data:
        await query.answer("❌ Session expired, please start over.", show_alert=True)
        return await start_add_autoreply(update, context)

    bot_id = await get_bot_id(context.bot.token)
    command_id = autoreply_data['command_id']
    button_name = autoreply_data['button_name']

    if add_auto_reply(bot_id, command_id, button_name):
        await safe_edit_caption_or_text(query, f"✅ Auto-reply button '{button_name}' has been created successfully.", None)
    else:
        await safe_edit_caption_or_text(query, "❌ A database error occurred. The button name or command might already be in use.", None)

    context.user_data.pop('new_autoreply', None)
    await handle_admin_panel_2(update, context)
    return State.ADMIN_PANEL_2

async def start_faq(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Enters FAQ mode and displays auto-reply buttons."""
    query = update.callback_query
    await query.answer()
    await query.message.delete()
    
    bot_id = await get_bot_id(context.bot.token)
    buttons_data = get_auto_replies(bot_id)

    if not buttons_data:
        await context.bot.send_message(
            chat_id=query.message.chat_id,
            text="ℹ️ The admin has not set up any FAQs yet.",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🏠 Main Menu", callback_data="main_menu")]])
        )
        return State.MAIN_MENU
    
    keyboard = []
    for item in buttons_data:
        keyboard.append([KeyboardButton(item['button_name'])])
    keyboard.append([KeyboardButton("Exit FAQ")])

    reply_markup = ReplyKeyboardMarkup(keyboard, resize_keyboard=True)
    await context.bot.send_message(
        chat_id=query.message.chat_id,
        text="❓ *FAQ Mode*\n\nHere are frequently asked questions.",
        reply_markup=reply_markup,
        parse_mode=ParseMode.MARKDOWN
    )
    return State.FAQ_MODE

# Lines: 6006-6025
async def exit_faq(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Exits FAQ mode and returns to the main menu."""
    chat_id = update.effective_chat.id
    exit_message = await context.bot.send_message(
        chat_id=chat_id,
        text="Exiting FAQ mode...",
        reply_markup=ReplyKeyboardRemove()
    )

    # Create a fake update object to pass to start()
    fake_update = Update(update.update_id, message=update.message or update.callback_query.message)
    
    return_state = State.MAIN_MENU # Default return state
    try:
        # Show the main menu
        return_state = await start(fake_update, context)
    finally:
        # Delete the temporary "Exiting..." message
        try:
            await context.bot.delete_message(chat_id=chat_id, message_id=exit_message.message_id)
        except Exception as e:
            logger.warning(f"Could not delete 'Exiting FAQ' message: {e}")
            
    return return_state


async def handle_faq_input(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Handles user pressing a reply button in FAQ mode."""
    button_text = update.message.text
    
    if button_text == "Exit FAQ":
        return await exit_faq(update, context)

    bot_id = await get_bot_id(context.bot.token)
    command_content = get_command_for_autoreply(bot_id, button_text)
    
    if command_content:
        for msg_data in command_content:
            msg_type = msg_data.get("type")
            text = msg_data.get("text") or msg_data.get("caption", "")
            entities = msg_data.get("entities")
            file_id = msg_data.get("file_id")
            try:
                if msg_type == "text": await context.bot.send_message(chat_id=update.effective_chat.id, text=text, entities=entities)
                elif msg_type == "photo": await context.bot.send_photo(chat_id=update.effective_chat.id, photo=file_id, caption=text, caption_entities=entities)
                elif msg_type == "video": await context.bot.send_video(chat_id=update.effective_chat.id, video=file_id, caption=text, caption_entities=entities)
                elif msg_type == "document": await context.bot.send_document(chat_id=update.effective_chat.id, document=file_id, caption=text, caption_entities=entities)
                await asyncio.sleep(0.1)
            except Exception as e:
                logger.error(f"Error sending FAQ content for button '{button_text}': {e}")
        return State.FAQ_MODE
    else:
        # If the button text doesn't match a known FAQ button, exit.
        return await exit_faq(update, context)

