async def handle_add_to_cart_quantity(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query

    try:
        data_parts = query.data.split('_')
        product_id = int(data_parts[4])
        quantity = int(data_parts[5])

        in_newsfeed = context.user_data.get('newsfeed_active')

        bot_id = await get_bot_id(context.bot.token)
        product = get_product(bot_id, product_id)
        if product:
            missing = get_missing_variant_requirements(product, context.user_data)
            if missing:
                await query.answer(f"⚠️ Please select {', '.join(missing)} first!", show_alert=True)
                return State.NEWSFEED if in_newsfeed else State.VIEW_PRODUCT

        if quantity <= 0:
            await query.answer("Please select a quantity greater than 0.", show_alert=True)
            return State.NEWSFEED if in_newsfeed else State.VIEW_PRODUCT

        user = update.effective_user
        user_data = await get_or_create_user(user.id, user.username, user.first_name, user.last_name, user.username, context.bot.token)

        if not user_data:
            await query.answer("❌ Error: User data not found. Please try again.", show_alert=True)
            return State.NEWSFEED if in_newsfeed else State.VIEW_PRODUCT

        if not product:
            await query.answer("❌ Error: Product not found.", show_alert=True)
            return State.NEWSFEED if in_newsfeed else State.VIEW_PRODUCT

        if product['stock_quantity'] is not None and product['stock_quantity'] < quantity:
            await query.answer(f"❌ Insufficient stock. Only {product['stock_quantity']} available.", show_alert=True)
            return State.NEWSFEED if in_newsfeed else State.VIEW_PRODUCT

        bot_id = await get_bot_id(context.bot.token)
        if not bot_id:
            await query.answer("Error: This bot is not registered correctly.", show_alert=True)
            return State.NEWSFEED if in_newsfeed else State.VIEW_PRODUCT

        variant_label = get_variant_label(product, context.user_data)
        item_name = f"{product['name']}{variant_label}"
        add_item_to_cart(bot_id, user_data['id'], product_id, quantity, custom_name=item_name)
        await query.answer(f"✅ Added {quantity} x {item_name} to your cart!", show_alert=True)

        context.user_data[f"qty_{product_id}"] = 0
        await show_product_detail(update, context, product_id)

        return State.NEWSFEED if in_newsfeed else State.VIEW_PRODUCT

    except Exception as e:
        print(f"Error in handle_add_to_cart_quantity: {e}")
        await query.answer("❌ An unexpected error occurred while adding to cart. Please try again or contact support.", show_alert=True)
        return State.NEWSFEED if context.user_data.get('newsfeed_active') else State.VIEW_PRODUCT

async def handle_increase_quantity(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    try:
        data_parts = query.data.split('_')
        product_id = int(data_parts[2])
        current_quantity = int(data_parts[3])

        bot_id = await get_bot_id(context.bot.token)
        product = get_product(bot_id, product_id)
        if product:
            missing = get_missing_variant_requirements(product, context.user_data)
            if missing:
                await query.answer(f"⚠️ Please select {', '.join(missing)} first!", show_alert=True)
                return State.NEWSFEED if context.user_data.get('newsfeed_active') else State.VIEW_PRODUCT

        await query.answer()
        if product and (product['stock_quantity'] is None or product['stock_quantity'] > current_quantity):
            context.user_data[f"qty_{product_id}"] = current_quantity + 1
        elif product:
            await query.answer(f"❌ Maximum stock ({product['stock_quantity']}) reached for this product.", show_alert=True)
        else:
            await query.answer("❌ Product not found or unavailable.", show_alert=True)

        await show_product_detail(update, context, product_id)
        return State.NEWSFEED if context.user_data.get('newsfeed_active') else State.VIEW_PRODUCT
    except Exception as e:
        print(f"Error in handle_increase_quantity: {e}")
        await query.answer("❌ An unexpected error occurred. Please try again or contact support.", show_alert=True)
        return State.NEWSFEED if context.user_data.get('newsfeed_active') else State.VIEW_PRODUCT

