async def handle_payment_confirmation(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """First click: show double confirmation prompt in-place."""
    query = update.callback_query
    await query.answer()

    parts = query.data.split('_')
    action = parts[2]  # 'yes' or 'no'
    order_number = parts[3]
    user_telegram_id = parts[4]

    if action == 'yes':
        confirm_text = (
            f"⚠️ *Confirm Payment Received?*\n\n"
            f"Order: `{order_number}`\n\n"
            f"Are you sure you want to mark this order as *Payment Received*?\n"
            f"This will notify the buyer and deduct stock."
        )
        confirm_btn = InlineKeyboardButton("✅ Yes, Confirm", callback_data=f"do_confirm_payment_yes_{order_number}_{user_telegram_id}")
        cancel_label = "🔙 Cancel"
    else:
        confirm_text = (
            f"⚠️ *Confirm Payment Rejection?*\n\n"
            f"Order: `{order_number}`\n\n"
            f"Are you sure you want to mark this order as *Payment Not Received*?\n"
            f"This will notify the buyer that payment failed."
        )
        confirm_btn = InlineKeyboardButton("❌ Yes, Reject", callback_data=f"do_confirm_payment_no_{order_number}_{user_telegram_id}")
        cancel_label = "🔙 Cancel"

    keyboard = InlineKeyboardMarkup([
        [confirm_btn],
        [InlineKeyboardButton(cancel_label, callback_data=f"cancel_payment_confirm_{order_number}_{user_telegram_id}")]
    ])

    try:
        await query.edit_message_text(text=confirm_text, reply_markup=keyboard, parse_mode=ParseMode.MARKDOWN)
    except Exception:
        await query.edit_message_caption(caption=confirm_text, reply_markup=keyboard, parse_mode=ParseMode.MARKDOWN)

    return


