async def handle_payment_confirmation_execute(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Second click confirmed — actually execute the payment confirmation."""
    query = update.callback_query
    await query.answer()

    parts = query.data.split('_')
    action = parts[3]
    order_number = parts[4]
    user_telegram_id = int(parts[5])
    acting_admin = query.from_user

    new_status = 'confirmed' if action == 'yes' else 'payment_failed'

    db.execute_query(
        "UPDATE orders SET status = %s, updated_at = CURRENT_TIMESTAMP WHERE order_number = %s",
        (new_status, order_number)
    )

    # Deduct stock when order is confirmed
    if new_status == 'confirmed':
        order = get_order(order_number)
        if order and order.get('items'):
            items = order['items'] if isinstance(order['items'], list) else __import__('json').loads(order['items'])
            for item in items:
                product_id = item.get('product_id')
                quantity = item.get('quantity', 1)
                if product_id:
                    db.execute_query(
                        """
                        UPDATE products
                        SET stock_quantity = GREATEST(0, stock_quantity - %s)
                        WHERE id = %s AND stock_quantity IS NOT NULL
                        """,
                        (quantity, product_id)
                    )

    # Award ecommerce points when order is confirmed
    if new_status == 'confirmed':
        try:
            pts_row = db.execute_query(
                "SELECT content_data FROM content_blocks WHERE key='ecommerce_points_settings' AND bot_id=%s",
                (order['bot_id'],), fetch=True
            )
            if pts_row and pts_row[0].get('content_data'):
                pts = pts_row[0]['content_data']
                if pts.get('enabled') and pts.get('earn_rate') and pts.get('earn_per'):
                    earn_rate = int(pts['earn_rate'])
                    earn_per = int(pts['earn_per'])
                    if earn_per > 0 and order.get('final_amount', 0) > 0:
                        points_to_award = int(float(order['final_amount']) / earn_per * earn_rate)
                        if points_to_award > 0:
                            cust = db.execute_query(
                                "SELECT id FROM website_customers WHERE telegram_id=%s AND bot_id=%s",
                                (user_telegram_id, order['bot_id']), fetch=True
                            )
                            if cust:
                                db.execute_query(
                                    "UPDATE website_customers SET points_balance=points_balance+%s, total_points_earned=COALESCE(total_points_earned,0)+%s WHERE id=%s",
                                    (points_to_award, points_to_award, cust[0]['id'])
                                )
                                db.execute_query(
                                    "INSERT INTO ecommerce_points_transactions (customer_id, bot_id, points, type, description, reference_order_id) VALUES (%s,%s,%s,'earn',%s,%s)",
                                    (cust[0]['id'], order['bot_id'], points_to_award, 'Earned from order #' + str(order_number), int(order.get('id', 0) or 0))
                                )
        except Exception as e:
            logger.error(f"Error awarding points for order {order_number}: {e}")

    user_lang_res = db.execute_query("SELECT language FROM users WHERE telegram_id = %s", (user_telegram_id,), fetch=True)
    user_lang = user_lang_res[0]['language'] if user_lang_res and user_lang_res[0]['language'] else 'en'

    if new_status == 'confirmed':
        custom_confirmation = db.execute_query(
            "SELECT content_data FROM content_blocks WHERE key = 'order_confirmation_message' AND bot_id = %s",
            (await get_bot_id(context.bot.token),), fetch=True
        )
        if custom_confirmation and custom_confirmation[0].get('content_data'):
            base_msg = custom_confirmation[0]['content_data'].get('content', '')
            user_message = base_msg + f"\n\nYour Order ID is: `{order_number}`"
        else:
            user_message = get_text('payment_confirmed_message', user_lang).format(order_number=order_number)
        await send_confirmation_slip(order_number, context, acting_admin.id)
    else:
        user_message = get_text('payment_failed_message', user_lang).format(order_number=order_number)

    try:
        await context.bot.send_message(chat_id=user_telegram_id, text=user_message, parse_mode=ParseMode.MARKDOWN)
    except Exception as e:
        logger.error(f"Could not send payment status update to user {user_telegram_id}: {e}")

    # Notify all admins when payment is declined
    if new_status == 'payment_failed':
        order_for_decline = get_order(order_number)
        buyer_for_decline = get_user_by_id(user_telegram_id) if order_for_decline else None
        decline_admin_notifications = order_for_decline.get('admin_notification_messages', []) if order_for_decline else []
        notified_admins = set()
        for notification in decline_admin_notifications:
            admin_id = notification['admin_id']
            if admin_id in notified_admins:
                continue
            notified_admins.add(admin_id)
            buyer_full = ""
            custom_buyer_name = "N/A"
            if buyer_for_decline:
                buyer_full = f"{buyer_for_decline.get('first_name', '')} {buyer_for_decline.get('last_name', '')}".strip()
                custom_buyer_name = buyer_for_decline.get('account_name') or buyer_full or 'N/A'
            decline_slip = (
                f"❌ *Payment Declined*\n\n"
                f"*Order ID:* `{order_number}` was marked as payment failed by {escape_markdown(acting_admin.first_name)}\n\n"
                f"*Buyer:* {escape_markdown(custom_buyer_name)}\n"
                f"User ID: `{user_telegram_id}`\n\n"
                f"⟵ Swipe left to send message"
            )
            try:
                await context.bot.send_message(
                    chat_id=admin_id,
                    text=decline_slip,
                    parse_mode=ParseMode.MARKDOWN
                )
            except Exception as e:
                logger.warning(f"Could not send decline notification to admin {admin_id}: {e}")

    order = get_order(order_number)
    admin_notifications = order.get('admin_notification_messages', []) if order else []

    status_text = new_status.replace('_', ' ').title()
    acting_admin_name = escape_markdown(acting_admin.first_name)

    for notification in admin_notifications:
        admin_id = notification['admin_id']
        message_id = notification['message_id']

        final_text = ""
        if admin_id == acting_admin.id:
            final_text = f"✅ Action complete. Order `{order_number}` marked as *{status_text}*."
        else:
            final_text = f"ℹ️ Order `{order_number}` was marked as *{status_text}* by {acting_admin_name}."

        try:
            await context.bot.edit_message_text(
                chat_id=admin_id,
                message_id=message_id,
                text=final_text,
                parse_mode=ParseMode.MARKDOWN,
                reply_markup=None
            )
        except Exception as e:
            logger.warning(f"Could not edit order notification for admin {admin_id}: {e}")

async def send_confirmation_slip(order_number: str, context: ContextTypes.DEFAULT_TYPE, admin_id: int):
    # Reset anti-spam penalty on successful payment
    try:
        ord_obj = get_order(order_number)
        if ord_obj:
            b_data = get_user_by_id(ord_obj[user_id])
            if b_data and b_data.get(telegram_id):
                u_id = b_data[telegram_id]
                context.bot_data.setdefault('mmpay_user_streaks', {})[u_id] = 0
                context.bot_data.setdefault('mmpay_user_blocked', {})[u_id] = 0
    except Exception:
        pass
    """Fetches order details, formats them into a slip, and sends to the buyer and admin."""
    order = get_order(order_number)
    if not order:
        logger.error(f"Could not generate slip: Order {order_number} not found.")
        return

    buyer_data = get_user_by_id(order['user_id'])
    if not buyer_data:
        logger.error(f"Could not generate slip: Buyer for order {order_number} not found.")
        return

    lang = buyer_data.get('language', 'en')
    bot_id = order.get('bot_id')


    buyer_full_name = f"{buyer_data.get('first_name', '')} {buyer_data.get('last_name', '')}".strip()
    custom_name = buyer_data.get('account_name') or buyer_full_name or 'N/A'
    phone = buyer_data.get('phone_number', 'N/A')
    email = buyer_data.get('email', 'N/A')
    payment_method = order.get('payment_method', 'N/A')


    items_lines = []
    for item in order.get('items', []):
        item_name = escape_markdown(item.get('name', 'Unknown Product'))
        quantity = item.get('quantity', 0)
        price = Decimal(item.get('price', 0))
        price_str = await format_price(context, price, lang)
        items_lines.append(f"• {item_name} (x{quantity}) - {price_str}")
    items_text = "\n".join(items_lines)

    confirmation_time = datetime.datetime.now(MYANMAR_TIMEZONE)
    date_str = confirmation_time.strftime('%B %d, %Y at %I:%M %p')

    total_amount_str = await format_price(context, order['final_amount'], lang)
    notes = get_text('confirmation_slip_notes', lang)


    # Slip for buyer — no User ID line, no swipe hint
    b_lines = [
        "🧾 *Order Confirmation Slip*",
        "",
        f"*Order ID:* `{order_number}`",
        ""
    ]
    if custom_name and custom_name not in [N/A, None]:
        b_lines.append(f"*Name:* {escape_markdown(custom_name)}")
    if phone and phone not in [N/A, None]:
        b_lines.append(f"*Phone:* {escape_markdown(phone)}")
    if email and email not in [N/A, None]:
        b_lines.append(f"*Email:* {escape_markdown(email)}")
    
    b_lines.append("")
    b_lines.append(f"*Products:*\n{items_text}")
    b_lines.append("")
    
    b_lines.append(f"*Amount:* *{total_amount_str}*")
    b_lines.append(f"*Payment Method:* {escape_markdown(payment_method)}")
    
    if notes and notes not in [N/A, None]:
        b_lines.append("")
        b_lines.append(f"{notes}")
    
    b_lines.append("")
    b_lines.append("Admin will shortly contact.")
    
    buyer_slip_text = "\n".join(b_lines)

    # Slip for admin — includes hidden User ID for swipe-to-reply + swipe hint
    admin_slip_text = (
        f"🧾 *Order Confirmation Slip*\n\n"
        f"*Order ID:* `{order_number}`\n\n"
        f"*Name:* {escape_markdown(custom_name)}\n"
        f"*Phone:* {escape_markdown(phone)}\n"
        f"*Email:* {escape_markdown(email)}\n"
        f"*User ID: {buyer_data['telegram_id']}*\n\n"
        f"*Products:*\n{items_text}\n\n"
        f"*Date:* {date_str}\n"
        f"*Amount:* *{total_amount_str}*\n"
        f"*Payment Method:* {escape_markdown(payment_method)}\n\n"
        f"{notes}\n\n"
        f"⟵ Swipe left to send message"
    )

    try:
        await context.bot.send_message(
            chat_id=buyer_data['telegram_id'],
            text=buyer_slip_text,
            parse_mode=ParseMode.MARKDOWN
        )
    except Exception as e:
        logger.error(f"Failed to send confirmation slip to buyer {buyer_data['telegram_id']}: {e}")

    try:
        if admin_id != buyer_data['telegram_id']:
            await context.bot.send_message(
                chat_id=admin_id,
                text=admin_slip_text,
                parse_mode=ParseMode.MARKDOWN
            )
    except Exception as e:
        logger.error(f"Failed to send confirmation slip copy to admin {admin_id}: {e}")

async def handle_upgrade_confirmation(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handles the super admin's decision on a plan upgrade request."""
    query = update.callback_query
    await query.answer()

    parts = query.data.split('_')
    action = parts[1]
    bot_id_to_upgrade = int(parts[2])
    admin_user_id = int(parts[3])
    plan_name = parts[4]
    plan_type = parts[5]


    original_text = query.message.text
    original_entities = query.message.entities

    if action == "confirm":

        keyboard = [
            [InlineKeyboardButton("⚠️ YES, UPGRADE NOW ⚠️", callback_data=f"upgrade_execute_{bot_id_to_upgrade}_{admin_user_id}_{plan_name}_{plan_type}")],
            [InlineKeyboardButton("Cancel", callback_data=f"upgrade_cancel_{bot_id_to_upgrade}_{admin_user_id}_{plan_name}_{plan_type}")]
        ]

        new_text = original_text + "\n\nARE YOU SURE you want to upgrade this bot?"
        await query.edit_message_text(
            text=new_text,
            entities=original_entities,
            reply_markup=InlineKeyboardMarkup(keyboard)

        )
    elif action == "decline":

        bot_to_notify_data = db.execute_query("SELECT bot_token FROM managed_bots WHERE id = %s", (bot_id_to_upgrade,), fetch=True)
        if bot_to_notify_data:
            bot_to_notify_app = Application.builder().token(bot_to_notify_data[0]['bot_token']).build()
            await bot_to_notify_app.bot.send_message(
                chat_id=admin_user_id,
                text=f"❌ Your request to upgrade to the *{plan_name}* plan has been declined. Please contact support if you believe this is an error.",
                parse_mode=ParseMode.MARKDOWN
            )
        new_text = original_text + "\n\n--- Request Declined by Admin. ---"
        await query.edit_message_text(
            text=new_text,
            entities=original_entities
        )
    elif action == "cancel":

        original_keyboard = [
            [
                InlineKeyboardButton("✅ Confirm & Upgrade", callback_data=f"upgrade_confirm_{bot_id_to_upgrade}_{admin_user_id}_{plan_name}_{plan_type}"),
                InlineKeyboardButton("❌ Decline", callback_data=f"upgrade_decline_{bot_id_to_upgrade}_{admin_user_id}_{plan_name}_{plan_type}")
            ]
        ]

        await query.edit_message_text(
            text=original_text,
            entities=original_entities,
            reply_markup=InlineKeyboardMarkup(original_keyboard)
        )




async def execute_upgrade(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Finalizes the upgrade in the database after super admin confirmation."""
    query = update.callback_query
    await query.answer("Processing upgrade...")

    parts = query.data.split('_')
    bot_id_to_upgrade = int(parts[2])
    admin_user_id = int(parts[3])
    plan_name = parts[4]
    plan_type = parts[5]

    current_text = query.message.text
    current_entities = query.message.entities

    if plan_type == "yearly":
        expiry_date = datetime.datetime.now() + datetime.timedelta(days=365)
    else:
        expiry_date = datetime.datetime.now() + datetime.timedelta(days=30)

    db.execute_query(
        "UPDATE managed_bots SET plan_name = %s, plan_expiry = %s, plan_start_date = NOW() WHERE id = %s",
        (plan_name, expiry_date, bot_id_to_upgrade)
    )

    try:
        referred_user_res = db.execute_query(
            "SELECT referred_by_telegram_id FROM affiliate_users WHERE telegram_id = %s",
            (admin_user_id,), fetch=True
        )
        if referred_user_res and referred_user_res[0]['referred_by_telegram_id']:
            referrer_tid = referred_user_res[0]['referred_by_telegram_id']
            # Changed to get MMK price
            amount = get_plan_price_mmk(plan_name, plan_type)
            if amount:
                pct_res = db.execute_query("SELECT commission_percent FROM affiliate_users WHERE telegram_id=%s", (referrer_tid,), fetch=True)
                pct = pct_res[0]['commission_percent'] if pct_res and pct_res[0]['commission_percent'] else 10
                commission = (amount * Decimal(str(pct)) / Decimal('100')).quantize(Decimal('1'))
                db.execute_query(
                    """
                    INSERT INTO referral_commissions (referrer_telegram_id, referred_telegram_id, managed_bot_id, plan_name, plan_type, amount_mmk, commission_mmk)
                    VALUES (%s, %s, %s, %s, %s, %s, %s)
                    """,
                    (referrer_tid, admin_user_id, bot_id_to_upgrade, plan_name, plan_type, amount, commission)
                )

                try:
                    upgrading_user_info = db.execute_query(
                        "SELECT full_name, username FROM affiliate_users WHERE telegram_id = %s",
                        (admin_user_id,), fetch=True
                    )
                    upgrading_user_name = "A referred user"
                    if upgrading_user_info:
                        full_name_db = upgrading_user_info[0].get('full_name')
                        username = upgrading_user_info[0].get('username')
                        
                        if full_name_db and full_name_db.strip():
                            upgrading_user_name = full_name_db.strip()
                        elif username:
                            upgrading_user_name = f"@{username}"
                    notification_text = (
                        f"🎉 Commission Earned!\n\n"
                        f"A user you referred, {upgrading_user_name}, has upgraded to the {plan_name} Plan.\n\n"
                        f"You have earned: {commission:,.0f} MMK"
                    )
                    await context.bot.send_message(
                        chat_id=referrer_tid,
                        text=notification_text
                    )
                    logger.info(f"Sent commission notification to referrer {referrer_tid} for {commission:,.0f} MMK")
                except Exception as notify_error:
                    logger.error(f"Failed to send commission notification to referrer {referrer_tid}: {notify_error}")
    except Exception as e:
        logger.error(f"Failed to record referral commission: {e}")

    bot_to_notify_data = db.execute_query("SELECT bot_token FROM managed_bots WHERE id = %s", (bot_id_to_upgrade,), fetch=True)
    if bot_to_notify_data:
        bot_to_notify_app = Application.builder().token(bot_to_notify_data[0]['bot_token']).build()
        await bot_to_notify_app.bot.send_message(
            chat_id=admin_user_id,
            text=f"🎉 Congratulations! Your bot has been successfully upgraded to the *{plan_name} Plan*.",
            parse_mode=ParseMode.MARKDOWN
        )

    original_notification_text = current_text.split("\n\nARE YOU SURE")[0]
    final_text = original_notification_text + f"\n\n--- Upgraded to {plan_name} by Admin. ---"
    await query.edit_message_text(
        text=final_text,
        entities=current_entities
    )



async def show_statistics(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """(Admin Command) Displays key performance indicators for the bot shop."""
    user = update.effective_user
    user_data = await get_or_create_user(user.id, user.username, user.first_name, user.last_name, user.username, context.bot.token)


    if not user_data or not user_data.get('is_admin'):
        await update.effective_message.reply_text("❌ This command is for admins only.")
        return

    status_msg = await update.effective_message.reply_text("📊 Generating statistics, please wait...")
    lang = await get_user_lang(context)

    try:
        bot_id = await get_bot_id(context.bot.token)
        stats = get_shop_statistics(bot_id)


        now = datetime.datetime.now(pytz.utc)
        start_of_week = (now - datetime.timedelta(days=now.weekday())).replace(hour=0, minute=0, second=0, microsecond=0)
        start_of_day = now.replace(hour=0, minute=0, second=0, microsecond=0)

        total_revenue_month = sum(o['final_amount'] for o in stats['monthly_orders'])
        total_orders_month = len(stats['monthly_orders'])

        orders_today = [o for o in stats['monthly_orders'] if o['created_at'].astimezone(pytz.utc) >= start_of_day]
        revenue_today = sum(o['final_amount'] for o in orders_today)

        orders_week = [o for o in stats['monthly_orders'] if o['created_at'].astimezone(pytz.utc) >= start_of_week]
        revenue_week = sum(o['final_amount'] for o in orders_week)

        avg_order_value = total_revenue_month / total_orders_month if total_orders_month > 0 else Decimal(0)


        f_revenue_month = await format_price(context, total_revenue_month, lang)
        f_revenue_week = await format_price(context, revenue_week, lang)
        f_revenue_today = await format_price(context, revenue_today, lang)
        f_avg_order_value = await format_price(context, avg_order_value, lang)

        message = "📈 Your Shop Statistics\n\n"
        message += "Sales Performance (This Month)\n"
        message += f"💰 Total Revenue: {f_revenue_month}\n"
        message += f"📦 Total Orders: {total_orders_month}\n"
        message += f"💸 Average Order Value: {f_avg_order_value}\n\n"

        message += "Period Summaries\n"
        message += f"📅 This Week: {f_revenue_week} ({len(orders_week)} orders)\n"
        message += f"☀️ Today: {f_revenue_today} ({len(orders_today)} orders)\n\n"

        message += "User Growth\n"
        message += f"👥 Total Users: {stats['total_users']}\n"
        message += f"📈 New This Week: {stats['new_users_week']}\n"
        message += f"✨ New Today: {stats['new_users_today']}\n\n"

        if stats['top_products_month']:
            message += "Top 5 Products (This Month)\n"
            for i, product in enumerate(stats['top_products_month']):
                message += f"{i+1}. {product['product_name']} ({product['total_sold']} sold)\n"
        else:
            message += "Top 5 Products (This Month)\n"
            message += "No products have been sold yet this month."

        message += "\n\nGet Excel File -> /statistics_excel"

        await status_msg.edit_text(message)

    except Exception as e:
        logger.error(f"Error in show_statistics handler: {e}", exc_info=True)
        await status_msg.edit_text("❌ An error occurred while generating the report.")


async def export_statistics_excel_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """(Admin Command) Generates a detailed Excel/CSV report of the shop statistics."""
    user = update.effective_user
    user_data = await get_or_create_user(user.id, user.username, user.first_name, user.last_name, user.username, context.bot.token)

    if not user_data or not user_data.get('is_admin'):
        await update.effective_message.reply_text("❌ This command is for admins only.")
        return

    status_msg = await update.effective_message.reply_text("📊 Generating Excel report, please wait...")
    
    try:
        bot_id = await get_bot_id(context.bot.token)
        lang = await get_user_lang(context)
        stats = get_shop_statistics(bot_id)
        
        # --- Calculate Summaries (Same as show_statistics) ---
        now = datetime.datetime.now(pytz.utc)
        start_of_week = (now - datetime.timedelta(days=now.weekday())).replace(hour=0, minute=0, second=0, microsecond=0)
        start_of_day = now.replace(hour=0, minute=0, second=0, microsecond=0)

        total_revenue_month = sum(o['final_amount'] for o in stats['monthly_orders'])
        total_orders_month = len(stats['monthly_orders'])

        orders_today = [o for o in stats['monthly_orders'] if o['created_at'].astimezone(pytz.utc) >= start_of_day]
        revenue_today = sum(o['final_amount'] for o in orders_today)

        orders_week = [o for o in stats['monthly_orders'] if o['created_at'].astimezone(pytz.utc) >= start_of_week]
        revenue_week = sum(o['final_amount'] for o in orders_week)

        avg_order_value = total_revenue_month / total_orders_month if total_orders_month > 0 else Decimal(0)

        # Get currency from DB in real time
        try:
            rows = db.execute_query("SELECT currency FROM managed_bots WHERE bot_token = %s", (context.bot.token,), fetch=True)
            curr_code = (rows[0]["currency"] or "MMK") if rows and rows[0] else "MMK"
        except Exception:
            curr_code = "MMK"

        # Helper for formatting price in CSV (raw number + symbol in separate col or string)
        async def fmt(val):
            return await format_price(context, val, lang)

        # --- Fetch Detailed Order List for the CSV ---
        detailed_orders = db.execute_query(
            """
            SELECT o.created_at, o.order_number, o.final_amount, o.status, u.username, u.first_name, u.last_name 
            FROM orders o 
            LEFT JOIN users u ON o.user_id = u.id 
            WHERE o.bot_id = %s AND o.status = 'confirmed' AND o.created_at >= DATE_TRUNC('month', NOW()) 
            ORDER BY o.created_at DESC
            """,
            (bot_id,), fetch=True
        )

        # --- Styles ---
        h_fill  = PatternFill("solid", start_color="2E86AB", end_color="2E86AB")
        h_font  = Font(name="Arial", bold=True, color="FFFFFF", size=11)
        h_align = Alignment(horizontal="center", vertical="center")
        s_fill  = PatternFill("solid", start_color="1B4F72", end_color="1B4F72")  # section header
        s_font  = Font(name="Arial", bold=True, color="FFFFFF", size=10)
        d_font  = Font(name="Arial", size=10)
        alt_fill = PatternFill("solid", start_color="F0F4F8", end_color="F0F4F8")
        center  = Alignment(horizontal="center", vertical="center")
        left    = Alignment(horizontal="left", vertical="center")

        def set_header(ws, row, cols):
            for col, val in enumerate(cols, 1):
                c = ws.cell(row=row, column=col, value=val)
                c.font = h_font; c.fill = h_fill; c.alignment = h_align
            ws.row_dimensions[row].height = 20

        def set_section(ws, row, label):
            c = ws.cell(row=row, column=1, value=label)
            c.font = s_font; c.fill = s_fill; c.alignment = left
            ws.row_dimensions[row].height = 18

        def set_row(ws, row, data, alt=False):
            fill = alt_fill if alt else None
            for col, val in enumerate(data, 1):
                c = ws.cell(row=row, column=col, value=val)
                c.font = d_font; c.alignment = left
                if fill: c.fill = fill
            ws.row_dimensions[row].height = 16

        wb = Workbook()

        # ── Sheet 1: Summary ──────────────────────────────────────
        ws1 = wb.active
        ws1.title = "Summary"
        ws1.column_dimensions['A'].width = 30
        ws1.column_dimensions['B'].width = 20
        ws1.column_dimensions['C'].width = 15

        r = 1
        # Title
        ws1.cell(row=r, column=1, value="📊 Shop Statistics Report").font = Font(name="Arial", bold=True, size=13)
        ws1.cell(row=r+1, column=1, value=f"Generated: {now.strftime('%Y-%m-%d %H:%M:%S')}")
        ws1.cell(row=r+2, column=1, value=f"Currency: {curr_code}")
        r += 4

        # Sales Performance
        set_section(ws1, r, "Sales Performance (This Month)"); r += 1
        set_header(ws1, r, ["Metric", "Value"]); r += 1
        for i, (metric, val) in enumerate([
            ("Total Revenue", await fmt(total_revenue_month)),
            ("Total Orders", total_orders_month),
            ("Average Order Value", await fmt(avg_order_value)),
        ]):
            set_row(ws1, r, [metric, val], alt=(i % 2 == 0)); r += 1
        r += 1

        # Period Summaries
        set_section(ws1, r, "Period Summaries"); r += 1
        set_header(ws1, r, ["Period", "Revenue", "Orders"]); r += 1
        for i, (period, rev, cnt) in enumerate([
            ("This Week", await fmt(revenue_week), len(orders_week)),
            ("Today",     await fmt(revenue_today), len(orders_today)),
        ]):
            set_row(ws1, r, [period, rev, cnt], alt=(i % 2 == 0)); r += 1
        r += 1

        # User Growth
        set_section(ws1, r, "User Growth"); r += 1
        set_header(ws1, r, ["Metric", "Count"]); r += 1
        for i, (metric, val) in enumerate([
            ("Total Users",           stats['total_users']),
            ("New Users (This Week)", stats['new_users_week']),
            ("New Users (Today)",     stats['new_users_today']),
        ]):
            set_row(ws1, r, [metric, val], alt=(i % 2 == 0)); r += 1
        r += 1

        # Top Products
        set_section(ws1, r, "Top 5 Products (This Month)"); r += 1
        set_header(ws1, r, ["Rank", "Product Name", "Units Sold", f"Price ({curr_code})"]); r += 1
        if stats['top_products_month']:
            for i, p in enumerate(stats['top_products_month']):
                price_val = f"{float(p['unit_price']):,.0f} {curr_code}" if p.get('unit_price') else 'N/A'
                set_row(ws1, r, [i+1, p['product_name'], p['total_sold'], price_val], alt=(i % 2 == 0)); r += 1
        else:
            set_row(ws1, r, ["-", "No sales yet", "-", "-"]); r += 1

        ws1.freeze_panes = "A1"

        # ── Sheet 2: Order Details ────────────────────────────────
        ws2 = wb.create_sheet("Order Details")
        for col, width in zip(['A','B','C','D','E','F'], [18, 20, 22, 18, 15, 12]):
            ws2.column_dimensions[col].width = width

        set_header(ws2, 1, ["Date", "Order Number", "Customer Name", "Username", "Amount", "Status"])
        ws2.freeze_panes = "A2"

        if detailed_orders:
            for i, order in enumerate(detailed_orders):
                c_name = f"{order.get('first_name','') or ''} {order.get('last_name','') or ''}".strip()
                c_user = f"@{order.get('username')}" if order.get('username') else "N/A"
                set_row(ws2, i+2, [
                    order['created_at'].strftime("%Y-%m-%d %H:%M"),
                    order['order_number'],
                    c_name,
                    c_user,
                    await fmt(order['final_amount']),
                    order['status'].title()
                ], alt=(i % 2 == 0))
        else:
            ws2.cell(row=2, column=1, value="No confirmed orders found for this month.")

        # Save & send
        buf = io.BytesIO()
        wb.save(buf)
        buf.seek(0)
        filename = f"Shop_Statistics_{now.strftime('%Y%m%d')}.xlsx"

        await context.bot.send_document(
            chat_id=user.id,
            document=buf,
            filename=filename,
            caption="📊 *Shop Statistics Report*\n\nTwo sheets: Summary + Order Details.",
            parse_mode=ParseMode.MARKDOWN
        )
        await status_msg.delete()

    except Exception as e:
        logger.error(f"Error exporting statistics excel: {e}", exc_info=True)
        await status_msg.edit_text("❌ An error occurred while creating the Excel file.")


async def share_referral(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Sends the user's referral link for inviting others."""
    # Ensure any stuck keyboard (FAQ, AI, etc) is removed
    await cleanup_ai_mode(update, context)

    user = update.effective_user
    try:
        affiliate_user_data = await get_or_create_affiliate_user(user.id, user.username, user.full_name)
        if not affiliate_user_data:
            if update.message:
                await update.message.reply_text("❌ Could not load your affiliate profile. Please try again later.")
            else:
                await context.bot.send_message(chat_id=user.id, text="❌ Could not load your affiliate profile. Please try again later.")
            return ConversationHandler.END

        main_bot_details = await get_bot_details(TOKEN)
        if main_bot_details and main_bot_details.get('username'):
            user_telegram_id = affiliate_user_data.get('telegram_id')
            referral_link = f"https://t.me/{main_bot_details['username']}?start=ref_{user_telegram_id}"
        else:
            referral_link = "Error: Main bot details not found."

        text = f"🔗 Share this link to invite friends and earn rewards:\n{referral_link}"
        if update.message:
            await update.message.reply_text(text)
        else:
            await context.bot.send_message(chat_id=user.id, text=text)
    except Exception as e:
        logger.error(f"/share failed: {e}", exc_info=True)
        if update.message:
            await update.message.reply_text("❌ Failed to generate your referral link. Please try again later.")
        else:
            await context.bot.send_message(chat_id=user.id, text="❌ Failed to generate your referral link. Please try again later.")
    return ConversationHandler.END


async def my_user_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Sends a CSV/Excel file listing all referred users and their bots."""
    await cleanup_ai_mode(update, context)

    if not update.effective_message:
        return

    user = update.effective_user
    fetching_msg = await update.effective_message.reply_text("⏳ Generating your referral report, please wait...")

    try:
        referred_users = db.execute_query(
            """
            SELECT telegram_id, full_name, username
                FROM affiliate_users
                WHERE referred_by_telegram_id = %s
                ORDER BY created_at
            """,
            (user.id,),
            fetch=True
        )

        if not referred_users:
            await update.effective_message.reply_text("You haven't referred any users yet. Share your referral link with others.")
            return

        referred_user_ids = [row['telegram_id'] for row in referred_users]

        bots_by_referred_users = db.execute_query(
            """
            SELECT owner_telegram_id, bot_full_name, bot_username
            FROM managed_bots
            WHERE owner_telegram_id = ANY(%s)
            ORDER BY owner_telegram_id, created_at
            """,
            (referred_user_ids,),
            fetch=True
        )

        bots_by_owner = {}
        if bots_by_referred_users:
            for bot in bots_by_referred_users:
                owner_id = bot['owner_telegram_id']
                if owner_id not in bots_by_owner:
                    bots_by_owner[owner_id] = []
                bots_by_owner[owner_id].append(bot)

        # Build CSV in memory
        output = io.StringIO()
        writer = csv.writer(output)

        # Header row
        writer.writerow(["#", "Full Name", "Username", "Telegram ID", "Bot Name", "Bot Username"])

        row_num = 1
        for referred_user in referred_users:
            uid       = referred_user['telegram_id']
            full_name = (referred_user.get('full_name') or 'N/A').strip() or 'N/A'
            username  = f"@{referred_user['username']}" if referred_user.get('username') else 'N/A'
            user_bots = bots_by_owner.get(uid)

            if user_bots:
                for bot in user_bots:
                    writer.writerow([
                        row_num,
                        full_name,
                        username,
                        uid,
                        bot.get('bot_full_name') or 'Unnamed Bot',
                        f"@{bot.get('bot_username')}" if bot.get('bot_username') else 'N/A'
                    ])
                    row_num += 1
            else:
                writer.writerow([row_num, full_name, username, uid, "No bots created yet", ""])
                row_num += 1

        output.seek(0)
        file_bytes = io.BytesIO(output.getvalue().encode('utf-8-sig'))
        now_str    = datetime.datetime.now().strftime('%Y%m%d_%H%M%S')
        filename   = f"Referred_Users_{now_str}.csv"

        await context.bot.send_document(
            chat_id=update.effective_chat.id,
            document=file_bytes,
            filename=filename,
            caption=f"👥 *Your Referred Users Report*\n\nTotal referred users: *{len(referred_users)}*",
            parse_mode=ParseMode.MARKDOWN
        )

    except Exception as e:
        logger.error(f"Error in my_user_command: {e}")
        await update.effective_message.reply_text("❌ An error occurred generating your report.")
    finally:
        try:
            await context.bot.delete_message(chat_id=update.effective_chat.id, message_id=fetching_msg.message_id)
        except Exception:
            pass




async def backup_database_job(context: ContextTypes.DEFAULT_TYPE):
    """Automatic job (every 6 hours) to backup database and send to Super Admin & Channel."""
    backup_filename = ""
    globals_filename = ""
    try:
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        backup_filename = f"db_backup_{DB_CONFIG['database']}_{timestamp}.dump"
        globals_filename = f"db_globals_{timestamp}.sql"

        env = os.environ.copy()
        env['PGPASSWORD'] = DB_CONFIG['password']

        command = (
            f"pg_dump -U {DB_CONFIG['user']} -h {DB_CONFIG['host']} -p {DB_CONFIG['port']} "
            f"-d {DB_CONFIG['database']} -F c -b -v -f {backup_filename}"
        )

        process = await asyncio.create_subprocess_shell(
            command, env=env,
            stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.PIPE
        )
        stdout, stderr = await process.communicate()

        if process.returncode != 0:
            error_details = stderr.decode().strip()
            logger.error(f"Auto-Backup failed. Error: {error_details}")
            # Notify admin of failure
            await context.bot.send_message(
                chat_id=SUPER_ADMIN_TELEGRAM_ID,
                text=f"❌ **Auto-Backup Failed**\n\n`{error_details}`",
                parse_mode=ParseMode.MARKDOWN
            )
            return

        # Dump roles/users (not included in pg_dump, needed for a clean restore on a new server)
        globals_command = (
            f"pg_dumpall -U {DB_CONFIG['user']} -h {DB_CONFIG['host']} -p {DB_CONFIG['port']} "
            f"--globals-only -f {globals_filename}"
        )
        globals_process = await asyncio.create_subprocess_shell(
            globals_command, env=env,
            stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.PIPE
        )
        await globals_process.communicate()

        # Send to Super Admin
        with open(backup_filename, 'rb') as f:
            await context.bot.send_document(
                chat_id=SUPER_ADMIN_TELEGRAM_ID,
                document=f,
                filename=backup_filename,
                caption=f"✅ Auto-Backup\n📅 {timestamp}"
            )
        if os.path.exists(globals_filename):
            with open(globals_filename, 'rb') as f:
                await context.bot.send_document(
                    chat_id=SUPER_ADMIN_TELEGRAM_ID,
                    document=f,
                    filename=globals_filename,
                    caption="✅ Roles/Users Backup (globals)"
                )

        # Send to backup channel
        try:
            with open(backup_filename, 'rb') as f:
                await context.bot.send_document(
                    chat_id=-1004328301651,
                    document=f,
                    filename=backup_filename,
                    caption=f"✅ Auto-Backup\n📅 {timestamp}"
                )
            if os.path.exists(globals_filename):
                with open(globals_filename, 'rb') as f:
                    await context.bot.send_document(
                        chat_id=-1004328301651,
                        document=f,
                        filename=globals_filename,
                        caption="✅ Roles/Users Backup (globals)"
                    )
        except Exception as e:
            logger.error(f"Failed to send auto-backup to channel: {e}")

    except Exception as e:
        logger.error(f"Auto-Backup Exception: {e}", exc_info=True)
    finally:
        if os.path.exists(backup_filename):
            os.remove(backup_filename)
        if os.path.exists(globals_filename):
            os.remove(globals_filename)

async def backup_database_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handles the /database command to back up the PostgreSQL database."""
    user = update.effective_user


    if user.id != SUPER_ADMIN_TELEGRAM_ID or context.bot.token != TOKEN:
        await update.message.reply_text("❌ This command is restricted to the Super Admin on the main bot only.")
        return

    status_message = await update.message.reply_text("⏳ Starting database backup... This may take a moment.")
    backup_filename = ""
    globals_filename = ""
    try:

        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        backup_filename = f"db_backup_{DB_CONFIG['database']}_{timestamp}.dump"
        globals_filename = f"db_globals_{timestamp}.sql"

        env = os.environ.copy()
        env['PGPASSWORD'] = DB_CONFIG['password']


        command = (
            f"pg_dump -U {DB_CONFIG['user']} -h {DB_CONFIG['host']} -p {DB_CONFIG['port']} "
            f"-d {DB_CONFIG['database']} -F c -b -v -f {backup_filename}"
        )

        process = await asyncio.create_subprocess_shell(
            command, env=env,
            stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.PIPE
        )
        stdout, stderr = await process.communicate()

        if process.returncode != 0:
            error_details = stderr.decode().strip()
            logger.error(f"Database backup failed. Error: {error_details}")
            await status_message.edit_text(f"❌ **Database backup failed.**\n\n`{error_details}`")
            return

        # Dump roles/users (not included in pg_dump, needed for a clean restore on a new server)
        globals_command = (
            f"pg_dumpall -U {DB_CONFIG['user']} -h {DB_CONFIG['host']} -p {DB_CONFIG['port']} "
            f"--globals-only -f {globals_filename}"
        )
        globals_process = await asyncio.create_subprocess_shell(
            globals_command, env=env,
            stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.PIPE
        )
        await globals_process.communicate()


        # 1. Send to Super Admin (You)
        try:
            with open(backup_filename, 'rb') as f:
                await context.bot.send_document(
                    chat_id=user.id,
                    document=f,
                    filename=backup_filename,
                    caption="✅ **Manual Backup Successful**\nHere is the database backup file.",
                    parse_mode=ParseMode.MARKDOWN
                )
            if os.path.exists(globals_filename):
                with open(globals_filename, 'rb') as f:
                    await context.bot.send_document(
                        chat_id=user.id,
                        document=f,
                        filename=globals_filename,
                        caption="✅ Roles/Users Backup (globals)"
                    )
        except Exception as e:
            logger.error(f"Failed to send backup to Super Admin: {e}")

        # 2. Send to backup channel
        try:
            with open(backup_filename, 'rb') as f:
                await context.bot.send_document(
                    chat_id=-1004328301651,
                    document=f,
                    filename=backup_filename,
                    caption="✅ **Manual Backup Successful**\nHere is the database backup file.",
                    parse_mode=ParseMode.MARKDOWN
                )
            if os.path.exists(globals_filename):
                with open(globals_filename, 'rb') as f:
                    await context.bot.send_document(
                        chat_id=-1004328301651,
                        document=f,
                        filename=globals_filename,
                        caption="✅ Roles/Users Backup (globals)"
                    )
        except Exception as e:
            logger.error(f"Failed to send manual backup to channel: {e}")

        # Cleanup status message safely
        try:
            await status_message.delete()
        except:
            pass

    except FileNotFoundError:
        logger.error("Backup failed: 'pg_dump' command not found.")
        await status_message.edit_text("❌ **Backup failed:** The `pg_dump` command was not found on the server. Please ensure PostgreSQL client tools are installed.")
    except Exception as e:
        logger.error(f"An unexpected error occurred during database backup: {e}", exc_info=True)
        await status_message.edit_text(f"❌ An unexpected error occurred: {e}")
    finally:
        # Wrap cleanup in try/except to prevent global error handler from triggering after success
        if os.path.exists(backup_filename):
            try:
                os.remove(backup_filename)
                logger.info(f"Cleaned up backup file: {backup_filename}")
            except Exception as cleanup_error:
                logger.error(f"Error cleaning up backup file: {cleanup_error}")
        if os.path.exists(globals_filename):
            try:
                os.remove(globals_filename)
            except Exception as cleanup_error:
                logger.error(f"Error cleaning up globals file: {cleanup_error}")


