async def execute_clear_persistence(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """(Super Admin) Manually deletes all .pkl persistence files to reset stuck states."""
    status_msg = await update.message.reply_text("🗑️ Scanning for stuck persistence files...")

    try:
        files_to_delete = [f for f in os.listdir('.') if f.startswith('bot_data_') and f.endswith('.pkl')]
        
        if not files_to_delete:
            await status_msg.edit_text("✅ System Clean: No persistence (.pkl) files found.")
            return

        deleted_count = 0
        errors = 0
        
        for file_name in files_to_delete:
            try:
                os.remove(file_name)
                deleted_count += 1
            except Exception as e:
                logger.error(f"Failed to delete {file_name}: {e}")
                errors += 1

        result_text = f"✅ **Cleanup Complete**\n\n🗑️ Deleted: {deleted_count} files\n"
        if errors > 0:
            result_text += f"⚠️ Errors: Failed to delete {errors} files (check logs)"
        
        result_text += "\n\nAny bots that were 'stuck' due to these files should work normally now."
        
        await status_msg.edit_text(result_text, parse_mode=ParseMode.MARKDOWN)

    except Exception as e:
        logger.error(f"Error in clear command: {e}", exc_info=True)
        await status_msg.edit_text("❌ An error occurred while trying to delete files.")

