async def export_subscribers_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """(Super Admin) Exports a list of all active subscribers to an Excel-compatible CSV file."""
    user = update.effective_user


    if user.id != SUPER_ADMIN_TELEGRAM_ID or context.bot.token != TOKEN:
        await update.message.reply_text("❌ This command is restricted to the Super Admin on the main bot only.")
        return

    status_message = await update.message.reply_text("⏳ Generating subscriber report, please wait...")

    try:

        subscribers = db.execute_query(
            """
            SELECT
                u.first_name,
                u.username,
                mb.bot_full_name,
                mb.bot_username,
                mb.plan_name,
                mb.plan_start_date,
                mb.plan_expiry
            FROM
                managed_bots mb
            JOIN
                users u ON mb.owner_telegram_id = u.telegram_id AND mb.id = u.bot_id
            WHERE
                mb.plan_name != 'Free' AND mb.plan_expiry IS NOT NULL
            ORDER BY
                mb.plan_expiry ASC;
            """,
            fetch=True
        )

        if not subscribers:
            await status_message.edit_text("ℹ️ There are no active subscribers found.")
            return


        wb = Workbook()
        ws = wb.active
        ws.title = "Subscribers"

        h_fill  = PatternFill("solid", start_color="1A5276", end_color="1A5276")
        h_font  = Font(name="Arial", bold=True, color="FFFFFF", size=11)
        h_align = Alignment(horizontal="center", vertical="center")
        d_font  = Font(name="Arial", size=10)
        alt_fill = PatternFill("solid", start_color="EAF2FF", end_color="EAF2FF")
        left    = Alignment(horizontal="left", vertical="center")

        headers = ["Name", "Username", "Bot Name", "Bot Username", "Plan", "Start Date", "End Date"]
        col_widths = [20, 18, 25, 20, 12, 14, 14]

        for col, (h, w) in enumerate(zip(headers, col_widths), 1):
            cell = ws.cell(row=1, column=col, value=h)
            cell.font = h_font; cell.fill = h_fill; cell.alignment = h_align
            ws.column_dimensions[cell.column_letter].width = w
        ws.row_dimensions[1].height = 20
        ws.freeze_panes = "A2"

        for i, sub in enumerate(subscribers):
            start_date = sub['plan_start_date'].strftime("%Y-%m-%d") if sub['plan_start_date'] else "N/A"
            end_date   = sub['plan_expiry'].strftime("%Y-%m-%d") if sub['plan_expiry'] else "N/A"
            row_data   = [
                sub.get('first_name', '') or '',
                f"@{sub.get('username', '')}" if sub.get('username') else 'N/A',
                sub.get('bot_full_name', '') or '',
                f"@{sub.get('bot_username', '')}" if sub.get('bot_username') else 'N/A',
                sub.get('plan_name', '') or '',
                start_date,
                end_date
            ]
            fill = alt_fill if i % 2 == 0 else None
            for col, val in enumerate(row_data, 1):
                cell = ws.cell(row=i+2, column=col, value=val)
                cell.font = d_font; cell.alignment = left
                if fill: cell.fill = fill
            ws.row_dimensions[i+2].height = 16

        buf = io.BytesIO()
        wb.save(buf)
        buf.seek(0)
        timestamp = datetime.datetime.now().strftime("%Y-%m-%d")
        filename = f"subscribers_export_{timestamp}.xlsx"

        await context.bot.send_document(
            chat_id=user.id,
            document=buf,
            filename=filename,
            caption=f"📋 *Subscribers Report*\n\nTotal: {len(subscribers)} active subscribers.",
            parse_mode=ParseMode.MARKDOWN
        )
        await status_message.delete()

    except Exception as e:
        logger.error(f"Failed to generate subscribers report: {e}", exc_info=True)
        await status_message.edit_text("❌ An error occurred while generating the report.")

