async def execute_downgrade_bot(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Executes the downgrade in the database."""
    query = update.callback_query
    await query.answer("Downgrading...")

    bot_id = int(query.data.split('_')[-1])

    # 1. Update Database
    db.execute_query(
        "UPDATE managed_bots SET plan_name = 'Free', plan_expiry = NULL, plan_start_date = NULL WHERE id = %s",
        (bot_id,)
    )

    # 2. Notify the Owner (Optional but good for testing)
    bot_info = db.execute_query("SELECT owner_telegram_id, bot_token FROM managed_bots WHERE id = %s", (bot_id,), fetch=True)
    if bot_info:
        owner_id = bot_info[0]['owner_telegram_id']
        token = bot_info[0]['bot_token']
        try:
            # Send msg as the bot itself
            app = Application.builder().token(token).build()
            await app.bot.send_message(
                chat_id=owner_id,
                text="📉 **Plan Update**\n\nYour plan has expired. Your bot has been downgraded to the **Free Plan.**",
                parse_mode=ParseMode.MARKDOWN
            )
        except Exception as e:
            logger.error(f"Failed to notify owner of downgrade: {e}")

    await safe_edit_caption_or_text(query, f"✅ Bot ID {bot_id} has been successfully downgraded to Free.", None)

async def cancel_downgrade(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Cancels the downgrade operation."""
    query = update.callback_query
    await query.answer("Cancelled")
    await safe_edit_caption_or_text(query, "❌ Downgrade operation cancelled.", None)

