async def save_ai_api_key(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Auto-detects provider, validates and saves the API Key."""
    api_key = update.message.text.strip()
    bot_id = await get_bot_id(context.bot.token)

    provider = detect_ai_provider(api_key)
    provider_labels = {"deepseek": "DeepSeek", "gemini": "Gemini", "openrouter": "OpenRouter"}
    provider_name = provider_labels[provider]

    msg = await update.message.reply_text(f"⏳ Detected *{provider_name}* — Validating API Key...", parse_mode=ParseMode.MARKDOWN)

    try:
        client, model = get_ai_client_and_model(api_key, provider)
        if provider == "gemini":
            def _validate():
                return call_gemini_ai(api_key, [{"role": "user", "content": "hi"}])
            await asyncio.get_event_loop().run_in_executor(None, _validate)
        else:
            def _validate():
                return client.chat.completions.create(
                    model=model,
                    messages=[{"role": "user", "content": "hi"}],
                    max_tokens=5
                )
            await asyncio.get_event_loop().run_in_executor(None, _validate)
    except Exception as e:
        logger.error(f"API Validation Failed ({provider}): {e}")
        await msg.edit_text(
            f"❌ *Invalid {provider_name} API Key*\n\nCould not verify the key. Please check and send again.",
            parse_mode=ParseMode.MARKDOWN
        )
        return State.ADD_AI_API_KEY

    # Save key and provider to DB
    db.execute_query(
        """
        INSERT INTO bot_ai_settings (bot_id, api_key, ai_provider) VALUES (%s, %s, %s)
        ON CONFLICT (bot_id) DO UPDATE SET api_key = EXCLUDED.api_key, ai_provider = EXCLUDED.ai_provider, updated_at = NOW()
        """,
        (bot_id, api_key, provider)
    )

    await msg.edit_text(f"✅ *{provider_name} API Key is Valid & Saved!*", parse_mode=ParseMode.MARKDOWN)
    return await manage_ai_agent_menu(update, context)

