async def save_ai_context(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Saves the AI System Context from text or PDF and returns to setup menu."""
    bot_id = await get_bot_id(context.bot.token)
    context_text = ""

    # 1. Handle Document (PDF or TXT)
    if update.message.document:
        doc = update.message.document
        is_pdf = doc.mime_type == 'application/pdf'
        is_txt = doc.mime_type in ('text/plain',) or (doc.file_name or '').lower().endswith('.txt')

        if not is_pdf and not is_txt:
            await update.message.reply_text("❌ Invalid file format. Please send a `.txt` file, a `.pdf` file, or plain text.")
            return State.ADD_AI_CONTEXT

        status_msg = await update.message.reply_text("⏳ Downloading and processing file...")
        
        try:
            file = await context.bot.get_file(doc.file_id)
            file_bytes = await file.download_as_bytearray()

            if is_txt:
                # Decode TXT file directly
                context_text = file_bytes.decode('utf-8', errors='replace').strip()
                if not context_text:
                    await status_msg.edit_text("❌ The `.txt` file appears to be empty.")
                    return State.ADD_AI_CONTEXT
            else:
                # Extract text from PDF using pypdf
                pdf_stream = io.BytesIO(file_bytes)
                reader = PdfReader(pdf_stream)
                extracted_pages = []
                for page in reader.pages:
                    text = page.extract_text()
                    if text:
                        extracted_pages.append(text)
                context_text = "\n".join(extracted_pages)
                if not context_text.strip():
                    await status_msg.edit_text("❌ Could not extract text from this PDF. It might be an image-only scanned PDF.")
                    return State.ADD_AI_CONTEXT

            await status_msg.delete()

        except Exception as e:
            logger.error(f"File extraction error: {e}")
            await status_msg.edit_text("❌ An error occurred while reading the file.")
            return State.ADD_AI_CONTEXT

    # 2. Handle Plain Text Message
    elif update.message.text:
        context_text = update.message.text.strip()

    # 3. Handle Invalid Input
    else:
        await update.message.reply_text("❌ Please send a text message, a `.txt` file, or a `.pdf` file.")
        return State.ADD_AI_CONTEXT

    # Upsert Context to Database
    db.execute_query(
        """
        INSERT INTO bot_ai_settings (bot_id, system_context) VALUES (%s, %s)
        ON CONFLICT (bot_id) DO UPDATE SET system_context = EXCLUDED.system_context, updated_at = NOW()
        """,
        (bot_id, context_text)
    )
    
    # Show success and character count
    char_count = len(context_text)
    await update.message.reply_text(f"✅ AI Context Saved!\n(Loaded {char_count} characters)")
    
    # Redirect back to AI Agent Setup menu
    return await manage_ai_agent_menu(update, context)

async def toggle_ai_enable(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    bot_id = await get_bot_id(context.bot.token)
    
    settings = db.execute_query("SELECT * FROM bot_ai_settings WHERE bot_id = %s", (bot_id,), fetch=True)
    
    plan_data = get_bot_plan_details(bot_id)
    plan_name = plan_data.get('plan_name', 'Free') if plan_data else 'Free'
    is_pro_or_business = plan_name.lower() in ['pro', 'business']

    if is_pro_or_business:
        # Pro/Business: only require superadmin API to exist; context is optional (has default)
        main = db.execute_query(
            "SELECT api_key FROM bot_ai_settings WHERE bot_id = 214", fetch=True
        )
        if not main or not main[0].get('api_key'):
            await query.answer("❌ Cannot Enable: Superadmin API not configured.", show_alert=True)
            return State.MANAGE_AI_AGENT

    elif plan_name.lower() == 'standard':
        # Standard: requires own API key AND context
        if not settings or not settings[0].get('api_key'):
            await query.answer("❌ Cannot Enable: Standard plan requires your own API Key.", show_alert=True)
            return State.MANAGE_AI_AGENT
        if not settings[0].get('system_context'):
            await query.answer("❌ Cannot Enable: Please set an AI Context first.", show_alert=True)
            return State.MANAGE_AI_AGENT

    # Get current enabled status; default False if no row yet
    current_status = settings[0]['is_enabled'] if settings else False
    new_status = not current_status

    # Upsert: create row if not exists, otherwise update
    db.execute_query(
        """
        INSERT INTO bot_ai_settings (bot_id, is_enabled) VALUES (%s, %s)
        ON CONFLICT (bot_id) DO UPDATE SET is_enabled = EXCLUDED.is_enabled, updated_at = NOW()
        """,
        (bot_id, new_status)
    )

    status_msg = "Enabled" if new_status else "Disabled"
    await query.answer(f"AI Agent {status_msg}!", show_alert=True)
    return await manage_ai_agent_menu(update, context)

