async def handle_restart_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handles the inline button confirmation for restart."""
    query = update.callback_query
    await query.answer()
    
    if query.data == "confirm_restart_yes":
        # If coming from /update flow, password already verified — restart immediately
        if context.user_data.get('update_password_verified'):
            context.user_data.pop('update_password_verified', None)
            await query.edit_message_text("✅ Restarting system now... (Please wait 10-20 seconds)")
            logger.info(f"System restart triggered after code update by Super Admin {update.effective_user.id}")
            db.disconnect()
            await asyncio.sleep(2)
            os.execl(sys.executable, sys.executable, *sys.argv)
        else:
            await query.edit_message_text("Please enter the Super Admin password to confirm:")
            return State.RESTART_PASSWORD
    else:
        await query.edit_message_text("❌ Restart cancelled.")
        return ConversationHandler.END

async def verify_restart_password(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Verifies the password and restarts the script."""
    password = update.message.text.strip()
    
    if password == "pythonlenn":
        await update.message.reply_text("✅ Password accepted. Restarting system now... (Please wait 10-20 seconds)")
        
        # Log the action
        logger.info(f"System restart triggered by Super Admin {update.effective_user.id}")
        
        # Optional: Close DB connection safely before restart
        db.disconnect()
        
        # Give the message a moment to send before killing the process
        await asyncio.sleep(2)
        
        # THIS COMMAND RESTARTS THE CODE
        # os.execl replaces the current process with a new one
        os.execl(sys.executable, sys.executable, *sys.argv)
    else:
        await update.message.reply_text("❌ Incorrect password. Restart cancelled.")
        return ConversationHandler.END

