async def receive_code_file(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Downloads the file and overwrites the current script."""
    if not update.message.document:
        await update.message.reply_text("❌ Please send the code as a **Document/File**, not as text or a photo.")
        return State.AWAITING_CODE_FILE
        
    doc = update.message.document
    if not doc.file_name.endswith('.py'):
        await update.message.reply_text("❌ Invalid file. Please send a Python (`.py`) file.")
        return State.AWAITING_CODE_FILE

    status_msg = await update.message.reply_text("⏳ Downloading and applying update...")
    
    try:
        # Get the absolute path of the currently running file (e.g., /opt/teleshop/Teleshop.py)
        current_file_path = os.path.abspath(__file__)
        
        # Download the file from Telegram
        file = await context.bot.get_file(doc.file_id)
        
        # Overwrite the running script
        await file.download_to_drive(current_file_path)
        
        # Success! Offer to restart immediately
        keyboard = [
            [InlineKeyboardButton("🔄 Restart Now", callback_data="confirm_restart_yes")],
            [InlineKeyboardButton("Not Now", callback_data="confirm_restart_no")]
        ]
        await status_msg.edit_text(
            f"✅ **Update Successful!**\n\nThe file `{current_file_path}` has been replaced with your new code.\n\n"
            "Do you want to restart the system now to apply the changes?",
            reply_markup=InlineKeyboardMarkup(keyboard),
            parse_mode=ParseMode.MARKDOWN
        )
        
        # Jump straight to the restart confirmation handler
        return State.CONFIRM_RESTART
        
    except PermissionError:
        logger.error("Permission denied when trying to overwrite the code file.")
        await status_msg.edit_text("❌ **Permission Denied!** The bot does not have root/write permissions to modify its own file. Please check folder permissions.")
        return ConversationHandler.END
    except Exception as e:
        logger.error(f"Failed to update code: {e}")
        await status_msg.edit_text("❌ An error occurred while applying the update.")
        return ConversationHandler.END

