async def verify_logs_password(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Verifies the password and sends the last 50 logs."""
    password = update.message.text.strip()
    
    if password == "pythonlenn":
        status_msg = await update.message.reply_text("⏳ Fetching logs...")
        try:
            with open("bot.log", "r", encoding="utf-8") as f:
                lines = f.readlines()
                last_50_lines = lines[-50:]
            
            log_text = "".join(last_50_lines)
            if not log_text.strip():
                log_text = "No logs recorded yet."
                
            file_content = io.BytesIO(log_text.encode('utf-8'))
            
            await context.bot.send_document(
                chat_id=update.effective_chat.id,
                document=file_content,
                filename="latest_50_logs.txt",
                caption="✅ Here are the latest 50 logs."
            )
            await status_msg.delete()
        except FileNotFoundError:
            await status_msg.edit_text("❌ Log file has not been generated yet.")
        except Exception as e:
            await status_msg.edit_text(f"❌ Failed to read logs: {e}")
        
        return ConversationHandler.END
    else:
        await update.message.reply_text("❌ Incorrect password. Logs request cancelled.")
        return ConversationHandler.END

