async def message_bot_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """/message_bot command — superadmin only, main bot only."""
    user_id = update.effective_user.id

    if user_id != SUPER_ADMIN_TELEGRAM_ID or context.bot.token != TOKEN:
        await update.message.reply_text("❌ Access Denied.")
        return ConversationHandler.END

    await update.message.reply_text(
        "📨 *Message Bot*\n\nPlease send the *@username* of the bot you want to message.\n\nExample: `@MyShopBot`",
        parse_mode=ParseMode.MARKDOWN,
        reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("❌ Cancel", callback_data="settings")]])
    )
    context.user_data['message_bot_source'] = 'command'
    context.user_data['message_bot_queue'] = []
    return State.MESSAGE_BOT_AWAIT_USERNAME


async def message_bot_receive_username(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Receives the bot username, looks it up in DB, and starts collecting messages."""
    raw = update.message.text.strip().lstrip('@')

    bot_info = db.execute_query(
        "SELECT id, bot_full_name, bot_username, bot_token FROM managed_bots WHERE LOWER(bot_username) = LOWER(%s) AND is_active = TRUE",
        (raw,), fetch=True
    )

    if not bot_info:
        await update.message.reply_text(
            f"❌ No active bot found with username @{raw}.\n\nPlease try again or press Cancel.",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("❌ Cancel", callback_data="settings")]])
        )
        return State.MESSAGE_BOT_AWAIT_USERNAME

    bot_info = bot_info[0]
    context.user_data['message_bot_target_id'] = bot_info['id']
    context.user_data['message_bot_target_name'] = bot_info['bot_full_name']
    context.user_data['message_bot_target_token'] = bot_info['bot_token']
    context.user_data['message_bot_queue'] = []

    bot_display = bot_info['bot_full_name'] or bot_info['bot_username'] or 'Unknown'
    await update.message.reply_text(
        f"✅ Bot found: {bot_display} (@{bot_info['bot_username']})\n\n"
        f"Now send the messages you want to deliver to all admins of this bot.\n"
        f"You can send text, photos, videos, documents, or voice notes.\n\n"
        f"Press ✅ Finish when done, or ❌ Cancel to abort.",
        reply_markup=ReplyKeyboardMarkup(
            [["✅ Finish", "❌ Cancel"]],
            resize_keyboard=True,
            one_time_keyboard=False
        )
    )
    return State.MESSAGE_BOT_COLLECT


async def message_bot_collect(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Collects messages into queue until admin presses Finish."""
    text = update.message.text or ""

    if text == "✅ Finish":
        return await message_bot_ask_confirm(update, context)
    if text == "❌ Cancel":
        return await message_bot_cancel(update, context)

    serialized = serialize_message(update.message)
    if serialized:
        context.user_data.setdefault('message_bot_queue', []).append(serialized)
        count = len(context.user_data['message_bot_queue'])
        await update.message.reply_text(
            f"👍 Message #{count} received. Send more or press *✅ Finish*.",
            parse_mode=ParseMode.MARKDOWN
        )
    else:
        await update.message.reply_text("⚠️ Unsupported message type. Please send text, photo, video, document, or voice.")

    return State.MESSAGE_BOT_COLLECT


async def message_bot_ask_confirm(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Shows confirmation before sending."""
    queue = context.user_data.get('message_bot_queue', [])
    target_name = context.user_data.get('message_bot_target_name', 'Unknown')

    if not queue:
        await update.message.reply_text(
            "⚠️ You haven't sent any messages yet. Please send at least one message, or press *❌ Cancel*.",
            parse_mode=ParseMode.MARKDOWN
        )
        return State.MESSAGE_BOT_COLLECT

    await update.message.reply_text(
        f"⚠️ *Confirmation*\n\n"
        f"You are about to send *{len(queue)} message(s)* to ALL users of:\n"
        f"🤖 *{escape_markdown(target_name)}*\n\n"
        f"Are you sure?",
        parse_mode=ParseMode.MARKDOWN,
        reply_markup=ReplyKeyboardRemove()
    )
    await update.message.reply_text(
        "Confirm sending?",
        reply_markup=InlineKeyboardMarkup([
            [
                InlineKeyboardButton("✅ Yes, Send", callback_data="message_bot_confirm_yes"),
                InlineKeyboardButton("❌ No, Cancel", callback_data="message_bot_confirm_no"),
            ]
        ])
    )
    return State.MESSAGE_BOT_CONFIRM


async def message_bot_confirm_send(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Executes the broadcast to all users of the target bot."""
    query = update.callback_query
    await query.answer()

    if query.data == "message_bot_confirm_no":
        return await message_bot_cancel(update, context)

    queue = context.user_data.get('message_bot_queue', [])
    target_bot_id = context.user_data.get('message_bot_target_id')
    target_token = context.user_data.get('message_bot_target_token')
    target_name = context.user_data.get('message_bot_target_name', 'Unknown')

    if not queue or not target_bot_id:
        await query.edit_message_text("❌ Session expired. Please start again with /message_bot.")
        return ConversationHandler.END

    status_msg = await query.message.reply_text("⏳ Processing and sending messages...")

    # Fetch admins only of the target bot
    admins_data = db.execute_query(
        "SELECT telegram_id FROM users WHERE bot_id = %s AND is_admin = TRUE",
        (target_bot_id,), fetch=True
    )
    admin_ids = {row['telegram_id'] for row in admins_data} if admins_data else set()

    # Also include the bot owner
    owner_data = db.execute_query(
        "SELECT owner_telegram_id FROM managed_bots WHERE id = %s",
        (target_bot_id,), fetch=True
    )
    if owner_data:
        admin_ids.add(owner_data[0]['owner_telegram_id'])

    user_ids = list(admin_ids)

    if not user_ids:
        await status_msg.edit_text("❌ No admins found for this bot.")
        _message_bot_cleanup(context)
        fake_update = Update(update.update_id, message=query.message)
        return await handle_settings(fake_update, context)

    # Pre-download media (file_ids are bot-specific)
    processed_queue = []
    try:
        for msg in queue:
            msg_data = msg.copy()
            file_id = msg_data.get("file_id")
            if file_id:
                file_obj = await context.bot.get_file(file_id)
                file_content = await file_obj.download_as_bytearray()
                msg_data['file_content'] = bytes(file_content)
            processed_queue.append(msg_data)
    except Exception as e:
        logger.error(f"[message_bot] Media download error: {e}")
        await status_msg.edit_text("❌ Error downloading media. Please try again.")
        return State.MESSAGE_BOT_CONFIRM

    # Send via target bot
    success_count = 0
    fail_count = 0
    try:
        target_app = Application.builder().token(target_token).build()
        for uid in user_ids:
            try:
                for msg in processed_queue:
                    msg_type = msg.get("type")
                    text = msg.get("text") or msg.get("caption", "")
                    entities = msg.get("entities")
                    file_bytes = msg.get("file_content")

                    if msg_type == "text":
                        await target_app.bot.send_message(chat_id=uid, text=text, entities=entities)
                    elif msg_type == "photo" and file_bytes:
                        await target_app.bot.send_photo(chat_id=uid, photo=file_bytes, caption=text, caption_entities=entities)
                    elif msg_type == "video" and file_bytes:
                        await target_app.bot.send_video(chat_id=uid, video=file_bytes, caption=text, caption_entities=entities)
                    elif msg_type == "document" and file_bytes:
                        await target_app.bot.send_document(chat_id=uid, document=file_bytes, caption=text, caption_entities=entities)
                    elif msg_type == "voice" and file_bytes:
                        await target_app.bot.send_voice(chat_id=uid, voice=file_bytes, caption=text, caption_entities=entities)
                    elif msg_type == "audio" and file_bytes:
                        await target_app.bot.send_audio(chat_id=uid, audio=file_bytes, caption=text, caption_entities=entities)
                    await asyncio.sleep(0.05)
                success_count += 1
            except Exception as e:
                logger.error(f"[message_bot] Failed to send to user {uid}: {e}")
                fail_count += 1

        try:
            await status_msg.delete()
        except:
            pass

        await query.message.reply_text(
            f"✅ *Broadcast Complete*\n\n"
            f"🤖 Bot: *{escape_markdown(target_name)}*\n"
            f"✅ Delivered: {success_count} users\n"
            f"❌ Failed: {fail_count} users",
            parse_mode=ParseMode.MARKDOWN
        )

    except Exception as e:
        logger.error(f"[message_bot] Critical send error: {e}")
        try:
            await status_msg.delete()
        except:
            pass
        await query.message.reply_text("❌ Critical error occurred while sending.")

    _message_bot_cleanup(context)
    fake_update = Update(update.update_id, message=query.message)
    return await handle_settings(fake_update, context)


async def message_bot_cancel(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Cancels the message_bot flow."""
    _message_bot_cleanup(context)

    if update.callback_query:
        await update.callback_query.answer("Cancelled")
        await update.callback_query.message.reply_text("❌ Cancelled.", reply_markup=ReplyKeyboardRemove())
    else:
        await update.message.reply_text("❌ Cancelled.", reply_markup=ReplyKeyboardRemove())

    fake_update = Update(
        update.update_id,
        message=update.effective_message,
        callback_query=update.callback_query
    )
    return await handle_settings(fake_update, context)


def _message_bot_cleanup(context: ContextTypes.DEFAULT_TYPE):
    """Clears message_bot session data."""
    for key in ['message_bot_queue', 'message_bot_target_id', 'message_bot_target_name',
                'message_bot_target_token', 'message_bot_source']:
        context.user_data.pop(key, None)


