async def super_upgrade_percent_start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    await safe_edit_caption_or_text(query, "📈 *Upgrade User %*\n\nPlease send the user's referral link.", InlineKeyboardMarkup([[InlineKeyboardButton("Cancel", callback_data="manage_affiliates")]]))
    return State.SUPER_AFF_LINK

async def super_upgrade_percent_link(update: Update, context: ContextTypes.DEFAULT_TYPE):
    link = update.message.text.strip()
    if "start=ref_" not in link:
        await update.message.reply_text("❌ Invalid referral link. Please try again.")
        return State.SUPER_AFF_LINK
    try:
        ref_id = int(link.split("start=ref_")[-1])
        user = db.execute_query("SELECT telegram_id, username FROM affiliate_users WHERE telegram_id=%s", (ref_id,), fetch=True)
        if not user:
            await update.message.reply_text("❌ User not found in affiliate system.")
            return State.SUPER_AFF_LINK
        context.user_data['super_aff_ref_id'] = ref_id
        await update.message.reply_text(f"✅ User @{user[0].get('username') or ref_id} found. Send the new commission percentage (1 to 100).", reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("Cancel", callback_data="manage_affiliates")]]))
        return State.SUPER_AFF_PERCENT
    except Exception:
        await update.message.reply_text("❌ Invalid referral link format.")
        return State.SUPER_AFF_LINK

async def super_upgrade_percent_value(update: Update, context: ContextTypes.DEFAULT_TYPE):
    text = update.message.text.strip()
    if not text.isdigit() or not (1 <= int(text) <= 100):
        await update.message.reply_text("❌ Must be a number between 1 and 100. Try again.")
        return State.SUPER_AFF_PERCENT

    new_pct = int(text)
    ref_id = context.user_data['super_aff_ref_id']
    db.execute_query("UPDATE affiliate_users SET commission_percent=%s WHERE telegram_id=%s", (new_pct, ref_id))
    await update.message.reply_text(f"✅ User's commission updated to {text}%!")

    if new_pct > 10:
        try:
            congrats_msg = (
                f"🎉 *Congratulations!*\n\n"
                f"You have been upgraded to *{new_pct}%* commission as an Affiliate Partner! 🚀\n\n"
                f"Keep referring users and enjoy your increased earnings. Thank you for being a valued partner! 💪"
            )
            await context.bot.send_message(
                chat_id=ref_id,
                text=congrats_msg,
                parse_mode=ParseMode.MARKDOWN
            )
        except Exception as e:
            logger.warning(f"Could not send commission upgrade notification to user {ref_id}: {e}")

    return await manage_affiliates_menu(update, context)

async def clean_volatile_states(application: Application):
    """
    Runs on startup. Preserves Shopping/Cart data but resets 
    users who were in 'AI Agent' or 'Create Bot' modes back to Main Menu.
    """
    # 1. Get the conversation state dictionary
    # Note: If you haven't named your handler, we iterate all conversations.
    # Typically there is one primary dict for the main handler.
    try:
        # Access the internal conversation storage
        for conv_key, conversation_dict in application.persistence.conversations.items():
            keys_to_reset = []
            
            # 2. Find users in Volatile States
            for key, state in conversation_dict.items():
                # AI Agent States (92-95) and Create Bot States (27-28)
                if state in [
                    State.AI_AGENT_MODE, State.MANAGE_AI_AGENT, State.ADD_AI_API_KEY, State.ADD_AI_CONTEXT, State.AI_ACCOUNTANT_MODE, # AI
                    State.PROMPT_FOR_BOT_TOKEN, State.AWAITING_BOT_TOKEN # Create Bot
                ]:
                    keys_to_reset.append(key)
            
            # 3. Reset them to MAIN_MENU (State 0) or remove them
            for key in keys_to_reset:
                # We simply remove their state so they restart at /start next time
                # Or set to State.MAIN_MENU (0)
                conversation_dict[key] = State.MAIN_MENU
                
                # Also clear the specific flags in user_data if possible
                # (Tuple key is usually (chat_id, user_id))
                if isinstance(key, tuple) and len(key) >= 1:
                    user_id = key[-1] # Usually the last element
                    if user_id in application.user_data:
                        application.user_data[user_id]['in_ai_agent_mode'] = False
                        application.user_data[user_id]['in_accountant_mode'] = False
                        application.user_data[user_id]['is_creating_bot'] = False

        logger.info(f"Cleanup Complete: Reset {len(keys_to_reset)} users from volatile states.")
        
        # Force a save of the cleaned data
        await application.persistence.flush()
        
    except Exception as e:
        logger.warning(f"Volatile state cleanup skipped (might be fresh start): {e}")

