async def list_bots_for_messaging(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """(Super Admin) Lists all bots to select one for messaging its admins."""
    query = update.callback_query
    await query.answer()

    if update.effective_user.id != SUPER_ADMIN_TELEGRAM_ID or context.bot.token != TOKEN:
        await query.answer("❌ Access Denied.", show_alert=True)
        return State.SETTINGS

    # Fetch active bots
    bots = db.execute_query(
        "SELECT id, bot_full_name, bot_username FROM managed_bots WHERE is_active = TRUE ORDER BY id",
        fetch=True
    )

    if not bots:
        await safe_edit_caption_or_text(
            query, 
            "ℹ️ No active bots found to message.", 
            InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Back", callback_data="settings")]])
        )
        return State.SETTINGS

    caption = "📨 *Message to Bot Admins*\n\nSelect a bot from the list below. The message you send next will be delivered to **all admins** of that bot, sent **from that bot**."
    
    keyboard = []
    for bot in bots:
        name = bot.get('bot_full_name', 'Unnamed')
        username = f"(@{bot.get('bot_username', 'No User')})"
        # Callback format: msg_bot_select_{bot_id}
        keyboard.append([InlineKeyboardButton(f"{name} {username}", callback_data=f"msg_bot_select_{bot['id']}")])

    keyboard.append([InlineKeyboardButton("🔙 Back to Settings", callback_data="settings")])
    
    await safe_edit_caption_or_text(query, caption, InlineKeyboardMarkup(keyboard))
    return State.SELECT_BOT_TO_MESSAGE

