async def collect_admin_message_content(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Collects messages to queue for sending."""
    serialized_msg = serialize_message(update.message)
    
    if serialized_msg:
        context.user_data.setdefault('admin_messages_queue', []).append(serialized_msg)
        await update.message.reply_text("👍 Received. Send more or press '✅ Send Now'.")
    else:
        await update.message.reply_text("⚠️ Unsupported message type.")
        
    return State.COLLECT_ADMIN_MESSAGE

async def send_messages_to_bot_admins(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Finalizes and sends the queued messages to the target bot's admins using Cross-Bot Media transfer."""
    queue = context.user_data.get('admin_messages_queue', [])
    target_bot_id = context.user_data.get('target_msg_bot_id')

    if not queue or not target_bot_id:
        await update.message.reply_text("❌ No messages to send or session expired.", reply_markup=ReplyKeyboardRemove())
        return await handle_settings(update, context)

    status_msg = await update.message.reply_text("⏳ Processing media and sending...", reply_markup=ReplyKeyboardRemove())

    # 1. Get Target Bot Token
    bot_data = db.execute_query("SELECT bot_token FROM managed_bots WHERE id = %s", (target_bot_id,), fetch=True)
    if not bot_data:
        await status_msg.edit_text("❌ Error: Target bot not found in database.")
        return await handle_settings(update, context)
    
    target_token = bot_data[0]['bot_token']

    # 2. Get Target Bot Admins
    admins_data = db.execute_query("SELECT telegram_id FROM users WHERE bot_id = %s AND is_admin = TRUE", (target_bot_id,), fetch=True)
    admin_ids = {row['telegram_id'] for row in admins_data}
    owner_data = db.execute_query("SELECT owner_telegram_id FROM managed_bots WHERE id = %s", (target_bot_id,), fetch=True)
    if owner_data:
        admin_ids.add(owner_data[0]['owner_telegram_id'])

    if not admin_ids:
        await status_msg.edit_text("❌ Error: No admins found for this bot.")
        return await handle_settings(update, context)

    # 3. PRE-PROCESS MEDIA: Download everything from Main Bot once
    # We store the byte content so we can send it via the other bot
    processed_queue = []
    
    try:
        for msg in queue:
            msg_data = msg.copy()
            file_id = msg_data.get("file_id")
            
            # If it has a file_id, we MUST download it because file_ids are bot-specific
            if file_id:
                try:
                    file_obj = await context.bot.get_file(file_id)
                    file_content = await file_obj.download_as_bytearray()
                    msg_data['file_content'] = bytes(file_content) # Store bytes
                except Exception as e:
                    logger.error(f"Failed to download media for cross-bot send: {e}")
                    await status_msg.edit_text(f"❌ Error downloading one of your media files. Please try again.")
                    return State.COLLECT_ADMIN_MESSAGE
            
            processed_queue.append(msg_data)

    except Exception as e:
        logger.error(f"Error processing media queue: {e}")
        await status_msg.edit_text("❌ Error processing media files.")
        return State.SETTINGS

    # 4. Send Messages using Target Bot
    success_count = 0
    fail_count = 0
    
    try:
        target_app = Application.builder().token(target_token).build()
        
        for admin_id in admin_ids:
            try:
                # Loop through pre-processed messages
                for msg in processed_queue:
                    msg_type = msg.get("type")
                    text = msg.get("text") or msg.get("caption", "")
                    entities = msg.get("entities")
                    file_bytes = msg.get("file_content") # Use the bytes we downloaded
                    
                    if msg_type == "text":
                        await target_app.bot.send_message(chat_id=admin_id, text=text, entities=entities)
                    
                    elif msg_type == "photo" and file_bytes:
                        await target_app.bot.send_photo(chat_id=admin_id, photo=file_bytes, caption=text, caption_entities=entities)
                    
                    elif msg_type == "video" and file_bytes:
                        await target_app.bot.send_video(chat_id=admin_id, video=file_bytes, caption=text, caption_entities=entities)
                    
                    elif msg_type == "document" and file_bytes:
                        await target_app.bot.send_document(chat_id=admin_id, document=file_bytes, caption=text, caption_entities=entities)
                    
                    elif msg_type == "voice" and file_bytes:
                        await target_app.bot.send_voice(chat_id=admin_id, voice=file_bytes, caption=text, caption_entities=entities)
                    
                    elif msg_type == "audio" and file_bytes:
                        await target_app.bot.send_audio(chat_id=admin_id, audio=file_bytes, caption=text, caption_entities=entities)
                        
                    elif msg_type == "sticker" and file_bytes:
                        await target_app.bot.send_sticker(chat_id=admin_id, sticker=file_bytes)
                    
                    await asyncio.sleep(0.2) # Slight delay to prevent flooding
                
                success_count += 1
            except Exception as e:
                logger.error(f"Failed to send to admin {admin_id} of bot {target_bot_id}: {e}")
                fail_count += 1
                
        # Delete the "Processing..." message
        try:
            await status_msg.delete()
        except Exception:
            pass

        # Send the summary as a new message
        await update.message.reply_text(
            f"✅ **Sent Successfully**\n\n"
            f"Delivered to: {success_count} admins\n"
            f"Failed: {fail_count}",
            parse_mode=ParseMode.MARKDOWN
        )

    except Exception as e:
        logger.error(f"Critical error sending admin messages: {e}")
        try:
            await status_msg.delete()
        except:
            pass
        await update.message.reply_text("❌ Critical error occurred while sending.")

    context.user_data.pop('admin_messages_queue', None)
    context.user_data.pop('target_msg_bot_id', None)
    
    fake_update = Update(update.update_id, callback_query=update.callback_query, message=update.message)
    return await handle_settings(fake_update, context)

async def cancel_admin_messaging(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Cancels the operation."""
    context.user_data.pop('admin_messages_queue', None)
    context.user_data.pop('target_msg_bot_id', None)
    
    if update.callback_query:
        await update.callback_query.answer("Cancelled")
    
    await update.effective_message.reply_text("❌ Operation Cancelled.", reply_markup=ReplyKeyboardRemove())
    
    # Return to settings
    fake_update = Update(update.update_id, callback_query=update.callback_query, message=update.effective_message)
    return await handle_settings(fake_update, context)

