async def user_view_giveaway(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    bot_id = await get_bot_id(context.bot.token)
    gw_id = int(query.data.split('_')[-1])
    user_id = update.effective_user.id
    
    gw = db.execute_query("SELECT * FROM giveaways WHERE id = %s", (gw_id,), fetch=True)
    if not gw:
        await query.answer("Giveaway ended or not found.", show_alert=True)
        return await user_list_giveaways(update, context)
        
    gw = gw[0]
    content_data = gw['content_data']
    messages_to_send = content_data.get('messages', [])
    
    # Check if user already joined
    participant = db.execute_query("SELECT tickets FROM giveaway_participants WHERE giveaway_id = %s AND telegram_id = %s", (gw_id, user_id), fetch=True)
    
    keyboard = []
    if not participant:
        keyboard.append([InlineKeyboardButton("🎟️ JOIN GIVEAWAY", callback_data=f"user_gw_join_{gw_id}")])
    else:
        bot_username = context.bot.username or (await context.bot.get_me()).username
        ref_link = f"https://t.me/{bot_username}?start=gwref_{gw_id}_{user_id}"
        keyboard.append([InlineKeyboardButton("🔗 Share to get more tickets!", url=f"https://t.me/share/url?url={ref_link}&text=Join this awesome giveaway!")])
    
    keyboard.append([InlineKeyboardButton("🔙 Back to Giveaways", callback_data="user_giveaways_list")])
    reply_markup = InlineKeyboardMarkup(keyboard)

    # Delete old menu and send the custom giveaway messages
    try: await query.message.delete()
    except: pass
    
    chat_id = query.message.chat_id
    total_messages = len(messages_to_send)
    
    for i, msg_data in enumerate(messages_to_send):
        is_last = (i == total_messages - 1)
        markup = reply_markup if is_last else None
        
        msg_type = msg_data.get("type")
        text = msg_data.get("text") or msg_data.get("caption", "")
        entities = msg_data.get("entities")
        file_id = msg_data.get("file_id")

        try:
            if msg_type == "text":
                # If it's the last message, append user stats
                if is_last and participant:
                    text += f"\n\n✅ You are in!\n🎟️ *Your Tickets:* {participant[0]['tickets']}\n🔗 *Referral Link:* `{ref_link}`"
                await context.bot.send_message(chat_id=chat_id, text=text, entities=entities, reply_markup=markup, parse_mode=ParseMode.MARKDOWN)
            elif msg_type == "photo":
                if is_last and participant: text += f"\n\n✅ You are in!\n🎟️ *Your Tickets:* {participant[0]['tickets']}\n🔗 *Referral Link:* `{ref_link}`"
                await context.bot.send_photo(chat_id=chat_id, photo=file_id, caption=text, caption_entities=entities, reply_markup=markup, parse_mode=ParseMode.MARKDOWN)
            elif msg_type == "video":
                await context.bot.send_video(chat_id=chat_id, video=file_id, caption=text, caption_entities=entities, reply_markup=markup)
            await asyncio.sleep(0.1)
        except Exception as e:
            logger.error(f"Error replaying giveaway message: {e}")

    return State.USER_GIVEAWAY_VIEW

async def user_join_giveaway(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    bot_id = await get_bot_id(context.bot.token)
    gw_id = int(query.data.split('_')[-1])
