async def gw_claim_prize(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Triggered when the winner clicks 'Claim Prize'."""
    query = update.callback_query
    await query.answer()
    
    gw_id = int(query.data.split('_')[-1])
    user = update.effective_user
    bot_id = await get_bot_id(context.bot.token)
    
    # 1. Update the button to show it's claimed (One-time use)
    try:
        await query.edit_message_reply_markup(
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("✅ Prize Claimed", callback_data="ignore_claim")]])
        )
    except Exception:
        pass
        
    # 2. Fetch Giveaway Title
    gw = db.execute_query("SELECT title FROM giveaways WHERE id = %s", (gw_id,), fetch=True)
    gw_title = gw[0]['title'] if gw else "Giveaway"
    
    # 3. Format message for Admin (User ID at the top enables Swipe-To-Reply!)
    full_name = escape_markdown(user.full_name)
    username = escape_markdown(user.username) if user.username else "N/A"
    
    admin_text = (
        f"User ID: `{user.id}`\n"
        f"🎁 *({escape_markdown(gw_title)}) Winner*\n\n"
        f"*Name* - {full_name}\n"
        f"*ID* - `{user.id}`\n"
        f"*Username* - @{username}\n\n"
        f"Swipe left this message to reply."
    )
    
    # 4. Create standard Admin Action Buttons (Profile & Block)
    user_data = get_user_by_telegram_id(user.id, bot_id)
    reply_markup = None
    if user_data:
        user_db_id = user_data['id']
        is_blocked = user_data.get('is_support_blocked', False)
        block_button = InlineKeyboardButton("✅ Unblock User", callback_data=f"admin_unblock_user_{user_db_id}") if is_blocked else InlineKeyboardButton("🚫 Block User", callback_data=f"admin_block_user_{user_db_id}")
        reply_markup = InlineKeyboardMarkup([[
            InlineKeyboardButton("👤 View Profile", callback_data=f"admin_view_user_{user_db_id}_{user.id}"),
            block_button
        ]])
    
    # 5. Send to all Admins
    admin_ids = await get_admin_telegram_ids(bot_id)
    for admin_id in admin_ids:
        try:
            await context.bot.send_message(
                chat_id=admin_id,
                text=admin_text,
                parse_mode=ParseMode.MARKDOWN,
                reply_markup=reply_markup
            )
        except Exception as e:
            logger.error(f"Failed to send claim notification to admin {admin_id}: {e}")
            
    # 6. Let the user know
    await context.bot.send_message(chat_id=user.id, text="✅ Your claim has been successfully sent to the admin. They will contact you shortly!")

