async def gw_data_export(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    gw_id = int(query.data.split('_')[-1])
    bot_id = await get_bot_id(context.bot.token)
    
    gw_info = db.execute_query("SELECT title FROM giveaways WHERE id = %s", (gw_id,), fetch=True)
    title = gw_info[0]['title'] if gw_info else "Giveaway"
    
    participants = db.execute_query(
        """SELECT u.first_name, u.last_name, u.username, gp.telegram_id, gp.tickets 
           FROM giveaway_participants gp 
           JOIN users u ON gp.telegram_id = u.telegram_id AND u.bot_id = %s 
           WHERE gp.giveaway_id = %s ORDER BY gp.tickets DESC""", 
        (bot_id, gw_id), fetch=True
    )
    
    output = io.StringIO()
    writer = csv.writer(output)
    writer.writerow(["No.", "Name", "Username", "ID", "Tickets", "Giveaway Title"])
    
    for i, p in enumerate(participants, 1):
        name = f"{p.get('first_name','')} {p.get('last_name','')}".strip()
        writer.writerow([i, name, f"@{p['username']}" if p['username'] else "N/A", p['telegram_id'], p['tickets'], title])
        
    output.seek(0)
    file_content = io.BytesIO(output.getvalue().encode('utf-8-sig'))
    
    await query.message.reply_document(document=file_content, filename=f"{title}_participants.csv", caption="📊 Participant Data")
    return State.GIVEAWAY_DATA_LIST

