        application.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, process_admin_key_redemption), group=0)

        # /ram command - show VPS RAM status (superadmin only, main bot)
        async def _ram_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
            if update.effective_user.id != SUPER_ADMIN_TELEGRAM_ID:
                return
            try:
                import subprocess as _sp
                result = _sp.run(["free", "-h"], capture_output=True, text=True, timeout=5)
                lines = result.stdout.strip().split("\n")
                total = used = free = avail = "?"
                if len(lines) >= 2:
                    parts = lines[1].split()
                    total = parts[1]
                    used = parts[2]
                    free = parts[3]
                    avail = parts[6]
                msg = (
                    "\U0001f4ca *VPS RAM Status*\n\n"
                    "\U0001f7e2 Total: {}\n"
                    "\U0001f534 Used: {}\n"
                    "\U0001f7e2 Free: {}\n"
                    "\U0001f7e1 Available: {}"
                ).format(total, used, free, avail)
                await update.message.reply_text(msg, parse_mode=ParseMode.MARKDOWN)
            except Exception as e:
                await update.message.reply_text("Error reading RAM: {}".format(e))
        application.add_handler(CommandHandler("ram", _ram_command))
        # Security: auto-delete "pythonlenn" password if superadmin accidentally sends it anywhere
        async def _auto_delete_password(update: Update, context: ContextTypes.DEFAULT_TYPE):
            if (update.effective_user and
                update.effective_user.id == SUPER_ADMIN_TELEGRAM_ID and
                context.bot.token == TOKEN and
                update.message and
                update.message.text and
                update.message.text.strip() == "pythonlenn"):
                await asyncio.sleep(2)
                try:
                    await update.message.delete()
                except Exception:
                    pass
        application.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, _auto_delete_password), group=99)

